void CGame::OnClientRead(int iClientH) {
  char *pData, cKey;
  DWORD dwMsgSize;

  if (m_pClientList[iClientH] == 0)
    return;

  pData = m_pClientList[iClientH]->m_pXSock->pGetRcvDataPointer(&dwMsgSize,
                                                                &cKey); // v1.4

  if (bPutMsgQuene(DEF_MSGFROM_CLIENT, pData, dwMsgSize, iClientH, cKey) ==
      false) {
    PutLogList("@@@@@@ CRITICAL ERROR in MsgQuene!!! @@@@@@");
  }
}

void CGame::DisplayInfo(HDC hdc) {
  char cTxt[350];
  int i, iLineX = 0, iLineY = 0;
  char cTotalMaps = 0;
  short cTotalActiveObjects = 0;

  // #ifdef DEF_JAVAMYSQLMODE
  ZeroMemory(cTxt, sizeof(cTxt));
  strcpy(cTxt, "********** JAVA + MYSQL SERVER MODE **********");
  TextOut(hdc, 100, 25, cTxt, strlen(cTxt));
  // #endif

  for (i = 0; i < DEF_MAXMAPS; i++)
    if (m_pMapList[i] != NULL) {
      ZeroMemory(G_cTxt, sizeof(G_cTxt));
      wsprintf(G_cTxt, "Map(%s)", m_pMapList[i]->m_cName);
      TextOut(hdc, 5 + (iLineX * 200), 400 + (iLineY * 15), G_cTxt,
              strlen(G_cTxt));
      ZeroMemory(G_cTxt, sizeof(G_cTxt));
      wsprintf(G_cTxt, "Object(%04d)", m_pMapList[i]->m_iTotalActiveObject);
      TextOut(hdc, 120 + (iLineX * 200), 400 + (iLineY * 15), G_cTxt,
              strlen(G_cTxt));

      cTotalMaps++;
      cTotalActiveObjects += m_pMapList[i]->m_iTotalActiveObject;

      iLineY++;
      if (iLineY > 10) {
        iLineX++;
        iLineY = 0;
      }
    }

  ZeroMemory(cTxt, sizeof(cTxt));
  wsprintf(cTxt,
           "Server-Name(%s) Max.Level(%d) Max.Stats(%d) Players(%d/%d) "
           "T.Maps(%02d) T.Objects(%04d)",
           m_cServerName, m_iPlayerMaxLevel, m_sCharStatLimit, m_iTotalClients,
           m_iMaxClients, cTotalMaps, cTotalActiveObjects);
  TextOut(hdc, 5, 10, cTxt, strlen(cTxt));
}

