void CGame::ClientMotionHandler(int iClientH, char *pData) {
  DWORD *dwp, dwClientTime;
  WORD *wp, wCommand, wTargetObjectID;
  short *sp, sX, sY, dX, dY, wType;
  char *cp, cDir;
  int iRet, iTemp;

  if (m_pClientList[iClientH] == 0)
    return;
  if (m_pClientList[iClientH]->m_bIsInitComplete == false)
    return;
  if (m_pClientList[iClientH]->m_bIsKilled)
    return;

  /*m_pClientList[iClientH]->m_cConnectionCheck++;
  if (m_pClientList[iClientH]->m_cConnectionCheck > 50) {
          wsprintf(G_cTxt, "Hex: (%s) Player: (%s) - removed 03203203h, vital to
  hack detection.", m_pClientList[iClientH]->m_cIPaddress,
  m_pClientList[iClientH]->m_cCharName); PutHackLogFileList(G_cTxt);
          DeleteClient(iClientH, true, true);
          return;
  }*/
  wp = (WORD *)(pData + DEF_INDEX2_MSGTYPE);
  wCommand = *wp;

  cp = (char *)(pData + DEF_INDEX2_MSGTYPE + 2);

  sp = (short *)cp;
  sX = *sp;
  cp += 2;

  sp = (short *)cp;
  sY = *sp;
  cp += 2;

  cDir = *cp;
  cp++;

  sp = (short *)cp;
  dX = *sp;
  cp += 2;

  sp = (short *)cp;
  dY = *sp;
  cp += 2;

  sp = (short *)cp;
  wType = *sp;
  cp += 2;

  if ((wCommand == DEF_OBJECTATTACK) ||
      (wCommand == DEF_OBJECTATTACKMOVE)) { // v1.4
    wp = (WORD *)cp;
    wTargetObjectID = *wp;
    cp += 2;
  }

  // v2.171
  dwp = (DWORD *)cp;
  dwClientTime = *dwp;
  cp += 4;

  switch (wCommand) {
  case DEF_OBJECTSTOP:
    iRet = iClientMotion_Stop_Handler(iClientH, sX, sY, cDir);
    if (iRet == 1) {
      SendEventToNearClient_TypeA(iClientH, DEF_OWNERTYPE_PLAYER,
                                  MSGID_EVENT_MOTION, DEF_OBJECTSTOP, 0, 0, 0);
    } else if (iRet == 2)
      SendObjectMotionRejectMsg(iClientH);
    break;

  case DEF_OBJECTRUN:
    iRet = iClientMotion_Move_Handler(iClientH, sX, sY, cDir, 1);
    if (iRet == 1) {
      SendEventToNearClient_TypeA(iClientH, DEF_OWNERTYPE_PLAYER,
                                  MSGID_EVENT_MOTION, DEF_OBJECTRUN, 0, 0, 0);
    }
    if ((m_pClientList[iClientH] != 0) && (m_pClientList[iClientH]->m_iHP <= 0))
      ClientKilledHandler(iClientH, 0, 0, 1); // v1.4
    // v2.171
    bCheckClientMoveFrequency(iClientH, dwClientTime);
    break;

  case DEF_OBJECTMOVE:
    iRet = iClientMotion_Move_Handler(iClientH, sX, sY, cDir, 2);
    if (iRet == 1) {
      SendEventToNearClient_TypeA(iClientH, DEF_OWNERTYPE_PLAYER,
                                  MSGID_EVENT_MOTION, DEF_OBJECTMOVE, 0, 0, 0);
    }
    if ((m_pClientList[iClientH] != 0) && (m_pClientList[iClientH]->m_iHP <= 0))
      ClientKilledHandler(iClientH, 0, 0, 1); // v1.4
    // v2.171
    bCheckClientMoveFrequency(iClientH, dwClientTime);
    break;

  case DEF_OBJECTDAMAGEMOVE:
    iRet = iClientMotion_Move_Handler(iClientH, sX, sY, cDir, 0);
    if (iRet == 1) {
      SendEventToNearClient_TypeA(iClientH, DEF_OWNERTYPE_PLAYER,
                                  MSGID_EVENT_MOTION, DEF_OBJECTDAMAGEMOVE,
                                  m_pClientList[iClientH]->m_iLastDamage, 0, 0);
    }
    if ((m_pClientList[iClientH] != 0) && (m_pClientList[iClientH]->m_iHP <= 0))
      ClientKilledHandler(iClientH, 0, 0, 1); // v1.4
    break;

  case DEF_OBJECTATTACKMOVE:
    iRet = iClientMotion_Move_Handler(iClientH, sX, sY, cDir, 0);
    if ((iRet == 1) && (m_pClientList[iClientH] != 0)) {
      SendEventToNearClient_TypeA(iClientH, DEF_OWNERTYPE_PLAYER,
                                  MSGID_EVENT_MOTION, DEF_OBJECTATTACKMOVE, 0,
                                  0, 0);
      iClientMotion_Attack_Handler(iClientH, m_pClientList[iClientH]->m_sX,
                                   m_pClientList[iClientH]->m_sY, dX, dY, wType,
                                   cDir, wTargetObjectID, false, true); // v1.4
    }
    if ((m_pClientList[iClientH] != 0) && (m_pClientList[iClientH]->m_iHP <= 0))
      ClientKilledHandler(iClientH, 0, 0, 1); // v1.4
    // v2.171
    bCheckClientAttackFrequency(iClientH, dwClientTime);
    break;

  case DEF_OBJECTATTACK:
    _CheckAttackType(iClientH, &wType);
    iRet = iClientMotion_Attack_Handler(iClientH, sX, sY, dX, dY, wType, cDir,
                                        wTargetObjectID); // v1.4
    if (iRet == 1) {
      if (wType >= 20) {
        m_pClientList[iClientH]->m_iSuperAttackLeft--;
        if (m_pClientList[iClientH]->m_iSuperAttackLeft < 0)
          m_pClientList[iClientH]->m_iSuperAttackLeft = 0;
      }

      SendEventToNearClient_TypeA(iClientH, DEF_OWNERTYPE_PLAYER,
                                  MSGID_EVENT_MOTION, DEF_OBJECTATTACK, dX, dY,
                                  wType);
    } else if (iRet == 2)
      SendObjectMotionRejectMsg(iClientH);
    // v2.171
    bCheckClientAttackFrequency(iClientH, dwClientTime);
    break;

  case DEF_OBJECTGETITEM:
    iRet = iClientMotion_GetItem_Handler(iClientH, sX, sY, cDir);
    if (iRet == 1) {
      SendEventToNearClient_TypeA(iClientH, DEF_OWNERTYPE_PLAYER,
                                  MSGID_EVENT_MOTION, DEF_OBJECTGETITEM, 0, 0,
                                  0);
    } else if (iRet == 2)
      SendObjectMotionRejectMsg(iClientH);
    break;

  case DEF_OBJECTMAGIC:
    iRet = iClientMotion_Magic_Handler(iClientH, sX, sY, cDir);
    // client hp recorded here ONLY if its less than
    if (iRet == 1) {
      if (m_pClientList[iClientH]->m_bMagicPauseTime == false) {
        m_pClientList[iClientH]->m_bMagicPauseTime = true;
        iTemp = 10;
        SendEventToNearClient_TypeA(iClientH, DEF_OWNERTYPE_PLAYER,
                                    MSGID_EVENT_MOTION, DEF_OBJECTMAGIC, dX,
                                    iTemp, 0);
        m_pClientList[iClientH]->m_iSpellCount++;
        bCheckClientMagicFrequency(iClientH, dwClientTime);
      } else if (m_pClientList[iClientH]->m_bMagicPauseTime) {
        try {
          wsprintf(
              G_cTxt,
              "Cast Delay Hack: (%s) Player: (%s) - player casting too fast.",
              m_pClientList[iClientH]->m_cIPaddress,
              m_pClientList[iClientH]->m_cCharName);
          PutHackLogFileList(G_cTxt);
          DeleteClient(iClientH, true, true);
        } catch (...) {
        }
      }
    } else if (iRet == 2)
      SendObjectMotionRejectMsg(iClientH);
    break;

  default:
    break;
  }
}

