void CGame::JoinGuildApproveHandler(int iClientH, char *pName) {
  int i;
  bool bIsExist = false;

  if (m_pClientList[iClientH] == 0)
    return;
  if (m_pClientList[iClientH]->m_bIsInitComplete == false)
    return;

  // pName脌禄 掳庐麓脗 脜卢露贸脌脤戮冒脝庐脌脟 iClientH 卤忙碌氓驴隆 麓毛脟脩
  // 掳隆脌脭驴盲卤赂掳隆 录潞掳酶脟脧驴麓麓脵.

  // pName脌脟 脌脤赂搂脌禄 掳庐麓脗 脜卢露贸脌脤戮冒脝庐 卤赂脕露脙录赂娄
  // 掳脣禄枚脟脩麓脵.
  for (i = 1; i < DEF_MAXCLIENTS; i++)
    if ((m_pClientList[i] != 0) &&
        (memcmp(m_pClientList[i]->m_cCharName, pName, 10) == 0)) {
      // v1.4 录脪录脫 赂露脌禄脌脤 麓脼露贸碌碌 鹿芦陆脙碌脠麓脵.
      if (memcmp(m_pClientList[i]->m_cLocation,
                 m_pClientList[iClientH]->m_cLocation, 10) != 0)
        return;

      // 卤忙碌氓脌脟 脌脤赂搂脌禄 潞鹿禄莽脟脧掳铆 录枚脛隆赂娄
      // 脙脢卤芒脠颅脟脴 脕脴麓脵.
      ZeroMemory(m_pClientList[i]->m_cGuildName,
                 sizeof(m_pClientList[i]->m_cGuildName));
      strcpy(m_pClientList[i]->m_cGuildName,
             m_pClientList[iClientH]->m_cGuildName);

      // 卤忙碌氓 GUID潞鹿禄莽脟脩麓脵.
      m_pClientList[i]->m_iGuildGUID = m_pClientList[iClientH]->m_iGuildGUID;

      // 卤忙碌氓脌脟 禄媒录潞脌搂脛隆赂娄 脙脢卤芒脠颅脟脩麓脵.
      ZeroMemory(m_pClientList[i]->m_cLocation,
                 sizeof(m_pClientList[i]->m_cLocation));
      strcpy(m_pClientList[i]->m_cLocation,
             m_pClientList[iClientH]->m_cLocation);

      m_pClientList[i]->m_iGuildRank =
          DEF_GUILDSTARTRANK; //@@@  GuildRank脌脟 陆脙脌脹脌潞
                              // DEF_GUILDSTARTRANK

      // 掳隆脌脭 陆脜脙禄脌脷驴隆掳脭 掳隆脌脭脌脤 录潞掳酶脟脽脌陆脌禄
      // 戮脣赂庐麓脗 赂脼陆脙脕枚赂娄 潞赂鲁禄脕脴麓脵.
      SendNotifyMsg(iClientH, i, DEF_COMMONTYPE_JOINGUILDAPPROVE, 0, 0, 0, 0);

      // 脝炉录潞脌脤 鹿脵虏卯鹿脟路脦 驴脺戮莽脌禄 禄玫路脦 潞赂鲁陆麓脵.
      SendEventToNearClient_TypeA(iClientH, DEF_OWNERTYPE_PLAYER,
                                  MSGID_EVENT_MOTION, DEF_OBJECTNULLACTION, 0,
                                  0, 0);

      // 麓脵赂楼 卤忙碌氓驴酶碌茅驴隆掳脭 禄玫 卤忙碌氓驴酶脌脤 脌脰脌陆脌禄
      // 戮脣赂掳麓脵.
      SendGuildMsg(i, DEF_NOTIFY_NEWGUILDSMAN, 0, 0, 0);

      // 卤忙碌氓脕陇潞赂脠颅脌脧驴隆 禄玫 卤忙碌氓驴酶脌脟 脌脤赂搂脌禄
      // 卤芒路脧脟脩麓脵.
      // bSendMsgToLS(MSGID_REQUEST_UPDATEGUILDINFO_NEWGUILDSMAN, i);
      return;
    }

  // 掳隆脌脭脌禄 陆脜脙禄脟脩 脜卢露贸脌脤戮冒脝庐赂娄 脙拢脌禄录枚
  // 戮酶麓脵.(脕垄录脫脌脤 卤脳禄莽脌脤 虏梅掳氓麓脵麓酶脕枚) 鹿芦脠驴脌脫
}

void CGame::JoinGuildRejectHandler(int iClientH, char *pName) {
  int i;

  if (m_pClientList[iClientH] == 0)
    return;
  if (m_pClientList[iClientH]->m_bIsInitComplete == false)
    return;

  // pName脌禄 掳庐麓脗 脜卢露贸脌脤戮冒脝庐脌脟 iClientH 卤忙碌氓驴隆 麓毛脟脩
  // 掳隆脌脭 驴盲卤赂掳隆 陆脟脝脨 脟脧驴麓麓脵.

  // pName脌脟 脌脤赂搂脌禄 掳庐麓脗 脜卢露贸脌脤戮冒脝庐 卤赂脕露脙录赂娄
  // 掳脣禄枚脟脩麓脵.
  for (i = 1; i < DEF_MAXCLIENTS; i++)
    if ((m_pClientList[i] != 0) &&
        (memcmp(m_pClientList[i]->m_cCharName, pName, 10) == 0)) {

      // 掳隆脌脭 陆脜脙禄脌脷驴隆掳脭 掳隆脌脭脌脤 陆脟脝脨脟脽脌陆脌禄
      // 戮脣赂庐麓脗 赂脼陆脙脕枚赂娄 潞赂鲁禄脕脴麓脵.
      SendNotifyMsg(iClientH, i, DEF_COMMONTYPE_JOINGUILDREJECT, 0, 0, 0, 0);
      return;
    }

  // 掳隆脌脭脌禄 陆脜脙禄脟脩 脜卢露贸脌脤戮冒脝庐赂娄 脙拢脌禄录枚
  // 戮酶麓脵.(脕垄录脫脌脤 卤脳禄莽脌脤 虏梅掳氓麓脵麓酶脕枚) 鹿芦脠驴脌脫
}

void CGame::DismissGuildApproveHandler(int iClientH, char *pName) {
  int i;

  if (m_pClientList[iClientH] == 0)
    return;
  if (m_pClientList[iClientH]->m_bIsInitComplete == false)
    return;
  for (i = 1; i < DEF_MAXCLIENTS; i++)
    if ((m_pClientList[i] != 0) &&
        (memcmp(m_pClientList[i]->m_cCharName, pName, 10) == 0)) {

      // bSendMsgToLS(MSGID_REQUEST_UPDATEGUILDINFO_DELGUILDSMAN, i);
      //_bItemLog(DEF_ITEMLOG_BANGUILD,i,(char *)0,0) ;
      SendGuildMsg(i, DEF_NOTIFY_DISMISSGUILDSMAN, 0, 0, 0);

      ZeroMemory(m_pClientList[i]->m_cGuildName,
                 sizeof(m_pClientList[i]->m_cGuildName));
      strcpy(m_pClientList[i]->m_cGuildName, "NONE");
      m_pClientList[i]->m_iGuildRank = -1;
      m_pClientList[i]->m_iGuildGUID = -1;

      SendNotifyMsg(iClientH, i, DEF_COMMONTYPE_DISMISSGUILDAPPROVE, 0, 0, 0,
                    0);

      SendEventToNearClient_TypeA(iClientH, DEF_OWNERTYPE_PLAYER,
                                  MSGID_EVENT_MOTION, DEF_OBJECTNULLACTION, 0,
                                  0, 0);
      return;
    }
}

