  case DEF_EQUIPPOS_RELEASEALL:
    sTemp = m_pClientList[iClientH]->m_sAppr3;
    sTemp = sTemp & 0x0FFF; // 赂脕脜盲 脝炉录潞脛隆 潞帽脝庐赂娄 脜卢赂庐戮卯.
