void CGame::TimeManaPointsUp(int iClientH) {
  int iMaxMP, iTotal;
  double dV1, dV2, dV3;

  if (m_pClientList[iClientH] == 0)
    return;
  if (m_pClientList[iClientH]->m_bIsKilled)
    return;
  if (m_pClientList[iClientH]->m_bIsInitComplete == false)
    return;
  if (m_pClientList[iClientH]->m_iHungerStatus <= 0)
    return;
  if (m_pClientList[iClientH]->m_bSkillUsingStatus[19])
    return;

  iMaxMP = iGetMaxMP(iClientH); // v1.4
  if (m_pClientList[iClientH]->m_iMP < iMaxMP) {
    iTotal = iDice(1, (m_pClientList[iClientH]->m_iMag +
                       m_pClientList[iClientH]->m_iAngelicMag));
    if (m_pClientList[iClientH]->m_iAddMP != 0) {
      dV2 = (double)iTotal;
      dV3 = (double)m_pClientList[iClientH]->m_iAddMP;
      dV1 = (dV3 / 100.0f) * dV2;
      iTotal += (int)dV1;
    }

    m_pClientList[iClientH]->m_iMP += iTotal;

    if (m_pClientList[iClientH]->m_iMP > iMaxMP)
      m_pClientList[iClientH]->m_iMP = iMaxMP;

    SendNotifyMsg(0, iClientH, DEF_NOTIFY_MP, 0, 0, 0, 0);
  }
}

// 05/29/2004 - Hypnotoad - fixed infinite sp bug
void CGame::TimeStaminarPointsUp(int iClientH) {
  int iMaxSP, iTotal = 0;
  double dV1, dV2, dV3;

  if (m_pClientList[iClientH] == 0)
    return;
  if (m_pClientList[iClientH]->m_bIsKilled)
    return;
  if (m_pClientList[iClientH]->m_bIsInitComplete == false)
    return;
  if (m_pClientList[iClientH]->m_iHungerStatus <= 0)
    return;
  if (m_pClientList[iClientH]->m_bSkillUsingStatus[19])
    return; // v1.4 脙聛脙鈥斆冣偓脗潞脙茠脗麓脙鈥∶兟徝偮泵兟� 脗卤脙垄脗录脙潞
            // 脗禄脙搂脗驴脙芦脙聛脙鸥脗驴脗隆脗麓脙鈥�
            // 脗陆脗潞脙鈥γ冣€斆偮姑兣捗偮趁兣� 脗驴脙鈧�偮该偮Ｃ兟伱兟�
            // 脗戮脙艩脙鈧�偮�.

  iMaxSP = iGetMaxSP(iClientH);
  if (m_pClientList[iClientH]->m_iSP < iMaxSP) {

    iTotal = iDice(1, (m_pClientList[iClientH]->m_iVit /
                       3)); // Staminar Point麓脗 10脙脢赂露麓脵 1D(Vit/3)戮驴
                            // 驴脙露贸掳拢麓脵.
    if (m_pClientList[iClientH]->m_iAddSP != 0) {
      dV2 = (double)iTotal;
      dV3 = (double)m_pClientList[iClientH]->m_iAddSP;
      dV1 = (dV3 / 100.0f) * dV2;
      iTotal += (int)dV1;
    }

    // v2.03 路鹿潞搂 60 脌脤脟脧麓脗 脕陇卤芒脌没脌赂路脦 陆潞脜脳鹿脤鲁陋掳隆
    // 赂鹿脌脤 脗霉麓脵.
    if (m_pClientList[iClientH]->m_iLevel <= 20) {
      iTotal += 15;
    } else if (m_pClientList[iClientH]->m_iLevel <= 40) {
      iTotal += 10;
    } else if (m_pClientList[iClientH]->m_iLevel <= 60) {
      iTotal += 5;
    }

    m_pClientList[iClientH]->m_iSP += iTotal;
    if (m_pClientList[iClientH]->m_iSP > iMaxSP)
      m_pClientList[iClientH]->m_iSP = iMaxSP;

    SendNotifyMsg(0, iClientH, DEF_NOTIFY_SP, 0, 0, 0, 0);
  }
}

void CGame::DelayEventProcess() {}

void CGame::SendGuildMsg(int iClientH, WORD wNotifyMsgType, short sV1,
                         short sV2, char *pString) {
  char cData[500];
  DWORD *dwp;
  WORD *wp;
  char *cp;
  int i, iRet;

  // 掳掳脌潞 卤忙碌氓驴酶碌茅驴隆掳脭赂赂 潞赂鲁禄麓脗 赂脼陆脙脕枚碌茅
  if (m_pClientList[iClientH] == 0)
    return;
  if (m_pClientList[iClientH]->m_bIsInitComplete == false)
    return;

  for (i = 0; i < DEF_MAXCLIENTS; i++)
    if ((m_pClientList[i] != 0) &&
        (memcmp(m_pClientList[i]->m_cGuildName,
                m_pClientList[iClientH]->m_cGuildName, 20) == 0)) {

      // ### BUG POINT 脌搂脛隆掳隆 脌脽赂酶碌脟戮卯 脝梅脌脦脜脥 驴卢禄锚脌脤
      // 脌脽赂酶碌脟戮煤麓脵.
      ZeroMemory(cData, sizeof(cData));

      dwp = (DWORD *)(cData + DEF_INDEX4_MSGID);
      *dwp = MSGID_NOTIFY;
      wp = (WORD *)(cData + DEF_INDEX2_MSGTYPE);
      *wp = wNotifyMsgType;

      cp = (char *)(cData + DEF_INDEX2_MSGTYPE + 2);

      // 掳掳脌潞 卤忙碌氓 脌脤赂搂脌禄 掳庐掳铆 脌脰麓脗
      // 脜卢露贸脌脤戮冒脝庐赂娄 脙拢戮脪麓脵.
      switch (wNotifyMsgType) {
      case DEF_NOTIFY_GUILDDISBANDED:
        if (i == iClientH)
          break; // <-- 卤忙碌氓 赂露陆潞脜脥 脌脷陆脜驴隆掳脭麓脗
                 // 赂脼陆脙脕枚赂娄 潞赂鲁禄脕枚 戮脢麓脗麓脵.
        // 卤忙碌氓 脟脴禄锚 脜毛潞赂驴隆 脟脴麓莽 脜卢露贸脌脤戮冒脝庐脌脟
        // 卤忙碌氓 路漏脜漏赂娄 脜卢赂庐戮卯脟脩麓脵.
        memcpy(cp, m_pClientList[iClientH]->m_cGuildName, 20);
        cp += 20;

        iRet = m_pClientList[i]->m_pXSock->iSendMsg(cData, 26);
        // 脟脴麓莽 脜卢露贸脌脤戮冒脝庐脌脟 卤忙碌氓鲁禄驴毛脌禄
        // 脜卢赂庐戮卯脟脩麓脵. @@@@@@@
        ZeroMemory(m_pClientList[i]->m_cGuildName,
                   sizeof(m_pClientList[i]->m_cGuildName));
        strcpy(m_pClientList[i]->m_cGuildName, "NONE");
        m_pClientList[i]->m_iGuildRank = -1;
        m_pClientList[i]->m_iGuildGUID = -1;
        break;

      case DEF_NOTIFY_EVENTMSGSTRING:
        // 卤忙碌氓驴酶碌茅驴隆掳脭 脌眉麓脼碌脟麓脗 脌脤潞楼脝庐 赂脼陆脙脕枚
        // 陆潞脝庐赂碌
        strcpy(cp, pString);
        cp += strlen(pString);

        iRet = m_pClientList[i]->m_pXSock->iSendMsg(cData,
                                                    6 + strlen(pString) + 1);
        break;

      case DEF_NOTIFY_NEWGUILDSMAN:
        memcpy(cp, m_pClientList[iClientH]->m_cCharName, 10);
        cp += 10;

        iRet = m_pClientList[i]->m_pXSock->iSendMsg(cData, 6 + 10 + 1);
        break;

      case DEF_NOTIFY_DISMISSGUILDSMAN:
        memcpy(cp, m_pClientList[iClientH]->m_cCharName, 10);
        cp += 10;

        iRet = m_pClientList[i]->m_pXSock->iSendMsg(cData, 6 + 10 + 1);
        break;
      }

      switch (iRet) {
      case DEF_XSOCKEVENT_QUENEFULL:
      case DEF_XSOCKEVENT_SOCKETERROR:
      case DEF_XSOCKEVENT_CRITICALERROR:
      case DEF_XSOCKEVENT_SOCKETCLOSED:
        // 赂脼陆脙脕枚赂娄 潞赂鲁戮露搂 驴隆路炉掳隆 鹿脽禄媒脟脽麓脵赂茅
        // 脕娄掳脜脟脩麓脵.
        DeleteClient(i, true, true);
        return;
      }
    }
}

void CGame::GuildNotifyHandler(char *pData, DWORD dwMsgSize) {
  // 麓脵赂楼 掳脭脌脫录颅鹿枚路脦潞脦脜脥 卤忙碌氓 脌脤潞楼脝庐掳隆
  // 碌碌脗酶脟脽麓脵.
  char *cp, cCharName[11], cGuildName[21];

  ZeroMemory(cCharName, sizeof(cCharName));
  ZeroMemory(cGuildName, sizeof(cGuildName));

  cp = (char *)(pData + DEF_INDEX2_MSGTYPE + 2);

  memcpy(cCharName, cp, 10);
  cp += 10;

  memcpy(cGuildName, cp, 20);
  cp += 20;

  // 戮脝脕梅 卤赂脟枚碌脟脕枚 戮脢戮脪麓脵.
}

void CGame::ToggleCombatModeHandler(int iClientH) {
  short sAppr2;

  if (m_pClientList[iClientH] == 0)
    return;
  if (m_pClientList[iClientH]->m_bIsInitComplete == false)
    return;
  if (m_pClientList[iClientH]->m_bIsKilled)
    return;
  // 脕脳脌潞脙麓脟脧卤芒鲁陋 脕脳脌潞 禄贸脜脗驴隆录颅麓脗 潞炉脠炉脟脪 录枚
  // 戮酶麓脵.
  if (m_pClientList[iClientH]->m_bSkillUsingStatus[19])
    return;

  sAppr2 = (short)((m_pClientList[iClientH]->m_sAppr2 & 0xF000) >> 12);

  m_pClientList[iClientH]->m_bIsAttackModeChange = true; // v2.172

  if (sAppr2 == 0) {
    // 潞帽脌眉脜玫 赂冒碌氓驴麓麓脵. 脌眉脜玫赂冒碌氓路脦 鹿脵虏脹麓脵.
    m_pClientList[iClientH]->m_sAppr2 =
        (0xF000 | m_pClientList[iClientH]->m_sAppr2);
  } else {
    // 脌眉脜玫 赂冒碌氓驴麓麓脵. 潞帽脌眉脜玫赂冒碌氓路脦 鹿脵虏脹麓脵.
    m_pClientList[iClientH]->m_sAppr2 =
        (0x0FFF & m_pClientList[iClientH]->m_sAppr2);
  }

  // 脛鲁赂炉脜脥脌脟 驴脺脟眉脌脤 鹿脵虏卯戮煤脌赂鹿脟路脦 脌脤潞楼脝庐赂娄
  // 脌眉麓脼脟脩麓脵.
  SendEventToNearClient_TypeA(iClientH, DEF_OWNERTYPE_PLAYER,
                              MSGID_EVENT_MOTION, DEF_OBJECTNULLACTION, 0, 0,
                              0);
}

