DWORD CGame::iGetLevelExp(int iLevel) {
  DWORD iRet;

  if (iLevel == 0)
    return 0;

  iRet = iGetLevelExp(iLevel - 1) +
         iLevel * (50 + (iLevel * (iLevel / 17) * (iLevel / 17)));

  return iRet;
}

int CGame::_iCalcSkillSSNpoint(int iLevel) {
  int iRet;

  if (iLevel < 1)
    return 1;

  if (iLevel <= 50)
    iRet = iLevel;
  else if (iLevel > 50) {
    iRet = (iLevel * 2);
  }

  return iRet;
}

/*****************************************************************
**---------------------------FUNCTION---------------------------**
**             void Game::CheckLevelUp(int iClientH)            **
**-------------------------DESCRIPTION--------------------------**
** Level-Up                                                     **
**  - Level +1                                                  **
**  - +3 Level Up Points                                        **
**  - Reset Next Level EXP                                      **
**  - Civilian Level Limit                                      **
**      Player mode switches to Combatant                       **
**      when the limit is reached                               **
**  - Majestic Points +1                                        **
**  - Reset Next Level EXP                                      **
**------------------------CREATION DATE-------------------------**
**                January 30, 2007; 3:06 PM; Dax                **
*****************************************************************/
bool CGame::bCheckLevelUp(int iClientH) {

  if (m_pClientList[iClientH] == 0)
    return false;
  if (m_pClientList[iClientH]->m_iAdminUserLevel > 0)
    return false;

  while (m_pClientList[iClientH]->m_iExp >=
         m_pClientList[iClientH]->m_iNextLevelExp) {
    if (m_pClientList[iClientH]->m_iLevel < m_iPlayerMaxLevel) {
      // 路鹿潞搂脌脤 驴脙露煤麓脵.
      m_pClientList[iClientH]->m_iLevel++;
      m_pClientList[iClientH]->m_iLU_Pool += 3;
      // 路鹿潞搂脌脤 驴脌赂楼掳脥驴隆 麓毛脟脩 脝炉录潞脛隆 脝梅脌脦脝庐赂娄
      // 脕玫掳隆陆脙脛脩戮脽 脟脩麓脵.
      //			if ( (m_pClientList[iClientH]->m_cLU_Str +
      // m_pClientList[iClientH]->m_cLU_Vit + m_pClientList[iClientH]->m_cLU_Dex
      //+ 	  		      m_pClientList[iClientH]->m_cLU_Int +
      // m_pClientList[iClientH]->m_cLU_Mag +
      // m_pClientList[iClientH]->m_cLU_Char) <= DEF_TOTALLEVELUPPOINT) {
      // 路鹿潞搂 戮梅 录录脝脙脌脤 3潞赂麓脵 掳掳掳脜鲁陋 脌脹戮脝戮脽
      // 脌炉脠驴脟脧麓脵.

      //			}

      // 录鲁脕陇脛隆赂娄 脠庐脌脦脟脩麓脵.
      if (m_pClientList[iClientH]->m_iStr > DEF_CHARPOINTLIMIT)
        m_pClientList[iClientH]->m_iStr = DEF_CHARPOINTLIMIT;
      if (m_pClientList[iClientH]->m_iDex > DEF_CHARPOINTLIMIT)
        m_pClientList[iClientH]->m_iDex = DEF_CHARPOINTLIMIT;
      if (m_pClientList[iClientH]->m_iVit > DEF_CHARPOINTLIMIT)
        m_pClientList[iClientH]->m_iVit = DEF_CHARPOINTLIMIT;
      if (m_pClientList[iClientH]->m_iInt > DEF_CHARPOINTLIMIT)
        m_pClientList[iClientH]->m_iInt = DEF_CHARPOINTLIMIT;
      if (m_pClientList[iClientH]->m_iMag > DEF_CHARPOINTLIMIT)
        m_pClientList[iClientH]->m_iMag = DEF_CHARPOINTLIMIT;
      if (m_pClientList[iClientH]->m_iCharisma > DEF_CHARPOINTLIMIT)
        m_pClientList[iClientH]->m_iCharisma = DEF_CHARPOINTLIMIT;

      // New 17/05/2004
      if (m_pClientList[iClientH]->m_iLevel > 100)
        if (m_pClientList[iClientH]->m_bIsPlayerCivil)
          ForceChangePlayMode(iClientH, true);

      // centu - max hp,mp,sp when level up
      m_pClientList[iClientH]->m_iHP = iGetMaxHP(iClientH);
      m_pClientList[iClientH]->m_iMP = iGetMaxMP(iClientH);
      m_pClientList[iClientH]->m_iSP = iGetMaxSP(iClientH);
      SendNotifyMsg(0, iClientH, DEF_NOTIFY_HP, 0, 0, 0, 0);
      SendNotifyMsg(0, iClientH, DEF_NOTIFY_MP, 0, 0, 0, 0);
      SendNotifyMsg(0, iClientH, DEF_NOTIFY_SP, 0, 0, 0, 0);

      // 路鹿潞搂脌脤 驴脌赂楼掳脥脌禄 脜毛潞赂脟脩麓脵.
      SendNotifyMsg(0, iClientH, DEF_NOTIFY_LEVELUP, 0, 0, 0, 0);

      // 麓脵脌陆 路鹿潞搂路脦脌脟 掳忙脟猫脛隆掳陋 掳猫禄锚, 脟脪麓莽.
      m_pClientList[iClientH]->m_iNextLevelExp =
          m_iLevelExpTable[m_pClientList[iClientH]->m_iLevel +
                           1]; // iGetLevelExp(m_pClientList[iClientH]->m_iLevel
                               // + 1);

      // 脝炉录潞脛隆 脌莽 掳猫禄锚.
      CalcTotalItemEffect(iClientH, -1, false);

      // v1.4 麓脵脌陆 路鹿潞搂
      // wsprintf(G_cTxt, "(!) Level up: Player (%s) Level (%d) Experience(%d)
      // Next Level Experience(%d)",
      // m_pClientList[iClientH]->m_cCharName,m_pClientList[iClientH]->m_iLevel,
      // m_pClientList[iClientH]->m_iExp,
      // m_pClientList[iClientH]->m_iNextLevelExp); PutLogFileList(G_cTxt);
    } else {
      m_pClientList[iClientH]->m_iGizonItemUpgradeLeft++;

      m_pClientList[iClientH]->m_iNextLevelExp =
          m_iLevelExpTable[m_iPlayerMaxLevel + 1];
      m_pClientList[iClientH]->m_iExp = m_iLevelExpTable[m_iPlayerMaxLevel];
      // addon
      SendNotifyMsg(0, iClientH, DEF_NOTIFY_GIZONITEMUPGRADELEFT,
                    m_pClientList[iClientH]->m_iGizonItemUpgradeLeft, 1, 0, 0);
    }

    SendNotifyMsg(0, iClientH, DEF_NOTIFY_EXP, 0, 0, 0, 0);
  }

  return false;
}
// 2003-04-14 脕枚脕赂 脝梅脌脦脝庐赂娄 路鹿潞搂 录枚脕陇驴隆 戮碌录枚
// 脌脰麓脵...
/////////////////////////////////////////////////////////////////////////////////////
//  StateChangeHandler(int iClientH, char * pData, DWORD dwMsgSize)
//  desc		 :: 脕枚脕赂脝梅脌脦脝庐赂娄 路鹿潞搂戮梅
//  脝梅脌脦脝庐路脦 碌鹿赂掳麓脵...
//	return value :: void
//  date		 :: [2003-04-14]    stupid koreans
/////////////////////////////////////////////////////////////////////////////////////
void CGame::StateChangeHandler(int iClientH, char *pData, DWORD dwMsgSize) {
  char *cp, cStateChange1, cStateChange2, cStateChange3;
  char cStr, cVit, cDex, cInt, cMag, cChar;
  char cStateTxt[512];
  int iOldStr, iOldVit, iOldDex, iOldInt, iOldMag, iOldChar;
  int iTotalSetting = 0;

  if (m_pClientList[iClientH] == 0)
    return;
  if (m_pClientList[iClientH]->m_bIsInitComplete == false)
    return;
  if (m_pClientList[iClientH]->m_iGizonItemUpgradeLeft <= 0)
    return;

  cStr = cVit = cDex = cInt = cMag = cChar = 0;

  cp = (char *)(pData + DEF_INDEX2_MSGTYPE + 2);

  cStateChange1 = *cp;
  cp++;

  cStateChange2 = *cp;
  cp++;

  cStateChange3 = *cp;
  cp++;

  iOldStr = m_pClientList[iClientH]->m_iStr;
  iOldVit = m_pClientList[iClientH]->m_iVit;
  iOldDex = m_pClientList[iClientH]->m_iDex;
  iOldInt = m_pClientList[iClientH]->m_iInt;
  iOldMag = m_pClientList[iClientH]->m_iMag;
  iOldChar = m_pClientList[iClientH]->m_iCharisma;

  try {
    wsprintf(
        G_cTxt, "(*) Char(%s) Str(%d) Vit(%d) Dex(%d) Int(%d) Mag(%d) Chr(%d) ",
        m_pClientList[iClientH]->m_cCharName, m_pClientList[iClientH]->m_iStr,
        m_pClientList[iClientH]->m_iVit, m_pClientList[iClientH]->m_iDex,
        m_pClientList[iClientH]->m_iInt, m_pClientList[iClientH]->m_iMag,
        m_pClientList[iClientH]->m_iCharisma);
    PutLogList(G_cTxt);
  } catch (...) {
  }

  if (!bChangeState(cStateChange1, &cStr, &cVit, &cDex, &cInt, &cMag, &cChar)) {
    // 脜卢露贸脌脤戮冒脝庐驴隆录颅 掳陋脌禄 脌脽赂酶 潞赂鲁禄驴脗碌铆...
    SendNotifyMsg(0, iClientH, DEF_NOTIFY_STATECHANGE_FAILED, 0, 0, 0, 0);
    return;
  }
  if (!bChangeState(cStateChange2, &cStr, &cVit, &cDex, &cInt, &cMag, &cChar)) {
    // 脜卢露贸脌脤戮冒脝庐驴隆录颅 掳陋脌禄 脌脽赂酶 潞赂鲁禄驴脗碌铆...
    SendNotifyMsg(0, iClientH, DEF_NOTIFY_STATECHANGE_FAILED, 0, 0, 0, 0);
    return;
  }
  if (!bChangeState(cStateChange3, &cStr, &cVit, &cDex, &cInt, &cMag, &cChar)) {
    // 脜卢露贸脌脤戮冒脝庐驴隆录颅 掳陋脌禄 脌脽赂酶 潞赂鲁禄驴脗碌铆...
    SendNotifyMsg(0, iClientH, DEF_NOTIFY_STATECHANGE_FAILED, 0, 0, 0, 0);
    return;
  }

  try {
    wsprintf(G_cTxt,
             "(*) Char(%s) St1(%d) St2(%d) St3(%d) Str(%d) Vit(%d) Dex(%d) "
             "Int(%d) Mag(%d) Chr(%d) ",
             m_pClientList[iClientH]->m_cCharName, cStateChange1, cStateChange2,
             cStateChange3, cStr, cVit, cDex, cInt, cMag, cChar);
    PutLogList(G_cTxt);
  } catch (...) {
  }

  // 卤忙碌氓 赂露陆潞脜脥赂茅 cChar赂娄 赂酶 鲁禄赂掳麓脵..
  if (m_pClientList[iClientH]->m_iGuildRank == 0) {
    if (m_pClientList[iClientH]->m_iCharisma - cChar < 20) {
      // 脜卢露贸脌脤戮冒脝庐驴隆录颅 掳陋脌禄 脌脽赂酶 潞赂鲁禄驴脗碌铆...
      SendNotifyMsg(0, iClientH, DEF_NOTIFY_STATECHANGE_FAILED, 0, 0, 0, 0);
      return;
    }
  }

  // 脝炉录潞脛隆 掳陋脌脤 路鹿潞搂掳煤 赂脗脕枚 戮脢麓脵赂茅 鲁禄赂卤录枚
  // 戮酶麓脵..
  if (iOldStr + iOldVit + iOldDex + iOldInt + iOldMag + iOldChar !=
      (179 * 3 + 70)) {
    // 脟脴脜路脌脤麓脵... 脜卢露贸脌脤戮冒脝庐驴隆录颅 赂酶潞赂鲁禄掳脭
    // 碌脟戮卯 脌脰麓脵 卤脵碌楼 驴脭麓脵赂茅 脟脴脜路...
    return;
  }

  if (cStr < 0 || cVit < 0 || cDex < 0 || cInt < 0 || cMag < 0 || cChar < 0 ||
      cStr + cVit + cDex + cInt + cMag + cChar != 3) {
    SendNotifyMsg(0, iClientH, DEF_NOTIFY_STATECHANGE_FAILED, 0, 0, 0, 0);
    return;
  }

  // 脝炉录潞脛隆掳陋脌脤 10脌脤脟脧路脦 赂酶鲁禄路脕 掳拢麓脵... 脕娄脟脩脌禄
  // 鲁脩脌禄录枚碌碌 戮酶麓脵...
  if ((m_pClientList[iClientH]->m_iStr - cStr > DEF_CHARPOINTLIMIT) ||
      (m_pClientList[iClientH]->m_iStr - cStr < 10)) {
    SendNotifyMsg(0, iClientH, DEF_NOTIFY_STATECHANGE_FAILED, 0, 0, 0, 0);
    return;
  }

  if ((m_pClientList[iClientH]->m_iDex - cDex > DEF_CHARPOINTLIMIT) ||
      (m_pClientList[iClientH]->m_iDex - cDex < 10)) {
    SendNotifyMsg(0, iClientH, DEF_NOTIFY_STATECHANGE_FAILED, 0, 0, 0, 0);
    return;
  }

  if ((m_pClientList[iClientH]->m_iInt - cInt > DEF_CHARPOINTLIMIT) ||
      (m_pClientList[iClientH]->m_iInt - cInt < 10)) {
    SendNotifyMsg(0, iClientH, DEF_NOTIFY_STATECHANGE_FAILED, 0, 0, 0, 0);
    return;
  }

  if ((m_pClientList[iClientH]->m_iVit - cVit > DEF_CHARPOINTLIMIT) ||
      (m_pClientList[iClientH]->m_iVit - cVit < 10)) {
    SendNotifyMsg(0, iClientH, DEF_NOTIFY_STATECHANGE_FAILED, 0, 0, 0, 0);
    return;
  }

  if ((m_pClientList[iClientH]->m_iMag - cMag > DEF_CHARPOINTLIMIT) ||
      (m_pClientList[iClientH]->m_iMag - cMag < 10)) {
    SendNotifyMsg(0, iClientH, DEF_NOTIFY_STATECHANGE_FAILED, 0, 0, 0, 0);
    return;
  }

  if ((m_pClientList[iClientH]->m_iCharisma - cChar > DEF_CHARPOINTLIMIT) ||
      (m_pClientList[iClientH]->m_iCharisma - cChar < 10)) {
    SendNotifyMsg(0, iClientH, DEF_NOTIFY_STATECHANGE_FAILED, 0, 0, 0, 0);
    return;
  }

  if (m_pClientList[iClientH]->m_iLU_Pool < 3)
    m_pClientList[iClientH]->m_iLU_Pool = 3;

  // 驴脌路霉掳隆 戮酶脌赂赂茅 掳陋脌禄 脟脪麓莽脟脩麓脵.
  // m_pClientList[iClientH]->m_iLU_Pool += 3;

  m_pClientList[iClientH]->m_iGizonItemUpgradeLeft--;

  // HBest uuendus, hp,mp,sp lowering, skillcheck
  m_pClientList[iClientH]->m_iHP -= (cStr + 3 * cVit);
  m_pClientList[iClientH]->m_iMP -= (cInt + 2 * cMag);
  m_pClientList[iClientH]->m_iSP -= (2 * cStr);
  m_pClientList[iClientH]->m_iStr -= cStr;
  m_pClientList[iClientH]->m_iVit -= cVit;
  m_pClientList[iClientH]->m_iDex -= cDex;
  m_pClientList[iClientH]->m_iInt -= cInt;
  // 2003-04-22脌脧 赂露鹿媒脌禄 禄猫脕娄 陆脙脜虏麓脵.... 脌脦脝庐掳隆
  // 鲁禄路脕掳隆掳铆 鲁陋录颅 碌鹿戮脝掳隆戮脽 脟脩麓脵...
  if (cInt > 0)
    bCheckMagicInt(iClientH);
  m_pClientList[iClientH]->m_iMag -= cMag;
  m_pClientList[iClientH]->m_iCharisma -= cChar;
  // SkillCheck(iClientH);

  try {
    ZeroMemory(cStateTxt, sizeof(cStateTxt));

    wsprintf(cStateTxt,
             "STR(%d->%d)VIT(%d->%d)DEX(%d->%d)INT(%d->%d)MAG(%d->%d)CHARISMA(%"
             "d->%d)",
             iOldStr, m_pClientList[iClientH]->m_iStr, iOldVit,
             m_pClientList[iClientH]->m_iVit, iOldDex,
             m_pClientList[iClientH]->m_iDex, iOldInt,
             m_pClientList[iClientH]->m_iInt, iOldMag,
             m_pClientList[iClientH]->m_iMag, iOldChar,
             m_pClientList[iClientH]->m_iCharisma);
  } catch (...) {
  }

  //_bCustomLog(DEF_ITEMLOG_CUSTOM,iClientH,0,cStateTxt);

  // 2003-04-22脌脧 陆潞脜鲁脌禄 鲁禄路脕掳隆掳脭 脟脩麓脵...
  // bCheckSkillState(iClientH);

  // 录潞掳酶..!!!
  SendNotifyMsg(0, iClientH, DEF_NOTIFY_STATECHANGE_SUCCESS, 0, 0, 0, 0);
}

// 2003-04-21 脌脦脝庐驴隆 碌没赂楼 赂露鹿媒脌禄 禄猫脕娄 陆脙脛脩脕脴麓脵...
/////////////////////////////////////////////////////////////////////////////////////
//  bool CGame::bCheckMagicInt(int iClientH)  //another retarded korean function
//  desc		 :: 脌脦脝庐掳隆 鲁禄路脕掳卢脌禄露搂 禄猫脕娄脟脪
//  赂露鹿媒脌禄 脙鲁赂庐脟脩麓脵... 脙录脜漏赂赂...
//	return value :: 鹿芦脕露掳脟 true   // ....dumbass koreans
//  date		 :: 2003-04-21
/////////////////////////////////////////////////////////////////////////////////////
bool CGame::bCheckMagicInt(int iClientH) {

  for (int i = 0; i < DEF_MAXMAGICTYPE; i++) {
    if (m_pMagicConfigList[i] != 0)
      if (m_pMagicConfigList[i]->m_sIntLimit >
          (m_pClientList[iClientH]->m_iInt +
           m_pClientList[iClientH]->m_iAngelicInt)) {
        m_pClientList[iClientH]->m_cMagicMastery[i] = 0;
      }
  }

  return true;
}

// 2003-04-14 脕枚脕赂 脝梅脌脦脝庐赂娄 路鹿潞搂 录枚脕陇驴隆 戮碌录枚
// 脌脰麓脵...
/////////////////////////////////////////////////////////////////////////////////////
//  bChangeState(char cStateChange
//  		  ,char* cStr, char *cVit,char *cDex,char *cInt,char *cMag,char
//  *cChar) desc		 :: 脕枚脕赂 脝梅脌脦脝庐路脦 脝炉录潞掳陋
//  鹿脵虏脺茠鈥澝€禄 麓玫脟脴 脕脴麓脵...
//	return value :: BOOL脟眉 0(FASLE) 驴隆路炉 路鹿潞搂 录枚脕陇 潞脪掳隆...
//  date		 :: [2003-04-14]
/////////////////////////////////////////////////////////////////////////////////////
bool CGame::bChangeState(char cStateChange, char *cStr, char *cVit, char *cDex,
                         char *cInt, char *cMag, char *cChar) {
  if (cStateChange == DEF_STR) {
    *cStr += 1;
  } else if (cStateChange == DEF_VIT) {
    *cInt += 1;
    //		if(m_pClientList[iClientH]->m_iStr - cVit < 10 ||
    // m_pClientList[iClientH]->cVit - cVit < DEF_CHARPOINTLIMIT )
    // return 0;
  } else if (cStateChange == DEF_DEX) {
    *cVit += 1;
  } else if (cStateChange == DEF_INT) {
    *cDex += 1;
  } else if (cStateChange == DEF_MAG) {
    *cMag += 1;
  } else if (cStateChange == DEF_CHR) {
    *cChar += 1;
  } else {
    // 脜卢露贸脌脤戮冒脝庐掳隆 脌脽赂酶碌脠 掳陋脌禄 潞赂鲁禄 驴脭麓脵..
    //		::MessageBox(0, "脜卢露贸脌脤戮冒脝庐 鹿枚卤脳? -
    // 韥措澕鞚挫柛韸� 氩勱犯?","debug", MB_ICONEXCLAMATION | MB_YESNO) ;
    return 0;
  }

  return cStateChange;
}

void CGame::LevelUpSettingsHandler(int iClientH, char *pData, DWORD dwMsgSize) {
  char *cp;
  int iTotalSetting = 0;

  short *sp;
  short cStr, cVit, cDex, cInt, cMag, cChar;

  if (m_pClientList[iClientH] == 0)
    return;
  if (m_pClientList[iClientH]->m_bIsInitComplete == false)
    return;
  if (m_pClientList[iClientH]->m_iLU_Pool <= 0) {
    // 脟脴脛驴脌脦掳隆??
    SendNotifyMsg(0, iClientH, DEF_NOTIFY_SETTING_FAILED, 0, 0, 0, 0);
    return;
  }

  cp = (char *)(pData + DEF_INDEX2_MSGTYPE + 2);

  sp = (short *)cp;
  cStr = *sp;
  cp += 2;

  sp = (short *)cp;
  cVit = *sp;
  cp += 2;

  sp = (short *)cp;
  cDex = *sp;
  cp += 2;

  sp = (short *)cp;
  cInt = *sp;
  cp += 2;

  sp = (short *)cp;
  cMag = *sp;
  cp += 2;

  sp = (short *)cp;
  cChar = *sp;
  cp += 2;

  //	if(m_pClientList[iClientH]->m_iLU_Pool < 3) {
  //		m_pClientList[iClientH]->m_iLU_Pool = 3;
  //	}

  if ((cStr + cVit + cDex + cInt + cMag + cChar) >
      m_pClientList[iClientH]->m_iLU_Pool) { // -3
    SendNotifyMsg(0, iClientH, DEF_NOTIFY_SETTING_FAILED, 0, 0, 0, 0);
    return;
  }

  // Level-Up Setting掳陋驴隆 驴脌路霉掳隆 脌脰麓脗脕枚 掳脣禄莽脟脩麓脵.
  if ((m_pClientList[iClientH]->m_iStr + cStr > DEF_CHARPOINTLIMIT) ||
      (cStr < 0))
    return;

  if ((m_pClientList[iClientH]->m_iDex + cDex > DEF_CHARPOINTLIMIT) ||
      (cDex < 0))
    return;

  if ((m_pClientList[iClientH]->m_iInt + cInt > DEF_CHARPOINTLIMIT) ||
      (cInt < 0))
    return;

  if ((m_pClientList[iClientH]->m_iVit + cVit > DEF_CHARPOINTLIMIT) ||
      (cVit < 0))
    return;

  if ((m_pClientList[iClientH]->m_iMag + cMag > DEF_CHARPOINTLIMIT) ||
      (cMag < 0))
    return;

  if ((m_pClientList[iClientH]->m_iCharisma + cChar > DEF_CHARPOINTLIMIT) ||
      (cChar < 0))
    return;

  iTotalSetting =
      m_pClientList[iClientH]->m_iStr + m_pClientList[iClientH]->m_iDex +
      m_pClientList[iClientH]->m_iVit + m_pClientList[iClientH]->m_iInt +
      m_pClientList[iClientH]->m_iMag + m_pClientList[iClientH]->m_iCharisma;

  //(路鹿潞搂 脝炉录潞掳陋 + 路鹿潞搂戮梅 脝梅脌脦脝庐 > 路鹿潞搂戮梅
  // 脝炉录潞掳陋 脕陇禄贸脛隆)赂茅 潞帽脕陇禄贸脌脤麓脵.. 脙鲁赂庐 潞脪掳隆..
  // 路鹿潞搂戮梅 脝梅脌脦脝庐赂娄 脕陇禄贸脛隆路脦 赂露脙脽掳铆 脙鲁赂庐
  // 潞脪掳隆..
  if (iTotalSetting + m_pClientList[iClientH]->m_iLU_Pool - 3 >
      ((m_pClientList[iClientH]->m_iLevel - 1) * 3 + 70)) {

    m_pClientList[iClientH]->m_iLU_Pool =
        /*m_cLU_Str 脙脢卤芒掳陋*/ 3 +
        (m_pClientList[iClientH]->m_iLevel - 1) * 3 + 70 - iTotalSetting;

    // iTotalSetting掳陋脌脤 脌脽赂酶碌脠 掳忙驴矛麓脵...
    if (m_pClientList[iClientH]->m_iLU_Pool < 3)
      m_pClientList[iClientH]->m_iLU_Pool = 3;
    SendNotifyMsg(0, iClientH, DEF_NOTIFY_SETTING_FAILED, 0, 0, 0, 0);
    return;
  }

  //(路鹿潞搂 脝炉录潞掳陋 + 路鹿潞搂戮梅 陆脙脜鲁 脝梅脌脦脝庐 脕D >
  // 路鹿潞搂戮梅 脝炉录潞掳陋 脕陇禄贸脛隆)脌脤赂茅 脙鲁赂庐 潞脪掳隆..
  if (iTotalSetting + (cStr + cVit + cDex + cInt + cMag + cChar) >
      ((m_pClientList[iClientH]->m_iLevel - 1) * 3 + 70)) {
    SendNotifyMsg(0, iClientH, DEF_NOTIFY_SETTING_FAILED, 0, 0, 0, 0);
    return;
  }

  m_pClientList[iClientH]->m_iLU_Pool =
      m_pClientList[iClientH]->m_iLU_Pool -
      (cStr + cVit + cDex + cInt + cMag + cChar);

  m_pClientList[iClientH]->m_iStr += cStr;
  m_pClientList[iClientH]->m_iVit += cVit;
  m_pClientList[iClientH]->m_iDex += cDex;
  m_pClientList[iClientH]->m_iInt += cInt;
  m_pClientList[iClientH]->m_iMag += cMag;
  m_pClientList[iClientH]->m_iCharisma += cChar;

  SendNotifyMsg(0, iClientH, DEF_NOTIFY_SETTING_SUCCESS, 0, 0, 0, 0);
}

