/*********************************************************************************************************************
**  int bool CGame::bCheckResistingMagicSuccess(char cAttackerDir, short
* sTargetH, char cTargetType, int iHitRatio) **
**  description			:: calculates if a player resists magic
*												**
**  last updated		:: November 20, 2004; 8:42 PM; Hypnotoad
*												**
**	return value		:: bool
*																**
**  commentary			::	-	hero armor for target mages adds
* 50 magic resistance 	** *
*	-	10000 or more it ratio will deduct 10000 hit ratio
*							** *
*				-	invincible tablet is 100% magic
* resistance
*		**
**********************************************************************************************************************/
bool CGame::bCheckResistingMagicSuccess(char cAttackerDir, short sTargetH,
                                        char cTargetType, int iHitRatio) {
  double dTmp1, dTmp2, dTmp3;
  int iTargetMagicResistRatio, iDestHitRatio, iResult;
  char cTargetDir, cProtect;

  switch (cTargetType) {
  case DEF_OWNERTYPE_PLAYER:
    if (m_pClientList[sTargetH] == 0)
      return false;
    if (m_pMapList[m_pClientList[sTargetH]->m_cMapIndex]->m_bIsAttackEnabled ==
        false)
      return false;
    if (m_pClientList[sTargetH]->m_iAdminUserLevel > 0)
      return true;
    if ((m_pClientList[sTargetH]->m_iStatus & 0x400000) != 0)
      return true;
    cTargetDir = m_pClientList[sTargetH]->m_cDir;
    iTargetMagicResistRatio = m_pClientList[sTargetH]->m_cSkillMastery[3] +
                              m_pClientList[sTargetH]->m_iAddMR;
    if ((m_pClientList[sTargetH]->m_iMag +
         m_pClientList[sTargetH]->m_iAngelicMag) > 50)
      iTargetMagicResistRatio += ((m_pClientList[sTargetH]->m_iMag +
                                   m_pClientList[sTargetH]->m_iAngelicMag) -
                                  50);
    iTargetMagicResistRatio += m_pClientList[sTargetH]->m_iAddResistMagic;
    cProtect =
        m_pClientList[sTargetH]->m_cMagicEffectStatus[DEF_MAGICTYPE_PROTECT];
    break;

  case DEF_OWNERTYPE_NPC:
    if (m_pNpcList[sTargetH] == 0)
      return false;
    cTargetDir = m_pNpcList[sTargetH]->m_cDir;
    iTargetMagicResistRatio = m_pNpcList[sTargetH]->m_cResistMagic;
    cProtect =
        m_pNpcList[sTargetH]->m_cMagicEffectStatus[DEF_MAGICTYPE_PROTECT];
    break;
  }

  if (cProtect == 5)
    return true;

  if ((iHitRatio < 1000) && (cProtect == 2))
    return true;
  if (iHitRatio >= 10000)
    iHitRatio -= 10000;
  if (iTargetMagicResistRatio < 1)
    iTargetMagicResistRatio = 1;
  if ((cAttackerDir != 0) && (m_pClientList[sTargetH] != 0) &&
      (m_pClientList[sTargetH]->m_cHeroArmourBonus == 2)) {
    iHitRatio += 50;
  }

  dTmp1 = (double)(iHitRatio);
  dTmp2 = (double)(iTargetMagicResistRatio);
  dTmp3 = (dTmp1 / dTmp2) * 50.0f;
  iDestHitRatio = (int)(dTmp3);

  if (iDestHitRatio < DEF_MINIMUMHITRATIO)
    iDestHitRatio = DEF_MINIMUMHITRATIO;
  if (iDestHitRatio > DEF_MAXIMUMHITRATIO)
    iDestHitRatio = DEF_MAXIMUMHITRATIO;
  if (iDestHitRatio >= 100)
    return false;

  iResult = iDice(1, 100);
  if (iResult <= iDestHitRatio)
    return false;

  if (cTargetType == DEF_OWNERTYPE_PLAYER)
    CalculateSSN_SkillIndex(sTargetH, 3, 1);
  return true;
}

bool CGame::bCheckResistingIceSuccess(char cAttackerDir, short sTargetH,
                                      char cTargetType, int iHitRatio) {
  // 趁悼瞪 巴牢啊狼 犬伏 拌魂.
  int iTargetIceResistRatio, iResult;

  switch (cTargetType) {
  case DEF_OWNERTYPE_PLAYER:
    if (m_pClientList[sTargetH] == 0)
      return false;
    // v1.4 款康磊俊 措茄 趁悼傍拜篮 公狼固
    if (m_pClientList[sTargetH]->m_iAdminUserLevel > 0)
      return true;
    iTargetIceResistRatio = m_pClientList[sTargetH]->m_iAddAbsWater * 2;
    // v2.172 秦悼 器记阑 冈绊 30檬埃篮 倔瘤 臼绰促.
    if (m_pClientList[sTargetH]->m_dwWarmEffectTime == 0) {
    } else if ((timeGetTime() - m_pClientList[sTargetH]->m_dwWarmEffectTime) <
               1000 * 30)
      return true;
    break;

  case DEF_OWNERTYPE_NPC:
    if (m_pNpcList[sTargetH] == 0)
      return false;
    iTargetIceResistRatio =
        (m_pNpcList[sTargetH]->m_cResistMagic) -
        (m_pNpcList[sTargetH]->m_cResistMagic /
         3); // 咯扁俊 倔澜 规绢 荐摹 涝仿. NPC狼 版快 付过 历亲狼 70% 荐霖
    break;
  }

  if (iTargetIceResistRatio < 1)
    iTargetIceResistRatio = 1;

  iResult = iDice(1, 100);
  if (iResult <= iTargetIceResistRatio)
    return true;

  return false;
}

bool CGame::bSetItemToBankItem(int iClientH, class CItem *pItem) {
  int i, iRet;
  DWORD *dwp;
  WORD *wp;
  char *cp;
  short *sp;
  char cData[100];

  if (m_pClientList[iClientH] == 0)
    return false;
  if (pItem == 0)
    return false;
  // wh remove
  // if (m_pClientList[iClientH]->m_bIsInsideWarehouse == false) return false;

  for (i = 0; i < DEF_MAXBANKITEMS; i++)
    if (m_pClientList[iClientH]->m_pItemInBankList[i] == 0) {

      m_pClientList[iClientH]->m_pItemInBankList[i] = pItem;

      dwp = (DWORD *)(cData + DEF_INDEX4_MSGID);
      *dwp = MSGID_NOTIFY;
      wp = (WORD *)(cData + DEF_INDEX2_MSGTYPE);
      *wp = DEF_NOTIFY_ITEMTOBANK;

      cp = (char *)(cData + DEF_INDEX2_MSGTYPE + 2);

      *cp = i; // 脌搂脛隆 脌煤脌氓
      cp++;

      // 1掳鲁.
      *cp = 1;
      cp++;

      memcpy(cp, pItem->m_cName, 20);
      cp += 20;

      dwp = (DWORD *)cp;
      *dwp = pItem->m_dwCount;
      cp += 4;

      *cp = pItem->m_cItemType;
      cp++;

      *cp = pItem->m_cEquipPos;
      cp++;

      *cp = (char)0;
      cp++;

      sp = (short *)cp;
      *sp = pItem->m_sLevelLimit;
      cp += 2;

      *cp = pItem->m_cGenderLimit;
      cp++;

      wp = (WORD *)cp;
      *wp = pItem->m_wCurLifeSpan;
      cp += 2;

      wp = (WORD *)cp;
      *wp = pItem->m_wWeight;
      cp += 2;

      sp = (short *)cp;
      *sp = pItem->m_sSprite;
      cp += 2;

      sp = (short *)cp;
      *sp = pItem->m_sSpriteFrame;
      cp += 2;

      *cp = pItem->m_cItemColor;
      cp++;

      // v1.432
      sp = (short *)cp;
      *sp = pItem->m_sItemEffectValue2;
      cp += 2;

      // v1.42
      dwp = (DWORD *)cp;
      *dwp = pItem->m_dwAttribute;
      cp += 4;

      // 戮脝脌脤脜脹 脕陇潞赂 脌眉录脹
      iRet = m_pClientList[iClientH]->m_pXSock->iSendMsg(cData, 55);
      switch (iRet) {
      case DEF_XSOCKEVENT_QUENEFULL:
      case DEF_XSOCKEVENT_SOCKETERROR:
      case DEF_XSOCKEVENT_CRITICALERROR:
      case DEF_XSOCKEVENT_SOCKETCLOSED:
        // 赂脼陆脙脕枚赂娄 潞赂鲁戮露搂 驴隆路炉掳隆 鹿脽禄媒脟脽麓脵赂茅
        // 脕娄掳脜脟脩麓脵. v1.41 脕娄掳脜脟脧脕枚 戮脢麓脗麓脵.
        // DeleteClient(iClientH, true, true);
        return true; // v1.41 FALSE赂娄 鹿脻脠炉脟脧赂茅 戮脝脌脤脜脹脌脤
                     // 鹿脵麓脷驴隆 潞鹿禄莽碌脠麓脵.
      }

      return true;
    }

  // 戮脝脌脤脜脹脌禄 潞赂掳眉脟脪 驴漏脌炉掳酶掳拢脌脤 戮酶麓脵.
  return false;
}

bool CGame::bCheckTotalSkillMasteryPoints(int iClientH, int iSkill) {
  int i;
  int iRemainPoint, iTotalPoints, iWeaponIndex, iDownSkillSSN, iDownPoint;
  short sDownSkillIndex;

  if (m_pClientList[iClientH] == 0)
    return false;

  iTotalPoints = 0;
  for (i = 0; i < DEF_MAXSKILLTYPE; i++)
    iTotalPoints += m_pClientList[iClientH]->m_cSkillMastery[i];

  iRemainPoint = iTotalPoints - DEF_MAXSKILLPOINTS;

  if (iRemainPoint > 0) {
    // 陆潞脜鲁脌脟 脝梅脌脦脝庐掳隆 脙脢掳煤碌脟戮煤麓脵. 脙脢掳煤碌脠
    // 脝梅脌脦脝庐 赂赂脜颅 路莽脟脕赂娄 碌鹿赂莽 SSN脌脤 掳隆脌氓 鲁路脌潞
    // 陆潞脜鲁脌禄 鲁禄赂掳麓脵.
    while (iRemainPoint > 0) {

      sDownSkillIndex = -1; // v1.4
      if (m_pClientList[iClientH]->m_iDownSkillIndex != -1) {
        // 脕枚脕陇碌脠 陆潞脜鲁脌脤 脌脰麓脵.
        switch (m_pClientList[iClientH]->m_iDownSkillIndex) {
        case 3: // 赂露鹿媒 脌煤脟脳

        default:
          // 陆潞脜鲁脌脤 20 脌脤脟脧脌脟 禄贸脜脗露贸赂茅 卤脳麓毛路脦
          // 0脌赂路脦 露鲁戮卯 露脽赂掳麓脵.
          if (m_pClientList[iClientH]->m_cSkillMastery
                  [m_pClientList[iClientH]->m_iDownSkillIndex] > 0) {
            sDownSkillIndex = m_pClientList[iClientH]->m_iDownSkillIndex;
          } else {
            // 麓脵赂楼 陆潞脜鲁脌禄 掳脣禄枚脟脩麓脵.
            // 麓脵赂楼 陆潞脜鲁脌禄 掳脣禄枚脟脩麓脵.
            iDownSkillSSN = 99999999;
            for (i = 0; i < DEF_MAXSKILLTYPE; i++)
              if ((m_pClientList[iClientH]->m_cSkillMastery[i] >= 21) &&
                  (i != iSkill) &&
                  (m_pClientList[iClientH]->m_iSkillSSN[i] <= iDownSkillSSN)) {
                // V1.22 麓脵驴卯 陆脙脜鲁 陆潞脜鲁脌潞 脙脰录脪 20
                // 脌脤脟脧路脦麓脗 露鲁戮卯脕煤 录枚 戮酶麓脵.
                iDownSkillSSN = m_pClientList[iClientH]->m_iSkillSSN[i];
                sDownSkillIndex = i;
              }
          }
          break;
        }
      }
      // 脟枚脌莽 1潞赂麓脵 脜芦 陆潞脜鲁 脕脽驴隆录颅 掳隆脌氓 脌脹脌潞 SSN脌禄
      // 掳庐麓脗 陆潞脜鲁脌潞 sDownSkillIndex

      if (sDownSkillIndex != -1) {

        if (m_pClientList[iClientH]->m_cSkillMastery[sDownSkillIndex] <=
            20) // v1.4
          iDownPoint =
              m_pClientList[iClientH]->m_cSkillMastery[sDownSkillIndex];
        else
          iDownPoint = 1;

        m_pClientList[iClientH]->m_cSkillMastery[sDownSkillIndex] -=
            iDownPoint; // v1.4
        m_pClientList[iClientH]->m_iSkillSSN[sDownSkillIndex] =
            m_iSkillSSNpoint[m_pClientList[iClientH]
                                 ->m_cSkillMastery[sDownSkillIndex] +
                             1] -
            1;
        iRemainPoint -= iDownPoint; // v1.4

        // 赂赂戮脿 鲁路戮脝脕酶 陆潞脜鲁脌脤 脟枚脌莽 禄莽驴毛脕脽脌脦
        // 鹿芦卤芒驴脥 掳眉路脙脌脤 脌脰麓脵赂茅 赂铆脕脽路眉脌禄
        // 鲁路脙脽戮卯戮脽 脟脩麓脵.
        if (m_pClientList[iClientH]
                ->m_sItemEquipmentStatus[DEF_EQUIPPOS_TWOHAND] != -1) {
          // 戮莽录脮鹿芦卤芒掳隆 脌氓脗酶碌脟戮卯 脌脰戮煤麓脵.
          iWeaponIndex = m_pClientList[iClientH]
                             ->m_sItemEquipmentStatus[DEF_EQUIPPOS_TWOHAND];
          if (m_pClientList[iClientH]
                  ->m_pItemList[iWeaponIndex]
                  ->m_sRelatedSkill == sDownSkillIndex) {
            // 脠掳路霉脌脟 禄莽驴毛驴隆 脌脟脟脩 陆潞脜鲁脌脟
            // 脟脧露么脌脤戮煤麓脵. 赂铆脕脽路眉脌禄 鲁路脙谩麓脵.
            m_pClientList[iClientH]->m_iHitRatio -= iDownPoint; // v1.4
            if (m_pClientList[iClientH]->m_iHitRatio < 0)
              m_pClientList[iClientH]->m_iHitRatio = 0;
          }
        }

        if (m_pClientList[iClientH]
                ->m_sItemEquipmentStatus[DEF_EQUIPPOS_RHAND] != -1) {
          iWeaponIndex = m_pClientList[iClientH]
                             ->m_sItemEquipmentStatus[DEF_EQUIPPOS_RHAND];
          if (m_pClientList[iClientH]
                  ->m_pItemList[iWeaponIndex]
                  ->m_sRelatedSkill == sDownSkillIndex) {
            m_pClientList[iClientH]->m_iHitRatio -= iDownPoint; // v1.4
            if (m_pClientList[iClientH]->m_iHitRatio < 0)
              m_pClientList[iClientH]->m_iHitRatio = 0;
          }
        }
        SendNotifyMsg(0, iClientH, DEF_NOTIFY_SKILL, sDownSkillIndex,
                      m_pClientList[iClientH]->m_cSkillMastery[sDownSkillIndex],
                      0, 0);
      } else {
        return false;
      }
    }
    return true;
  }

  return false;
}

void CGame::OnKeyDown(WPARAM wParam, LPARAM lParam) {
  switch (wParam) {
  case VK_F1:
    m_bF1pressed = true;
    break;
  case VK_F4:
    m_bF4pressed = true;
    break;
  case VK_F5:
    m_bF5pressed = true;
    break;
  case VK_F12:
    m_bF12pressed = true;
    break;
  }
}

void CGame::OnKeyUp(WPARAM wParam, LPARAM lParam) {
  int i;

  switch (wParam) {
  case VK_F2:
    break;

  case VK_F1:
    m_bF1pressed = false;
    break;
  case VK_F4:
    m_bF4pressed = false;
    break;
  case VK_F5:
    m_bF5pressed = false;
    break;
  case VK_F12:
    m_bF12pressed = false;
    break;

  case VK_F6:
    if (m_bF1pressed) {
      PutLogList("(!) Send server shutdown announcement1...");
      for (i = 1; i < DEF_MAXCLIENTS; i++)
        if ((m_pClientList[i] != 0) && (m_pClientList[i]->m_bIsInitComplete)) {
          SendNotifyMsg(0, i, DEF_NOTIFY_SERVERSHUTDOWN, 1, 0, 0, 0);
        }
    }
    break;

  case VK_F7:
    if (m_bF1pressed) {
      PutLogList("(!) Send server shutdown announcement2...");
      for (i = 1; i < DEF_MAXCLIENTS; i++)
        if ((m_pClientList[i] != 0) && (m_pClientList[i]->m_bIsInitComplete)) {
          SendNotifyMsg(0, i, DEF_NOTIFY_SERVERSHUTDOWN, 2, 0, 0, 0);
        }
    }
    break;

  case VK_F9:
    if ((m_bF1pressed)) {
      PutLogList("(!!!) Resume Crusade Mode...");
      LocalStartCrusadeMode(0);
    }
    break;

  case VK_F11:
    if ((m_bF1pressed)) {
      PutLogList("(!!!) ManualEndCrusadeMode: side 0");
      ManualEndCrusadeMode(0);
    }
    break;

#define VK_1 0x31
  case VK_1:
    if ((m_bF1pressed)) {
      GlobalUpdateConfigs(1);
    }
    break;

#define VK_2 0x32
  case VK_2:
    if ((m_bF1pressed)) {
      GlobalUpdateConfigs(2);
    }
    break;

#define VK_3 0x33
  case VK_3:
    if ((m_bF1pressed)) {
      GlobalUpdateConfigs(3);
    }
    break;

#define VK_4 0x34
  case VK_4:
    if ((m_bF1pressed)) {
      GlobalUpdateConfigs(1);
    }
    break;

    /*#define VK_A 0x41 // a key
    case VK_A:
            if ((m_bF1pressed )) {
                    GlobalStartApocalypseMode();
            }
            break;*/

    /*#define VK_H 0x49 // H key
    case VK_H:
            if ((m_bF1pressed )) {
                    GlobalStartHeldenianMode();
            }
            break;*/

    // Crusade Testcode
  case VK_HOME:
    if ((m_bF1pressed)) {
      GlobalStartCrusadeMode();
    }
    break;

  case VK_INSERT:
    _GrandMagicLaunchMsgSend(1, 1);
    MeteorStrikeMsgHandler(1);
    break;

  case VK_DELETE:
    _GrandMagicLaunchMsgSend(1, 2);
    MeteorStrikeMsgHandler(2);
    break;
  }
}

int CGame::iGetFollowerNumber(short sOwnerH, char cOwnerType) {
  int i, iTotal;

  iTotal = 0;

  for (i = 1; i < DEF_MAXNPCS; i++)
    if ((m_pNpcList[i] != 0) &&
        (m_pNpcList[i]->m_cMoveType == DEF_MOVETYPE_FOLLOW)) {

      if ((m_pNpcList[i]->m_iFollowOwnerIndex == sOwnerH) &&
          (m_pNpcList[i]->m_cFollowOwnerType == cOwnerType))
        iTotal++;
    }

  return iTotal;
}

/*********************************************************************************************************************
**  bool CGame::bRegisterDelayEvent(int iDelayType, int iEffectType, DWORD
* dwLastTime, int iTargetH,				** *
*						   char cTargetType, char
* cMapIndex, int dX, int dY, int iV1, int iV2, int iV3) **
**  description			:: initiates the delayed event process
*												**
**  last updated		:: November 20, 2004; 9:30 PM; Hypnotoad
*												**
**	return value		:: bool
*																**
**********************************************************************************************************************/
bool CGame::bRegisterDelayEvent(int iDelayType, int iEffectType,
                                DWORD dwLastTime, int iTargetH,
                                char cTargetType, char cMapIndex, int dX,
                                int dY, int iV1, int iV2, int iV3) {
  int i;

  for (i = 0; i < DEF_MAXDELAYEVENTS; i++)
    if (m_pDelayEventList[i] == 0) {
      m_pDelayEventList[i] = new class CDelayEvent;
      m_pDelayEventList[i]->m_iDelayType = iDelayType;
      m_pDelayEventList[i]->m_iEffectType = iEffectType;
      m_pDelayEventList[i]->m_cMapIndex = cMapIndex;
      m_pDelayEventList[i]->m_dX = dX;
      m_pDelayEventList[i]->m_dY = dY;
      m_pDelayEventList[i]->m_iTargetH = iTargetH;
      m_pDelayEventList[i]->m_cTargetType = cTargetType;
      m_pDelayEventList[i]->m_iV1 = iV1;
      m_pDelayEventList[i]->m_iV2 = iV2;
      m_pDelayEventList[i]->m_iV3 = iV3;
      m_pDelayEventList[i]->m_dwTriggerTime = dwLastTime;
      return true;
    }
  return false;
}

void CGame::DelayEventProcessor() {
  int i, iSkillNum, iResult;
  DWORD dwTime = timeGetTime();
  int iTemp;

  for (i = 0; i < DEF_MAXDELAYEVENTS; i++)
    if ((m_pDelayEventList[i] != 0) &&
        (m_pDelayEventList[i]->m_dwTriggerTime < dwTime)) {

      // 脌脤潞楼脝庐掳隆 碌驴脌脹脟脪 陆脙掳拢脌脤 碌脝麓脵. 碌驴脌脹脠脛
      // 禄猫脕娄碌脠麓脵.
      switch (m_pDelayEventList[i]->m_iDelayType) {

      case DEF_DELAYEVENTTYPE_ANCIENT_TABLET:
        if ((m_pClientList[m_pDelayEventList[i]->m_iTargetH]->m_iStatus &
             0x400000) != 0) {
          iTemp = 1;
        } else if ((m_pClientList[m_pDelayEventList[i]->m_iTargetH]->m_iStatus &
                    0x800000) != 0) {
          iTemp = 3;
        } else if ((m_pClientList[m_pDelayEventList[i]->m_iTargetH]->m_iStatus &
                    0x10000) != 0) {
          iTemp = 4;
        }

        SendNotifyMsg(0, m_pDelayEventList[i]->m_iTargetH,
                      DEF_NOTIFY_SLATE_STATUS, iTemp, 0, 0, 0);
        SetSlateFlag(m_pDelayEventList[i]->m_iTargetH, iTemp, false);
        break;

      case DEF_DELAYEVENTTYPE_CALCMETEORSTRIKEEFFECT:
        CalcMeteorStrikeEffectHandler(m_pDelayEventList[i]->m_cMapIndex);
        break;

      case DEF_DELAYEVENTTYPE_DOMETEORSTRIKEDAMAGE:
        DoMeteorStrikeDamageHandler(m_pDelayEventList[i]->m_cMapIndex);
        break;

      case DEF_DELAYEVENTTYPE_METEORSTRIKE:
        MeteorStrikeHandler(m_pDelayEventList[i]->m_cMapIndex);
        break;

      case DEF_DELAYEVENTTYPE_USEITEM_SKILL:
        // 戮脝脌脤脜脹 禄莽驴毛驴隆 碌没赂楼 掳谩掳煤 掳猫禄锚, 脜毛潞赂
        switch (m_pDelayEventList[i]->m_cTargetType) {
        case DEF_OWNERTYPE_PLAYER:
          iSkillNum = m_pDelayEventList[i]->m_iEffectType;

          if (m_pClientList[m_pDelayEventList[i]->m_iTargetH] == 0)
            break;
          // 卤芒录煤 禄莽驴毛脌脤 鹿芦脠驴脠颅 碌脟戮煤麓脵赂茅 鹿芦陆脙.
          if (m_pClientList[m_pDelayEventList[i]->m_iTargetH]
                  ->m_bSkillUsingStatus[iSkillNum] == false)
            break;
          // 卤芒录煤 禄莽驴毛 陆脙掳拢 ID掳隆 麓脼露贸碌碌 鹿芦陆脙 v1.12
          if (m_pClientList[m_pDelayEventList[i]->m_iTargetH]
                  ->m_iSkillUsingTimeID[iSkillNum] !=
              m_pDelayEventList[i]->m_iV2)
            break;

          // 卤芒录煤 禄莽驴毛 禄贸脜脗 脟脴脕娄
          m_pClientList[m_pDelayEventList[i]->m_iTargetH]
              ->m_bSkillUsingStatus[iSkillNum] = false;
          m_pClientList[m_pDelayEventList[i]->m_iTargetH]
              ->m_iSkillUsingTimeID[iSkillNum] = 0;

          // 脌脤脕娄 Skill脌脟 脠驴掳煤驴隆 碌没赂楼 掳猫禄锚脌禄 脟脩麓脵.
          iResult = iCalculateUseSkillItemEffect(
              m_pDelayEventList[i]->m_iTargetH,
              m_pDelayEventList[i]->m_cTargetType, m_pDelayEventList[i]->m_iV1,
              iSkillNum, m_pDelayEventList[i]->m_cMapIndex,
              m_pDelayEventList[i]->m_dX, m_pDelayEventList[i]->m_dY);

          // 卤芒录煤 禄莽驴毛脌脤 脕脽脕枚 碌脟戮煤脌陆脌禄 戮脣赂掳麓脵.
          SendNotifyMsg(0, m_pDelayEventList[i]->m_iTargetH,
                        DEF_NOTIFY_SKILLUSINGEND, iResult, 0, 0, 0);
          break;
        }
        break;

      case DEF_DELAYEVENTTYPE_DAMAGEOBJECT:
        break;

      case DEF_DELAYEVENTTYPE_MAGICRELEASE:
        // Removes the aura after time
        switch (m_pDelayEventList[i]->m_cTargetType) {
        case DEF_OWNERTYPE_PLAYER:
          if (m_pClientList[m_pDelayEventList[i]->m_iTargetH] == 0)
            break;

          SendNotifyMsg(
              0, m_pDelayEventList[i]->m_iTargetH, DEF_NOTIFY_MAGICEFFECTOFF,
              m_pDelayEventList[i]->m_iEffectType,
              m_pClientList[m_pDelayEventList[i]->m_iTargetH]
                  ->m_cMagicEffectStatus[m_pDelayEventList[i]->m_iEffectType],
              0, 0);

          m_pClientList[m_pDelayEventList[i]->m_iTargetH]
              ->m_cMagicEffectStatus[m_pDelayEventList[i]->m_iEffectType] = 0;

          // Inbitition casting
          if (m_pDelayEventList[i]->m_iEffectType == DEF_MAGICTYPE_INHIBITION)
            m_pClientList[m_pDelayEventList[i]->m_iTargetH]->m_bInhibition =
                false;

          // Invisibility 瓤苞 秦力
          if (m_pDelayEventList[i]->m_iEffectType == DEF_MAGICTYPE_INVISIBILITY)
            SetInvisibilityFlag(m_pDelayEventList[i]->m_iTargetH,
                                DEF_OWNERTYPE_PLAYER, false);

          // Berserk 瓤苞 秦力
          if (m_pDelayEventList[i]->m_iEffectType == DEF_MAGICTYPE_BERSERK)
            SetBerserkFlag(m_pDelayEventList[i]->m_iTargetH,
                           DEF_OWNERTYPE_PLAYER, false);

          // Haste
          if (m_pDelayEventList[i]->m_iEffectType == DEF_MAGICTYPE_HASTE)
            SetHasteFlag(m_pDelayEventList[i]->m_iTargetH, DEF_OWNERTYPE_PLAYER,
                         false);

          // Confusion
          if (m_pDelayEventList[i]->m_iEffectType == DEF_MAGICTYPE_CONFUSE)
            switch (m_pDelayEventList[i]->m_iV1) {
            case 3:
              SetIllusionFlag(m_pDelayEventList[i]->m_iTargetH,
                              DEF_OWNERTYPE_PLAYER, false);
              break;
            case 4:
              SetIllusionMovementFlag(m_pDelayEventList[i]->m_iTargetH,
                                      DEF_OWNERTYPE_PLAYER, false);
              break;
            }

          // Protection Magic
          if (m_pDelayEventList[i]->m_iEffectType == DEF_MAGICTYPE_PROTECT) {
            switch (m_pDelayEventList[i]->m_iV1) {
            case 1:
              SetProtectionFromArrowFlag(m_pDelayEventList[i]->m_iTargetH,
                                         DEF_OWNERTYPE_PLAYER, false);
              break;
            case 2:
            case 5:
              SetMagicProtectionFlag(m_pDelayEventList[i]->m_iTargetH,
                                     DEF_OWNERTYPE_PLAYER, false);
              break;
            case 3:
            case 4:
              SetDefenseShieldFlag(m_pDelayEventList[i]->m_iTargetH,
                                   DEF_OWNERTYPE_PLAYER, false);
              break;
            }
          }

          // polymorph 瓤苞 秦力
          if (m_pDelayEventList[i]->m_iEffectType == DEF_MAGICTYPE_POLYMORPH) {
            m_pClientList[m_pDelayEventList[i]->m_iTargetH]->m_sType =
                m_pClientList[m_pDelayEventList[i]->m_iTargetH]
                    ->m_sOriginalType;
            SendEventToNearClient_TypeA(
                m_pDelayEventList[i]->m_iTargetH, DEF_OWNERTYPE_PLAYER,
                MSGID_EVENT_MOTION, DEF_OBJECTNULLACTION, 0, 0, 0);
          }

          // Ice 瓤苞 秦力
          if (m_pDelayEventList[i]->m_iEffectType == DEF_MAGICTYPE_ICE)
            SetIceFlag(m_pDelayEventList[i]->m_iTargetH, DEF_OWNERTYPE_PLAYER,
                       false);
          break;

        case DEF_OWNERTYPE_NPC:
          if (m_pNpcList[m_pDelayEventList[i]->m_iTargetH] == 0)
            break;

          m_pNpcList[m_pDelayEventList[i]->m_iTargetH]
              ->m_cMagicEffectStatus[m_pDelayEventList[i]->m_iEffectType] = 0;

          // Invisibility 脠驴掳煤 脟脴脕娄
          if (m_pDelayEventList[i]->m_iEffectType == DEF_MAGICTYPE_INVISIBILITY)
            SetInvisibilityFlag(m_pDelayEventList[i]->m_iTargetH,
                                DEF_OWNERTYPE_NPC, false);

          // Berserk 脠驴掳煤 脟脴脕娄
          if (m_pDelayEventList[i]->m_iEffectType == DEF_MAGICTYPE_BERSERK)
            SetBerserkFlag(m_pDelayEventList[i]->m_iTargetH, DEF_OWNERTYPE_NPC,
                           false);

          // polymorph 脠驴掳煤 脟脴脕娄
          if (m_pDelayEventList[i]->m_iEffectType == DEF_MAGICTYPE_POLYMORPH) {
            m_pNpcList[m_pDelayEventList[i]->m_iTargetH]->m_sType =
                m_pNpcList[m_pDelayEventList[i]->m_iTargetH]->m_sOriginalType;
            SendEventToNearClient_TypeA(m_pDelayEventList[i]->m_iTargetH,
                                        DEF_OWNERTYPE_NPC, MSGID_EVENT_MOTION,
                                        DEF_OBJECTNULLACTION, 0, 0, 0);
          }

          // Ice 脠驴掳煤 脟脴脕娄
          if (m_pDelayEventList[i]->m_iEffectType == DEF_MAGICTYPE_ICE)
            SetIceFlag(m_pDelayEventList[i]->m_iTargetH, DEF_OWNERTYPE_NPC,
                       false);

          // Illusion
          if (m_pDelayEventList[i]->m_iEffectType == DEF_MAGICTYPE_CONFUSE)
            SetIllusionFlag(m_pDelayEventList[i]->m_iTargetH, DEF_OWNERTYPE_NPC,
                            false);

          // Protection Magic
          if (m_pDelayEventList[i]->m_iEffectType == DEF_MAGICTYPE_PROTECT) {
            switch (m_pDelayEventList[i]->m_iV1) {
            case 1:
              SetProtectionFromArrowFlag(m_pDelayEventList[i]->m_iTargetH,
                                         DEF_OWNERTYPE_NPC, false);
              break;
            case 2:
            case 5:
              SetMagicProtectionFlag(m_pDelayEventList[i]->m_iTargetH,
                                     DEF_OWNERTYPE_NPC, false);
              break;
            case 3:
            case 4:
              SetDefenseShieldFlag(m_pDelayEventList[i]->m_iTargetH,
                                   DEF_OWNERTYPE_NPC, false);
              break;
            }
          }
          //	if (m_pDelayEventList[i]->m_iEffectType == /*notcoded*/)

          break;
        }
        break;
      }

      delete m_pDelayEventList[i];
      m_pDelayEventList[i] = 0;
    }
}
bool CGame::bRemoveFromDelayEventList(int iH, char cType, int iEffectType) {
  int i;

  for (i = 0; i < DEF_MAXDELAYEVENTS; i++)
    if (m_pDelayEventList[i] != 0) {

      if (iEffectType == 0) {
        // Effect 脕戮路霉驴隆 禄贸掳眉戮酶脌脤 赂冒碌脦 禄猫脕娄
        if ((m_pDelayEventList[i]->m_iTargetH == iH) &&
            (m_pDelayEventList[i]->m_cTargetType == cType)) {
          delete m_pDelayEventList[i];
          m_pDelayEventList[i] = 0;
        }
      } else {
        // 脟脴麓莽 Effect赂赂 禄猫脕娄.
        if ((m_pDelayEventList[i]->m_iTargetH == iH) &&
            (m_pDelayEventList[i]->m_cTargetType == cType) &&
            (m_pDelayEventList[i]->m_iEffectType == iEffectType)) {
          delete m_pDelayEventList[i];
          m_pDelayEventList[i] = 0;
        }
      }
    }

  return true;
}

void CGame::SendObjectMotionRejectMsg(int iClientH) {
  char *cp, cData[30];
  DWORD *dwp;
  WORD *wp;
  short *sp;
  int iRet;

  m_pClientList[iClientH]->m_bIsMoveBlocked = true; // v2.171

  // 脌脤碌驴脌脤 潞脪掳隆麓脡脟脧麓脵.
  dwp = (DWORD *)(cData + DEF_INDEX4_MSGID);
  *dwp = MSGID_RESPONSE_MOTION;
  wp = (WORD *)(cData + DEF_INDEX2_MSGTYPE);
  *wp = DEF_OBJECTMOTION_REJECT;

  cp = (char *)(cData + DEF_INDEX2_MSGTYPE + 2);
  sp = (short *)cp;
  *sp = m_pClientList[iClientH]->m_sX;
  cp += 2;
  sp = (short *)cp;
  *sp = m_pClientList[iClientH]->m_sY;
  cp += 2;

  iRet = m_pClientList[iClientH]->m_pXSock->iSendMsg(cData, 10);
  switch (iRet) {
  case DEF_XSOCKEVENT_QUENEFULL:
  case DEF_XSOCKEVENT_SOCKETERROR:
  case DEF_XSOCKEVENT_CRITICALERROR:
  case DEF_XSOCKEVENT_SOCKETCLOSED:
    // 赂脼陆脙脕枚赂娄 潞赂鲁戮露搂 驴隆路炉掳隆 鹿脽禄媒脟脽麓脵赂茅
    // 脕娄掳脜脟脩麓脵.
    DeleteClient(iClientH, true, true);
    return;
  }
  return;
}

int CGame::_iGetTotalClients() {
  int i, iTotal;

  iTotal = 0;
  for (i = 1; i < DEF_MAXCLIENTS; i++)
    if (m_pClientList[i] != 0)
      iTotal++;

  return iTotal;
}

void CGame::DynamicObjectEffectProcessor() {
  int i, ix, iy, iIndex;
  short sOwnerH, iDamage, sType;
  char cOwnerType;
  DWORD dwTime = timeGetTime(), dwRegisterTime;

  //
  for (i = 0; i < DEF_MAXDYNAMICOBJECTS; i++)
    if (m_pDynamicObjectList[i] != 0) {
      switch (m_pDynamicObjectList[i]->m_sType) {

      case DEF_DYNAMICOBJECT_PCLOUD_BEGIN:
        // 脝梅脌脤脕冒 脜卢露贸驴矛碌氓
        for (ix = m_pDynamicObjectList[i]->m_sX - 1;
             ix <= m_pDynamicObjectList[i]->m_sX + 1; ix++)
          for (iy = m_pDynamicObjectList[i]->m_sY - 1;
               iy <= m_pDynamicObjectList[i]->m_sY + 1; iy++) {

            m_pMapList[m_pDynamicObjectList[i]->m_cMapIndex]->GetOwner(
                &sOwnerH, &cOwnerType, ix, iy);
            if (sOwnerH != 0) {
              // Poison Damage赂娄 脌脭麓脗麓脵.
              switch (cOwnerType) {
              case DEF_OWNERTYPE_PLAYER:
                if (m_pClientList[sOwnerH] == 0)
                  break;
                if (m_pClientList[sOwnerH]->m_bIsKilled)
                  break;
                // v1.41 脕脽赂鲁脌脤掳铆 脌眉脜玫赂冒碌氓掳隆 戮脝麓脧赂茅
                // 脟脟脟脴赂娄 脌脭脕枚 戮脢麓脗麓脵.
                // if ((m_pClientList[sOwnerH]->m_bIsNeutral ) &&
                // (m_pClientList[sOwnerH]->m_sAppr2 & 0xF000) == 0) break;

                // 脌脤路卤 陆脛脌赂路脦 麓毛鹿脤脕枚脌脟 脜漏卤芒赂娄 掳谩脕陇
                if (m_pDynamicObjectList[i]->m_iV1 < 20)
                  iDamage = iDice(1, 6);
                else
                  iDamage = iDice(1, 8);

                // New 17/05/2004 Changed
                if (m_pClientList[sOwnerH]->m_iAdminUserLevel == 0)
                  m_pClientList[sOwnerH]->m_iHP -= iDamage;

                if (m_pClientList[sOwnerH]->m_iHP <= 0) {
                  // 脟脙路鹿脌脤戮卯掳隆 禄莽赂脕脟脽麓脵.
                  ClientKilledHandler(sOwnerH, sOwnerH, cOwnerType, iDamage);
                } else {
                  if (iDamage > 0) {
                    // 鹿脼脌潞 麓毛鹿脤脕枚赂娄 脜毛潞赂脟脩麓脵. <- HP赂娄
                    // 卤脳麓毛路脦 戮脣赂掳麓脵.
                    SendNotifyMsg(0, sOwnerH, DEF_NOTIFY_HP, 0, 0, 0, 0);

                    if (m_pClientList[sOwnerH]
                            ->m_cMagicEffectStatus[DEF_MAGICTYPE_HOLDOBJECT] !=
                        0) {
                      // 赂露潞帽 禄贸脜脗掳隆 脟庐赂掳麓脵.
                      // 1: Hold-Person
                      // 2: Paralize
                      SendNotifyMsg(
                          0, sOwnerH, DEF_NOTIFY_MAGICEFFECTOFF,
                          DEF_MAGICTYPE_HOLDOBJECT,
                          m_pClientList[sOwnerH]
                              ->m_cMagicEffectStatus[DEF_MAGICTYPE_HOLDOBJECT],
                          0, 0);

                      m_pClientList[sOwnerH]
                          ->m_cMagicEffectStatus[DEF_MAGICTYPE_HOLDOBJECT] = 0;
                      bRemoveFromDelayEventList(sOwnerH, DEF_OWNERTYPE_PLAYER,
                                                DEF_MAGICTYPE_HOLDOBJECT);
                    }
                  }

                  // v1.42 Poison 脠驴掳煤
                  if ((bCheckResistingMagicSuccess(
                           1, sOwnerH, DEF_OWNERTYPE_PLAYER, 100) == false) &&
                      (m_pClientList[sOwnerH]->m_bIsPoisoned == false)) {

                    m_pClientList[sOwnerH]->m_bIsPoisoned = true;
                    m_pClientList[sOwnerH]->m_iPoisonLevel =
                        m_pDynamicObjectList[i]->m_iV1;
                    m_pClientList[sOwnerH]->m_dwPoisonTime = dwTime;
                    // 脕脽碌露碌脟戮煤脌陆脌禄 戮脣赂掳麓脵.
                    SetPoisonFlag(
                        sOwnerH, cOwnerType,
                        true); // poison aura appears from dynamic objects
                    SendNotifyMsg(0, sOwnerH, DEF_NOTIFY_MAGICEFFECTON,
                                  DEF_MAGICTYPE_POISON,
                                  m_pClientList[sOwnerH]->m_iPoisonLevel, 0, 0);
                  }
                }
                break;

              case DEF_OWNERTYPE_NPC:
                // 赂贸陆潞脜脥脌脟 脕脽碌露脠驴掳煤麓脗 戮脝脕梅 卤赂脟枚
                // 戮脠碌脢
                if (m_pNpcList[sOwnerH] == 0)
                  break;

                // 脌脤路卤 陆脛脌赂路脦 麓毛鹿脤脕枚脌脟 脜漏卤芒赂娄 掳谩脕陇
                if (m_pDynamicObjectList[i]->m_iV1 < 20)
                  iDamage = iDice(1, 6);
                else
                  iDamage = iDice(1, 8);

                // 脌眉脌茂驴毛 卤赂脕露鹿掳脕脽 卤脳路拢碌氓 赂脜脕梅
                // 脕娄鲁脳路鹿脌脤脜脥, 驴隆鲁脢脕枚 陆脟碌氓
                // 脕娄鲁脳路鹿脌脤脜脥麓脗 脟脢碌氓路霉 赂露鹿媒驴隆
                // 麓毛鹿脤脕枚赂娄 脌脭脕枚 戮脢麓脗麓脵.
                switch (m_pNpcList[sOwnerH]->m_sType) {
                case 40: // ESG
                case 41: // GMG
                case 67: // McGaffin
                case 68: // Perry
                case 69: // Devlin
                  iDamage = 0;
                  break;
                }

                // HP驴隆录颅 禄芦麓脵. Action Limit驴隆 碌没露贸
                // 脙鲁赂庐脟脩麓脵.
                switch (m_pNpcList[sOwnerH]->m_cActionLimit) {
                case 0: // 脌脧鹿脻
                case 3: // 麓玫鹿脤路霉
                case 5: // 掳脟脙脿鹿掳
                  m_pNpcList[sOwnerH]->m_iHP -= iDamage;
                  break;
                }
                // if (m_pNpcList[sOwnerH]->m_cActionLimit == 0)
                //	m_pNpcList[sOwnerH]->m_iHP -= iDamage;

                if (m_pNpcList[sOwnerH]->m_iHP <= 0) {
                  // NPC掳隆 禄莽赂脕脟脽麓脵.
                  NpcKilledHandler(
                      sOwnerH, cOwnerType, sOwnerH,
                      0); // v1.2 脕脽碌露卤赂赂搂驴隆 脕脳脌赂赂茅 赂露脕枚赂路
                          // 麓毛鹿脤脕枚掳隆 0. 戮脝脌脤脜脹脌禄 陆卤掳脭
                          // 卤赂脟脧脕枚 赂酶脟脧掳脭 脟脧卤芒 脌搂脟脭.
                } else {
                  // Damage赂娄 脌脭脌潞 脙忙掳脻脌赂路脦 脌脦脟脩
                  // 脕枚驴卢脠驴掳煤.
                  if (iDice(1, 3) == 2)
                    m_pNpcList[sOwnerH]->m_dwTime = dwTime;

                  if (m_pNpcList[sOwnerH]
                          ->m_cMagicEffectStatus[DEF_MAGICTYPE_HOLDOBJECT] !=
                      0) {
                    // Hold 碌脟戮卯 脌脰戮煤麓酶 禄贸脜脗露贸赂茅 脟庐赂掳麓脵.
                    m_pNpcList[sOwnerH]
                        ->m_cMagicEffectStatus[DEF_MAGICTYPE_HOLDOBJECT] = 0;
                  }

                  // NPC赂娄 碌碌赂脕掳隆麓脗 赂冒碌氓路脦 脌眉脠炉陆脙脜虏麓脵.
                  SendEventToNearClient_TypeA(sOwnerH, DEF_OWNERTYPE_NPC,
                                              MSGID_EVENT_MOTION,
                                              DEF_OBJECTDAMAGE, iDamage, 0, 0);
                }
                break;
              }
            }
          }
        break;

      case DEF_DYNAMICOBJECT_ICESTORM:
        for (ix = m_pDynamicObjectList[i]->m_sX - 2;
             ix <= m_pDynamicObjectList[i]->m_sX + 2; ix++)
          for (iy = m_pDynamicObjectList[i]->m_sY - 2;
               iy <= m_pDynamicObjectList[i]->m_sY + 2; iy++) {

            m_pMapList[m_pDynamicObjectList[i]->m_cMapIndex]->GetOwner(
                &sOwnerH, &cOwnerType, ix, iy);
            if (sOwnerH != 0) {
              switch (cOwnerType) {
              case DEF_OWNERTYPE_PLAYER:
                if (m_pClientList[sOwnerH] == 0)
                  break;
                if (m_pClientList[sOwnerH]->m_bIsKilled)
                  break;

                iDamage = iDice(3, 3) + 5;

                if (m_pClientList[sOwnerH]->m_iAdminUserLevel == 0)
                  m_pClientList[sOwnerH]->m_iHP -= iDamage;

                if (m_pClientList[sOwnerH]->m_iHP <= 0) {
                  // 脟脙路鹿脌脤戮卯掳隆 禄莽赂脕脟脽麓脵.
                  ClientKilledHandler(sOwnerH, sOwnerH, cOwnerType, iDamage);
                } else {
                  if (iDamage > 0) {

                    SendNotifyMsg(0, sOwnerH, DEF_NOTIFY_HP, 0, 0, 0, 0);

                    if (m_pClientList[sOwnerH]
                            ->m_cMagicEffectStatus[DEF_MAGICTYPE_HOLDOBJECT] ==
                        1) {

                      SendNotifyMsg(
                          0, sOwnerH, DEF_NOTIFY_MAGICEFFECTOFF,
                          DEF_MAGICTYPE_HOLDOBJECT,
                          m_pClientList[sOwnerH]
                              ->m_cMagicEffectStatus[DEF_MAGICTYPE_HOLDOBJECT],
                          0, 0);

                      m_pClientList[sOwnerH]
                          ->m_cMagicEffectStatus[DEF_MAGICTYPE_HOLDOBJECT] = 0;
                      bRemoveFromDelayEventList(sOwnerH, DEF_OWNERTYPE_PLAYER,
                                                DEF_MAGICTYPE_HOLDOBJECT);
                    }
                  }

                  if ((bCheckResistingIceSuccess(
                           1, sOwnerH, DEF_OWNERTYPE_PLAYER,
                           m_pDynamicObjectList[i]->m_iV1) == false) &&
                      (m_pClientList[sOwnerH]
                           ->m_cMagicEffectStatus[DEF_MAGICTYPE_ICE] == 0)) {

                    m_pClientList[sOwnerH]
                        ->m_cMagicEffectStatus[DEF_MAGICTYPE_ICE] = 1;
                    SetIceFlag(sOwnerH, cOwnerType, true);
                    // 脠驴掳煤掳隆 脟脴脕娄碌脡 露搂 鹿脽禄媒脟脪 碌么路鹿脌脤
                    // 脌脤潞楼脝庐赂娄 碌卯路脧脟脩麓脵.
                    bRegisterDelayEvent(DEF_DELAYEVENTTYPE_MAGICRELEASE,
                                        DEF_MAGICTYPE_ICE, dwTime + (20 * 1000),
                                        sOwnerH, cOwnerType, 0, 0, 0, 1, 0, 0);

                    SendNotifyMsg(0, sOwnerH, DEF_NOTIFY_MAGICEFFECTON,
                                  DEF_MAGICTYPE_ICE, 1, 0, 0);
                  }
                }
                break;

              case DEF_OWNERTYPE_NPC:
                if (m_pNpcList[sOwnerH] == 0)
                  break;

                iDamage = iDice(3, 3) + 5;

                switch (m_pNpcList[sOwnerH]->m_sType) {
                case 40: // ESG
                case 41: // GMG
                case 67: // McGaffin
                case 68: // Perry
                case 69: // Devlin
                  iDamage = 0;
                  break;
                }

                switch (m_pNpcList[sOwnerH]->m_cActionLimit) {
                case 0:
                case 3:
                case 5:
                  m_pNpcList[sOwnerH]->m_iHP -= iDamage;
                  break;
                }

                if (m_pNpcList[sOwnerH]->m_iHP <= 0) {
                  // NPC掳隆 禄莽赂脕脟脽麓脵.
                  NpcKilledHandler(
                      sOwnerH, cOwnerType, sOwnerH,
                      0); // v1.2 脜赂录颅 脕脳脌赂赂茅 赂露脕枚赂路
                          // 麓毛鹿脤脕枚掳隆 0. 戮脝脌脤脜脹脌禄 陆卤掳脭
                          // 卤赂脟脧脕枚 赂酶脟脧掳脭 脟脧卤芒 脌搂脟脭.
                } else {
                  // Damage赂娄 脌脭脌潞 脙忙掳脻脌赂路脦 脌脦脟脩
                  // 脕枚驴卢脠驴掳煤.
                  if (iDice(1, 3) == 2)
                    m_pNpcList[sOwnerH]->m_dwTime = dwTime;

                  if (m_pNpcList[sOwnerH]
                          ->m_cMagicEffectStatus[DEF_MAGICTYPE_HOLDOBJECT] !=
                      0) {
                    // Hold 碌脟戮卯 脌脰戮煤麓酶 禄贸脜脗露贸赂茅 脟庐赂掳麓脵.
                    m_pNpcList[sOwnerH]
                        ->m_cMagicEffectStatus[DEF_MAGICTYPE_HOLDOBJECT] = 0;
                  }

                  // NPC赂娄 碌碌赂脕掳隆麓脗 赂冒碌氓路脦 脌眉脠炉陆脙脜虏麓脵.
                  SendEventToNearClient_TypeA(sOwnerH, DEF_OWNERTYPE_NPC,
                                              MSGID_EVENT_MOTION,
                                              DEF_OBJECTDAMAGE, iDamage, 0, 0);

                  // v1.42 Ice 脠驴掳煤
                  if ((bCheckResistingIceSuccess(
                           1, sOwnerH, DEF_OWNERTYPE_NPC,
                           m_pDynamicObjectList[i]->m_iV1) == false) &&
                      (m_pNpcList[sOwnerH]
                           ->m_cMagicEffectStatus[DEF_MAGICTYPE_ICE] == 0)) {

                    m_pNpcList[sOwnerH]
                        ->m_cMagicEffectStatus[DEF_MAGICTYPE_ICE] = 1;
                    SetIceFlag(sOwnerH, cOwnerType, true);
                    // 脠驴掳煤掳隆 脟脴脕娄碌脡 露搂 鹿脽禄媒脟脪 碌么路鹿脌脤
                    // 脌脤潞楼脝庐赂娄 碌卯路脧脟脩麓脵.
                    bRegisterDelayEvent(DEF_DELAYEVENTTYPE_MAGICRELEASE,
                                        DEF_MAGICTYPE_ICE, dwTime + (20 * 1000),
                                        sOwnerH, cOwnerType, 0, 0, 0, 1, 0, 0);
                  }
                }
                break;
              }
            }

            // 脕脳脌潞脙麓脟脧掳铆 脌脰麓脗 脛鲁赂炉脌脤 脌脰麓脵赂茅
            m_pMapList[m_pDynamicObjectList[i]->m_cMapIndex]->GetDeadOwner(
                &sOwnerH, &cOwnerType, ix, iy);
            if ((cOwnerType == DEF_OWNERTYPE_PLAYER) &&
                (m_pClientList[sOwnerH] != 0) &&
                (m_pClientList[sOwnerH]->m_iHP > 0)) {
              // 脕脳脌潞 脙麓脟脧掳铆 脌脰麓脗 脟脙路鹿脌脤戮卯麓脵.
              iDamage = iDice(3, 2);
              m_pClientList[sOwnerH]->m_iHP -= iDamage;

              if (m_pClientList[sOwnerH]->m_iHP <= 0) {
                // 脟脙路鹿脌脤戮卯掳隆 禄莽赂脕脟脽麓脵.
                ClientKilledHandler(sOwnerH, sOwnerH, cOwnerType, iDamage);
              } else {
                if (iDamage > 0) {
                  // 鹿脼脌潞 麓毛鹿脤脕枚赂娄 脜毛潞赂脟脩麓脵. <- HP赂娄
                  // 卤脳麓毛路脦 戮脣赂掳麓脵.
                  SendNotifyMsg(0, sOwnerH, DEF_NOTIFY_HP, 0, 0, 0, 0);
                }
              }
            }

            // 卤脵脙鲁驴隆 Fire Object掳隆 脌脰麓脵赂茅 录枚赂铆脌禄
            // 脕脵脌脦麓脵.
            m_pMapList[m_pDynamicObjectList[i]->m_cMapIndex]->bGetDynamicObject(
                ix, iy, &sType, &dwRegisterTime, &iIndex);
            if (((sType == DEF_DYNAMICOBJECT_FIRE) ||
                 (sType == DEF_DYNAMICOBJECT_FIRE3)) &&
                (m_pDynamicObjectList[iIndex] != 0))
              m_pDynamicObjectList[iIndex]->m_dwLastTime =
                  m_pDynamicObjectList[iIndex]->m_dwLastTime -
                  (m_pDynamicObjectList[iIndex]->m_dwLastTime / 10);
          }
        break;

      case DEF_DYNAMICOBJECT_FIRE3:
      case DEF_DYNAMICOBJECT_FIRE:
        // Fire-Wall路霉脌脟 脜赂麓脗 潞脪虏脡
        if (m_pDynamicObjectList[i]->m_iCount == 1) {
          // 卤脵脙鲁驴隆 脜赂麓脗 鹿掳掳脟脌脤 脌脰麓脵赂茅 鹿酶脕酶麓脵.
          CheckFireBluring(m_pDynamicObjectList[i]->m_cMapIndex,
                           m_pDynamicObjectList[i]->m_sX,
                           m_pDynamicObjectList[i]->m_sY);
        }
        m_pDynamicObjectList[i]->m_iCount++;
        if (m_pDynamicObjectList[i]->m_iCount > 10)
          m_pDynamicObjectList[i]->m_iCount = 10;

        for (ix = m_pDynamicObjectList[i]->m_sX - 1;
             ix <= m_pDynamicObjectList[i]->m_sX + 1; ix++)
          for (iy = m_pDynamicObjectList[i]->m_sY - 1;
               iy <= m_pDynamicObjectList[i]->m_sY + 1; iy++) {

            m_pMapList[m_pDynamicObjectList[i]->m_cMapIndex]->GetOwner(
                &sOwnerH, &cOwnerType, ix, iy);
            if (sOwnerH != 0) {
              // Fire Damage赂娄 脌脭麓脗麓脵.
              switch (cOwnerType) {

              case DEF_OWNERTYPE_PLAYER:
                if (m_pClientList[sOwnerH] == 0)
                  break;
                if (m_pClientList[sOwnerH]->m_bIsKilled)
                  break;
                // v1.41 脕脽赂鲁脌脤掳铆 脌眉脜玫赂冒碌氓掳隆 戮脝麓脧赂茅
                // 脟脟脟脴赂娄 脌脭脕枚 戮脢麓脗麓脵.
                // if ((m_pClientList[sOwnerH]->m_bIsNeutral ) &&
                // (m_pClientList[sOwnerH]->m_sAppr2 & 0xF000) == 0) break;

                iDamage = iDice(1, 6);
                // New 17/05/2004
                if (m_pClientList[sOwnerH]->m_iAdminUserLevel == 0)
                  m_pClientList[sOwnerH]->m_iHP -= iDamage;

                if (m_pClientList[sOwnerH]->m_iHP <= 0) {
                  // 脟脙路鹿脌脤戮卯掳隆 禄莽赂脕脟脽麓脵.
                  ClientKilledHandler(sOwnerH, sOwnerH, cOwnerType, iDamage);
                } else {
                  if (iDamage > 0) {
                    // 鹿脼脌潞 麓毛鹿脤脕枚赂娄 脜毛潞赂脟脩麓脵. <- HP赂娄
                    // 卤脳麓毛路脦 戮脣赂掳麓脵.
                    SendNotifyMsg(0, sOwnerH, DEF_NOTIFY_HP, 0, 0, 0, 0);

                    if (m_pClientList[sOwnerH]
                            ->m_cMagicEffectStatus[DEF_MAGICTYPE_HOLDOBJECT] !=
                        0) {
                      // Hold-Person 碌脟戮卯 脌脰戮煤麓酶 禄贸脜脗露贸赂茅
                      // 脟庐赂掳麓脵. Fire Field路脦麓脗 脝脨路虏露贸脌脤脕卯
                      // 碌脠掳脥碌碌 脟庐赂掳麓脵. 1: Hold-Person 2: Paralize
                      SendNotifyMsg(
                          0, sOwnerH, DEF_NOTIFY_MAGICEFFECTOFF,
                          DEF_MAGICTYPE_HOLDOBJECT,
                          m_pClientList[sOwnerH]
                              ->m_cMagicEffectStatus[DEF_MAGICTYPE_HOLDOBJECT],
                          0, 0);

                      m_pClientList[sOwnerH]
                          ->m_cMagicEffectStatus[DEF_MAGICTYPE_HOLDOBJECT] = 0;
                      bRemoveFromDelayEventList(sOwnerH, DEF_OWNERTYPE_PLAYER,
                                                DEF_MAGICTYPE_HOLDOBJECT);
                    }
                  }
                }
                break;

              case DEF_OWNERTYPE_NPC:
                if (m_pNpcList[sOwnerH] == 0)
                  break;

                iDamage = iDice(1, 6);

                // 脌眉脌茂驴毛 卤赂脕露鹿掳脕脽 卤脳路拢碌氓 赂脜脕梅
                // 脕娄鲁脳路鹿脌脤脜脥, 驴隆鲁脢脕枚 陆脟碌氓
                // 脕娄鲁脳路鹿脌脤脜脥麓脗 脟脢碌氓路霉 赂露鹿媒驴隆
                // 麓毛鹿脤脕枚赂娄 脌脭脕枚 戮脢麓脗麓脵.
                switch (m_pNpcList[sOwnerH]->m_sType) {
                case 40: // ESG
                case 41: // GMG
                case 67: // McGaffin
                case 68: // Perry
                case 69: // Devlin
                  iDamage = 0;
                  break;
                }

                // HP驴隆录颅 禄芦麓脵. Action Limit驴隆 碌没露贸
                // 脙鲁赂庐脟脩麓脵.
                switch (m_pNpcList[sOwnerH]->m_cActionLimit) {
                case 0: // 脌脧鹿脻
                case 3: // 麓玫鹿脤路霉
                case 5: // 掳脟脙脿鹿掳
                  m_pNpcList[sOwnerH]->m_iHP -= iDamage;
                  break;
                }
                // if (m_pNpcList[sOwnerH]->m_cActionLimit == 0)
                //	m_pNpcList[sOwnerH]->m_iHP -= iDamage;

                if (m_pNpcList[sOwnerH]->m_iHP <= 0) {
                  // NPC掳隆 禄莽赂脕脟脽麓脵.
                  NpcKilledHandler(
                      sOwnerH, cOwnerType, sOwnerH,
                      0); // v1.2 脜赂录颅 脕脳脌赂赂茅 赂露脕枚赂路
                          // 麓毛鹿脤脕枚掳隆 0. 戮脝脌脤脜脹脌禄 陆卤掳脭
                          // 卤赂脟脧脕枚 赂酶脟脧掳脭 脟脧卤芒 脌搂脟脭.
                } else {
                  // Damage赂娄 脌脭脌潞 脙忙掳脻脌赂路脦 脌脦脟脩
                  // 脕枚驴卢脠驴掳煤.
                  if (iDice(1, 3) == 2)
                    m_pNpcList[sOwnerH]->m_dwTime = dwTime;

                  if (m_pNpcList[sOwnerH]
                          ->m_cMagicEffectStatus[DEF_MAGICTYPE_HOLDOBJECT] !=
                      0) {
                    // Hold 碌脟戮卯 脌脰戮煤麓酶 禄贸脜脗露贸赂茅 脟庐赂掳麓脵.
                    m_pNpcList[sOwnerH]
                        ->m_cMagicEffectStatus[DEF_MAGICTYPE_HOLDOBJECT] = 0;
                  }

                  // NPC赂娄 碌碌赂脕掳隆麓脗 赂冒碌氓路脦 脌眉脠炉陆脙脜虏麓脵.
                  SendEventToNearClient_TypeA(sOwnerH, DEF_OWNERTYPE_NPC,
                                              MSGID_EVENT_MOTION,
                                              DEF_OBJECTDAMAGE, iDamage, 0, 0);
                }
                break;
              }
            }

            // 脕脳脌潞脙麓脟脧掳铆 脌脰麓脗 脛鲁赂炉脌脤 脌脰麓脵赂茅
            m_pMapList[m_pDynamicObjectList[i]->m_cMapIndex]->GetDeadOwner(
                &sOwnerH, &cOwnerType, ix, iy);
            if ((cOwnerType == DEF_OWNERTYPE_PLAYER) &&
                (m_pClientList[sOwnerH] != 0) &&
                (m_pClientList[sOwnerH]->m_iHP > 0)) {
              // 脕脳脌潞 脙麓脟脧掳铆 脌脰麓脗 脟脙路鹿脌脤戮卯麓脵.
              iDamage = iDice(1, 6);
              m_pClientList[sOwnerH]->m_iHP -= iDamage;

              if (m_pClientList[sOwnerH]->m_iHP <= 0) {
                // 脟脙路鹿脌脤戮卯掳隆 禄莽赂脕脟脽麓脵.
                ClientKilledHandler(sOwnerH, sOwnerH, cOwnerType, iDamage);
              } else {
                if (iDamage > 0) {
                  // 鹿脼脌潞 麓毛鹿脤脕枚赂娄 脜毛潞赂脟脩麓脵. <- HP赂娄
                  // 卤脳麓毛路脦 戮脣赂掳麓脵.
                  SendNotifyMsg(0, sOwnerH, DEF_NOTIFY_HP, 0, 0, 0, 0);
                }
              }
            }

            // 卤脵脙鲁驴隆 Ice Object掳隆 脌脰麓脵赂茅 录枚赂铆脌禄
            // 脕脵脌脦麓脵.
            m_pMapList[m_pDynamicObjectList[i]->m_cMapIndex]->bGetDynamicObject(
                ix, iy, &sType, &dwRegisterTime, &iIndex);
            if ((sType == DEF_DYNAMICOBJECT_ICESTORM) &&
                (m_pDynamicObjectList[iIndex] != 0))
              m_pDynamicObjectList[iIndex]->m_dwLastTime =
                  m_pDynamicObjectList[iIndex]->m_dwLastTime -
                  (m_pDynamicObjectList[iIndex]->m_dwLastTime / 10);
          }
        break;
      }
    }
}

char _tmp_cCorpseX[] = {0, 1, 1, 1, 0, -1, -1, -1, 0, 0, 0, 0};
char _tmp_cCorpseY[] = {-1, -1, 0, 1, 1, 1, 0, -1, 0, 0, 0};

void CGame::ClearSkillUsingStatus(int iClientH) {
  int i;
  short tX, fX, tY, fY;

  if (m_pClientList[iClientH] == 0)
    return;

  if (m_pClientList[iClientH]->m_bSkillUsingStatus[19]) {
    tX = m_pClientList[iClientH]->m_sX;
    tY = m_pClientList[iClientH]->m_sY;
    if (m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->bGetMoveable(
            tX, tY, 0) == false) {
      fX = m_pClientList[iClientH]->m_sX +
           _tmp_cCorpseX[m_pClientList[iClientH]->m_cDir];
      fY = m_pClientList[iClientH]->m_sY +
           _tmp_cCorpseY[m_pClientList[iClientH]->m_cDir];
      if (m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->bGetMoveable(
              fX, fY, 0) == false) {
        m_pClientList[iClientH]->m_cDir = iDice(1, 8);
        fX = m_pClientList[iClientH]->m_sX +
             _tmp_cCorpseX[m_pClientList[iClientH]->m_cDir];
        fY = m_pClientList[iClientH]->m_sY +
             _tmp_cCorpseY[m_pClientList[iClientH]->m_cDir];
        if (m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->bGetMoveable(
                fX, fY, 0) == false) {
          return;
        }
      }
      SendNotifyMsg(0, iClientH, DEF_NOTIFY_DAMAGEMOVE,
                    m_pClientList[iClientH]->m_cDir, 0, 0, 0);
    }
  }
  for (i = 0; i < DEF_MAXSKILLTYPE; i++) {
    m_pClientList[iClientH]->m_bSkillUsingStatus[i] = false;
    m_pClientList[iClientH]->m_iSkillUsingTimeID[i] = 0;
  }

  if (m_pClientList[iClientH]->m_iAllocatedFish != 0) {
    if (m_pFish[m_pClientList[iClientH]->m_iAllocatedFish] != 0)
      m_pFish[m_pClientList[iClientH]->m_iAllocatedFish]->m_sEngagingCount--;

    m_pClientList[iClientH]->m_iAllocatedFish = 0;
    SendNotifyMsg(0, iClientH, DEF_NOTIFY_FISHCANCELED, 0, 0, 0, 0);
  }
}

int CGame::iCalculateUseSkillItemEffect(int iOwnerH, char cOwnerType,
                                        char cOwnerSkill, int iSkillNum,
                                        char cMapIndex, int dX, int dY) {
  class CItem *pItem;
  char cItemName[21];
  short lX, lY;
  int iResult, iFish;

  switch (cOwnerType) {
  case DEF_OWNERTYPE_PLAYER:
    if (m_pClientList[iOwnerH] == 0)
      return 0;
    if (m_pClientList[iOwnerH]->m_cMapIndex != cMapIndex)
      return 0;
    lX = m_pClientList[iOwnerH]->m_sX;
    lY = m_pClientList[iOwnerH]->m_sY;
    break;

  case DEF_OWNERTYPE_NPC:
    if (m_pNpcList[iOwnerH] == 0)
      return 0;
    if (m_pNpcList[iOwnerH]->m_cMapIndex != cMapIndex)
      return 0;
    lX = m_pNpcList[iOwnerH]->m_sX;
    lY = m_pNpcList[iOwnerH]->m_sY;
    break;
  }

  // 陆潞脜鲁 禄莽驴毛 驴漏潞脦 脕脰禄莽脌搂赂娄 卤录赂掳麓脵.
  if (cOwnerSkill == 0)
    return 0;

  // 陆潞脜鲁脌脤 100脌脤露贸掳铆 脟脴碌碌 掳隆虏没 鲁卢陆脙赂娄
  // 陆脟脝脨脟脧掳脭 脟脧卤芒 脌搂脟脴录颅 1D105
  iResult = iDice(1, 105);
  if (cOwnerSkill <= iResult)
    return 0; // 陆脟脝脨麓脵.

  // 露楼驴隆录颅麓脗 鲁卢陆脙掳隆 潞脪掳隆麓脡
  if (m_pMapList[cMapIndex]->bGetIsWater(dX, dY) == false)
    return 0;

  // 录潞掳酶脟脽脌赂鹿脟路脦 陆潞脜鲁 脛芦驴卯脝庐赂娄 驴脙赂掳麓脵.
  if (cOwnerType == DEF_OWNERTYPE_PLAYER)
    CalculateSSN_SkillIndex(iOwnerH, iSkillNum, 1);

  switch (m_pSkillConfigList[iSkillNum]->m_sType) {
  case DEF_SKILLEFFECTTYPE_TAMING:
    // 卤忙碌茅脌脤卤芒 卤芒录煤: dX, dY 潞脦卤脵脌脟 赂贸陆潞脜脥赂娄
    // 卤忙碌茅脌脦麓脵.
    _TamingHandler(iOwnerH, iSkillNum, cMapIndex, dX, dY);
    break;

  case DEF_SKILLEFFECTTYPE_GET:
    // 戮脝脌脤脜脹脌禄 戮貌麓脗 卤芒录煤脌脤戮煤麓脵.
    ZeroMemory(cItemName, sizeof(cItemName));
    switch (m_pSkillConfigList[iSkillNum]->m_sValue1) {
    case 1:
      // 卤陇鹿掳
      wsprintf(cItemName, "Meat");
      break;

    case 2:
      // 鹿掳掳铆卤芒
      // 鲁卢陆脙脌脟 掳忙驴矛 脌搂脛隆驴脥 陆脙掳拢麓毛脌脟 驴碌脟芒驴隆
      // 碌没露贸 露脟 录潞掳酶路眉脌脤 麓脼露贸脕酶麓脵.
      // if (m_pMapList[cMapIndex]->bGetIsWater(dX, dY) == false) return 0;

      // 卤脵脙鲁驴隆 麓脵脌脤鲁陋鹿脥 驴脌潞锚脕搂脝庐 鹿掳掳铆卤芒掳隆
      // 脕赂脌莽脟脩麓脵赂茅 潞禄掳脻鲁卢陆脙 赂冒碌氓路脦 碌茅戮卯掳拢麓脵.
      if (cOwnerType == DEF_OWNERTYPE_PLAYER) {
        iFish = iCheckFish(iOwnerH, cMapIndex, dX, dY);
        if (iFish == 0)
          wsprintf(cItemName, "Fish");
      } else
        wsprintf(cItemName, "Fish");
      break;
    }

    if (strlen(cItemName) != 0) {

      // 鲁卢陆脙驴隆 录潞掳酶脟脽麓脵赂茅 赂脼陆脙脕枚赂娄 脌眉录脹.
      if (memcmp(cItemName, "Fish", 6) == 0) {
        SendNotifyMsg(0, iOwnerH, DEF_NOTIFY_FISHSUCCESS, 0, 0, 0, 0);
        // v1.41 戮脿掳拢脌脟 掳忙脟猫脛隆 禄贸陆脗
        m_pClientList[iOwnerH]->m_iExpStock += iDice(1, 2);
      }

      pItem = new class CItem;
      if (pItem == 0)
        return 0;
      if (_bInitItemAttr(pItem, cItemName)) {
        // 戮脝脌脤脜脹脌禄 鲁玫麓脗麓脵.
        m_pMapList[cMapIndex]->bSetItem(lX, lY, pItem);

        // 麓脵赂楼 脜卢露贸脌脤戮冒脝庐驴隆掳脭 戮脝脌脤脜脹脌脤 露鲁戮卯脕酶
        // 掳脥脌禄 戮脣赂掳麓脵.
        SendEventToNearClient_TypeB(MSGID_EVENT_COMMON, DEF_COMMONTYPE_ITEMDROP,
                                    cMapIndex, lX, lY, pItem->m_sIDnum, 0,
                                    pItem->m_cItemColor,
                                    pItem->m_dwAttribute); // v1.4
      }
    }
    break;
  }

  return 1;
}

void CGame::UseSkillHandler(int iClientH, int iV1, int iV2, int iV3) {
  char cOwnerType;
  short sAttackerWeapon, sOwnerH;
  int iResult, iPlayerSkillLevel;

  if (m_pClientList[iClientH] == 0)
    return;
  if (m_pClientList[iClientH]->m_bIsInitComplete == false)
    return;

  if ((iV1 < 0) || (iV1 >= DEF_MAXSKILLTYPE))
    return;
  if (m_pSkillConfigList[iV1] == 0)
    return;
  // 脌脤鹿脤 卤芒录煤脌禄 禄莽驴毛脕脽脌脤露贸碌碌 赂庐脜脧.
  if (m_pClientList[iClientH]->m_bSkillUsingStatus[iV1])
    return;

  // v1.3 !!1脟脴脜路 掳脡路炉鲁禄卤芒驴毛!
  /*
  if (iV1 != 19) {
          m_pClientList[iClientH]->m_iAbuseCount++;
          if ((m_pClientList[iClientH]->m_iAbuseCount % 30) == 0) {
                  wsprintf(G_cTxt, "(!) 脟脴脜路 驴毛脌脟脌脷(%s) Skill(%d)
  Tries(%d)",m_pClientList[iClientH]->m_cCharName, iV1,
  m_pClientList[iClientH]->m_iAbuseCount); PutLogFileList(G_cTxt);
          }
  }
  */

  // 脟脙路鹿脌脤戮卯脌脟 卤芒录煤录枚脕脴驴隆 碌没露贸 录潞掳酶驴漏潞脦赂娄
  // 掳猫禄锚脟脩麓脵.
  iPlayerSkillLevel = m_pClientList[iClientH]->m_cSkillMastery[iV1];
  iResult = iDice(1, 100);

  if (iResult > iPlayerSkillLevel) {
    // 陆脟脝脨麓脵.
    // 卤芒录煤 禄莽驴毛脌脤 脕脽脕枚 碌脟戮煤脌陆脌禄 戮脣赂掳麓脵.
    SendNotifyMsg(0, iClientH, DEF_NOTIFY_SKILLUSINGEND, 0, 0, 0, 0);
    return;
  }

  // iV1脌脤 卤芒录煤 鹿酶脠拢
  switch (m_pSkillConfigList[iV1]->m_sType) {
  case DEF_SKILLEFFECTTYPE_PRETEND:
    switch (m_pSkillConfigList[iV1]->m_sValue1) {
    case 1:
      // 脕脳脌潞脙麓脟脧卤芒 卤芒录煤脌脤麓脵.

      // v1.44 禄莽脜玫脌氓脌脤赂茅 脕脳脌潞脙麓脟脧卤芒 赂酶脟脩麓脵.
      if (m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->m_bIsFightZone) {
        SendNotifyMsg(0, iClientH, DEF_NOTIFY_SKILLUSINGEND, 0, 0, 0, 0);
        return;
      }

      // 赂赂戮脿 鹿脵麓脷驴隆 陆脙脙录掳隆 脌脰麓脵赂茅 脕脳脌潞脙麓
      // 脟脧卤芒赂娄 脟脪 录枚 戮酶麓脵.
      m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->GetDeadOwner(
          &sOwnerH, &cOwnerType, m_pClientList[iClientH]->m_sX,
          m_pClientList[iClientH]->m_sY);
      if (sOwnerH != 0) {
        // 脕脳脌潞脙麓 脟脧卤芒赂娄 脟脪 脌脷赂庐驴隆 陆脙脙录掳隆 脌脰戮卯
        // 卤芒录煤 禄莽驴毛脌脤 脕脽脕枚 碌脟戮煤脌陆脌禄 戮脣赂掳麓脵.
        SendNotifyMsg(0, iClientH, DEF_NOTIFY_SKILLUSINGEND, 0, 0, 0, 0);
        return;
      }

      // 脕脳脌潞脙麓 脟脧掳铆脌脷 脟脧麓脗 脕脰潞炉驴隆 鹿掳脙录掳隆
      // 脌脰戮卯碌碌 脟脪 录枚 戮酶麓脵.
      iResult = 0;
      if (m_pClientList[iClientH]->m_iAdminUserLevel <= 0) {
        m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->GetOwner(
            &sOwnerH, &cOwnerType, m_pClientList[iClientH]->m_sX,
            m_pClientList[iClientH]->m_sY - 1);
        iResult += sOwnerH;
        m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->GetOwner(
            &sOwnerH, &cOwnerType, m_pClientList[iClientH]->m_sX,
            m_pClientList[iClientH]->m_sY + 1);
        iResult += sOwnerH;
        m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->GetOwner(
            &sOwnerH, &cOwnerType, m_pClientList[iClientH]->m_sX - 1,
            m_pClientList[iClientH]->m_sY);
        iResult += sOwnerH;
        m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->GetOwner(
            &sOwnerH, &cOwnerType, m_pClientList[iClientH]->m_sX + 1,
            m_pClientList[iClientH]->m_sY);
        iResult += sOwnerH;

        m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->GetOwner(
            &sOwnerH, &cOwnerType, m_pClientList[iClientH]->m_sX - 1,
            m_pClientList[iClientH]->m_sY - 1);
        iResult += sOwnerH;
        m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->GetOwner(
            &sOwnerH, &cOwnerType, m_pClientList[iClientH]->m_sX + 1,
            m_pClientList[iClientH]->m_sY - 1);
        iResult += sOwnerH;
        m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->GetOwner(
            &sOwnerH, &cOwnerType, m_pClientList[iClientH]->m_sX - 1,
            m_pClientList[iClientH]->m_sY + 1);
        iResult += sOwnerH;
        m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->GetOwner(
            &sOwnerH, &cOwnerType, m_pClientList[iClientH]->m_sX + 1,
            m_pClientList[iClientH]->m_sY + 1);
        iResult += sOwnerH;
      }

      if (iResult != 0) {
        // 脕脳脌潞脙麓 脟脧卤芒赂娄 脟脪 脌脷赂庐驴隆 陆脙脙录掳隆 脌脰戮卯
        // 卤芒录煤 禄莽驴毛脌脤 脕脽脕枚 碌脟戮煤脌陆脌禄 戮脣赂掳麓脵.
        SendNotifyMsg(0, iClientH, DEF_NOTIFY_SKILLUSINGEND, 0, 0, 0, 0);
        return;
      }

      // 陆潞脜鲁 脛芦驴卯脝庐 驴脙赂掳麓脵. <-- 鲁禄潞脦驴隆录颅
      // 脛芦驴卯脝脙脌禄 脟脴戮脽 戮没露脳脟脩 陆潞脜鲁脌脤 驴脌赂拢麓脗
      // 掳忙驴矛掳隆 戮酶麓脵.
      CalculateSSN_SkillIndex(iClientH, iV1, 1);

      // 麓脵赂楼 脜卢露贸脌脤戮冒脝庐驴隆掳脭 脕脳麓脗 碌驴脌脹 脌眉录脹.
      sAttackerWeapon = 1;
      SendEventToNearClient_TypeA(iClientH, DEF_OWNERTYPE_PLAYER,
                                  MSGID_EVENT_MOTION, DEF_OBJECTDYING, 0,
                                  sAttackerWeapon, 0);
      // 脕陇禄贸 脌搂脛隆驴隆录颅 脕枚驴卯麓脵.
      m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->ClearOwner(
          14, iClientH, DEF_OWNERTYPE_PLAYER, m_pClientList[iClientH]->m_sX,
          m_pClientList[iClientH]->m_sY);
      // 脕脳脌潞 脌搂脛隆 脟楼陆脙赂娄 脟脩麓脵.
      m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->SetDeadOwner(
          iClientH, DEF_OWNERTYPE_PLAYER, m_pClientList[iClientH]->m_sX,
          m_pClientList[iClientH]->m_sY);
      break;
    }
    break;
  }

  m_pClientList[iClientH]->m_bSkillUsingStatus[iV1] = true;
}

void CGame::ReqSellItemHandler(int iClientH, char cItemID, char cSellToWhom,
                               int iNum, char *pItemName) {
  char cItemCategory, cItemName[21];
  short sRemainLife;
  int iPrice;
  double d1, d2, d3;
  bool bNeutral;
  DWORD dwSWEType, dwSWEValue, dwAddPrice1, dwAddPrice2, dwMul1, dwMul2;
  CItem *m_pGold;

  // 禄莽驴毛脌脷脌脟 戮脝脌脤脜脹 脝脠卤芒 驴盲卤赂.
  if (m_pClientList[iClientH] == 0)
    return;
  if (m_pClientList[iClientH]->m_bIsInitComplete == false)
    return;
  if ((cItemID < 0) || (cItemID >= 50))
    return;
  if (m_pClientList[iClientH]->m_pItemList[cItemID] == 0)
    return;
  if (iNum <= 0)
    return;
  if (m_pClientList[iClientH]->m_pItemList[cItemID]->m_dwCount < iNum)
    return;

  iCalcTotalWeight(iClientH);

  m_pGold = new class CItem;
  ZeroMemory(cItemName, sizeof(cItemName));
  wsprintf(cItemName, "Gold");
  _bInitItemAttr(m_pGold, cItemName);

  // v1.42
  bNeutral = false;
  if (memcmp(m_pClientList[iClientH]->m_cLocation, "NONE", 4) == 0)
    bNeutral = true;
  // v2.13 录潞脠脛麓脧 录枚脕陇 鹿掳掳脟脌禄 戮卯碌冒录颅鲁陋 脝脠掳脭
  // 录枚脕陇脟脧驴漏录颅 脝脠露搂麓脗 NPC 卤赂潞脨脌脤 脟脢驴盲戮酶麓脵. 麓脺
  // 脛芦脜脳掳铆赂庐赂娄 卤芒脕脴脌赂路脦 戮脝脌脤脜脹 掳隆掳脻脌禄
  // 掳谩脕陇脟脩麓脵.
  switch (cSellToWhom) {
  case 15: // 禄贸脕隆 戮脝脕脺赂露
  case 24: // 麓毛脌氓掳拢 脕脰脌脦
    cItemCategory = m_pClientList[iClientH]->m_pItemList[cItemID]->m_cCategory;
    // 12-22 录潞脠脛麓脧 录枚脕陇 戮卯碌冒录颅碌莽 脝脠录枚 脌脰掳脭 录枚脕陇
    // 禄贸脕隆戮脝脌脤脜脹
    if ((cItemCategory >= 11) && (cItemCategory <= 50)) {

      // 脌没脟脮脟脧麓脵. 鹿芦脕露掳脟 鹿脻掳陋
      iPrice =
          (m_pClientList[iClientH]->m_pItemList[cItemID]->m_wPrice / 2) * iNum;
      sRemainLife =
          m_pClientList[iClientH]->m_pItemList[cItemID]->m_wCurLifeSpan;

      // v1.42 脕脽赂鲁脌脦 掳忙驴矛 鹿脻脌脟 鹿脻掳陋.
      if (bNeutral)
        iPrice = iPrice / 2;
      if (iPrice <= 0)
        iPrice = 1;
      if (iPrice > 1000000)
        iPrice = 1000000;

      if (m_pClientList[iClientH]->m_iCurWeightLoad +
              iGetItemWeight(m_pGold, iPrice) >
          (DWORD)_iCalcMaxLoad(iClientH)) {
        // v2.12 脝脠 掳忙驴矛 鹿芦掳脭掳隆 脙脢掳煤碌脟戮卯录颅 脝脠 录枚
        // 戮酶麓脵.
        SendNotifyMsg(0, iClientH, DEF_NOTIFY_CANNOTSELLITEM, cItemID, 4, 0,
                      m_pClientList[iClientH]->m_pItemList[cItemID]->m_cName);
      } else
        SendNotifyMsg(
            0, iClientH, DEF_NOTIFY_SELLITEMPRICE, cItemID, sRemainLife, iPrice,
            m_pClientList[iClientH]->m_pItemList[cItemID]->m_cName, iNum);
    }
    // 麓毛脌氓掳拢 戮脝脌脤脜脹
    else if ((cItemCategory >= 1) && (cItemCategory <= 10)) {
      // 驴酶路隆 戮脝脌脤脜脹脌脟 录枚赂铆掳煤 潞帽卤鲁脟脴录颅 掳篓掳隆
      // 禄贸掳垄脌禄 掳猫禄锚, 戮脝脌脤脜脹脌脟 掳隆掳脻脌禄 赂脜卤盲麓脵.
      sRemainLife =
          m_pClientList[iClientH]->m_pItemList[cItemID]->m_wCurLifeSpan;

      if (sRemainLife == 0) {
        // 掳铆脌氓鲁颅 戮脝脌脤脜脹脌潞 脝脠 录枚 戮酶麓脵
        SendNotifyMsg(0, iClientH, DEF_NOTIFY_CANNOTSELLITEM, cItemID, 2, 0,
                      m_pClientList[iClientH]->m_pItemList[cItemID]->m_cName);
      } else {
        d1 = (double)sRemainLife;
        if (m_pClientList[iClientH]->m_pItemList[cItemID]->m_wMaxLifeSpan != 0)
          d2 = (double)m_pClientList[iClientH]
                   ->m_pItemList[cItemID]
                   ->m_wMaxLifeSpan;
        else
          d2 = 1.0f;
        d3 = (d1 / d2) * 0.5f;
        d2 = (double)m_pClientList[iClientH]
                 ->m_pItemList[cItemID]
                 ->m_wPrice; // 驴酶路隆 掳隆掳脻
        d3 = d3 * d2;        // 脙脽禄锚碌脠 掳隆掳脻

        iPrice = (int)d3;
        iPrice = iPrice * iNum;

        dwAddPrice1 = 0;
        dwAddPrice2 = 0;
        // 戮脝脌脤脜脹 脝炉录潞脛隆驴隆 碌没赂楼 掳隆掳脻 禄贸陆脗
        if ((m_pClientList[iClientH]->m_pItemList[cItemID]->m_dwAttribute &
             0x00F00000) != 0) {
          dwSWEType =
              (m_pClientList[iClientH]->m_pItemList[cItemID]->m_dwAttribute &
               0x00F00000) >>
              20;
          dwSWEValue =
              (m_pClientList[iClientH]->m_pItemList[cItemID]->m_dwAttribute &
               0x000F0000) >>
              16;

          switch (dwSWEType) {
          case 6:
            dwMul1 = 2;
            break; // 掳隆潞颅驴卯
          case 8:
            dwMul1 = 2;
            break; // 掳颅脠颅碌脠
          case 5:
            dwMul1 = 3;
            break; // 鹿脦脙赂脌脟
          case 1:
            dwMul1 = 4;
            break; // 脟脢禄矛脌脟
          case 7:
            dwMul1 = 5;
            break; // 驴鹿赂庐脟脩
          case 2:
            dwMul1 = 6;
            break; // 脕脽碌露脌脟
          case 3:
            dwMul1 = 15;
            break; // 脕陇脌脟脌脟
          case 9:
            dwMul1 = 20;
            break; // 掳铆麓毛鹿庐赂铆
          default:
            dwMul1 = 1;
            break;
          }

          d1 = (double)iPrice * dwMul1;
          switch (dwSWEValue) {
          case 1:
            d2 = 10.0f;
            break;
          case 2:
            d2 = 20.0f;
            break;
          case 3:
            d2 = 30.0f;
            break;
          case 4:
            d2 = 35.0f;
            break;
          case 5:
            d2 = 40.0f;
            break;
          case 6:
            d2 = 50.0f;
            break;
          case 7:
            d2 = 100.0f;
            break;
          case 8:
            d2 = 200.0f;
            break;
          case 9:
            d2 = 300.0f;
            break;
          case 10:
            d2 = 400.0f;
            break;
          case 11:
            d2 = 500.0f;
            break;
          case 12:
            d2 = 700.0f;
            break;
          case 13:
            d2 = 900.0f;
            break;
          default:
            d2 = 0.0f;
            break;
          }
          d3 = d1 * (d2 / 100.0f);

          dwAddPrice1 = (int)(d1 + d3);
        }

        // v1.42 脠帽卤脥 戮脝脌脤脜脹脌脤露贸赂茅 Sub 脠驴掳煤赂娄
        // 录鲁脕陇脟脩麓脵. 掳酶掳脻鹿芦卤芒麓脗 1掳鲁赂赂 脌氓脗酶碌脠麓脵掳铆
        // 脟脽脌禄露搂赂赂 脌炉脠驴脟脭.
        if ((m_pClientList[iClientH]->m_pItemList[cItemID]->m_dwAttribute &
             0x0000F000) != 0) {
          dwSWEType =
              (m_pClientList[iClientH]->m_pItemList[cItemID]->m_dwAttribute &
               0x0000F000) >>
              12;
          dwSWEValue =
              (m_pClientList[iClientH]->m_pItemList[cItemID]->m_dwAttribute &
               0x00000F00) >>
              8;

          switch (dwSWEType) {
          case 1:
          case 12:
            dwMul2 = 2;
            break;

          case 2:
          case 3:
          case 4:
          case 5:
          case 6:
          case 7:
            dwMul2 = 4;
            break;

          case 8:
          case 9:
          case 10:
          case 11:
            dwMul2 = 6;
            break;
          }

          d1 = (double)iPrice * dwMul2;
          switch (dwSWEValue) {
          case 1:
            d2 = 10.0f;
            break;
          case 2:
            d2 = 20.0f;
            break;
          case 3:
            d2 = 30.0f;
            break;
          case 4:
            d2 = 35.0f;
            break;
          case 5:
            d2 = 40.0f;
            break;
          case 6:
            d2 = 50.0f;
            break;
          case 7:
            d2 = 100.0f;
            break;
          case 8:
            d2 = 200.0f;
            break;
          case 9:
            d2 = 300.0f;
            break;
          case 10:
            d2 = 400.0f;
            break;
          case 11:
            d2 = 500.0f;
            break;
          case 12:
            d2 = 700.0f;
            break;
          case 13:
            d2 = 900.0f;
            break;
          default:
            d2 = 0.0f;
            break;
          }
          d3 = d1 * (d2 / 100.0f);

          dwAddPrice2 = (int)(d1 + d3);
        }

        // v2.03 925 脝炉录枚 戮脝脌脤脜脹 掳隆掳脻 掳隆脕脽脛隆赂娄
        // 77%录枚脕脴脌赂路脦 麓脵驴卯
        iPrice = iPrice + (dwAddPrice1 - (dwAddPrice1 / 3)) +
                 (dwAddPrice2 - (dwAddPrice2 / 3));

        // v1.42 脕脽赂鲁脌脦 掳忙驴矛 鹿脻脌脟 鹿脻掳陋.
        if (bNeutral)
          iPrice = iPrice / 2;
        if (iPrice <= 0)
          iPrice = 1;
        if (iPrice > 1000000)
          iPrice = 1000000;

        if (m_pClientList[iClientH]->m_iCurWeightLoad +
                iGetItemWeight(m_pGold, iPrice) >
            (DWORD)_iCalcMaxLoad(iClientH)) {
          // v2.12 脝脠 掳忙驴矛 鹿芦掳脭掳隆 脙脢掳煤碌脟戮卯录颅 脝脠 录枚
          // 戮酶麓脵.
          SendNotifyMsg(0, iClientH, DEF_NOTIFY_CANNOTSELLITEM, cItemID, 4, 0,
                        m_pClientList[iClientH]->m_pItemList[cItemID]->m_cName);
        } else
          SendNotifyMsg(0, iClientH, DEF_NOTIFY_SELLITEMPRICE, cItemID,
                        sRemainLife, iPrice,
                        m_pClientList[iClientH]->m_pItemList[cItemID]->m_cName,
                        iNum);
      }
    } else
      SendNotifyMsg(0, iClientH, DEF_NOTIFY_CANNOTSELLITEM, cItemID, 1, 0,
                    m_pClientList[iClientH]->m_pItemList[cItemID]->m_cName);
    break;

  default:
    break;
  }
  if (m_pGold != 0)
    delete m_pGold;
}

void CGame::ReqSellItemConfirmHandler(int iClientH, char cItemID, int iNum,
                                      char *pString) {
  class CItem *pItemGold;
  short sRemainLife;
  int iPrice;
  double d1, d2, d3;
  char *cp, cItemName[21], cData[120], cItemCategory;
  DWORD *dwp, dwMul1, dwMul2, dwSWEType, dwSWEValue, dwAddPrice1, dwAddPrice2;
  WORD *wp;
  int iEraseReq, iRet;
  short *sp;
  bool bNeutral;

  // 戮脝脌脤脜脹脌禄 脝脠掳脷麓脵麓脗 掳脥脌脤 掳谩脕陇碌脟戮煤麓脵.
  if (m_pClientList[iClientH] == 0)
    return;
  if (m_pClientList[iClientH]->m_bIsInitComplete == false)
    return;
  if ((cItemID < 0) || (cItemID >= 50))
    return;
  if (m_pClientList[iClientH]->m_pItemList[cItemID] == 0)
    return;
  if (iNum <= 0)
    return;
  if (m_pClientList[iClientH]->m_pItemList[cItemID]->m_dwCount < iNum)
    return;

  // New 18/05/2004
  if (m_pClientList[iClientH]->m_pIsProcessingAllowed == false)
    return;

  iCalcTotalWeight(iClientH);
  cItemCategory = m_pClientList[iClientH]->m_pItemList[cItemID]->m_cCategory;

  // v1.42
  bNeutral = false;
  if (memcmp(m_pClientList[iClientH]->m_cLocation, "NONE", 4) == 0)
    bNeutral = true;

  iPrice = 0;
  // 戮脝脌脤脜脹脌脟 脕戮路霉驴隆 碌没露贸 掳隆掳脻 掳猫禄锚.
  if ((cItemCategory >= 1) && (cItemCategory <= 10)) {
    // 鹿芦卤芒路霉麓脵
    // 驴酶路隆 戮脝脌脤脜脹脌脟 录枚赂铆掳煤 潞帽卤鲁脟脴录颅 掳篓掳隆
    // 禄贸掳垄脌禄 掳猫禄锚, 戮脝脌脤脜脹脌脟 掳隆掳脻脌禄 赂脜卤盲麓脵.
    sRemainLife = m_pClientList[iClientH]->m_pItemList[cItemID]->m_wCurLifeSpan;

    if (sRemainLife <= 0) {
      // 赂脕掳隆脕酶 戮脝脌脤脜脹脌潞 脝脠脕枚 赂酶脟脩麓脵.
      return;
    } else {
      d1 = (double)sRemainLife;
      if (m_pClientList[iClientH]->m_pItemList[cItemID]->m_wMaxLifeSpan != 0)
        d2 = (double)m_pClientList[iClientH]
                 ->m_pItemList[cItemID]
                 ->m_wMaxLifeSpan;
      else
        d2 = 1.0f;
      d3 = (d1 / d2) * 0.5f;
      d2 = (double)m_pClientList[iClientH]
               ->m_pItemList[cItemID]
               ->m_wPrice; // 驴酶路隆 掳隆掳脻
      d3 = d3 * d2;        // 脙脽禄锚碌脠 掳隆掳脻

      iPrice = (short)d3;
      iPrice = iPrice * iNum;

      dwAddPrice1 = 0;
      dwAddPrice2 = 0;
      // 戮脝脌脤脜脹 脝炉录潞脛隆驴隆 碌没赂楼 掳隆掳脻 禄贸陆脗
      if ((m_pClientList[iClientH]->m_pItemList[cItemID]->m_dwAttribute &
           0x00F00000) != 0) {
        dwSWEType =
            (m_pClientList[iClientH]->m_pItemList[cItemID]->m_dwAttribute &
             0x00F00000) >>
            20;
        dwSWEValue =
            (m_pClientList[iClientH]->m_pItemList[cItemID]->m_dwAttribute &
             0x000F0000) >>
            16;

        // 脠帽卤脥 戮脝脌脤脜脹 脠驴掳煤 脕戮路霉:
        // 0-None 1-脟脢禄矛卤芒麓毛鹿脤脕枚脙脽掳隆 2-脕脽碌露脠驴掳煤
        // 3-脕陇脌脟脌脟 4-脌煤脕脰脌脟 5-鹿脦脙赂脌脟 6-掳隆潞颅驴卯
        // 7-驴鹿赂庐脟脩 8-掳颅脠颅碌脠 9-掳铆麓毛鹿庐赂铆脌脟
        switch (dwSWEType) {
        case 6:
          dwMul1 = 2;
          break; // 掳隆潞颅驴卯
        case 8:
          dwMul1 = 2;
          break; // 掳颅脠颅碌脠
        case 5:
          dwMul1 = 3;
          break; // 鹿脦脙赂脌脟
        case 1:
          dwMul1 = 4;
          break; // 脟脢禄矛脌脟
        case 7:
          dwMul1 = 5;
          break; // 驴鹿赂庐脟脩
        case 2:
          dwMul1 = 6;
          break; // 脕脽碌露脌脟
        case 3:
          dwMul1 = 15;
          break; // 脕陇脌脟脌脟
        case 9:
          dwMul1 = 20;
          break; // 掳铆麓毛鹿庐赂铆
        default:
          dwMul1 = 1;
          break;
        }

        d1 = (double)iPrice * dwMul1;
        switch (dwSWEValue) {
        case 1:
          d2 = 10.0f;
          break;
        case 2:
          d2 = 20.0f;
          break;
        case 3:
          d2 = 30.0f;
          break;
        case 4:
          d2 = 35.0f;
          break;
        case 5:
          d2 = 40.0f;
          break;
        case 6:
          d2 = 50.0f;
          break;
        case 7:
          d2 = 100.0f;
          break;
        case 8:
          d2 = 200.0f;
          break;
        case 9:
          d2 = 300.0f;
          break;
        case 10:
          d2 = 400.0f;
          break;
        case 11:
          d2 = 500.0f;
          break;
        case 12:
          d2 = 700.0f;
          break;
        case 13:
          d2 = 900.0f;
          break;
        default:
          d2 = 0.0f;
          break;
        }
        d3 = d1 * (d2 / 100.0f);
        dwAddPrice1 = (int)(d1 + d3);
      }

      // v1.42 脠帽卤脥 戮脝脌脤脜脹脌脤露贸赂茅 Sub 脠驴掳煤赂娄
      // 录鲁脕陇脟脩麓脵. 掳酶掳脻鹿芦卤芒麓脗 1掳鲁赂赂 脌氓脗酶碌脠麓脵掳铆
      // 脟脽脌禄露搂赂赂 脌炉脠驴脟脭.
      if ((m_pClientList[iClientH]->m_pItemList[cItemID]->m_dwAttribute &
           0x0000F000) != 0) {
        dwSWEType =
            (m_pClientList[iClientH]->m_pItemList[cItemID]->m_dwAttribute &
             0x0000F000) >>
            12;
        dwSWEValue =
            (m_pClientList[iClientH]->m_pItemList[cItemID]->m_dwAttribute &
             0x00000F00) >>
            8;

        // 脠帽卤脥 戮脝脌脤脜脹 脠驴掳煤 脕戮路霉:
        // 脙脽掳隆 碌露录潞脌煤脟脳(1), 脙脽掳隆 赂铆脕脽掳陋(2), 脙脽掳隆
        // 鹿忙戮卯掳陋(3), HP 脠赂潞鹿路庐 脙脽掳隆(4), SP 脠赂潞鹿路庐
        // 脙脽掳隆(5) MP 脠赂潞鹿路庐 脙脽掳隆(6), 脙脽掳隆
        // 赂露鹿媒脌煤脟脳(7), 鹿掳赂庐 麓毛鹿脤脕枚 脠铆录枚(8), 赂露鹿媒
        // 麓毛鹿脤脕枚 脠铆录枚(9) 驴卢脜赂 麓毛鹿脤脕枚 脙脽掳隆(10), 麓玫
        // 赂鹿脌潞 掳忙脟猫脛隆(11), 麓玫赂鹿脌潞 Gold(12)
        switch (dwSWEType) {
        case 1:
        case 12:
          dwMul2 = 2;
          break;

        case 2:
        case 3:
        case 4:
        case 5:
        case 6:
        case 7:
          dwMul2 = 4;
          break;

        case 8:
        case 9:
        case 10:
        case 11:
          dwMul2 = 6;
          break;
        }

        d1 = (double)iPrice * dwMul2;
        switch (dwSWEValue) {
        case 1:
          d2 = 10.0f;
          break;
        case 2:
          d2 = 20.0f;
          break;
        case 3:
          d2 = 30.0f;
          break;
        case 4:
          d2 = 35.0f;
          break;
        case 5:
          d2 = 40.0f;
          break;
        case 6:
          d2 = 50.0f;
          break;
        case 7:
          d2 = 100.0f;
          break;
        case 8:
          d2 = 200.0f;
          break;
        case 9:
          d2 = 300.0f;
          break;
        case 10:
          d2 = 400.0f;
          break;
        case 11:
          d2 = 500.0f;
          break;
        case 12:
          d2 = 700.0f;
          break;
        case 13:
          d2 = 900.0f;
          break;
        default:
          d2 = 0.0f;
          break;
        }
        d3 = d1 * (d2 / 100.0f);
        dwAddPrice2 = (int)(d1 + d3);
      }

      iPrice = iPrice + (dwAddPrice1 - (dwAddPrice1 / 3)) +
               (dwAddPrice2 - (dwAddPrice2 / 3));

      // v1.42 脕脽赂鲁脌脦 掳忙驴矛 鹿脻脌脟 鹿脻掳陋.
      if (bNeutral)
        iPrice = iPrice / 2;
      if (iPrice <= 0)
        iPrice = 1;
      if (iPrice > 1000000)
        iPrice = 1000000; // New 06/05/2004

      // 戮脝脌脤脜脹脌禄 脝脠戮脪麓脵麓脗 赂脼陆脙脕枚 脌眉录脹
      // (麓脵脌脤戮贸路脦卤脳 鹿脷陆潞 潞帽脠掳录潞脠颅驴毛)
      SendNotifyMsg(0, iClientH, DEF_NOTIFY_ITEMSOLD, cItemID, 0, 0, 0);

      _bItemLog(DEF_ITEMLOG_SELL, iClientH, (int)-1,
                m_pClientList[iClientH]->m_pItemList[cItemID]);

      // 脝脠 戮脝脌脤脜脹脌禄 禄猫脕娄
      if ((m_pClientList[iClientH]->m_pItemList[cItemID]->m_cItemType ==
           DEF_ITEMTYPE_CONSUME) ||
          (m_pClientList[iClientH]->m_pItemList[cItemID]->m_cItemType ==
           DEF_ITEMTYPE_ARROW)) {
        // 录枚路庐 掳鲁鲁盲脌脤 脌脰麓脵赂茅 掳鹿录枚赂娄 脕脵脌脦麓脵.
        // v1.41 !!!
        SetItemCount(iClientH, cItemID,
                     m_pClientList[iClientH]->m_pItemList[cItemID]->m_dwCount -
                         iNum);
      } else
        ItemDepleteHandler(iClientH, cItemID, false);
    }
  } else if ((cItemCategory >= 11) && (cItemCategory <= 50)) {
    // 陆脛脟掳, 脌芒脠颅碌卯脌脟 鹿脻掳陋鹿掳掳脟碌茅
    iPrice = m_pClientList[iClientH]->m_pItemList[cItemID]->m_wPrice / 2;
    iPrice = iPrice * iNum;

    // v1.42 脕脽赂鲁脌脦 掳忙驴矛 鹿脻脌脟 鹿脻掳陋.
    if (bNeutral)
      iPrice = iPrice / 2;
    if (iPrice <= 0)
      iPrice = 1;
    if (iPrice > 1000000)
      iPrice = 1000000; // New 06/05/2004

    // 戮脝脌脤脜脹脌禄 脝脠戮脪麓脵麓脗 赂脼陆脙脕枚 脌眉录脹
    // (麓脵脌脤戮贸路脦卤脳 鹿脷陆潞 潞帽脠掳录潞脠颅驴毛)
    SendNotifyMsg(0, iClientH, DEF_NOTIFY_ITEMSOLD, cItemID, 0, 0, 0);

    _bItemLog(DEF_ITEMLOG_SELL, iClientH, (int)-1,
              m_pClientList[iClientH]->m_pItemList[cItemID]);

    // 戮脝脌脤脜脹脌脟 脕戮路霉驴隆 碌没露贸 脌没脌媒脟脩 脙鲁赂庐赂娄
    // 脟脩麓脵.
    if ((m_pClientList[iClientH]->m_pItemList[cItemID]->m_cItemType ==
         DEF_ITEMTYPE_CONSUME) ||
        (m_pClientList[iClientH]->m_pItemList[cItemID]->m_cItemType ==
         DEF_ITEMTYPE_ARROW)) {
      // 录枚路庐 掳鲁鲁盲脌脤 脌脰麓脵赂茅 掳鹿录枚赂娄 脕脵脌脦麓脵.
      // v1.41 !!!
      SetItemCount(iClientH, cItemID,
                   m_pClientList[iClientH]->m_pItemList[cItemID]->m_dwCount -
                       iNum);
    } else
      ItemDepleteHandler(iClientH, cItemID, false);
  }

  // Gold赂娄 脕玫掳隆陆脙脜虏麓脵. 赂赂戮脿 脝脟 掳隆掳脻脌脤 0 脠陇脌潞
  // 赂露脌脤鲁脢陆潞脌脤赂茅 卤脻脌禄 脕脰脕枚 戮脢麓脗麓脵.
  if (iPrice <= 0)
    return;

  pItemGold = new class CItem;
  ZeroMemory(cItemName, sizeof(cItemName));
  wsprintf(cItemName, "Gold");
  _bInitItemAttr(pItemGold, cItemName);

  pItemGold->m_dwCount = iPrice;

  if (_bAddClientItemList(iClientH, pItemGold, &iEraseReq)) {
    // 戮脝脌脤脜脹脌禄 脠鹿碌忙脟脽麓脵.

    dwp = (DWORD *)(cData + DEF_INDEX4_MSGID);
    *dwp = MSGID_NOTIFY;
    wp = (WORD *)(cData + DEF_INDEX2_MSGTYPE);
    *wp = DEF_NOTIFY_ITEMOBTAINED;

    cp = (char *)(cData + DEF_INDEX2_MSGTYPE + 2);

    // 1掳鲁 脠鹿碌忙脟脽麓脵. <- 驴漏卤芒录颅 1掳鲁露玫 脛芦驴卯脝庐赂娄
    // 赂禄脟脧麓脗 掳脥脌脤 戮脝麓脧麓脵
    *cp = 1;
    cp++;

    memcpy(cp, pItemGold->m_cName, 20);
    cp += 20;

    dwp = (DWORD *)cp;
    *dwp = pItemGold->m_dwCount;
    cp += 4;

    *cp = pItemGold->m_cItemType;
    cp++;

    *cp = pItemGold->m_cEquipPos;
    cp++;

    *cp = (char)0; // 戮貌脌潞 戮脝脌脤脜脹脌脤鹿脟路脦 脌氓脗酶碌脟脕枚
                   // 戮脢戮脪麓脵.
    cp++;

    sp = (short *)cp;
    *sp = pItemGold->m_sLevelLimit;
    cp += 2;

    *cp = pItemGold->m_cGenderLimit;
    cp++;

    wp = (WORD *)cp;
    *wp = pItemGold->m_wCurLifeSpan;
    cp += 2;

    wp = (WORD *)cp;
    *wp = pItemGold->m_wWeight;
    cp += 2;

    sp = (short *)cp;
    *sp = pItemGold->m_sSprite;
    cp += 2;

    sp = (short *)cp;
    *sp = pItemGold->m_sSpriteFrame;
    cp += 2;

    *cp = pItemGold->m_cItemColor;
    cp++;

    *cp = (char)pItemGold->m_sItemSpecEffectValue2; // v1.41
    cp++;

    dwp = (DWORD *)cp;
    *dwp = pItemGold->m_dwAttribute;
    cp += 4;
    /*
    *cp = (char)(pItemGold->m_dwAttribute & 0x00000001); //
    Custom-Item脌脦脕枚脌脟 驴漏潞脦 cp++;
    */

    if (iEraseReq == 1)
      delete pItemGold;

    // 戮脝脌脤脜脹 脕陇潞赂 脌眉录脹
    iRet = m_pClientList[iClientH]->m_pXSock->iSendMsg(cData, 53);

    // 录脪脕枚脟掳 脙脩 脕脽路庐 脌莽 掳猫禄锚
    iCalcTotalWeight(iClientH);

    switch (iRet) {
    case DEF_XSOCKEVENT_QUENEFULL:
    case DEF_XSOCKEVENT_SOCKETERROR:
    case DEF_XSOCKEVENT_CRITICALERROR:
    case DEF_XSOCKEVENT_SOCKETCLOSED:
      // 赂脼陆脙脕枚赂娄 潞赂鲁戮露搂 驴隆路炉掳隆 鹿脽禄媒脟脽麓脵赂茅
      // 脕娄掳脜脟脩麓脵.
      DeleteClient(iClientH, true, true);
      break;
    }
  } else {
    // 脕脽路庐 脙脢掳煤碌卯脌脟 鹿庐脕娄路脦 脙脽掳隆 陆脟脝脨.
    // 鹿脼脕枚 赂酶脟脽脌赂鹿脟路脦 鹿脵麓脷驴隆 露鲁戮卯脕酶麓脵.
    m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->bSetItem(
        m_pClientList[iClientH]->m_sX, m_pClientList[iClientH]->m_sY,
        pItemGold);

    // 麓脵赂楼 脜卢露贸脌脤戮冒脝庐驴隆掳脭 戮脝脌脤脜脹脌脤 露鲁戮卯脕酶
    // 掳脥脌禄 戮脣赂掳麓脵.
    SendEventToNearClient_TypeB(
        MSGID_EVENT_COMMON, DEF_COMMONTYPE_ITEMDROP,
        m_pClientList[iClientH]->m_cMapIndex, m_pClientList[iClientH]->m_sX,
        m_pClientList[iClientH]->m_sY, pItemGold->m_sIDnum, 0,
        pItemGold->m_cItemColor, pItemGold->m_dwAttribute); // v1.4 color

    // 录脪脕枚脟掳 脙脩 脕脽路庐 脌莽 掳猫禄锚
    iCalcTotalWeight(iClientH);

    // 麓玫脌脤禄贸 掳隆脕煤录枚 戮酶麓脵麓脗 赂脼陆脙脕枚赂娄 潞赂鲁陆麓脵.
    dwp = (DWORD *)(cData + DEF_INDEX4_MSGID);
    *dwp = MSGID_NOTIFY;
    wp = (WORD *)(cData + DEF_INDEX2_MSGTYPE);
    *wp = DEF_NOTIFY_CANNOTCARRYMOREITEM;

    iRet = m_pClientList[iClientH]->m_pXSock->iSendMsg(cData, 6);
    switch (iRet) {
    case DEF_XSOCKEVENT_QUENEFULL:
    case DEF_XSOCKEVENT_SOCKETERROR:
    case DEF_XSOCKEVENT_CRITICALERROR:
    case DEF_XSOCKEVENT_SOCKETCLOSED:
      // 赂脼陆脙脕枚赂娄 潞赂鲁戮露搂 驴隆路炉掳隆 鹿脽禄媒脟脽麓脵赂茅
      // 脕娄掳脜脟脩麓脵.
      DeleteClient(iClientH, true, true);
      return;
    }
  }
}

void CGame::ReqRepairItemHandler(int iClientH, char cItemID, char cRepairWhom,
                                 char *pString) {
  char cItemCategory;
  short sRemainLife, sPrice;
  double d1, d2, d3;

  // 戮脝脌脤脜脹脌禄 掳铆脛隆掳脷麓脵麓脗 驴盲卤赂.
  if (m_pClientList[iClientH] == 0)
    return;
  if (m_pClientList[iClientH]->m_bIsInitComplete == false)
    return;
  if ((cItemID < 0) || (cItemID >= 50))
    return;
  if (m_pClientList[iClientH]->m_pItemList[cItemID] == 0)
    return;

  cItemCategory = m_pClientList[iClientH]->m_pItemList[cItemID]->m_cCategory;

  // 戮脝脌脤脜脹脌脟 脕戮路霉驴隆 碌没露贸 掳隆掳脻 掳猫禄锚.
  if ((cItemCategory >= 1) && (cItemCategory <= 10)) {
    // 鹿芦卤芒路霉麓脵

    // 赂赂戮脿 鹿芦卤芒赂娄 麓毛脌氓掳拢 脕脰脌脦脌脤 戮脝麓脩 脌脤驴隆掳脭
    // 掳铆脙脛麓脼露贸掳铆 脟脩麓脵赂茅 脟脪 录枚 戮酶麓脵.
    if (cRepairWhom != 24) {
      SendNotifyMsg(0, iClientH, DEF_NOTIFY_CANNOTREPAIRITEM, cItemID, 2, 0,
                    m_pClientList[iClientH]->m_pItemList[cItemID]->m_cName);
      return;
    }

    // 驴酶路隆 戮脝脌脤脜脹脌脟 录枚赂铆掳煤 潞帽卤鲁脟脴录颅 掳篓掳隆
    // 禄贸掳垄脌禄 掳猫禄锚, 戮脝脌脤脜脹脌脟 录枚赂庐 潞帽驴毛脌禄
    // 赂脜卤盲麓脵.
    sRemainLife = m_pClientList[iClientH]->m_pItemList[cItemID]->m_wCurLifeSpan;
    if (sRemainLife == 0) {
      // 驴脧脌眉脠梅 赂脕掳隆脕酶 掳脥脌脤露贸赂茅 驴酶路隆掳隆掳脻脌脟
      // 脌媒鹿脻脌脤 碌莽麓脵.
      sPrice = m_pClientList[iClientH]->m_pItemList[cItemID]->m_wPrice / 2;
    } else {
      d1 = (double)sRemainLife;
      if (m_pClientList[iClientH]->m_pItemList[cItemID]->m_wMaxLifeSpan != 0)
        d2 = (double)m_pClientList[iClientH]
                 ->m_pItemList[cItemID]
                 ->m_wMaxLifeSpan;
      else
        d2 = 1.0f;
      d3 = (d1 / d2) * 0.5f;
      d2 = (double)m_pClientList[iClientH]
               ->m_pItemList[cItemID]
               ->m_wPrice; // 驴酶路隆 掳隆掳脻
      d3 = d3 * d2;        // 脙脽禄锚碌脠 掳隆掳脻

      sPrice = (m_pClientList[iClientH]->m_pItemList[cItemID]->m_wPrice / 2) -
               (short)d3;
    }

    SendNotifyMsg(0, iClientH, DEF_NOTIFY_REPAIRITEMPRICE, cItemID, sRemainLife,
                  sPrice,
                  m_pClientList[iClientH]->m_pItemList[cItemID]->m_cName);
  } else if (((cItemCategory >= 43) && (cItemCategory <= 50)) ||
             ((cItemCategory >= 11) && (cItemCategory <= 12))) {
    // 鲁卢陆脙麓毛, 掳卯卤陋脌脤 碌卯掳煤 掳掳脌潞 潞帽鹿芦卤芒路霉
    // 录枚赂庐掳隆麓脡 戮脝脌脤脜脹. 驴脢, 潞脦脙梅路霉

    // 赂赂戮脿 禄贸脕隆 脕脰脌脦脌脤 戮脝麓脩 脌脤驴隆掳脭 掳铆脙脛麓脼露贸掳铆
    // 脟脩麓脵赂茅 脟脪 录枚 戮酶麓脵.
    if (cRepairWhom != 15) {
      SendNotifyMsg(0, iClientH, DEF_NOTIFY_CANNOTREPAIRITEM, cItemID, 2, 0,
                    m_pClientList[iClientH]->m_pItemList[cItemID]->m_cName);
      return;
    }

    // 驴酶路隆 戮脝脌脤脜脹脌脟 录枚赂铆掳煤 潞帽卤鲁脟脴录颅 掳篓掳隆
    // 禄贸掳垄脌禄 掳猫禄锚, 戮脝脌脤脜脹脌脟 录枚赂庐 潞帽驴毛脌禄
    // 赂脜卤盲麓脵.
    sRemainLife = m_pClientList[iClientH]->m_pItemList[cItemID]->m_wCurLifeSpan;
    if (sRemainLife == 0) {
      // 驴脧脌眉脠梅 赂脕掳隆脕酶 掳脥脌脤露贸赂茅 驴酶路隆掳隆掳脻脌脟
      // 脌媒鹿脻脌脤 碌莽麓脵.
      sPrice = m_pClientList[iClientH]->m_pItemList[cItemID]->m_wPrice / 2;
    } else {
      d1 = (double)sRemainLife;
      if (m_pClientList[iClientH]->m_pItemList[cItemID]->m_wMaxLifeSpan != 0)
        d2 = (double)m_pClientList[iClientH]
                 ->m_pItemList[cItemID]
                 ->m_wMaxLifeSpan;
      else
        d2 = 1.0f;
      d3 = (d1 / d2) * 0.5f;
      d2 = (double)m_pClientList[iClientH]
               ->m_pItemList[cItemID]
               ->m_wPrice; // 驴酶路隆 掳隆掳脻
      d3 = d3 * d2;        // 脙脽禄锚碌脠 掳隆掳脻

      sPrice = (m_pClientList[iClientH]->m_pItemList[cItemID]->m_wPrice / 2) -
               (short)d3;
    }

    SendNotifyMsg(0, iClientH, DEF_NOTIFY_REPAIRITEMPRICE, cItemID, sRemainLife,
                  sPrice,
                  m_pClientList[iClientH]->m_pItemList[cItemID]->m_cName);
  } else {
    // 掳铆脛楼录枚 戮酶麓脗 戮脝脌脤脜脹脌脤麓脵.
    SendNotifyMsg(0, iClientH, DEF_NOTIFY_CANNOTREPAIRITEM, cItemID, 1, 0,
                  m_pClientList[iClientH]->m_pItemList[cItemID]->m_cName);
  }
}

void CGame::ReqRepairItemCofirmHandler(int iClientH, char cItemID,
                                       char *pString) {
  short sRemainLife, sPrice;
  char *cp, cItemCategory, cData[120];
  double d1, d2, d3;
  DWORD *dwp, dwGoldCount;
  WORD *wp;
  int iRet, iGoldWeight;

  // 戮脝脌脤脜脹脌禄 录枚赂庐脟脧掳脷麓脵麓脗 掳脥脌脤 掳谩脕陇碌脟戮煤麓脵.
  if (m_pClientList[iClientH] == 0)
    return;
  if (m_pClientList[iClientH]->m_bIsInitComplete == false)
    return;

  if ((cItemID < 0) || (cItemID >= 50))
    return;
  if (m_pClientList[iClientH]->m_pItemList[cItemID] == 0)
    return;

  // New 18/05/2004
  if (m_pClientList[iClientH]->m_pIsProcessingAllowed == false)
    return;

  // testcode
  // PutLogList("Repair!");

  cItemCategory = m_pClientList[iClientH]->m_pItemList[cItemID]->m_cCategory;

  // 戮脝脌脤脜脹脌脟 脕戮路霉驴隆 碌没露贸 掳隆掳脻 掳猫禄锚.
  if (((cItemCategory >= 1) && (cItemCategory <= 10)) ||
      ((cItemCategory >= 43) && (cItemCategory <= 50)) ||
      ((cItemCategory >= 11) && (cItemCategory <= 12))) {
    // 鹿芦卤芒路霉 脠陇脌潞 鲁卢陆脙麓毛, 掳卯卤陋脌脤驴脥 掳掳脌潞
    // 戮脝脌脤脜脹, 驴脢, 陆脜鹿脽

    // 驴酶路隆 戮脝脌脤脜脹脌脟 录枚赂铆掳煤 潞帽卤鲁脟脴录颅 掳篓掳隆
    // 禄贸掳垄脌禄 掳猫禄锚, 戮脝脌脤脜脹脌脟 录枚赂庐 潞帽驴毛脌禄
    // 赂脜卤盲麓脵.
    sRemainLife = m_pClientList[iClientH]->m_pItemList[cItemID]->m_wCurLifeSpan;
    if (sRemainLife == 0) {
      // 驴脧脌眉脠梅 赂脕掳隆脕酶 掳脥脌脤露贸赂茅 驴酶路隆掳隆掳脻脌脟
      // 脌媒鹿脻脌脤 碌莽麓脵.
      sPrice = m_pClientList[iClientH]->m_pItemList[cItemID]->m_wPrice / 2;
    } else {
      d1 = (double)abs(sRemainLife);
      if (m_pClientList[iClientH]->m_pItemList[cItemID]->m_wMaxLifeSpan != 0)
        d2 = (double)abs(
            m_pClientList[iClientH]->m_pItemList[cItemID]->m_wMaxLifeSpan);
      else
        d2 = 1.0f;
      d3 = (d1 / d2) * 0.5f;
      d2 = (double)m_pClientList[iClientH]
               ->m_pItemList[cItemID]
               ->m_wPrice; // 驴酶路隆 掳隆掳脻
      d3 = d3 * d2;        // 脙脽禄锚碌脠 掳隆掳脻

      sPrice = (m_pClientList[iClientH]->m_pItemList[cItemID]->m_wPrice / 2) -
               (short)d3;
    }

    // sPrice赂赂脜颅脌脟 碌路脌脤 碌脟赂茅 掳铆脛楼 录枚 脌脰脌赂鲁陋
    // 潞脦脕路脟脧赂茅 掳铆脛楼 录枚 戮酶麓脵.
    dwGoldCount = dwGetItemCount(iClientH, "Gold");

    if (dwGoldCount < (DWORD)sPrice) {
      // 脟脙路鹿脌脤戮卯掳隆 掳庐掳铆脌脰麓脗 Gold掳隆 戮脝脌脤脜脹 录枚赂庐
      // 潞帽驴毛驴隆 潞帽脟脴 脌没麓脵. 掳铆脛楼 录枚 戮酶脌陆.
      dwp = (DWORD *)(cData + DEF_INDEX4_MSGID);
      *dwp = MSGID_NOTIFY;
      wp = (WORD *)(cData + DEF_INDEX2_MSGTYPE);
      *wp = DEF_NOTIFY_NOTENOUGHGOLD;
      cp = (char *)(cData + DEF_INDEX2_MSGTYPE + 2);
      *cp = cItemID;
      cp++;

      iRet = m_pClientList[iClientH]->m_pXSock->iSendMsg(cData, 7);
      switch (iRet) {
      case DEF_XSOCKEVENT_QUENEFULL:
      case DEF_XSOCKEVENT_SOCKETERROR:
      case DEF_XSOCKEVENT_CRITICALERROR:
      case DEF_XSOCKEVENT_SOCKETCLOSED:
        // 赂脼陆脙脕枚赂娄 潞赂鲁戮露搂 驴隆路炉掳隆 鹿脽禄媒脟脽麓脵赂茅
        // 脕娄掳脜脟脩麓脵.
        DeleteClient(iClientH, true, true);
        return;
      }
      return;
    } else {
      // 碌路脌脤 脙忙潞脨脟脧麓脵. 掳铆脛楼 录枚 脌脰麓脵.

      // 戮脝脌脤脜脹脌脟 录枚赂铆脌禄 麓脙赂庐掳铆 脜毛潞赂脟脩麓脵. !BUG POINT
      // 脌搂脛隆掳隆 脕脽驴盲脟脧麓脵. 赂脮脌煤 录枚赂铆脌禄 麓脙赂庐掳铆
      // 碌路脌脟 脛芦驴卯脝庐赂娄 鲁路脙谩麓脵.
      m_pClientList[iClientH]->m_pItemList[cItemID]->m_wCurLifeSpan =
          m_pClientList[iClientH]->m_pItemList[cItemID]->m_wMaxLifeSpan;
      SendNotifyMsg(
          0, iClientH, DEF_NOTIFY_ITEMREPAIRED, cItemID,
          m_pClientList[iClientH]->m_pItemList[cItemID]->m_wCurLifeSpan, 0, 0);

      iGoldWeight = SetItemCount(iClientH, "Gold", dwGoldCount - sPrice);

      // 录脪脕枚脟掳 脙脩 脕脽路庐 脌莽 掳猫禄锚
      iCalcTotalWeight(iClientH);

      // v1.4 赂露脌禄脌脟 脌脷卤脻驴隆 麓玫脟脩麓脵.
      m_stCityStatus[m_pClientList[iClientH]->m_cSide].iFunds += sPrice;
    }
  } else {
    // 掳铆脛楼 脟脢驴盲掳隆 戮酶麓脗 戮脝脌脤脜脹
    // 脟脴脜路脌脤鲁陋 鹿枚卤脳驴隆 脌脟脟脩 掳脥脌脧碌铆
  }
}

int CGame::iCalcTotalWeight(int iClientH) {
  int i, iWeight;
  short sItemIndex;

  if (m_pClientList[iClientH] == 0)
    return 0;

  m_pClientList[iClientH]->m_iAlterItemDropIndex = -1;
  // 脗酶驴毛脟脧脕枚 戮脢戮脝碌碌 脠驴掳煤掳隆 脌脰麓脗 戮脝脌脤脜脹 脠驴掳煤.
  // 录脪脕枚脟脧掳铆 脌脰戮卯碌碌 脠驴掳煤掳隆 脌脰卤芒 露搂鹿庐驴隆
  // 驴漏卤芒录颅 掳脣禄莽.
  for (sItemIndex = 0; sItemIndex < DEF_MAXITEMS; sItemIndex++)
    if (m_pClientList[iClientH]->m_pItemList[sItemIndex] != 0) {
      switch (
          m_pClientList[iClientH]->m_pItemList[sItemIndex]->m_sItemEffectType) {
      case DEF_ITEMEFFECTTYPE_ALTERITEMDROP:
        if (m_pClientList[iClientH]->m_pItemList[sItemIndex]->m_wCurLifeSpan >
            0) {
          // 录枚赂铆脌脤 脌脰戮卯戮脽 脠驴掳煤掳隆 脌脰麓脵.
          m_pClientList[iClientH]->m_iAlterItemDropIndex = sItemIndex;
        }
        break;
      }
    }

  iWeight = 0;
  for (i = 0; i < DEF_MAXITEMS; i++)
    if (m_pClientList[iClientH]->m_pItemList[i] != 0) {

      iWeight +=
          iGetItemWeight(m_pClientList[iClientH]->m_pItemList[i],
                         m_pClientList[iClientH]->m_pItemList[i]->m_dwCount);
    }

  m_pClientList[iClientH]->m_iCurWeightLoad = iWeight;

  return iWeight;
}

void CGame::CheckAndNotifyPlayerConnection(int iClientH, char *pMsg,
                                           DWORD dwSize) {
  char seps[] = "= \t\n";
  char *token, *cp, cName[11], cBuff[256], cPlayerLocation[120];
  class CStrTok *pStrTok;
  int i;
  WORD *wp;

  if (m_pClientList[iClientH] == 0)
    return;
  if (dwSize <= 0)
    return;

  ZeroMemory(cPlayerLocation, sizeof(cPlayerLocation));
  ZeroMemory(cName, sizeof(cName));
  ZeroMemory(cBuff, sizeof(cBuff));
  memcpy(cBuff, pMsg, dwSize);

  pStrTok = new class CStrTok(cBuff, seps);
  token = pStrTok->pGet();
  token = pStrTok->pGet();

  if (token == 0) {
    delete pStrTok;
    return;
  }

  if (strlen(token) > 10)
    memcpy(cName, token, 10);
  else
    memcpy(cName, token, strlen(token));

  // cName脌脟 脌脤赂搂脌禄 掳隆脕酶 脟脙路鹿脌脤戮卯掳隆 脕垄录脫脕脽脌脦脕枚
  // 脙拢麓脗麓脵.
  for (i = 1; i < DEF_MAXCLIENTS; i++)
    if ((m_pClientList[i] != 0) &&
        (memcmp(cName, m_pClientList[i]->m_cCharName, 10) == 0)) {
      // 掳掳脌潞 脌脤赂搂脌禄 掳隆脕酶 脛鲁赂炉脜脥赂娄 脙拢戮脪麓脵.
      if (m_pClientList[iClientH]->m_iAdminUserLevel >
          0) { // GM's get more info
        cp = (char *)cPlayerLocation;

        memcpy(cp, m_pClientList[i]->m_cMapName, 10);
        cp += 10;

        wp = (WORD *)cp;
        *wp = m_pClientList[i]->m_sX;
        cp += 2;

        wp = (WORD *)cp;
        *wp = m_pClientList[i]->m_sY;
        cp += 2;
      }
      SendNotifyMsg(0, iClientH, DEF_NOTIFY_PLAYERONGAME, 0, 0, 0,
                    m_pClientList[i]->m_cCharName, 0, 0, 0, 0, 0, 0,
                    cPlayerLocation);

      delete pStrTok;
      return;
    }

  /*ZeroMemory(cBuff, sizeof(cBuff));
  cp = (char *)cBuff;
  *cp = GSM_REQUEST_FINDCHARACTER;
  cp++;

  wp = (WORD *)cp;
  *wp = m_wServerID_GSS;
  cp += 2;

  wp = (WORD *)cp;
  *wp = iClientH;
  cp += 2;

  memcpy(cp, cName, 10);
  cp += 10;

  memcpy(cp, m_pClientList[iClientH]->m_cCharName, 10);
  cp += 10;

  bStockMsgToGateServer(cBuff, 25);*/

  delete pStrTok;
}

void CGame::ToggleWhisperPlayer(int iClientH, char *pMsg, DWORD dwMsgSize) {
  char seps[] = "= \t\n";
  char *token, cName[11], cBuff[256];
  class CStrTok *pStrTok;
  int i;
  char *cp;
  WORD *wp;

  if (m_pClientList[iClientH] == 0)
    return;
  if (dwMsgSize <= 0)
    return;

  ZeroMemory(cName, sizeof(cName));
  ZeroMemory(cBuff, sizeof(cBuff));
  memcpy(cBuff, pMsg, dwMsgSize);

  pStrTok = new class CStrTok(cBuff, seps);
  token = pStrTok->pGet();
  token = pStrTok->pGet();

  if (token == 0) {
    // 卤脫录脫赂禄 禄贸麓毛掳隆 脕枚脕陇碌脟脕枚 戮脢戮脪麓脵. 卤脫录脫赂禄
    // 赂冒碌氓赂娄 脟脴脕娄脟脩麓脵.
    m_pClientList[iClientH]->m_iWhisperPlayerIndex = -1;
    ZeroMemory(m_pClientList[iClientH]->m_cWhisperPlayerName,
               sizeof(m_pClientList[iClientH]->m_cWhisperPlayerName));
    m_pClientList[iClientH]->m_bIsCheckingWhisperPlayer = false;
    // 卤脫录脫赂禄 禄贸脜脗掳隆 脟脴脕娄碌脟戮煤脌陆脌禄 脜毛潞赂.
    SendNotifyMsg(0, iClientH, DEF_NOTIFY_WHISPERMODEOFF, 0, 0, 0, cName);
  } else {
    if (strlen(token) > 10)
      memcpy(cName, token, 10);
    else
      memcpy(cName, token, strlen(token));

    m_pClientList[iClientH]->m_iWhisperPlayerIndex = -1;

    for (i = 1; i < DEF_MAXCLIENTS; i++)
      if ((m_pClientList[i] != 0) &&
          (memcmp(m_pClientList[i]->m_cCharName, cName, 10) == 0)) {
        // 掳掳脌潞 脌脤赂搂脌禄 掳隆脕酶 脟脙路鹿脌脤戮卯赂娄 脙拢戮脪麓脵.
        // 脌脷卤芒 脌脷陆脜脌脤露贸赂茅 脟脪麓莽脟脧脕枚 戮脢麓脗麓脵.
        if (i == iClientH) {
          delete pStrTok;
          return;
        }
        // 脌脦碌娄陆潞赂娄 脟脪麓莽
        m_pClientList[iClientH]->m_iWhisperPlayerIndex = i;
        ZeroMemory(m_pClientList[iClientH]->m_cWhisperPlayerName,
                   sizeof(m_pClientList[iClientH]->m_cWhisperPlayerName));
        strcpy(m_pClientList[iClientH]->m_cWhisperPlayerName, cName);
        break;
      }

    if (m_pClientList[iClientH]->m_iWhisperPlayerIndex == -1) {
      /*ZeroMemory(cBuff, sizeof(cBuff));
      cp = (char *)cBuff;
      *cp = GSM_REQUEST_FINDCHARACTER;
      cp++;

      wp = (WORD *)cp;
      *wp = m_wServerID_GSS;
      cp += 2;

      wp = (WORD *)cp;
      *wp = iClientH;
      cp += 2;

      memcpy(cp, cName, 10);
      cp += 10;

      memcpy(cp, m_pClientList[iClientH]->m_cCharName, 10);
      cp += 10;

      bStockMsgToGateServer(cBuff, 25);*/

      ZeroMemory(m_pClientList[iClientH]->m_cWhisperPlayerName,
                 sizeof(m_pClientList[iClientH]->m_cWhisperPlayerName));
      strcpy(m_pClientList[iClientH]->m_cWhisperPlayerName, cName);
      m_pClientList[iClientH]->m_bIsCheckingWhisperPlayer = true;
    } else {
      SendNotifyMsg(0, iClientH, DEF_NOTIFY_WHISPERMODEON, 0, 0, 0,
                    m_pClientList[iClientH]->m_cWhisperPlayerName);
    }
  }

  delete pStrTok;
}

void CGame::SetPlayerProfile(int iClientH, char *pMsg, DWORD dwMsgSize) {
  char cTemp[256];
  int i;

  if (m_pClientList[iClientH] == 0)
    return;
  if ((dwMsgSize - 7) <= 0)
    return;

  ZeroMemory(cTemp, sizeof(cTemp));
  memcpy(cTemp, (pMsg + 7), dwMsgSize - 7);

  // 掳酶鹿茅露玫脌禄 戮冒麓玫鹿脵路脦 鹿脵虏脹麓脵.
  for (i = 0; i < 256; i++)
    if (cTemp[i] == ' ')
      cTemp[i] = '_';

  // 驴隆路炉 鹿忙脕枚 脛脷碌氓
  cTemp[255] = 0;

  ZeroMemory(m_pClientList[iClientH]->m_cProfile,
             sizeof(m_pClientList[iClientH]->m_cProfile));
  strcpy(m_pClientList[iClientH]->m_cProfile, cTemp);
}

void CGame::GetPlayerProfile(int iClientH, char *pMsg, DWORD dwMsgSize) {
  char seps[] = "= \t\n";
  char *token, cName[11], cBuff[256], cBuff2[500];
  class CStrTok *pStrTok;
  int i;

  if (m_pClientList[iClientH] == 0)
    return;
  if ((dwMsgSize) <= 0)
    return;

  ZeroMemory(cName, sizeof(cName));
  ZeroMemory(cBuff, sizeof(cBuff));
  memcpy(cBuff, pMsg, dwMsgSize);

  pStrTok = new class CStrTok(cBuff, seps);
  token = pStrTok->pGet();
  token = pStrTok->pGet();

  if (token != 0) {
    // token脌脤 掳冒 脟脕路脦脟脢脌禄 戮貌掳铆脌脷 脟脧麓脗 禄莽驴毛脌脷
    // 脌脤赂搂
    if (strlen(token) > 10)
      memcpy(cName, token, 10);
    else
      memcpy(cName, token, strlen(token));

    for (i = 1; i < DEF_MAXCLIENTS; i++)
      if ((m_pClientList[i] != 0) &&
          (memcmp(m_pClientList[i]->m_cCharName, cName, 10) == 0)) {

        ZeroMemory(cBuff2, sizeof(cBuff2));
        wsprintf(cBuff2, "%s Profile: %s", cName, m_pClientList[i]->m_cProfile);
        SendNotifyMsg(0, iClientH, DEF_NOTIFY_PLAYERPROFILE, 0, 0, 0, cBuff2);

        delete pStrTok;
        return;
      }
    // 脟枚脌莽 脕垄录脫脕脽脌脤 戮脝麓脧麓脵.
    SendNotifyMsg(0, iClientH, DEF_NOTIFY_PLAYERNOTONGAME, 0, 0, 0, cName);
  }

  delete pStrTok;
  return;
}

void CGame::___RestorePlayerCharacteristics(int iClientH) {
  int iStr, iDex, iInt, iVit, iMag, iCharisma;
  int iOriginalPoint, iCurPoint, iVerifyPoint, iToBeRestoredPoint;
  int iMax, iA, iB;
  bool bFlag;
  char cTxt[120];
  return;
  if (m_pClientList[iClientH] == 0)
    return;

  // 赂脮脌煤 掳陋脌禄 鹿茅戮梅脟脩麓脵.
  iStr = m_pClientList[iClientH]->m_iStr;
  iDex = m_pClientList[iClientH]->m_iDex;
  iInt = m_pClientList[iClientH]->m_iInt;
  iVit = m_pClientList[iClientH]->m_iVit;
  iMag = m_pClientList[iClientH]->m_iMag;
  iCharisma = m_pClientList[iClientH]->m_iCharisma;

  iCurPoint =
      m_pClientList[iClientH]->m_iStr + m_pClientList[iClientH]->m_iInt +
      m_pClientList[iClientH]->m_iVit + m_pClientList[iClientH]->m_iDex +
      m_pClientList[iClientH]->m_iMag + m_pClientList[iClientH]->m_iCharisma;

  iOriginalPoint = (m_pClientList[iClientH]->m_iLevel - 1) * 3 + 70;

  iToBeRestoredPoint = iOriginalPoint - iCurPoint;

  // 潞鹿卤赂脟脪 脟脢驴盲掳隆 戮酶麓脵赂茅 卤脥脠炉.
  if (iToBeRestoredPoint == 0)
    return;

  if (iToBeRestoredPoint > 0) {
    // 脌脤脕娄 iToBeRestoredPoint 赂赂脜颅脌脟 脝梅脌脦脝庐赂娄
    // 潞鹿卤赂脟脩麓脵. 赂脮脌煤 10 脌脤脟脧脌脟 脝梅脌脦脝庐掳隆 脌脰麓脵赂茅
    // 驴矛录卤脌没脌赂路脦 脙陇驴卯麓脵.
    while (1) {
      bFlag = false;

      if ((iToBeRestoredPoint > 0) && (m_pClientList[iClientH]->m_iStr < 10)) {
        m_pClientList[iClientH]->m_iStr++;
        iToBeRestoredPoint--;
        bFlag = true;
      }
      if ((iToBeRestoredPoint > 0) && (m_pClientList[iClientH]->m_iMag < 10)) {
        m_pClientList[iClientH]->m_iMag++;
        iToBeRestoredPoint--;
        bFlag = true;
      }
      if ((iToBeRestoredPoint > 0) && (m_pClientList[iClientH]->m_iInt < 10)) {
        m_pClientList[iClientH]->m_iInt++;
        iToBeRestoredPoint--;
        bFlag = true;
      }
      if ((iToBeRestoredPoint > 0) && (m_pClientList[iClientH]->m_iDex < 10)) {
        m_pClientList[iClientH]->m_iDex++;
        iToBeRestoredPoint--;
        bFlag = true;
      }
      if ((iToBeRestoredPoint > 0) && (m_pClientList[iClientH]->m_iVit < 10)) {
        m_pClientList[iClientH]->m_iVit++;
        iToBeRestoredPoint--;
        bFlag = true;
      }
      if ((iToBeRestoredPoint > 0) &&
          (m_pClientList[iClientH]->m_iCharisma < 10)) {
        m_pClientList[iClientH]->m_iCharisma++;
        iToBeRestoredPoint--;
        bFlag = true;
      }

      if (bFlag == false)
        break;
      if (iToBeRestoredPoint <= 0)
        break;
    }

    // 赂脟录脮 掳脻脜玫 陆潞脜鲁脌脟 脙脰麓毛脛隆麓脗 iMax, Str脌脤
    // iMax/2潞赂麓脵 鲁路麓脵赂茅 卤脳赂赂脜颅 驴脙赂掳麓脵.
    iMax = m_pClientList[iClientH]->m_cSkillMastery[5];

    if (m_pClientList[iClientH]->m_iStr < (iMax / 2)) {

      while (1) {
        if ((iToBeRestoredPoint > 0) &&
            (m_pClientList[iClientH]->m_iStr < (iMax / 2))) {
          m_pClientList[iClientH]->m_iStr++;
          iToBeRestoredPoint--;
        }

        if (m_pClientList[iClientH]->m_iStr == (iMax / 2))
          break;
        if (iToBeRestoredPoint <= 0)
          break;
      }
    }

    // 鹿芦卤芒 禄莽驴毛 陆潞脜鲁脌脟 脙脰麓毛脛隆麓脗 iMax, Dex掳隆
    // iMax/2潞赂麓脵 鲁路麓脵赂茅 卤脳赂赂脜颅 驴脙赂掳麓脵.
    iA = m_pClientList[iClientH]->m_cSkillMastery[7];
    iB = m_pClientList[iClientH]->m_cSkillMastery[8];
    if (iA > iB)
      iMax = iA;
    else
      iMax = iB;
    iA = m_pClientList[iClientH]->m_cSkillMastery[9];
    if (iA > iMax)
      iMax = iA;
    iA = m_pClientList[iClientH]->m_cSkillMastery[6];
    if (iA > iMax)
      iMax = iA;

    if (m_pClientList[iClientH]->m_iDex < (iMax / 2)) {

      while (1) {
        if ((iToBeRestoredPoint > 0) &&
            (m_pClientList[iClientH]->m_iDex < (iMax / 2))) {
          m_pClientList[iClientH]->m_iDex++;
          iToBeRestoredPoint--;
        }

        if (m_pClientList[iClientH]->m_iDex == (iMax / 2))
          break;
        if (iToBeRestoredPoint <= 0)
          break;
      }
    }

    // 脕脳脌潞脙麓脟脧卤芒 陆潞脜鲁脌脟 脙脰麓毛脛隆麓脗 iMax, Int脌脤
    // iMax/2潞赂麓脵 鲁路麓脵赂茅 卤脳赂赂脜颅 驴脙赂掳麓脵.
    iMax = m_pClientList[iClientH]->m_cSkillMastery[19];

    if (m_pClientList[iClientH]->m_iInt < (iMax / 2)) {

      while (1) {
        if ((iToBeRestoredPoint > 0) &&
            (m_pClientList[iClientH]->m_iInt < (iMax / 2))) {
          m_pClientList[iClientH]->m_iInt++;
          iToBeRestoredPoint--;
        }

        if (m_pClientList[iClientH]->m_iInt == (iMax / 2))
          break;
        if (iToBeRestoredPoint <= 0)
          break;
      }
    }

    // 赂露鹿媒 陆潞脜鲁脌脟 脙脰麓毛脛隆麓脗 iMax, Mag脌脤 iMax/2潞赂麓脵
    // 鲁路麓脵赂茅 卤脳赂赂脜颅 驴脙赂掳麓脵.
    iA = m_pClientList[iClientH]->m_cSkillMastery[3];
    iB = m_pClientList[iClientH]->m_cSkillMastery[4];
    if (iA > iB)
      iMax = iA;
    else
      iMax = iB;

    if (m_pClientList[iClientH]->m_iMag < (iMax / 2)) {

      while (1) {
        if ((iToBeRestoredPoint > 0) &&
            (m_pClientList[iClientH]->m_iMag < (iMax / 2))) {
          m_pClientList[iClientH]->m_iMag++;
          iToBeRestoredPoint--;
        }

        if (m_pClientList[iClientH]->m_iMag == (iMax / 2))
          break;
        if (iToBeRestoredPoint <= 0)
          break;
      }
    }

    // 鲁虏脌潞 脝梅脌脦脝庐赂娄 路拢麓媒脟脧掳脭 驴脙赂掳麓脵.
    while (iToBeRestoredPoint != 0) {
      switch (iDice(1, 6)) {
      case 1:
        if (m_pClientList[iClientH]->m_iStr < DEF_CHARPOINTLIMIT) {
          m_pClientList[iClientH]->m_iStr++;
          iToBeRestoredPoint--;
        }
        break;
      case 2:
        if (m_pClientList[iClientH]->m_iVit < DEF_CHARPOINTLIMIT) {
          m_pClientList[iClientH]->m_iVit++;
          iToBeRestoredPoint--;
        }
        break;
      case 3:
        if (m_pClientList[iClientH]->m_iDex < DEF_CHARPOINTLIMIT) {
          m_pClientList[iClientH]->m_iDex++;
          iToBeRestoredPoint--;
        }
        break;
      case 4:
        if (m_pClientList[iClientH]->m_iMag < DEF_CHARPOINTLIMIT) {
          m_pClientList[iClientH]->m_iMag++;
          iToBeRestoredPoint--;
        }
        break;
      case 5:
        if (m_pClientList[iClientH]->m_iInt < DEF_CHARPOINTLIMIT) {
          m_pClientList[iClientH]->m_iInt++;
          iToBeRestoredPoint--;
        }
        break;
      case 6:
        if (m_pClientList[iClientH]->m_iCharisma < DEF_CHARPOINTLIMIT) {
          m_pClientList[iClientH]->m_iCharisma++;
          iToBeRestoredPoint--;
        }
        break;
      }
    }

    // 潞鹿卤赂掳隆 录潞掳酶脌没脌赂路脦 碌脟戮煤麓脗脕枚 脠庐脌脦脟脩麓脵.
    iVerifyPoint =
        m_pClientList[iClientH]->m_iStr + m_pClientList[iClientH]->m_iInt +
        m_pClientList[iClientH]->m_iVit + m_pClientList[iClientH]->m_iDex +
        m_pClientList[iClientH]->m_iMag + m_pClientList[iClientH]->m_iCharisma;

    if (iVerifyPoint != iOriginalPoint) {
      wsprintf(
          cTxt,
          "(T_T) RestorePlayerCharacteristics(Minor) FAIL! Player(%s)-(%d/%d)",
          m_pClientList[iClientH]->m_cCharName, iVerifyPoint, iOriginalPoint);
      PutLogList(cTxt);

      // 驴隆路炉麓脵. 脌脤脌眉 掳陋脌赂路脦 潞鹿卤赂.
      m_pClientList[iClientH]->m_iStr = iStr;
      m_pClientList[iClientH]->m_iDex = iDex;
      m_pClientList[iClientH]->m_iInt = iInt;
      m_pClientList[iClientH]->m_iVit = iVit;
      m_pClientList[iClientH]->m_iMag = iMag;
      m_pClientList[iClientH]->m_iCharisma = iCharisma;
    } else {
      wsprintf(cTxt,
               "(^o^) RestorePlayerCharacteristics(Minor) SUCCESS! "
               "Player(%s)-(%d/%d)",
               m_pClientList[iClientH]->m_cCharName, iVerifyPoint,
               iOriginalPoint);
      PutLogList(cTxt);
    }
  } else {
    // 脟脴脜路脌脤鲁陋 驴隆路炉驴隆 脌脟脟脴录颅 脝炉录潞脛隆掳隆 驴脌鹿枚碌脠
    // 掳忙驴矛脌脤麓脵. 驴脌鹿枚碌脠 脝梅脌脦脝庐赂赂脜颅 禄芦麓脵.
    // iToBeRestoredPoint掳隆 赂露脌脤鲁脢陆潞禄贸脜脗!

    // 赂脮脌煤 脝炉录潞脛隆 脕娄脟脩脛隆赂娄 驴脌鹿枚脟脩 掳陋脌禄 禄芦麓脵.
    while (1) {
      bFlag = false;
      if (m_pClientList[iClientH]->m_iStr > DEF_CHARPOINTLIMIT) {
        bFlag = true;
        m_pClientList[iClientH]->m_iStr--;
        iToBeRestoredPoint++;
      }

      if (m_pClientList[iClientH]->m_iDex > DEF_CHARPOINTLIMIT) {
        bFlag = true;
        m_pClientList[iClientH]->m_iDex--;
        iToBeRestoredPoint++;
      }

      if (m_pClientList[iClientH]->m_iVit > DEF_CHARPOINTLIMIT) {
        bFlag = true;
        m_pClientList[iClientH]->m_iVit--;
        iToBeRestoredPoint++;
      }

      if (m_pClientList[iClientH]->m_iInt > DEF_CHARPOINTLIMIT) {
        bFlag = true;
        m_pClientList[iClientH]->m_iInt--;
        iToBeRestoredPoint++;
      }

      if (m_pClientList[iClientH]->m_iMag > DEF_CHARPOINTLIMIT) {
        bFlag = true;
        m_pClientList[iClientH]->m_iMag--;
        iToBeRestoredPoint++;
      }

      if (m_pClientList[iClientH]->m_iCharisma > DEF_CHARPOINTLIMIT) {
        bFlag = true;
        m_pClientList[iClientH]->m_iCharisma--;
        iToBeRestoredPoint++;
      }

      if (bFlag == false)
        break;
      if (iToBeRestoredPoint >= 0)
        break;
    }

    if (iToBeRestoredPoint < 0) {
      // 鲁虏脌潞 脝梅脌脦脝庐 赂赂脜颅 路拢麓媒脟脧掳脭 录卤脜脙碌脠
      // 脝炉录潞脛隆脌脟 掳陋脌禄 鲁禄赂掳麓脵.
      while (iToBeRestoredPoint != 0) {
        switch (iDice(1, 6)) {
        case 1:
          if (m_pClientList[iClientH]->m_iStr > 10) {
            m_pClientList[iClientH]->m_iStr--;
            iToBeRestoredPoint++;
          }
          break;
        case 2:
          if (m_pClientList[iClientH]->m_iVit > 10) {
            m_pClientList[iClientH]->m_iVit--;
            iToBeRestoredPoint++;
          }
          break;
        case 3:
          if (m_pClientList[iClientH]->m_iDex > 10) {
            m_pClientList[iClientH]->m_iDex--;
            iToBeRestoredPoint++;
          }
          break;
        case 4:
          if (m_pClientList[iClientH]->m_iMag > 10) {
            m_pClientList[iClientH]->m_iMag--;
            iToBeRestoredPoint++;
          }
          break;
        case 5:
          if (m_pClientList[iClientH]->m_iInt > 10) {
            m_pClientList[iClientH]->m_iInt--;
            iToBeRestoredPoint++;
          }
          break;
        case 6:
          if (m_pClientList[iClientH]->m_iCharisma > 10) {
            m_pClientList[iClientH]->m_iCharisma--;
            iToBeRestoredPoint++;
          }
          break;
        }
      }
    } else {
      // 掳猫禄锚脌禄 脟脽麓玫麓脧 麓脵陆脙 掳陋脌脤 驴脌鹿枚碌脟戮煤麓脵.
      // 脌脤路虏录枚掳隆 脌脰脌禄卤卯?
      while (iToBeRestoredPoint != 0) {
        switch (iDice(1, 6)) {
        case 1:
          if (m_pClientList[iClientH]->m_iStr < DEF_CHARPOINTLIMIT) {
            m_pClientList[iClientH]->m_iStr++;
            iToBeRestoredPoint--;
          }
          break;
        case 2:
          if (m_pClientList[iClientH]->m_iVit < DEF_CHARPOINTLIMIT) {
            m_pClientList[iClientH]->m_iVit++;
            iToBeRestoredPoint--;
          }
          break;
        case 3:
          if (m_pClientList[iClientH]->m_iDex < DEF_CHARPOINTLIMIT) {
            m_pClientList[iClientH]->m_iDex++;
            iToBeRestoredPoint--;
          }
          break;
        case 4:
          if (m_pClientList[iClientH]->m_iMag < DEF_CHARPOINTLIMIT) {
            m_pClientList[iClientH]->m_iMag++;
            iToBeRestoredPoint--;
          }
          break;
        case 5:
          if (m_pClientList[iClientH]->m_iInt < DEF_CHARPOINTLIMIT) {
            m_pClientList[iClientH]->m_iInt++;
            iToBeRestoredPoint--;
          }
          break;
        case 6:
          if (m_pClientList[iClientH]->m_iCharisma < DEF_CHARPOINTLIMIT) {
            m_pClientList[iClientH]->m_iCharisma++;
            iToBeRestoredPoint--;
          }
          break;
        }
      }
    }

    // 潞鹿卤赂掳隆 录潞掳酶脌没脌赂路脦 碌脟戮煤麓脗脕枚 脠庐脌脦脟脩麓脵.
    iVerifyPoint =
        m_pClientList[iClientH]->m_iStr + m_pClientList[iClientH]->m_iInt +
        m_pClientList[iClientH]->m_iVit + m_pClientList[iClientH]->m_iDex +
        m_pClientList[iClientH]->m_iMag + m_pClientList[iClientH]->m_iCharisma;

    if (iVerifyPoint != iOriginalPoint) {
      wsprintf(
          cTxt,
          "(T_T) RestorePlayerCharacteristics(Over) FAIL! Player(%s)-(%d/%d)",
          m_pClientList[iClientH]->m_cCharName, iVerifyPoint, iOriginalPoint);
      PutLogList(cTxt);

    } else {
      wsprintf(cTxt,
               "(^o^) RestorePlayerCharacteristics(Over) SUCCESS! "
               "Player(%s)-(%d/%d)",
               m_pClientList[iClientH]->m_cCharName, iVerifyPoint,
               iOriginalPoint);
      PutLogList(cTxt);
    }
  }
}

void CGame::CalcTotalItemEffect(int iClientH, int iEquipItemID, bool bNotify) {
  short sItemIndex;
  int i, iArrowIndex, iPrevSAType, iTemp;
  char cEquipPos;
  double dV1, dV2, dV3;
  DWORD dwSWEType, dwSWEValue;
  short sTemp;

  if (m_pClientList[iClientH] == 0)
    return;

  if ((m_pClientList[iClientH]->m_sItemEquipmentStatus[DEF_EQUIPPOS_RHAND] !=
       -1) &&
      (m_pClientList[iClientH]->m_sItemEquipmentStatus[DEF_EQUIPPOS_TWOHAND] !=
       -1)) {

    // 肋给等 公扁 厘馒 炼钦捞促. 笛 吝 窍唱甫 郴妨 初绰促.
    if (m_pClientList[iClientH]
            ->m_pItemList[m_pClientList[iClientH]
                              ->m_sItemEquipmentStatus[DEF_EQUIPPOS_RHAND]] !=
        0) {
      // 茄颊 八狼 厘馒 惑怕甫 秦力茄促.
      m_pClientList[iClientH]
          ->m_bIsItemEquipped[m_pClientList[iClientH]->m_sItemEquipmentStatus
                                  [DEF_EQUIPPOS_RHAND]] = false;
      m_pClientList[iClientH]->m_sItemEquipmentStatus[DEF_EQUIPPOS_RHAND] = -1;
    }
  }

  m_pClientList[iClientH]->m_iAngelicStr = 0; // By Snoopy81
  m_pClientList[iClientH]->m_iAngelicInt = 0; // By Snoopy81
  m_pClientList[iClientH]->m_iAngelicDex = 0; // By Snoopy81
  m_pClientList[iClientH]->m_iAngelicMag = 0; // By Snoopy81
  SetAngelFlag(iClientH, DEF_OWNERTYPE_PLAYER, 0, 0);

  m_pClientList[iClientH]->m_cAttackDiceThrow_SM = 0;
  m_pClientList[iClientH]->m_cAttackDiceRange_SM = 0;
  m_pClientList[iClientH]->m_cAttackBonus_SM = 0;

  m_pClientList[iClientH]->m_cAttackDiceThrow_L = 0;
  m_pClientList[iClientH]->m_cAttackDiceRange_L = 0;
  m_pClientList[iClientH]->m_cAttackBonus_L = 0;

  m_pClientList[iClientH]->m_iHitRatio = 0;
  m_pClientList[iClientH]->m_iDefenseRatio =
      m_pClientList[iClientH]->m_iDex * 2;
  m_pClientList[iClientH]->m_iDamageAbsorption_Shield = 0;

  for (i = 0; i < DEF_MAXITEMEQUIPPOS; i++)
    m_pClientList[iClientH]->m_iDamageAbsorption_Armor[i] = 0;

  m_pClientList[iClientH]->m_iManaSaveRatio = 0;
  m_pClientList[iClientH]->m_iAddResistMagic = 0;

  m_pClientList[iClientH]->m_iAddPhysicalDamage = 0;
  m_pClientList[iClientH]->m_iAddMagicalDamage = 0;

  m_pClientList[iClientH]->m_bIsLuckyEffect = false;
  m_pClientList[iClientH]->m_iMagicDamageSaveItemIndex = -1;
  m_pClientList[iClientH]->m_iSideEffect_MaxHPdown = 0;

  m_pClientList[iClientH]->m_iAddAbsAir = 0; // 加己喊 措固瘤 软荐
  m_pClientList[iClientH]->m_iAddAbsEarth = 0;
  m_pClientList[iClientH]->m_iAddAbsFire = 0;
  m_pClientList[iClientH]->m_iAddAbsWater = 0;

  m_pClientList[iClientH]->m_iCustomItemValue_Attack = 0;
  m_pClientList[iClientH]->m_iCustomItemValue_Defense = 0;

  m_pClientList[iClientH]->m_iMinAP_SM = 0;
  m_pClientList[iClientH]->m_iMinAP_L = 0;

  m_pClientList[iClientH]->m_iMaxAP_SM = 0;
  m_pClientList[iClientH]->m_iMaxAP_L = 0;

  m_pClientList[iClientH]->m_iSpecialWeaponEffectType =
      0; // 锐蓖 酒捞袍 瓤苞 辆幅: 0-None 1-鞘混扁措固瘤眠啊 2-吝刀瓤苞 3-沥狼狼
         // 4-历林狼
  m_pClientList[iClientH]->m_iSpecialWeaponEffectValue =
      0; // 锐蓖 酒捞袍 瓤苞 蔼

  m_pClientList[iClientH]->m_iAddHP = m_pClientList[iClientH]->m_iAddSP =
      m_pClientList[iClientH]->m_iAddMP = 0;
  m_pClientList[iClientH]->m_iAddAR = m_pClientList[iClientH]->m_iAddPR =
      m_pClientList[iClientH]->m_iAddDR = 0;
  m_pClientList[iClientH]->m_iAddMR = m_pClientList[iClientH]->m_iAddAbsPD =
      m_pClientList[iClientH]->m_iAddAbsMD = 0;
  m_pClientList[iClientH]->m_iAddCD = m_pClientList[iClientH]->m_iAddExp =
      m_pClientList[iClientH]->m_iAddGold = 0;

  iPrevSAType = m_pClientList[iClientH]->m_iSpecialAbilityType;

  m_pClientList[iClientH]->m_iSpecialAbilityType = 0;
  m_pClientList[iClientH]->m_iSpecialAbilityLastSec = 0;
  m_pClientList[iClientH]->m_iSpecialAbilityEquipPos = 0;

  m_pClientList[iClientH]->m_iAddTransMana = 0;
  m_pClientList[iClientH]->m_iAddChargeCritical = 0;

  m_pClientList[iClientH]->m_iAlterItemDropIndex = -1;
  // 馒侩窍瘤 臼酒档 瓤苞啊 乐绰 酒捞袍.
  for (sItemIndex = 0; sItemIndex < DEF_MAXITEMS; sItemIndex++)
    if (m_pClientList[iClientH]->m_pItemList[sItemIndex] != 0) {
      switch (
          m_pClientList[iClientH]->m_pItemList[sItemIndex]->m_sItemEffectType) {
      case DEF_ITEMEFFECTTYPE_ALTERITEMDROP:
        if (m_pClientList[iClientH]->m_pItemList[sItemIndex]->m_wCurLifeSpan >
            0) {
          // 荐疙捞 乐绢具 瓤苞啊 乐促.
          m_pClientList[iClientH]->m_iAlterItemDropIndex = sItemIndex;
        }
        break;
      }
    }

  // 馒侩阑 秦具 瓤苞啊 乐绰 酒捞袍
  for (sItemIndex = 0; sItemIndex < DEF_MAXITEMS; sItemIndex++)
    if ((m_pClientList[iClientH]->m_pItemList[sItemIndex] != 0) &&
        (m_pClientList[iClientH]->m_bIsItemEquipped[sItemIndex])) {

      cEquipPos = m_pClientList[iClientH]->m_pItemList[sItemIndex]->m_cEquipPos;

      switch (
          m_pClientList[iClientH]->m_pItemList[sItemIndex]->m_sItemEffectType) {

      case DEF_ITEMEFFECTTYPE_MAGICDAMAGESAVE:
        // 付过 单固瘤 例皑 酒捞袍. 牢郸胶甫 历厘茄促.
        m_pClientList[iClientH]->m_iMagicDamageSaveItemIndex = sItemIndex;
        break;

      case DEF_ITEMEFFECTTYPE_ATTACK_SPECABLTY:
      case DEF_ITEMEFFECTTYPE_ATTACK_DEFENSE:
      case DEF_ITEMEFFECTTYPE_ATTACK_MANASAVE:
      case DEF_ITEMEFFECTTYPE_ATTACK_MAXHPDOWN:
      case DEF_ITEMEFFECTTYPE_ATTACK:
        // 公扁 厘馒 瓤苞
        m_pClientList[iClientH]->m_cAttackDiceThrow_SM =
            m_pClientList[iClientH]
                ->m_pItemList[sItemIndex]
                ->m_sItemEffectValue1;
        m_pClientList[iClientH]->m_cAttackDiceRange_SM =
            m_pClientList[iClientH]
                ->m_pItemList[sItemIndex]
                ->m_sItemEffectValue2;
        m_pClientList[iClientH]->m_cAttackBonus_SM =
            m_pClientList[iClientH]
                ->m_pItemList[sItemIndex]
                ->m_sItemEffectValue3;
        m_pClientList[iClientH]->m_cAttackDiceThrow_L =
            m_pClientList[iClientH]
                ->m_pItemList[sItemIndex]
                ->m_sItemEffectValue4;
        m_pClientList[iClientH]->m_cAttackDiceRange_L =
            m_pClientList[iClientH]
                ->m_pItemList[sItemIndex]
                ->m_sItemEffectValue5;
        m_pClientList[iClientH]->m_cAttackBonus_L =
            m_pClientList[iClientH]
                ->m_pItemList[sItemIndex]
                ->m_sItemEffectValue6;

        // v2.05 公扁狼 漂己摹 眠啊
        iTemp =
            (m_pClientList[iClientH]->m_pItemList[sItemIndex]->m_dwAttribute &
             0xF0000000) >>
            28;
        // testcode
        // wsprintf(G_cTxt, "Add Damage: %d", iTemp);
        // PutLogList(G_cTxt);

        // 绊沥 措固瘤 眠啊
        m_pClientList[iClientH]->m_iAddPhysicalDamage += iTemp;
        m_pClientList[iClientH]->m_iAddMagicalDamage += iTemp;

        // 傍拜公扁狼 秦寸 胶懦父怒狼 疙吝伏阑 歹茄促.
        m_pClientList[iClientH]->m_iHitRatio +=
            m_pClientList[iClientH]
                ->m_cSkillMastery[m_pClientList[iClientH]
                                      ->m_pItemList[sItemIndex]
                                      ->m_sRelatedSkill];

        // v1.432 荤侩窍瘤 臼绰促. 公扁狼 傍拜措惑喊 疙吝伏 啊皑摹甫 歹茄促.
        // m_pClientList[iClientH]->m_iHitRatio_ItemEffect_SM +=
        // m_pClientList[iClientH]->m_pItemList[sItemIndex]->m_sSM_HitRatio;
        // m_pClientList[iClientH]->m_iHitRatio_ItemEffect_L  +=
        // m_pClientList[iClientH]->m_pItemList[sItemIndex]->m_sL_HitRatio;
        // 敲饭捞绢啊 荤侩窍绰 公扁狼 胶懦阑 历厘茄促.
        m_pClientList[iClientH]->m_sUsingWeaponSkill =
            m_pClientList[iClientH]->m_pItemList[sItemIndex]->m_sRelatedSkill;

        // v1.41 Custom-Made 酒捞袍捞扼搁 瓤苞甫 汲沥茄促. 傍拜公扁绰 1俺父
        // 厘馒等促绊 沁阑锭父 蜡瓤窃.
        if ((m_pClientList[iClientH]->m_pItemList[sItemIndex]->m_dwAttribute &
             0x00000001) != 0) {
          m_pClientList[iClientH]->m_iCustomItemValue_Attack +=
              m_pClientList[iClientH]
                  ->m_pItemList[sItemIndex]
                  ->m_sItemSpecEffectValue2;
          // 俊矾 焊沥侩
          if (m_pClientList[iClientH]->m_iCustomItemValue_Attack > 100)
            m_pClientList[iClientH]->m_iCustomItemValue_Attack = 100;

          if (m_pClientList[iClientH]->m_iCustomItemValue_Attack < -100)
            m_pClientList[iClientH]->m_iCustomItemValue_Attack = -100;

          if (m_pClientList[iClientH]->m_iCustomItemValue_Attack > 0) {
            // 剧荐搁 公扁狼 鸥拜摹 弥家蔼捞 弥措 5鳖瘤 棵扼埃促.
            dV2 = (double)m_pClientList[iClientH]->m_iCustomItemValue_Attack;
            dV1 = (dV2 / 100.0f) * (5.0f);
            m_pClientList[iClientH]->m_iMinAP_SM =
                m_pClientList[iClientH]->m_cAttackDiceThrow_SM +
                m_pClientList[iClientH]->m_cAttackBonus_SM + (int)dV1;

            m_pClientList[iClientH]->m_iMinAP_L =
                m_pClientList[iClientH]->m_cAttackDiceThrow_L +
                m_pClientList[iClientH]->m_cAttackBonus_L + (int)dV1;

            // 荐摹 炼沥
            if (m_pClientList[iClientH]->m_iMinAP_SM < 1)
              m_pClientList[iClientH]->m_iMinAP_SM = 1;
            if (m_pClientList[iClientH]->m_iMinAP_L < 1)
              m_pClientList[iClientH]->m_iMinAP_L = 1;

            // 弥家蔼捞 弥措蔼焊促 农搁 弥措蔼父怒
            if (m_pClientList[iClientH]->m_iMinAP_SM >
                (m_pClientList[iClientH]->m_cAttackDiceThrow_SM *
                     m_pClientList[iClientH]->m_cAttackDiceRange_SM +
                 m_pClientList[iClientH]->m_cAttackBonus_SM))
              m_pClientList[iClientH]->m_iMinAP_SM =
                  (m_pClientList[iClientH]->m_cAttackDiceThrow_SM *
                       m_pClientList[iClientH]->m_cAttackDiceRange_SM +
                   m_pClientList[iClientH]->m_cAttackBonus_SM);

            if (m_pClientList[iClientH]->m_iMinAP_L >
                (m_pClientList[iClientH]->m_cAttackDiceThrow_L *
                     m_pClientList[iClientH]->m_cAttackDiceRange_L +
                 m_pClientList[iClientH]->m_cAttackBonus_L))
              m_pClientList[iClientH]->m_iMinAP_L =
                  (m_pClientList[iClientH]->m_cAttackDiceThrow_L *
                       m_pClientList[iClientH]->m_cAttackDiceRange_L +
                   m_pClientList[iClientH]->m_cAttackBonus_L);

            // testcode
            // wsprintf(G_cTxt, "MinAP: %d %d +(%d)",
            // m_pClientList[iClientH]->m_iMinAP_SM,
            // m_pClientList[iClientH]->m_iMinAP_L, (int)dV1);
            // PutLogList(G_cTxt);
          } else if (m_pClientList[iClientH]->m_iCustomItemValue_Attack < 0) {
            // 澜荐搁 公扁狼 鸥拜摹 弥措蔼捞 弥措 5鳖瘤 郴妨埃促.
            dV2 = (double)m_pClientList[iClientH]->m_iCustomItemValue_Attack;
            dV1 = (dV2 / 100.0f) * (5.0f);
            m_pClientList[iClientH]->m_iMaxAP_SM =
                m_pClientList[iClientH]->m_cAttackDiceThrow_SM *
                    m_pClientList[iClientH]->m_cAttackDiceRange_SM +
                m_pClientList[iClientH]->m_cAttackBonus_SM + (int)dV1;

            m_pClientList[iClientH]->m_iMaxAP_L =
                m_pClientList[iClientH]->m_cAttackDiceThrow_L *
                    m_pClientList[iClientH]->m_cAttackDiceRange_L +
                m_pClientList[iClientH]->m_cAttackBonus_L + (int)dV1;

            // 荐摹 炼沥
            if (m_pClientList[iClientH]->m_iMaxAP_SM < 1)
              m_pClientList[iClientH]->m_iMaxAP_SM = 1;
            if (m_pClientList[iClientH]->m_iMaxAP_L < 1)
              m_pClientList[iClientH]->m_iMaxAP_L = 1;

            // 弥措蔼捞 弥家蔼焊促 累栏搁 弥家蔼父怒
            if (m_pClientList[iClientH]->m_iMaxAP_SM <
                (m_pClientList[iClientH]->m_cAttackDiceThrow_SM *
                     m_pClientList[iClientH]->m_cAttackDiceRange_SM +
                 m_pClientList[iClientH]->m_cAttackBonus_SM))
              m_pClientList[iClientH]->m_iMaxAP_SM =
                  (m_pClientList[iClientH]->m_cAttackDiceThrow_SM *
                       m_pClientList[iClientH]->m_cAttackDiceRange_SM +
                   m_pClientList[iClientH]->m_cAttackBonus_SM);

            if (m_pClientList[iClientH]->m_iMaxAP_L <
                (m_pClientList[iClientH]->m_cAttackDiceThrow_L *
                     m_pClientList[iClientH]->m_cAttackDiceRange_L +
                 m_pClientList[iClientH]->m_cAttackBonus_L))
              m_pClientList[iClientH]->m_iMaxAP_L =
                  (m_pClientList[iClientH]->m_cAttackDiceThrow_L *
                       m_pClientList[iClientH]->m_cAttackDiceRange_L +
                   m_pClientList[iClientH]->m_cAttackBonus_L);

            // testcode
            // wsprintf(G_cTxt, "MaxAP: %d %d +(%d)",
            // m_pClientList[iClientH]->m_iMaxAP_SM,
            // m_pClientList[iClientH]->m_iMaxAP_L, (int)dV1);
            // PutLogList(G_cTxt);
          }
        }

        // v1.42 锐蓖 酒捞袍捞扼搁 Main 瓤苞甫 汲沥茄促. 傍拜公扁绰 1俺父
        // 厘馒等促绊 沁阑锭父 蜡瓤窃.
        if ((m_pClientList[iClientH]->m_pItemList[sItemIndex]->m_dwAttribute &
             0x00F00000) != 0) {
          dwSWEType =
              (m_pClientList[iClientH]->m_pItemList[sItemIndex]->m_dwAttribute &
               0x00F00000) >>
              20;
          dwSWEValue =
              (m_pClientList[iClientH]->m_pItemList[sItemIndex]->m_dwAttribute &
               0x000F0000) >>
              16;

          // 锐蓖 酒捞袍 瓤苞 辆幅:
          // 0-None 1-鞘混扁措固瘤眠啊 2-吝刀瓤苞 3-沥狼狼 4-历林狼
          // 5-刮酶狼 6-啊涵款 7-抗府茄 8-碍拳等 9-绊措巩疙狼 10-付过 己傍狼
          m_pClientList[iClientH]->m_iSpecialWeaponEffectType = (int)dwSWEType;
          m_pClientList[iClientH]->m_iSpecialWeaponEffectValue =
              (int)dwSWEValue;

          switch (dwSWEType) {
          case 7: // 抗府茄
            m_pClientList[iClientH]->m_cAttackDiceRange_SM++;
            m_pClientList[iClientH]->m_cAttackDiceRange_L++;
            break;

          case 9: // 绊措巩疙狼
            m_pClientList[iClientH]->m_cAttackDiceRange_SM += 2;
            m_pClientList[iClientH]->m_cAttackDiceRange_L += 2;
            break;
          }
        }

        // v1.42 锐蓖 酒捞袍捞扼搁 Sub 瓤苞甫 汲沥茄促. 傍拜公扁绰 1俺父
        // 厘馒等促绊 沁阑锭父 蜡瓤窃.
        if ((m_pClientList[iClientH]->m_pItemList[sItemIndex]->m_dwAttribute &
             0x0000F000) != 0) {
          dwSWEType =
              (m_pClientList[iClientH]->m_pItemList[sItemIndex]->m_dwAttribute &
               0x0000F000) >>
              12;
          dwSWEValue =
              (m_pClientList[iClientH]->m_pItemList[sItemIndex]->m_dwAttribute &
               0x00000F00) >>
              8;

          // 锐蓖 酒捞袍 瓤苞 辆幅:
          // 眠啊 刀己历亲(1), 眠啊 疙吝蔼(2), 眠啊 规绢蔼(3), HP 雀汗樊
          // 眠啊(4), SP 雀汗樊 眠啊(5) MP 雀汗樊 眠啊(6), 眠啊 付过历亲(7),
          // 拱府 措固瘤 软荐(8), 付过 措固瘤 软荐(9) 楷鸥 措固瘤 眠啊(10), 歹
          // 腹篮 版氰摹(11), 歹腹篮 Gold(12)

          switch (dwSWEType) {
          case 0:
            break;
          case 1:
            m_pClientList[iClientH]->m_iAddPR += (int)dwSWEValue * 7;
            break;
          case 2:
            m_pClientList[iClientH]->m_iAddAR += (int)dwSWEValue * 7;
            break;
          case 3:
            m_pClientList[iClientH]->m_iAddDR += (int)dwSWEValue * 7;
            break;
          case 4:
            m_pClientList[iClientH]->m_iAddHP += (int)dwSWEValue * 7;
            break;
          case 5:
            m_pClientList[iClientH]->m_iAddSP += (int)dwSWEValue * 7;
            break;
          case 6:
            m_pClientList[iClientH]->m_iAddMP += (int)dwSWEValue * 7;
            break;
          case 7:
            m_pClientList[iClientH]->m_iAddMR += (int)dwSWEValue * 7;
            break;
          case 8:
            m_pClientList[iClientH]
                ->m_iDamageAbsorption_Armor[m_pClientList[iClientH]
                                                ->m_pItemList[sItemIndex]
                                                ->m_cEquipPos] +=
                (int)dwSWEValue * 3;
            break;
          case 9:
            m_pClientList[iClientH]->m_iAddAbsMD += (int)dwSWEValue * 3;
            break;
          case 10:
            m_pClientList[iClientH]->m_iAddCD += (int)dwSWEValue;
            break;
          case 11:
            m_pClientList[iClientH]->m_iAddExp += (int)dwSWEValue * 10;
            break;
          case 12:
            m_pClientList[iClientH]->m_iAddGold += (int)dwSWEValue * 10;
            break;
          }

          // v2.04 漂己摹 力茄阑 嘿烙.
          switch (dwSWEType) {
          case 9:
            if (m_pClientList[iClientH]->m_iAddAbsMD > 80)
              m_pClientList[iClientH]->m_iAddAbsMD = 80;
            break;
          }
        }

        // 老馆 傍拜 捞寇狼 瓤苞甫 汲沥.
        switch (m_pClientList[iClientH]
                    ->m_pItemList[sItemIndex]
                    ->m_sItemEffectType) {
        case DEF_ITEMEFFECTTYPE_ATTACK_MAXHPDOWN:
          // 弥措 HP 皑家 瓤苞
          m_pClientList[iClientH]->m_iSideEffect_MaxHPdown =
              m_pClientList[iClientH]
                  ->m_pItemList[sItemIndex]
                  ->m_sSpecialEffect;
          break;

        case DEF_ITEMEFFECTTYPE_ATTACK_MANASAVE:
          // 付唱 例距 瓤苞: 付唱 例皑伏篮 弥措 80%
          m_pClientList[iClientH]->m_iManaSaveRatio +=
              m_pClientList[iClientH]
                  ->m_pItemList[sItemIndex]
                  ->m_sItemEffectValue4;
          if (m_pClientList[iClientH]->m_iManaSaveRatio > 80)
            m_pClientList[iClientH]->m_iManaSaveRatio = 80;
          break;

        case DEF_ITEMEFFECTTYPE_ATTACK_DEFENSE:
          // 眠啊 拱府 规绢 瓷仿 瓤苞
          m_pClientList[iClientH]
              ->m_iDamageAbsorption_Armor[DEF_EQUIPPOS_BODY] +=
              m_pClientList[iClientH]
                  ->m_pItemList[sItemIndex]
                  ->m_sSpecialEffect;
          break;

        case DEF_ITEMEFFECTTYPE_ATTACK_SPECABLTY:
          // 漂荐 瓷仿 辆幅
          m_pClientList[iClientH]->m_iSpecialAbilityType =
              m_pClientList[iClientH]
                  ->m_pItemList[sItemIndex]
                  ->m_sSpecialEffect;
          // 漂荐 瓷仿 瘤加 矫埃
          m_pClientList[iClientH]->m_iSpecialAbilityLastSec =
              m_pClientList[iClientH]
                  ->m_pItemList[sItemIndex]
                  ->m_sSpecialEffectValue1;
          // 厘馒 困摹 扁撅秦 初绰促.
          m_pClientList[iClientH]->m_iSpecialAbilityEquipPos = (int)cEquipPos;

          // 漂荐 瓷仿 汲沥凳阑 舅妨霖促.
          if ((bNotify) && (iEquipItemID == (int)sItemIndex))
            SendNotifyMsg(0, iClientH, DEF_NOTIFY_SPECIALABILITYSTATUS, 2,
                          m_pClientList[iClientH]->m_iSpecialAbilityType,
                          m_pClientList[iClientH]->m_iSpecialAbilityTime, 0);
          break;
        }
        break;

      case DEF_ITEMEFFECTTYPE_ADDEFFECT:
        switch (m_pClientList[iClientH]
                    ->m_pItemList[sItemIndex]
                    ->m_sItemEffectValue1) {
        case 1:
          // 眠啊 付过 历亲 刘啊
          m_pClientList[iClientH]->m_iAddResistMagic +=
              m_pClientList[iClientH]
                  ->m_pItemList[sItemIndex]
                  ->m_sItemEffectValue2;
          break;

        case 2:
          // 付唱 例距 瓤苞
          m_pClientList[iClientH]->m_iManaSaveRatio +=
              m_pClientList[iClientH]
                  ->m_pItemList[sItemIndex]
                  ->m_sItemEffectValue2;
          // 付唱 例皑伏篮 弥措 80%
          if (m_pClientList[iClientH]->m_iManaSaveRatio > 80)
            m_pClientList[iClientH]->m_iManaSaveRatio = 80;
          break;

        case 3:
          // 绊沥 拱府 措固瘤 瓤苞. 葛电 拱府 傍拜俊 措秦辑 绊沥 措固瘤啊
          // 嘿绰促.
          m_pClientList[iClientH]->m_iAddPhysicalDamage +=
              m_pClientList[iClientH]
                  ->m_pItemList[sItemIndex]
                  ->m_sItemEffectValue2;
          break;

        case 4:
          // 眠啊 拱府 规绢仿
          m_pClientList[iClientH]->m_iDefenseRatio +=
              m_pClientList[iClientH]
                  ->m_pItemList[sItemIndex]
                  ->m_sItemEffectValue2;
          break;

        case 5:
          // 青款 瓤苞?
          if (m_pClientList[iClientH]
                  ->m_pItemList[sItemIndex]
                  ->m_sItemEffectValue2 != 0)
            m_pClientList[iClientH]->m_bIsLuckyEffect = true;
          else
            m_pClientList[iClientH]->m_bIsLuckyEffect = false;
          break;

        case 6:
          // 绊沥 付过 措固瘤 瓤苞. 葛电 付过 傍拜俊 措秦辑 绊沥 措固瘤啊
          // 嘿绰促.
          m_pClientList[iClientH]->m_iAddMagicalDamage +=
              m_pClientList[iClientH]
                  ->m_pItemList[sItemIndex]
                  ->m_sItemEffectValue2;
          break;

        case 7:
          m_pClientList[iClientH]->m_iAddAbsAir += m_pClientList[iClientH]
                                                       ->m_pItemList[sItemIndex]
                                                       ->m_sItemEffectValue2;
          break;

        case 8:
          m_pClientList[iClientH]->m_iAddAbsEarth +=
              m_pClientList[iClientH]
                  ->m_pItemList[sItemIndex]
                  ->m_sItemEffectValue2;
          break;

        case 9:
          m_pClientList[iClientH]->m_iAddAbsFire +=
              m_pClientList[iClientH]
                  ->m_pItemList[sItemIndex]
                  ->m_sItemEffectValue2;
          break;

        case 10:
          // 拱拌凯 傍拜 措固瘤 皑家绰 倔绢嘿阑 犬伏狼 皑家瓤苞啊 乐促. (2硅肺
          // 犬伏 拌魂凳)
          m_pClientList[iClientH]->m_iAddAbsWater +=
              m_pClientList[iClientH]
                  ->m_pItemList[sItemIndex]
                  ->m_sItemEffectValue2;
          break;

        case 11:
          // 刀己 历亲.
          m_pClientList[iClientH]->m_iAddPR += m_pClientList[iClientH]
                                                   ->m_pItemList[sItemIndex]
                                                   ->m_sItemEffectValue2;
          break;

        case 12:
          m_pClientList[iClientH]->m_iHitRatio += m_pClientList[iClientH]
                                                      ->m_pItemList[sItemIndex]
                                                      ->m_sItemEffectValue2;
          break;

        case 13: // Magin Ruby		Characters Hp recovery rate(% applied)
                 // added by the purity formula.
          m_pClientList[iClientH]->m_iAddHP += (m_pClientList[iClientH]
                                                    ->m_pItemList[sItemIndex]
                                                    ->m_sItemSpecEffectValue2 /
                                                5);
          break;

        case 14: // Magin Diamond	Attack probability(physical&magic) added
                 // by the purity formula.
          m_pClientList[iClientH]->m_iAddAR += (m_pClientList[iClientH]
                                                    ->m_pItemList[sItemIndex]
                                                    ->m_sItemSpecEffectValue2 /
                                                5);
          break;

        case 15: // Magin Emerald	Magical damage decreased(% applied) by
                 // the purity formula.
          m_pClientList[iClientH]->m_iAddAbsMD +=
              (m_pClientList[iClientH]
                   ->m_pItemList[sItemIndex]
                   ->m_sItemSpecEffectValue2 /
               10);
          if (m_pClientList[iClientH]->m_iAddAbsMD > 80)
            m_pClientList[iClientH]->m_iAddAbsMD = 80;
          break;

        case 30: // Magin Sapphire	Phisical damage decreased(% applied) by
                 // the purity formula.
          iTemp = (m_pClientList[iClientH]
                       ->m_pItemList[sItemIndex]
                       ->m_sItemSpecEffectValue2 /
                   10);
          m_pClientList[iClientH]
              ->m_iDamageAbsorption_Armor[DEF_EQUIPPOS_HEAD] += iTemp;
          m_pClientList[iClientH]
              ->m_iDamageAbsorption_Armor[DEF_EQUIPPOS_BODY] += iTemp;
          m_pClientList[iClientH]
              ->m_iDamageAbsorption_Armor[DEF_EQUIPPOS_ARMS] += iTemp;
          m_pClientList[iClientH]
              ->m_iDamageAbsorption_Armor[DEF_EQUIPPOS_PANTS] += iTemp;
          break;

          /*Functions rates confirm.
          Magic Diamond: Completion rate / 5 = Functions rate. ? Maximum 20.
          (not%) Magic Ruby: Completion rate / 5 = Functions rate.(%) ? Maximum
          20%. Magic Emerald: Completion rate / 10 = Functions rate.(%) ?
          Maximum 10%. Magic Sapphire: Completion rate / 10 = Functions rate.(%)
          ? Maximum 10%.*/

          // ******* Angel Code - Begin ******* //
        case 16: // Angel STR//AngelicPandent(STR)
          iTemp =
              (m_pClientList[iClientH]->m_pItemList[sItemIndex]->m_dwAttribute &
               0xF0000000) >>
              28;
          m_pClientList[iClientH]->m_iAngelicStr = iTemp + 1;
          SetAngelFlag(iClientH, DEF_OWNERTYPE_PLAYER, 1, iTemp);
          SendNotifyMsg(0, iClientH, DEF_NOTIFY_SETTING_SUCCESS, 0, 0, 0, 0);
          break;
        case 17: // Angel DEX //AngelicPandent(DEX)
          iTemp =
              (m_pClientList[iClientH]->m_pItemList[sItemIndex]->m_dwAttribute &
               0xF0000000) >>
              28;
          m_pClientList[iClientH]->m_iAngelicDex = iTemp + 1;
          SetAngelFlag(iClientH, DEF_OWNERTYPE_PLAYER, 2, iTemp);
          SendNotifyMsg(0, iClientH, DEF_NOTIFY_SETTING_SUCCESS, 0, 0, 0, 0);
          break;
        case 18: // Angel INT//AngelicPandent(INT)
          iTemp =
              (m_pClientList[iClientH]->m_pItemList[sItemIndex]->m_dwAttribute &
               0xF0000000) >>
              28;
          m_pClientList[iClientH]->m_iAngelicInt = iTemp + 1;
          SetAngelFlag(iClientH, DEF_OWNERTYPE_PLAYER, 3, iTemp);
          SendNotifyMsg(0, iClientH, DEF_NOTIFY_SETTING_SUCCESS, 0, 0, 0, 0);
          break;
        case 19: // Angel MAG//AngelicPandent(MAG)
          iTemp =
              (m_pClientList[iClientH]->m_pItemList[sItemIndex]->m_dwAttribute &
               0xF0000000) >>
              28;
          m_pClientList[iClientH]->m_iAngelicMag = iTemp + 1;
          SetAngelFlag(iClientH, DEF_OWNERTYPE_PLAYER, 4, iTemp);
          SendNotifyMsg(0, iClientH, DEF_NOTIFY_SETTING_SUCCESS, 0, 0, 0, 0);
          break;
        }
        break;

      case DEF_ITEMEFFECTTYPE_ATTACK_ARROW:
        // 拳混阑 鞘夸肺 窍绰 公扁(劝幅)
        // 公扁狼 傍拜瓤苞绰 绢恫 拳混捞 急琶登蠢衬俊 蝶扼 崔扼柳促. 酒捞袍吝
        // 拳混阑 茫酒 且寸茄促.
        if ((m_pClientList[iClientH]->m_cArrowIndex != -1) &&
            (m_pClientList[iClientH]
                 ->m_pItemList[m_pClientList[iClientH]->m_cArrowIndex] == 0)) {
          // ArrowIndex俊 拳混捞 绝促. (厚绢乐绰 酒捞袍)
          m_pClientList[iClientH]->m_cArrowIndex =
              _iGetArrowItemIndex(iClientH);
        } else if (m_pClientList[iClientH]->m_cArrowIndex == -1)
          m_pClientList[iClientH]->m_cArrowIndex =
              _iGetArrowItemIndex(iClientH);

        if (m_pClientList[iClientH]->m_cArrowIndex == -1) {
          // 拳混捞 绝促.
          m_pClientList[iClientH]->m_cAttackDiceThrow_SM = 0;
          m_pClientList[iClientH]->m_cAttackDiceRange_SM = 0;
          m_pClientList[iClientH]->m_cAttackBonus_SM = 0;
          m_pClientList[iClientH]->m_cAttackDiceThrow_L = 0;
          m_pClientList[iClientH]->m_cAttackDiceRange_L = 0;
          m_pClientList[iClientH]->m_cAttackBonus_L = 0;
        } else {
          iArrowIndex = m_pClientList[iClientH]->m_cArrowIndex;
          m_pClientList[iClientH]->m_cAttackDiceThrow_SM =
              m_pClientList[iClientH]
                  ->m_pItemList[sItemIndex]
                  ->m_sItemEffectValue1;
          m_pClientList[iClientH]->m_cAttackDiceRange_SM =
              m_pClientList[iClientH]
                  ->m_pItemList[sItemIndex]
                  ->m_sItemEffectValue2;
          m_pClientList[iClientH]->m_cAttackBonus_SM =
              m_pClientList[iClientH]
                  ->m_pItemList[sItemIndex]
                  ->m_sItemEffectValue3;
          m_pClientList[iClientH]->m_cAttackDiceThrow_L =
              m_pClientList[iClientH]
                  ->m_pItemList[sItemIndex]
                  ->m_sItemEffectValue4;
          m_pClientList[iClientH]->m_cAttackDiceRange_L =
              m_pClientList[iClientH]
                  ->m_pItemList[sItemIndex]
                  ->m_sItemEffectValue5;
          m_pClientList[iClientH]->m_cAttackBonus_L =
              m_pClientList[iClientH]
                  ->m_pItemList[sItemIndex]
                  ->m_sItemEffectValue6;
        }

        m_pClientList[iClientH]->m_iHitRatio +=
            m_pClientList[iClientH]
                ->m_cSkillMastery[m_pClientList[iClientH]
                                      ->m_pItemList[sItemIndex]
                                      ->m_sRelatedSkill];
        break;

      case DEF_ITEMEFFECTTYPE_DEFENSE_SPECABLTY:
      case DEF_ITEMEFFECTTYPE_DEFENSE:
        m_pClientList[iClientH]->m_iDefenseRatio +=
            m_pClientList[iClientH]
                ->m_pItemList[sItemIndex]
                ->m_sItemEffectValue1;

        if ((m_pClientList[iClientH]->m_pItemList[sItemIndex]->m_dwAttribute &
             0x00000001) != 0) {
          m_pClientList[iClientH]->m_iCustomItemValue_Defense +=
              m_pClientList[iClientH]
                  ->m_pItemList[sItemIndex]
                  ->m_sItemSpecEffectValue2;

          dV2 = (double)m_pClientList[iClientH]
                    ->m_pItemList[sItemIndex]
                    ->m_sItemSpecEffectValue2;
          dV3 = (double)m_pClientList[iClientH]
                    ->m_pItemList[sItemIndex]
                    ->m_sItemEffectValue1;
          dV1 = (double)(dV2 / 100.0f) * dV3;

          dV1 = dV1 / 2.0f;
          m_pClientList[iClientH]->m_iDefenseRatio += (int)dV1;
          if (m_pClientList[iClientH]->m_iDefenseRatio <= 0)
            m_pClientList[iClientH]->m_iDefenseRatio = 1;

          // testcode
          // wsprintf(G_cTxt, "Custom-Defense: %d", (int)dV1);
          // PutLogList(G_cTxt);
        }

        if ((m_pClientList[iClientH]->m_pItemList[sItemIndex]->m_dwAttribute &
             0x00F00000) != 0) {
          dwSWEType =
              (m_pClientList[iClientH]->m_pItemList[sItemIndex]->m_dwAttribute &
               0x00F00000) >>
              20;
          dwSWEValue =
              (m_pClientList[iClientH]->m_pItemList[sItemIndex]->m_dwAttribute &
               0x000F0000) >>
              16;

          // 锐蓖 酒捞袍 瓤苞 辆幅:
          // 0-None 1-鞘混扁措固瘤眠啊 2-吝刀瓤苞 3-沥狼狼 4-历林狼
          // 5-刮酶狼 6-啊涵款 7-抗府茄 8-碍拳等 9-绊措巩疙狼 10-付过己傍狼
          // 11-付唱函券狼 12-鞘混面傈狼

          switch (dwSWEType) {
          case 7: // 抗府茄
            m_pClientList[iClientH]->m_cAttackDiceRange_SM++;
            m_pClientList[iClientH]->m_cAttackDiceRange_L++;
            break;

          case 9: // 绊措巩疙狼
            m_pClientList[iClientH]->m_cAttackDiceRange_SM += 2;
            m_pClientList[iClientH]->m_cAttackDiceRange_L += 2;
            break;

          // v2.04
          case 11: // 付唱 函券狼
            m_pClientList[iClientH]->m_iAddTransMana += dwSWEValue;
            if (m_pClientList[iClientH]->m_iAddTransMana > 13)
              m_pClientList[iClientH]->m_iAddTransMana = 13;
            break;

          case 12: // 鞘混 面傈狼
            m_pClientList[iClientH]->m_iAddChargeCritical += dwSWEValue;
            if (m_pClientList[iClientH]->m_iAddChargeCritical > 20)
              m_pClientList[iClientH]->m_iAddChargeCritical = 20;
            break;
          }
        }

        // v1.42 锐蓖 酒捞袍捞扼搁 Sub 瓤苞甫 汲沥茄促. 傍拜公扁绰 1俺父
        // 厘馒等促绊 沁阑锭父 蜡瓤窃.
        if ((m_pClientList[iClientH]->m_pItemList[sItemIndex]->m_dwAttribute &
             0x0000F000) != 0) {
          dwSWEType =
              (m_pClientList[iClientH]->m_pItemList[sItemIndex]->m_dwAttribute &
               0x0000F000) >>
              12;
          dwSWEValue =
              (m_pClientList[iClientH]->m_pItemList[sItemIndex]->m_dwAttribute &
               0x00000F00) >>
              8;

          // 锐蓖 酒捞袍 瓤苞 辆幅:
          // 眠啊 刀己历亲(1), 眠啊 疙吝蔼(2), 眠啊 规绢蔼(3), HP 雀汗樊
          // 眠啊(4), SP 雀汗樊 眠啊(5) MP 雀汗樊 眠啊(6), 眠啊 付过历亲(7),
          // 拱府 措固瘤 软荐(8), 付过 措固瘤 软荐(9) 楷鸥 措固瘤 眠啊(10), 歹
          // 腹篮 版氰摹(11), 歹腹篮 Gold(12)

          switch (dwSWEType) {
          case 0:
            break;
          case 1:
            m_pClientList[iClientH]->m_iAddPR += (int)dwSWEValue * 7;
            break;
          case 2:
            m_pClientList[iClientH]->m_iAddAR += (int)dwSWEValue * 7;
            break;
          case 3:
            m_pClientList[iClientH]->m_iAddDR += (int)dwSWEValue * 7;
            break;
          case 4:
            m_pClientList[iClientH]->m_iAddHP += (int)dwSWEValue * 7;
            break;
          case 5:
            m_pClientList[iClientH]->m_iAddSP += (int)dwSWEValue * 7;
            break;
          case 6:
            m_pClientList[iClientH]->m_iAddMP += (int)dwSWEValue * 7;
            break;
          case 7:
            m_pClientList[iClientH]->m_iAddMR += (int)dwSWEValue * 7;
            break;
          case 8:
            m_pClientList[iClientH]
                ->m_iDamageAbsorption_Armor[m_pClientList[iClientH]
                                                ->m_pItemList[sItemIndex]
                                                ->m_cEquipPos] +=
                (int)dwSWEValue * 3;
            break;
          case 9:
            m_pClientList[iClientH]->m_iAddAbsMD += (int)dwSWEValue * 3;
            break;
          case 10:
            m_pClientList[iClientH]->m_iAddCD += (int)dwSWEValue;
            break;
          case 11:
            m_pClientList[iClientH]->m_iAddExp += (int)dwSWEValue * 10;
            break;
          case 12:
            m_pClientList[iClientH]->m_iAddGold += (int)dwSWEValue * 10;
            break;
          }

          // v2.04 漂己摹 力茄阑 嘿烙.
          switch (dwSWEType) {
          case 9:
            if (m_pClientList[iClientH]->m_iAddAbsMD > 80)
              m_pClientList[iClientH]->m_iAddAbsMD = 80;
            break; // 付过 措固瘤 软荐 弥措 80%
          }
        }

        switch (cEquipPos) {
        case DEF_EQUIPPOS_LHAND:
          // 规绢备 吝 规菩啊 厘馒 登菌促.
          // 规菩俊 狼茄 面拜 软荐 瓤苞 且寸茄促. 规绢蔼狼 70% 荐霖
          m_pClientList[iClientH]->m_iDamageAbsorption_Shield =
              (m_pClientList[iClientH]
                   ->m_pItemList[sItemIndex]
                   ->m_sItemEffectValue1) -
              (m_pClientList[iClientH]
                   ->m_pItemList[sItemIndex]
                   ->m_sItemEffectValue1) /
                  3;
          break;
        default:
          // 癌渴俊 狼茄 面拜 软荐 瓤苞甫 歹茄促. 规绢蔼狼 70% 荐霖 <- v1.43
          // 100%肺 函版登菌促. V2!
          m_pClientList[iClientH]->m_iDamageAbsorption_Armor
              [m_pClientList[iClientH]->m_pItemList[sItemIndex]->m_cEquipPos] +=
              (m_pClientList[iClientH]
                   ->m_pItemList[sItemIndex]
                   ->m_sItemEffectValue2);
          break;
        }

        // 老馆 傍拜 捞寇狼 瓤苞甫 汲沥.
        switch (m_pClientList[iClientH]
                    ->m_pItemList[sItemIndex]
                    ->m_sItemEffectType) {
        case DEF_ITEMEFFECTTYPE_DEFENSE_SPECABLTY:
          // 漂荐 瓷仿 辆幅
          m_pClientList[iClientH]->m_iSpecialAbilityType =
              m_pClientList[iClientH]
                  ->m_pItemList[sItemIndex]
                  ->m_sSpecialEffect;
          // 漂荐 瓷仿 瘤加 矫埃
          m_pClientList[iClientH]->m_iSpecialAbilityLastSec =
              m_pClientList[iClientH]
                  ->m_pItemList[sItemIndex]
                  ->m_sSpecialEffectValue1;
          // 厘馒 困摹 扁撅秦 初绰促.
          m_pClientList[iClientH]->m_iSpecialAbilityEquipPos = (int)cEquipPos;

          // 漂荐 瓷仿 汲沥凳阑 舅妨霖促.
          if ((bNotify) && (iEquipItemID == (int)sItemIndex))
            SendNotifyMsg(0, iClientH, DEF_NOTIFY_SPECIALABILITYSTATUS, 2,
                          m_pClientList[iClientH]->m_iSpecialAbilityType,
                          m_pClientList[iClientH]->m_iSpecialAbilityTime, 0);
          break;
        }
        break;
      }
    }

  // Snoopy: Bonus for Angels
  m_pClientList[iClientH]->m_iDefenseRatio +=
      m_pClientList[iClientH]->m_iAngelicDex * 2;
  if (m_pClientList[iClientH]->m_iHP > iGetMaxHP(iClientH))
    m_pClientList[iClientH]->m_iHP = iGetMaxHP(iClientH);
  if (m_pClientList[iClientH]->m_iMP > iGetMaxMP(iClientH))
    m_pClientList[iClientH]->m_iMP = iGetMaxMP(iClientH);
  if (m_pClientList[iClientH]->m_iSP > iGetMaxSP(iClientH))
    m_pClientList[iClientH]->m_iSP = iGetMaxSP(iClientH);

  // v1.432
  if ((iPrevSAType != 0) &&
      (m_pClientList[iClientH]->m_iSpecialAbilityType == 0) && (bNotify)) {
    // 漂荐 瓷仿捞 秦力登菌促.
    SendNotifyMsg(0, iClientH, DEF_NOTIFY_SPECIALABILITYSTATUS, 4, 0, 0, 0);
    // 父距 漂荐 瓷仿 荤侩 吝捞菌促搁 寇葛档 函拳窍哥 荤侩档 辆丰.
    if (m_pClientList[iClientH]->m_bIsSpecialAbilityEnabled) {
      m_pClientList[iClientH]->m_bIsSpecialAbilityEnabled = false;
      // 促澜 荤侩 啊瓷 矫埃阑 涝仿茄促.
      m_pClientList[iClientH]->m_iSpecialAbilityTime = DEF_SPECABLTYTIMESEC;
      // 瓤苞 厚飘 努府绢
      sTemp = m_pClientList[iClientH]->m_sAppr4;
      sTemp = sTemp & 0xFF0F;
      m_pClientList[iClientH]->m_sAppr4 = sTemp;
      // 寇屈捞 函沁澜阑 舅赴促.
      SendEventToNearClient_TypeA(iClientH, DEF_OWNERTYPE_PLAYER,
                                  MSGID_EVENT_MOTION, DEF_OBJECTNULLACTION, 0,
                                  0, 0);
    }
  }

  if ((iPrevSAType != 0) &&
      (m_pClientList[iClientH]->m_iSpecialAbilityType != 0) &&
      (iPrevSAType != m_pClientList[iClientH]->m_iSpecialAbilityType) &&
      (bNotify)) {
    // 漂荐 瓷仿 荤侩 档吝俊 漂荐 瓷仿阑 官操搁 瓷仿 荤侩捞 肛冕促.
    if (m_pClientList[iClientH]->m_bIsSpecialAbilityEnabled) {
      // 荤侩矫埃捞 促 登菌促.
      SendNotifyMsg(0, i, DEF_NOTIFY_SPECIALABILITYSTATUS, 3, 0, 0, 0);
      m_pClientList[iClientH]->m_bIsSpecialAbilityEnabled = false;
      // 促澜 荤侩 啊瓷 矫埃阑 涝仿茄促.
      m_pClientList[iClientH]->m_iSpecialAbilityTime = DEF_SPECABLTYTIMESEC;
      // 瓤苞 厚飘 努府绢
      sTemp = m_pClientList[iClientH]->m_sAppr4;
      sTemp = sTemp & 0xFF0F;
      m_pClientList[iClientH]->m_sAppr4 = sTemp;
      // 寇屈捞 函沁澜阑 舅赴促.
      SendEventToNearClient_TypeA(iClientH, DEF_OWNERTYPE_PLAYER,
                                  MSGID_EVENT_MOTION, DEF_OBJECTNULLACTION, 0,
                                  0, 0);
    }
  }
}

int CGame::_iGetPlayerNumberOnSpot(short dX, short dY, char cMapIndex,
                                   char cRange) {
  int ix, iy, iSum = 0;
  short sOwnerH;
  char cOwnerType;

  for (ix = dX - cRange; ix <= dX + cRange; ix++)
    for (iy = dY - cRange; iy <= dY + cRange; iy++) {
      m_pMapList[cMapIndex]->GetOwner(&sOwnerH, &cOwnerType, ix, iy);
      if ((sOwnerH != 0) && (cOwnerType == DEF_OWNERTYPE_PLAYER))
        iSum++;
    }

  return iSum;
}

void CGame::RequestAdminUserMode(int iClientH, char *pData) {
  // 驴卯驴碌脌脷 赂冒碌氓赂娄 脠庐脌脦脟脧卤芒 脌搂脟脴录颅麓脗 脌脧麓脺 脌脤
  // 赂脼陆脙脕枚赂娄 脌眉录脹脟脧麓脗 脜卢露贸脌脤戮冒脝庐赂娄 掳庐掳铆
  // 脌脰戮卯戮脽 脟脩麓脵. 露脟脟脩 鲁炉脗楼赂娄 脕露脟脮脟脴录颅
  // 禄媒录潞碌脟麓脗 脠庐脌脦 脛脷碌氓掳隆 脌脧脛隆脟脴戮脽 脟脩麓脵.
}

bool CGame::bAnalyzeCriminalAction(int iClientH, short dX, short dY,
                                   bool bIsCheck) {
  int iNamingValue, tX, tY;
  short sOwnerH;
  char cOwnerType, cName[11], cNpcName[21];
  char cNpcWaypoint[11];

  if (m_pClientList[iClientH] == 0)
    return false;
  if (m_pClientList[iClientH]->m_bIsInitComplete == false)
    return false;
  if (m_bIsCrusadeMode)
    return false;

  m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->GetOwner(
      &sOwnerH, &cOwnerType, dX, dY);

  if ((cOwnerType == DEF_OWNERTYPE_PLAYER) && (m_pClientList[sOwnerH] != 0)) {
    if (_bGetIsPlayerHostile(iClientH, sOwnerH) != true) {
      if (bIsCheck)
        return true;

      ZeroMemory(cNpcName, sizeof(cNpcName));
      if (strcmp(m_pClientList[iClientH]->m_cMapName, "aresden") == 0)
        strcpy(cNpcName, "Guard-Aresden");
      else if (strcmp(m_pClientList[iClientH]->m_cMapName, "elvine") == 0)
        strcpy(cNpcName, "Guard-Elvine");
      else if (strcmp(m_pClientList[iClientH]->m_cMapName, "default") == 0)
        strcpy(cNpcName, "Guard-Neutral");

      iNamingValue = m_pMapList[m_pClientList[iClientH]->m_cMapIndex]
                         ->iGetEmptyNamingValue();
      if (iNamingValue == -1) {

      } else {
        ZeroMemory(cNpcWaypoint, sizeof(cNpcWaypoint));
        ZeroMemory(cName, sizeof(cName));
        wsprintf(cName, "XX%d", iNamingValue);
        cName[0] = '_';
        cName[1] = m_pClientList[iClientH]->m_cMapIndex + 65;

        tX = (int)m_pClientList[iClientH]->m_sX;
        tY = (int)m_pClientList[iClientH]->m_sY;
        if (bCreateNewNpc(
                cNpcName, cName,
                m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->m_cName, 0, 0,
                DEF_MOVETYPE_RANDOM, &tX, &tY, cNpcWaypoint, 0, 0, -1, false,
                true) == false) {
          m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->SetNamingValueEmpty(
              iNamingValue);
        } else {
          bSetNpcAttackMode(cName, iClientH, DEF_OWNERTYPE_PLAYER, true);
        }
      }
    }
  }
  return false;
}

bool CGame::_bGetIsPlayerHostile(int iClientH, int sOwnerH) {
  if (m_pClientList[iClientH] == 0)
    return false;
  if (m_pClientList[sOwnerH] == 0)
    return false;

  // 脌脷卤芒 脌脷陆脜驴隆 麓毛脟脩 掳酶掳脻脌潞 鹿眉脕脣露贸 潞录 录枚
  // 戮酶麓脵.
  if (iClientH == sOwnerH)
    return true;

  if (m_pClientList[iClientH]->m_cSide == 0) {
    // 掳酶掳脻脌脷麓脗 驴漏脟脿脌脷脌脤麓脵.
    // 禄贸麓毛鹿忙脌脤 鹿眉脕脣脌脷脌脤赂茅 脌没录潞脌脤赂莽 卤脳
    // 脌脤驴脺驴隆麓脗 戮脝麓脧麓脵.
    if (m_pClientList[sOwnerH]->m_iPKCount != 0)
      return true;
    else
      return false;
  } else {
    // 掳酶掳脻脌脷麓脗 录脪录脫 赂露脌禄脌禄 掳庐掳铆 脌脰麓脵.
    if (m_pClientList[iClientH]->m_cSide != m_pClientList[sOwnerH]->m_cSide) {
      // 录颅路脦 禄莽脌脤碌氓掳隆 麓脵赂拢麓脵.
      if (m_pClientList[sOwnerH]->m_cSide == 0) {
        if (m_pClientList[sOwnerH]->m_iPKCount != 0)
          return true;
        else
          return false;
      } else
        return true;
    } else {
      if (m_pClientList[sOwnerH]->m_iPKCount != 0)
        return true;
      else
        return false;
    }
  }

  return false;
}

void CGame::bSetNpcAttackMode(char *cName, int iTargetH, char cTargetType,
                              bool bIsPermAttack) {
  int i, iIndex;

  for (i = 1; i < DEF_MAXNPCS; i++)
    if ((m_pNpcList[i] != 0) &&
        (memcmp(m_pNpcList[i]->m_cName, cName, 5) == 0)) {
      iIndex = i;
      goto NEXT_STEP_SNAM1;

      // testcode
      // PutLogList("bSetNpcAttackMode - Npc found");
    }
  // 掳掳脌潞 脌脤赂搂脌禄 掳隆脕酶 NPC掳隆 戮酶麓脵.
  return;

NEXT_STEP_SNAM1:

  switch (cTargetType) {
  case DEF_OWNERTYPE_PLAYER:
    if (m_pClientList[iTargetH] == 0)
      return;
    break;

  case DEF_OWNERTYPE_NPC:
    if (m_pNpcList[iTargetH] == 0)
      return;
    break;
  }

  // 赂帽脟楼鹿掳脌禄 脟脪麓莽脟脩麓脵.
  m_pNpcList[iIndex]->m_cBehavior = DEF_BEHAVIOR_ATTACK;
  m_pNpcList[iIndex]->m_sBehaviorTurnCount = 0;
  m_pNpcList[iIndex]->m_iTargetIndex = iTargetH;
  m_pNpcList[iIndex]->m_cTargetType = cTargetType;

  // 驴碌卤赂 掳酶掳脻 赂冒碌氓 驴漏潞脦 录鲁脕陇
  m_pNpcList[iIndex]->m_bIsPermAttackMode = bIsPermAttack;

  // testcode
  // PutLogList("bSetNpcAttackMode - complete");
}

void CGame::PoisonEffect(int iClientH, int iV1) {
  int iPoisonLevel, iDamage, iPrevHP, iProb;

  // 脕脽碌露脌赂路脦 脕脳脕枚麓脗 戮脢麓脗麓脵. 麓脵赂赂 脙录路脗脌脤 掳猫录脫
  // 卤茂脌脤掳铆 脙脰录脪 1赂赂 鲁虏麓脗麓脵.
  if (m_pClientList[iClientH] == 0)
    return;
  if (m_pClientList[iClientH]->m_bIsKilled)
    return;
  if (m_pClientList[iClientH]->m_bIsInitComplete == false)
    return;

  iPoisonLevel = m_pClientList[iClientH]->m_iPoisonLevel;

  iDamage = iDice(1, iPoisonLevel);

  iPrevHP = m_pClientList[iClientH]->m_iHP;
  m_pClientList[iClientH]->m_iHP -= iDamage;
  if (m_pClientList[iClientH]->m_iHP <= 0)
    m_pClientList[iClientH]->m_iHP = 1;

  if (iPrevHP != m_pClientList[iClientH]->m_iHP)
    SendNotifyMsg(0, iClientH, DEF_NOTIFY_HP, 0, 0, 0, 0);

  // 碌露录潞 脌煤脟脳 脠庐路眉路脦 脕脽碌露脌脤 脟庐赂卤 录枚 脌脰麓脵.
  iProb = m_pClientList[iClientH]->m_cSkillMastery[23] - 10 +
          m_pClientList[iClientH]->m_iAddPR;
  if (iProb <= 10)
    iProb = 10;
  if (iDice(1, 100) <= iProb) {
    m_pClientList[iClientH]->m_bIsPoisoned = false;
    // 脕脽碌露脌脤 脟庐路脠脌陆脌禄 戮脣赂掳麓脵.
    SetPoisonFlag(iClientH, DEF_OWNERTYPE_PLAYER,
                  false); // remove poison aura after effect complete
    SendNotifyMsg(0, iClientH, DEF_NOTIFY_MAGICEFFECTOFF, DEF_MAGICTYPE_POISON,
                  0, 0, 0);
  }
}
bool CGame::bCheckResistingPoisonSuccess(short sOwnerH, char cOwnerType) {
  int iResist, iResult;

  // 碌露录潞 脌煤脟脳脌脤 录潞掳酶脟脽麓脗脕枚赂娄 掳猫禄锚脟脩麓脵.
  switch (cOwnerType) {
  case DEF_OWNERTYPE_PLAYER:
    if (m_pClientList[sOwnerH] == 0)
      return false;
    iResist = m_pClientList[sOwnerH]->m_cSkillMastery[23] +
              m_pClientList[sOwnerH]->m_iAddPR;
    break;

  case DEF_OWNERTYPE_NPC:
    if (m_pNpcList[sOwnerH] == 0)
      return false;
    iResist = 0;
    break;
  }

  iResult = iDice(1, 100);
  if (iResult >= iResist) // 碌露录潞 脌煤脟脳 陆脟脝脨. 脕脽碌露碌脠麓脵.
    return false;

  // 碌露录潞 脌煤脟脳 录潞掳酶. 脟脙路鹿脌脤戮卯露贸赂茅 陆潞脜鲁脌禄
  // 驴脙赂掳麓脵.
  if (cOwnerType == DEF_OWNERTYPE_PLAYER)
    CalculateSSN_SkillIndex(sOwnerH, 23, 1);

  return true;
}

