void CGame::CheckDayOrNightMode() {
  SYSTEMTIME SysTime;
  char cPrevMode;
  int i;

  // if (m_bManualTime = true) return;

  // 脟枚脌莽 陆脙掳拢驴隆 碌没露贸 鲁路 脠陇脌潞 鹿茫脌禄 掳谩脕陇脟脩麓脵.
  // 脕脰, 戮脽掳拢 赂冒碌氓 录鲁脕陇
  cPrevMode = m_cDayOrNight;

  GetLocalTime(&SysTime);
  if (SysTime.wMinute >= DEF_NIGHTTIME)
    m_cDayOrNight = 2;
  else
    m_cDayOrNight = 1;

  if (cPrevMode != m_cDayOrNight) {
    // 脕脰, 戮脽掳拢 赂冒碌氓掳隆 潞炉掳忙碌脟戮煤麓脵. 脕脰, 戮脽掳拢
    // 赂冒碌氓脌脟 驴碌脟芒脌禄 鹿脼麓脗 赂脢驴隆 脕赂脌莽脟脧麓脗
    // 脜卢露贸脌脤戮冒脝庐碌茅驴隆掳脭 戮脣赂掳麓脵.
    for (i = 1; i < DEF_MAXCLIENTS; i++)
      if ((m_pClientList[i] != 0) && (m_pClientList[i]->m_bIsInitComplete)) {
        if ((m_pClientList[i]->m_cMapIndex >= 0) &&
            (m_pMapList[m_pClientList[i]->m_cMapIndex] != 0) &&
            (m_pMapList[m_pClientList[i]->m_cMapIndex]->m_bIsFixedDayMode ==
             false))
          SendNotifyMsg(0, i, DEF_NOTIFY_TIMECHANGE, m_cDayOrNight, 0, 0, 0);
      }
  }
}

void CGame::ShutUpPlayer(int iClientH, char *pMsg, DWORD dwMsgSize) {
  char seps[] = "= \t\n";
  char *token, cName[11], cBuff[256];
  class CStrTok *pStrTok;
  int i, iTime;

  if (m_pClientList[iClientH] == 0)
    return;
  if ((dwMsgSize) <= 0)
    return;

  if (m_pClientList[iClientH]->m_iAdminUserLevel < m_iAdminLevelShutup) {
    // Admin user level脌脤 鲁路戮脝录颅 脌脤 卤芒麓脡脌禄 禄莽驴毛脟脪 录枚
    // 戮酶麓脵.
    SendNotifyMsg(0, iClientH, DEF_NOTIFY_ADMINUSERLEVELLOW, 0, 0, 0, 0);
    return;
  }

  ZeroMemory(cName, sizeof(cName));
  ZeroMemory(cBuff, sizeof(cBuff));
  memcpy(cBuff, pMsg, dwMsgSize);

  pStrTok = new class CStrTok(cBuff, seps);
  token = pStrTok->pGet();
  token = pStrTok->pGet();

  if (token != 0) {
    // token脌脤 掳冒 脙陇脝脙脌禄 潞脪掳隆麓脡脟脧掳脭 赂赂碌茅 禄莽驴毛脌脷
    // 脌脤赂搂
    if (strlen(token) > 10)
      memcpy(cName, token, 10);
    else
      memcpy(cName, token, strlen(token));

    // 麓脵脌陆 脜盲脜芦脌潞 脕陇脕枚 陆脙脜鲁 陆脙掳拢.
    token = pStrTok->pGet();
    if (token == 0)
      iTime = 0;
    else
      iTime = atoi(token);

    if (iTime < 0)
      iTime = 0;

    for (i = 1; i < DEF_MAXCLIENTS; i++)
      if ((m_pClientList[i] != 0) &&
          (memcmp(m_pClientList[i]->m_cCharName, cName, 10) == 0)) {

        m_pClientList[i]->m_iTimeLeft_ShutUp =
            iTime * 20; // 1脌脤 3脙脢麓脵. 20脌脤赂茅 1潞脨
        SendNotifyMsg(0, iClientH, DEF_NOTIFY_PLAYERSHUTUP, iTime, 0, 0, cName);
        SendNotifyMsg(0, i, DEF_NOTIFY_PLAYERSHUTUP, iTime, 0, 0, cName);

        // Admin Log
        wsprintf(G_cTxt, "GM Order(%s): Shutup PC(%s) (%d)Min",
                 m_pClientList[iClientH]->m_cCharName,
                 m_pClientList[i]->m_cCharName, iTime);
        PutAdminLogFileList(G_cTxt);

        delete pStrTok;
        return;
      }
    // 脟枚脌莽 脕垄录脫脕脽脌脤 戮脝麓脧麓脵.
    /*ZeroMemory(cBuff, sizeof(cBuff));

    char *cp;
    WORD *wp;

    cp = (char *)cBuff;

    *cp = GSM_REQUEST_SHUTUPPLAYER;
    cp++;

    wp = (WORD *)cp;
    *wp = m_wServerID_GSS;
    cp += 2;

    wp = (WORD *)cp;
    *wp = (WORD)iClientH;
    cp += 2;

    memcpy(cp, cName, 10);
    cp += 10;

    wp = (WORD *)cp;
    *wp = iTime;
    cp += 2;

    memcpy(cp, m_pClientList[iClientH]->m_cCharName, 10);
    cp += 10;

    bStockMsgToGateServer(cBuff, 27);*/
  }

  delete pStrTok;
  return;
}

void CGame::SetPlayerReputation(int iClientH, char *pMsg, char cValue,
                                DWORD dwMsgSize) {
  char seps[] = "= \t\n";
  char *token, cName[11], cBuff[256];
  class CStrTok *pStrTok;
  int i;

  if (m_pClientList[iClientH] == 0)
    return;
  if ((dwMsgSize) <= 0)
    return;
  if (m_pClientList[iClientH]->m_iLevel < 40)
    return;

  if ((m_pClientList[iClientH]->m_iTimeLeft_Rating != 0) ||
      (m_pClientList[iClientH]->m_iPKCount != 0)) {
    // 乞啊甫 郴副 矫埃捞 登瘤 臼疽芭唱 裹了磊绰 乞啊甫 郴副 荐 绝促. 扁瓷阑
    // 荤侩且 荐 绝促.
    SendNotifyMsg(0, iClientH, DEF_NOTIFY_CANNOTRATING,
                  m_pClientList[iClientH]->m_iTimeLeft_Rating, 0, 0, 0);
    return;
  } else if (memcmp(m_pClientList[iClientH]->m_cLocation, "NONE", 4) == 0) {
    // 家加 付阑捞 绝绰 荤恩篮 乞魄阑 郴副 荐 绝促.
    SendNotifyMsg(0, iClientH, DEF_NOTIFY_CANNOTRATING, 0, 0, 0, 0);
    return;
  }

  ZeroMemory(cName, sizeof(cName));
  ZeroMemory(cBuff, sizeof(cBuff));
  memcpy(cBuff, pMsg, dwMsgSize);

  pStrTok = new class CStrTok(cBuff, seps);
  token = pStrTok->pGet();
  token = pStrTok->pGet();

  if (token != 0) {
    // token捞 梆 乞魄阑 乞啊且 荤侩磊 捞抚
    if (strlen(token) > 10)
      memcpy(cName, token, 10);
    else
      memcpy(cName, token, strlen(token));

    for (i = 1; i < DEF_MAXCLIENTS; i++)
      if ((m_pClientList[i] != 0) &&
          (memcmp(m_pClientList[i]->m_cCharName, cName, 10) == 0)) {

        if (i != iClientH) {
          // 磊扁 磊脚阑 乞啊且 荐绰 绝促.
          if (cValue == 0)
            m_pClientList[i]->m_iRating--;
          else if (cValue == 1)
            m_pClientList[i]->m_iRating++;

          if (m_pClientList[i]->m_iRating > 500)
            m_pClientList[i]->m_iRating = 500;
          if (m_pClientList[i]->m_iRating < -500)
            m_pClientList[i]->m_iRating = -500;
          // 乞啊甫 郴啡栏骨肺 矫埃 埃拜阑 犁 且寸.
          m_pClientList[iClientH]->m_iTimeLeft_Rating = 20 * 60;

          SendNotifyMsg(0, i, DEF_NOTIFY_RATINGPLAYER, cValue, 0, 0, cName);
          SendNotifyMsg(0, iClientH, DEF_NOTIFY_RATINGPLAYER, cValue, 0, 0,
                        cName);

          delete pStrTok;
          return;
        }
      }
    // 泅犁 立加吝捞 酒聪促.
    SendNotifyMsg(0, iClientH, DEF_NOTIFY_PLAYERNOTONGAME, 0, 0, 0, cName);
  }

  delete pStrTok;
  return;
}

bool CGame::bReadNotifyMsgListFile(char *cFn) {
  FILE *pFile;
  HANDLE hFile;
  DWORD dwFileSize;
  char *cp, *token, cReadMode;
  char seps[] = "=\t\n;";
  class CStrTok *pStrTok;
  int i;

  cReadMode = 0;
  m_iTotalNoticeMsg = 0;

  hFile = CreateFile(cFn, GENERIC_READ, 0, 0, OPEN_EXISTING, 0, 0);
  dwFileSize = GetFileSize(hFile, 0);
  if (hFile != INVALID_HANDLE_VALUE)
    CloseHandle(hFile);

  pFile = fopen(cFn, "rt");
  if (pFile == 0) {
    PutLogList("(!) Notify Message list file not found!...");
    return false;
  } else {
    PutLogList("(!) Reading Notify Message list file...");
    cp = new char[dwFileSize + 2];
    ZeroMemory(cp, dwFileSize + 2);
    fread(cp, dwFileSize, 1, pFile);

    pStrTok = new class CStrTok(cp, seps);
    token = pStrTok->pGet();
    // token = strtok( cp, seps );
    while (token != 0) {

      if (cReadMode != 0) {
        switch (cReadMode) {
        case 1:
          for (i = 0; i < DEF_MAXNOTIFYMSGS; i++)
            if (m_pNoticeMsgList[i] == 0) {
              m_pNoticeMsgList[i] = new class CMsg;
              m_pNoticeMsgList[i]->bPut(0, token, strlen(token), 0, 0);
              m_iTotalNoticeMsg++;
              goto LNML_NEXTSTEP1;
            }
        LNML_NEXTSTEP1:
          cReadMode = 0;
          break;
        }
      } else {
        if (memcmp(token, "notify_msg", 10) == 0)
          cReadMode = 1;
      }

      token = pStrTok->pGet();
      // token = strtok( 0, seps );
    }

    delete pStrTok;
    delete cp;
  }
  if (pFile != 0)
    fclose(pFile);

  return true;
}
void CGame::NoticeHandler() {
  char cTemp, cBuffer[1000], cKey;
  DWORD dwSize, dwTime = timeGetTime();
  int i, iMsgIndex, iTemp;

  // 掳酶脕枚禄莽脟脳脌脤 1掳鲁 脌脤脟脧露贸赂茅 潞赂鲁戮 脟脢驴盲掳隆 戮酶麓脵.
  if (m_iTotalNoticeMsg <= 1)
    return;

  if ((dwTime - m_dwNoticeTime) > DEF_NOTICETIME) {
    // 掳酶脕枚禄莽脟脳脌禄 脌眉录脹脟脪 陆脙掳拢脌脤 碌脟戮煤麓脵.
    m_dwNoticeTime = dwTime;
    do {
      iMsgIndex = iDice(1, m_iTotalNoticeMsg) - 1;
    } while (iMsgIndex == m_iPrevSendNoticeMsg);

    m_iPrevSendNoticeMsg = iMsgIndex;

    ZeroMemory(cBuffer, sizeof(cBuffer));
    if (m_pNoticeMsgList[iMsgIndex] != 0) {
      m_pNoticeMsgList[iMsgIndex]->Get(&cTemp, cBuffer, &dwSize, &iTemp, &cKey);
    }

    for (i = 1; i < DEF_MAXCLIENTS; i++)
      if (m_pClientList[i] != 0) {
        SendNotifyMsg(0, i, DEF_NOTIFY_NOTICEMSG, 0, 0, 0, cBuffer);
      }
  }
}

void CGame::ResponseSavePlayerDataReplyHandler(char *pData, DWORD dwMsgSize) {
  char *cp, cCharName[11];
  int i;

  ZeroMemory(cCharName, sizeof(cCharName));

  cp = (char *)(pData + DEF_INDEX2_MSGTYPE + 2);
  memcpy(cCharName, cp, 10);

  // 脌脤脕娄 脌脤 脌脤赂搂脌禄 掳庐麓脗 脜卢露贸脌脤戮冒脝庐赂娄 脙拢戮脝
  // 脕垄录脫脌禄 虏梅戮卯碌碌 脕脕麓脵麓脗 赂脼陆脙脕枚赂娄 潞赂鲁陆麓脵.
  for (i = 0; i < DEF_MAXCLIENTS; i++)
    if (m_pClientList[i] != 0) {
      if (memcmp(m_pClientList[i]->m_cCharName, cCharName, 10) == 0) {
        // 掳掳脌潞 脌脤赂搂脌禄 掳隆脕酶 脛鲁赂炉脜脥赂娄 脙拢戮脪麓脵.
        // 脕垄录脫脌禄 脕戮路谩脟脧露贸麓脗 赂脼陆脙脕枚赂娄 潞赂鲁陆麓脵.
        SendNotifyMsg(0, i, DEF_NOTIFY_SERVERCHANGE, 0, 0, 0, 0);
      }
    }
}

void CGame::CalcExpStock(int iClientH) {
  bool bIsLevelUp;
  class CItem *pItem;

  if (m_pClientList[iClientH] == 0)
    return;
  if (m_pClientList[iClientH]->m_bIsInitComplete == false)
    return;
  if (m_pClientList[iClientH]->m_iExpStock <= 0)
    return;
  // !!!!
  // v2.12 2002-2-6 脕枚脕赂碌碌 脟枚脌莽 掳忙脟猫脛隆掳隆 脙脰麓毛 路鹿潞搂
  // 掳忙脟猫脛隆潞赂麓脵 脌没脌赂赂茅 掳忙脟猫脛隆赂娄 戮貌脌禄录枚 脌脰掳脭
  // 潞炉掳忙 .. v2.15 禄猫脕娄. 脕枚脕赂碌碌 掳忙脟猫脛隆 戮貌麓脗麓脵.
  // if ((m_pClientList[iClientH]->m_iLevel >= m_iPlayerMaxLevel) &&
  // (m_pClientList[iClientH]->m_iExp >= m_iLevelExpTable[m_iPlayerMaxLevel]))
  // return;

  // 脝梅禄贸掳煤 脝盲鲁脦脝录掳隆 戮酶麓脗 赂脢 脌搂驴隆 录颅 脌脰麓脵赂茅
  // 掳忙脟猫脛隆麓脗 驴脙露贸掳隆脕枚 戮脢麓脗麓脵.
  if (m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->m_cType ==
      DEF_MAPTYPE_NOPENALTY_NOREWARD) {
    m_pClientList[iClientH]->m_iExpStock = 0;
    return;
  }

  // 卤脳碌驴戮脠 脙脿脌没 碌脟戮煤麓酶 掳忙脟猫脛隆赂娄 掳猫禄锚脟脩麓脵.
  m_pClientList[iClientH]->m_iExp += m_pClientList[iClientH]->m_iExpStock;
  m_pClientList[iClientH]->m_iAutoExpAmount +=
      m_pClientList[iClientH]->m_iExpStock;
  m_pClientList[iClientH]->m_iExpStock = 0;

  if (bCheckLimitedUser(iClientH) == false) {
    // 脙录脟猫脝脟 禄莽驴毛脌脷 脕娄脟脩驴隆 脟脴麓莽碌脟脕枚 戮脢脌赂赂茅
    // 掳忙脟猫脛隆掳隆 驴脙露煤麓脵麓脗 脜毛潞赂赂娄 脟脩麓脵.
    SendNotifyMsg(0, iClientH, DEF_NOTIFY_EXP, 0, 0, 0, 0);
  }
  // 路鹿潞搂脌脤 驴脙露煤麓脗脕枚赂娄 掳脣禄莽脟脩麓脵.
  bIsLevelUp = bCheckLevelUp(iClientH);

  // v2.03 潞炉掳忙 9/1
  if ((bIsLevelUp) && (m_pClientList[iClientH]->m_iLevel <= 5)) {
    // 脙脢潞赂驴毛 Gold 脕枚卤脼. 路鹿潞搂 1~5卤卯脕枚 100 Gold 脕枚卤脼.
    pItem = new class CItem;
    if (_bInitItemAttr(pItem, "Gold") == false) {
      delete pItem;
      return;
    } else
      pItem->m_dwCount = (DWORD)100000;
    bAddItem(iClientH, pItem, 0);
  }

  // v2.03 潞炉掳忙 9/1
  if ((bIsLevelUp) && (m_pClientList[iClientH]->m_iLevel > 5) &&
      (m_pClientList[iClientH]->m_iLevel <= 20)) {
    // 脙脢潞赂驴毛 Gold 脕枚卤脼. 路鹿潞搂 5~20卤卯脕枚 300 Gold 脕枚卤脼.
    pItem = new class CItem;
    if (_bInitItemAttr(pItem, "Gold") == false) {
      delete pItem;
      return;
    } else
      pItem->m_dwCount = (DWORD)100000;
    bAddItem(iClientH, pItem, 0);
  }
}

void CGame::___RestorePlayerRating(int iClientH) {
  if (m_pClientList[iClientH] == 0)
    return;

  if (m_pClientList[iClientH]->m_iRating < -10000)
    m_pClientList[iClientH]->m_iRating = 0;
  if (m_pClientList[iClientH]->m_iRating > 10000)
    m_pClientList[iClientH]->m_iRating = 0;
}

int CGame::iGetExpLevel(DWORD iExp) {
  int i;

  // 掳忙脟猫脛隆掳隆 戮卯麓脌 路鹿潞搂 录枚脕脴驴隆 录脫脟脧麓脗脕枚
  // 脝脟麓脺脟脩麓脵.
  for (i = 1; i < 1000; i++)
    if ((m_iLevelExpTable[i] <= iExp) && (m_iLevelExpTable[i + 1] > iExp))
      return i;

  return 0;
}

void CGame::AdminOrder_CallGuard(int iClientH, char *pData, DWORD dwMsgSize) {
  char seps[] = "= \t\n";
  char *token, cName[11], cTargetName[11], cBuff[256], cNpcName[21],
      cNpcWaypoint[11];
  class CStrTok *pStrTok;
  int i, iNamingValue, tX, tY;

  if (m_pClientList[iClientH] == 0)
    return;
  if ((dwMsgSize) <= 0)
    return;

  if (m_pClientList[iClientH]->m_iAdminUserLevel < m_iAdminLevelCallGaurd) {
    // Admin user level脌脤 鲁路戮脝录颅 脌脤 卤芒麓脡脌禄 禄莽驴毛脟脪 录枚
    // 戮酶麓脵.
    SendNotifyMsg(0, iClientH, DEF_NOTIFY_ADMINUSERLEVELLOW, 0, 0, 0, 0);
    return;
  }

  ZeroMemory(cName, sizeof(cName));
  ZeroMemory(cNpcWaypoint, sizeof(cNpcWaypoint));
  ZeroMemory(cTargetName, sizeof(cTargetName));
  ZeroMemory(cNpcName, sizeof(cNpcName));
  ZeroMemory(cBuff, sizeof(cBuff));
  memcpy(cBuff, pData, dwMsgSize);

  pStrTok = new class CStrTok(cBuff, seps);
  token = pStrTok->pGet();
  token = pStrTok->pGet();

  if (token != 0) {
    // token脌脤 掳冒 脙陇脝脙脌禄 潞脪掳隆麓脡脟脧掳脭 赂赂碌茅 禄莽驴毛脌脷
    // 脌脤赂搂
    if (strlen(token) > 10)
      memcpy(cTargetName, token, 10);
    else
      memcpy(cTargetName, token, strlen(token));

    for (i = 1; i < DEF_MAXCLIENTS; i++)
      if ((m_pClientList[i] != 0) &&
          (memcmp(m_pClientList[i]->m_cCharName, cTargetName, 10) == 0)) {
        // 赂帽脟楼 脛鲁赂炉脜脥赂娄 脙拢戮脪麓脵.

        if (memcmp(m_pClientList[i]->m_cMapName, "aresden", 7) == 0)
          strcpy(cNpcName, "Guard-Aresden");
        else if (memcmp(m_pClientList[i]->m_cMapName, "elvine", 6) == 0)
          strcpy(cNpcName, "Guard-Elvine");
        else
          strcpy(
              cNpcName,
              "Guard-Neutral"); // <- 脌脤掳脥脌潞 赂露脌禄脌脤 戮脝麓脧鹿脟路脦
                                // 脕脽赂鲁 掳隆碌氓赂娄 禄媒录潞陆脙脜虏麓脵.

        iNamingValue =
            m_pMapList[m_pClientList[i]->m_cMapIndex]->iGetEmptyNamingValue();
        if (iNamingValue == -1) {
          // 麓玫脌脤禄贸 脌脤 赂脢驴隆 NPC赂娄 赂赂碌茅录枚 戮酶麓脵.
          // 脌脤赂搂脌禄 脟脪麓莽脟脪 录枚 戮酶卤芒 露搂鹿庐.
        } else {
          // NPC赂娄 禄媒录潞脟脩麓脵.
          wsprintf(cName, "XX%d", iNamingValue);
          cName[0] = '_';
          cName[1] = m_pClientList[i]->m_cMapIndex + 65;

          tX = (int)m_pClientList[i]->m_sX;
          tY = (int)m_pClientList[i]->m_sY;
          if (bCreateNewNpc(cNpcName, cName,
                            m_pMapList[m_pClientList[i]->m_cMapIndex]->m_cName,
                            0, 0, DEF_MOVETYPE_RANDOM, &tX, &tY, cNpcWaypoint,
                            0, 0, -1, false, true) == false) {
            // 陆脟脝脨脟脽脌赂鹿脟路脦 驴鹿戮脿碌脠 NameValue赂娄
            // 脟脴脕娄陆脙脜虏麓脵.
            m_pMapList[m_pClientList[i]->m_cMapIndex]->SetNamingValueEmpty(
                iNamingValue);
          } else {
            // 掳隆碌氓赂娄 禄媒录潞陆脙脛脳麓脵. 掳酶掳脻 赂帽脟楼赂娄
            // 脟脪麓莽脟脩麓脵.
            bSetNpcAttackMode(cName, i, DEF_OWNERTYPE_PLAYER, true);
          }
        }

        delete pStrTok;
        return;
      }

    // 脟枚脌莽 脕垄录脫脕脽脌脤 戮脝麓脧麓脵.
    SendNotifyMsg(0, iClientH, DEF_NOTIFY_PLAYERNOTONGAME, 0, 0, 0,
                  cTargetName);
  }

  delete pStrTok;
  return;
}
void CGame::AdminOrder_Kill(int iClientH, char *pData, DWORD dwMsgSize) {
  char seps[] = "= \t\n";
  char *token, cName[11], cTargetName[11], cBuff[256], cNpcName[21],
      cNpcWaypoint[11];
  class CStrTok *pStrTok;
  int i;
  int sAttackerWeapon, sDamage, iExH;

  if (m_pClientList[iClientH] == 0)
    return;
  if ((dwMsgSize) <= 0)
    return;

  if (m_pClientList[iClientH]->m_iAdminUserLevel < m_iAdminLevelGMKill) {
    // Admin user level脌脤 鲁路戮脝录颅 脌脤 卤芒麓脡脌禄 禄莽驴毛脟脪 录枚
    // 戮酶麓脵.
    SendNotifyMsg(0, iClientH, DEF_NOTIFY_ADMINUSERLEVELLOW, 0, 0, 0, 0);
    return;
  }

  ZeroMemory(cNpcWaypoint, sizeof(cNpcWaypoint));
  ZeroMemory(cTargetName, sizeof(cTargetName));
  ZeroMemory(cNpcName, sizeof(cNpcName));
  ZeroMemory(cBuff, sizeof(cBuff));
  memcpy(cBuff, pData, dwMsgSize);

  pStrTok = new class CStrTok(cBuff, seps);
  token = pStrTok->pGet();
  // testcode
  // wsprintf(G_cTxt, "%s", token);
  // PutLogList(G_cTxt);
  //
  token = pStrTok->pGet();
  // testcode
  // wsprintf(G_cTxt, "%s", token);
  // PutLogList(G_cTxt);
  //
  if (token != 0) {
    ZeroMemory(cName, sizeof(cName));
    strcpy(cName, token);
  } else {
    ZeroMemory(cName, sizeof(cName));
    strcpy(cName, "null");
  }

  token = pStrTok->pGet();
  if (token != 0) {
    sDamage = atoi(token);
  } else {
    sDamage = 1;
  }

  // testcode
  // wsprintf(G_cTxt, "%s", token);
  // PutLogList(G_cTxt);
  //

  if (token == 0) {
    token = "null";
  }
  if (cName != 0) {
    token = cName;
    // token脌脤 掳冒 脙陇脝脙脌禄 潞脪掳隆麓脡脟脧掳脭 赂赂碌茅 禄莽驴毛脌脷
    // 脌脤赂搂
    if (strlen(token) > 10)
      memcpy(cTargetName, token, 10);
    else
      memcpy(cTargetName, token, strlen(token));

    for (i = 1; i < DEF_MAXCLIENTS; i++)
      if ((m_pClientList[i] != 0) &&
          (memcmp(m_pClientList[i]->m_cCharName, cTargetName, 10) == 0)) {
        // 赂帽脟楼 脛鲁赂炉脜脥赂娄 脙拢戮脪麓脵.

        m_pClientList[i]->m_iHP = 0;
        // if (iGetMaxHP(i) < m_pClientList[i]->m_iHP) m_pClientList[i]->m_iHP =
        // iGetMaxHP(i);
        m_pClientList[i]->m_bIsKilled = true;

        if (m_pClientList[i]->m_bIsExchangeMode) {
          iExH = m_pClientList[i]->m_iExchangeH;
          _ClearExchangeStatus(iExH);
          _ClearExchangeStatus(i);
        }

        RemoveFromTarget(i, DEF_OWNERTYPE_PLAYER);

        SendNotifyMsg(0, i, DEF_NOTIFY_KILLED, 0, 0, 0,
                      m_pClientList[iClientH]->m_cCharName);
        sAttackerWeapon = 1;
        SendEventToNearClient_TypeA(i, DEF_OWNERTYPE_PLAYER, MSGID_EVENT_MOTION,
                                    DEF_OBJECTDYING, sDamage, sAttackerWeapon,
                                    0);
        // 脕陇禄贸 脌搂脛隆驴隆录颅 脕枚驴卯麓脵.
        m_pMapList[m_pClientList[i]->m_cMapIndex]->ClearOwner(
            12, i, DEF_OWNERTYPE_PLAYER, m_pClientList[i]->m_sX,
            m_pClientList[i]->m_sY);
        // 脕脳脌潞 脌搂脛隆 脟楼陆脙赂娄 脟脩麓脵.
        m_pMapList[m_pClientList[i]->m_cMapIndex]->SetDeadOwner(
            i, DEF_OWNERTYPE_PLAYER, m_pClientList[i]->m_sX,
            m_pClientList[i]->m_sY);

        delete pStrTok;
        return;
      }

    // 脟枚脌莽 脕垄录脫脕脽脌脤 戮脝麓脧麓脵.
    SendNotifyMsg(0, iClientH, DEF_NOTIFY_PLAYERNOTONGAME, 0, 0, 0,
                  cTargetName);
  }

  delete pStrTok;
  return;
}

void CGame::AdminOrder_Revive(int iClientH, char *pData, DWORD dwMsgSize) {
  char seps[] = "= \t\n";
  char *token, cName[11], cTargetName[11], cBuff[256], cNpcName[21],
      cNpcWaypoint[11];
  class CStrTok *pStrTok;
  int i;
  int sAttackerWeapon, sDamage, sHP;

  if (m_pClientList[iClientH] == 0)
    return;
  if ((dwMsgSize) <= 0)
    return;

  if (m_pClientList[iClientH]->m_iAdminUserLevel < m_iAdminLevelGMRevive) {
    // Admin user level脌脤 鲁路戮脝录颅 脌脤 卤芒麓脡脌禄 禄莽驴毛脟脪 录枚
    // 戮酶麓脵.
    SendNotifyMsg(0, iClientH, DEF_NOTIFY_ADMINUSERLEVELLOW, 0, 0, 0, 0);
    return;
  }

  ZeroMemory(cNpcWaypoint, sizeof(cNpcWaypoint));
  ZeroMemory(cTargetName, sizeof(cTargetName));
  ZeroMemory(cNpcName, sizeof(cNpcName));
  ZeroMemory(cBuff, sizeof(cBuff));
  memcpy(cBuff, pData, dwMsgSize);

  pStrTok = new class CStrTok(cBuff, seps);

  token = pStrTok->pGet();
  token = pStrTok->pGet();

  if (token != 0) {
    ZeroMemory(cName, sizeof(cName));
    strcpy(cName, token);
  } else {
    ZeroMemory(cName, sizeof(cName));
    strcpy(cName, "null");
  }

  token = pStrTok->pGet();

  if (token != 0) {
    sDamage = atoi(token);
  } else {
    sDamage = 1;
  }
  token = pStrTok->pGet();
  if (token != 0) {
    sHP = atoi(token);
  } else {
    sHP = 1;
  }

  token = cName;
  // if (token == 0) { token = "null"; }
  if (cName != 0) {
    // token脌脤 掳冒 脙陇脝脙脌禄 潞脪掳隆麓脡脟脧掳脭 赂赂碌茅 禄莽驴毛脌脷
    // 脌脤赂搂
    if (strlen(token) > 10)
      memcpy(cTargetName, token, 10);
    else
      memcpy(cTargetName, token, strlen(token));

    for (i = 1; i < DEF_MAXCLIENTS; i++)
      if ((m_pClientList[i] != 0) &&
          (memcmp(m_pClientList[i]->m_cCharName, cTargetName, 10) == 0)) {
        // 赂帽脟楼 脛鲁赂炉脜脥赂娄 脙拢戮脪麓脵.

        m_pClientList[i]->m_iHP = sHP;
        if (iGetMaxHP(i) < m_pClientList[i]->m_iHP)
          m_pClientList[i]->m_iHP = iGetMaxHP(i);
        m_pClientList[i]->m_bIsKilled = false;
        m_pClientList[i]->m_iLastDamage = sDamage;
        //			SendEventToNearClient_TypeA(i,
        // DEF_OWNERTYPE_PLAYER, MSGID_EVENT_MOTION, DEF_OBJECTDAMAGEMOVE,
        // m_pClientList[i]->m_iLastDamage, 0, 0);
        SendNotifyMsg(0, i, DEF_NOTIFY_HP, 0, 0, 0, 0);
        sAttackerWeapon = 1;
        SendEventToNearClient_TypeA(i, DEF_OWNERTYPE_PLAYER, MSGID_EVENT_MOTION,
                                    DEF_OBJECTDAMAGE, sDamage, sAttackerWeapon,
                                    0);
        m_pMapList[m_pClientList[i]->m_cMapIndex]->ClearOwner(
            14, i, DEF_OWNERTYPE_PLAYER, m_pClientList[i]->m_sX,
            m_pClientList[i]->m_sY);
        m_pMapList[m_pClientList[i]->m_cMapIndex]->SetDeadOwner(
            i, DEF_OWNERTYPE_PLAYER, m_pClientList[i]->m_sX,
            m_pClientList[i]->m_sY);

        delete pStrTok;
        return;
      }

    // 脟枚脌莽 脕垄录脫脕脽脌脤 戮脝麓脧麓脵.
    SendNotifyMsg(0, iClientH, DEF_NOTIFY_PLAYERNOTONGAME, 0, 0, 0,
                  cTargetName);
  }

  delete pStrTok;
  return;
}
void CGame::AdminOrder_SummonDemon(int iClientH) {
  char cName[21], cNpcName[21], cNpcWaypoint[11];
  int iNamingValue, tX, tY;

  if (m_pClientList[iClientH] == 0)
    return;
  if (m_pClientList[iClientH]->m_bIsAdminCommandEnabled == false)
    return;

  if (m_pClientList[iClientH]->m_iAdminUserLevel < m_iAdminLevelSummonDemon) {
    // Admin user level脌脤 鲁路戮脝录颅 脌脤 卤芒麓脡脌禄 禄莽驴毛脟脪 录枚
    // 戮酶麓脵.
    SendNotifyMsg(0, iClientH, DEF_NOTIFY_ADMINUSERLEVELLOW, 0, 0, 0, 0);
    return;
  }

  iNamingValue =
      m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->iGetEmptyNamingValue();
  if (iNamingValue == -1) {
    // 麓玫脌脤禄贸 脌脤 赂脢驴隆 NPC赂娄 赂赂碌茅录枚 戮酶麓脵. 脌脤赂搂脌禄
    // 脟脪麓莽脟脪 录枚 戮酶卤芒 露搂鹿庐.
  } else {
    // NPC赂娄 禄媒录潞脟脩麓脵.
    ZeroMemory(cNpcName, sizeof(cNpcName));
    strcpy(cNpcName, "Demon");

    ZeroMemory(cName, sizeof(cName));
    wsprintf(cName, "XX%d", iNamingValue);
    cName[0] = '_';
    cName[1] = m_pClientList[iClientH]->m_cMapIndex + 65;

    ZeroMemory(cNpcWaypoint, sizeof(cNpcWaypoint));

    tX = (int)m_pClientList[iClientH]->m_sX;
    tY = (int)m_pClientList[iClientH]->m_sY;
    if (bCreateNewNpc(cNpcName, cName,
                      m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->m_cName,
                      0, (rand() % 9), DEF_MOVETYPE_RANDOM, &tX, &tY,
                      cNpcWaypoint, 0, 0, -1, false, false) == false) {
      // 陆脟脝脨脟脽脌赂鹿脟路脦 驴鹿戮脿碌脠 NameValue赂娄
      // 脟脴脕娄陆脙脜虏麓脵.
      m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->SetNamingValueEmpty(
          iNamingValue);
    } else {
      // Admin Log
      wsprintf(G_cTxt, "Admin Order(%s): Summon Demon",
               m_pClientList[iClientH]->m_cCharName);
      PutAdminLogFileList(G_cTxt);
    }
  }
}
void CGame::AdminOrder_SummonDeath(int iClientH) {
  char cName[21], cNpcName[21], cNpcWaypoint[11];
  int iNamingValue, tX, tY;

  if (m_pClientList[iClientH] == 0)
    return;
  if (m_pClientList[iClientH]->m_bIsAdminCommandEnabled == false)
    return;

  if (m_pClientList[iClientH]->m_iAdminUserLevel < m_iAdminLevelSummonDeath) {
    // Admin user level脌脤 鲁路戮脝录颅 脌脤 卤芒麓脡脌禄 禄莽驴毛脟脪 录枚
    // 戮酶麓脵.
    SendNotifyMsg(0, iClientH, DEF_NOTIFY_ADMINUSERLEVELLOW, 0, 0, 0, 0);
    return;
  }

  iNamingValue =
      m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->iGetEmptyNamingValue();
  if (iNamingValue == -1) {
    // 麓玫脌脤禄贸 脌脤 赂脢驴隆 NPC赂娄 赂赂碌茅录枚 戮酶麓脵. 脌脤赂搂脌禄
    // 脟脪麓莽脟脪 录枚 戮酶卤芒 露搂鹿庐.
  } else {
    // NPC赂娄 禄媒录潞脟脩麓脵.
    ZeroMemory(cNpcName, sizeof(cNpcName));
    strcpy(cNpcName, "Wyvern");

    ZeroMemory(cName, sizeof(cName));
    wsprintf(cName, "XX%d", iNamingValue);
    cName[0] = '_';
    cName[1] = m_pClientList[iClientH]->m_cMapIndex + 65;

    ZeroMemory(cNpcWaypoint, sizeof(cNpcWaypoint));

    tX = (int)m_pClientList[iClientH]->m_sX;
    tY = (int)m_pClientList[iClientH]->m_sY;
    if (bCreateNewNpc(cNpcName, cName,
                      m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->m_cName,
                      0, (rand() % 9), DEF_MOVETYPE_RANDOM, &tX, &tY,
                      cNpcWaypoint, 0, 0, -1, false, false) == false) {
      // 陆脟脝脨脟脽脌赂鹿脟路脦 驴鹿戮脿碌脠 NameValue赂娄
      // 脟脴脕娄陆脙脜虏麓脵.
      m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->SetNamingValueEmpty(
          iNamingValue);
    } else {
      // Admin Log
      wsprintf(G_cTxt, "Admin Order(%s): Summon Death",
               m_pClientList[iClientH]->m_cCharName);
      PutAdminLogFileList(G_cTxt);
    }
  }
}
// v1.4311-3 脙脽掳隆 驴卯驴碌脌脷掳隆 禄莽脜玫脌氓脌禄 驴鹿戮脿脟脩麓脵.
void CGame::AdminOrder_ReserveFightzone(int iClientH, char *pData,
                                        DWORD dwMsgSize) {
  char seps[] = "= \t\n";
  char *token, cBuff[256];
  class CStrTok *pStrTok;
  int iNum;

  if (m_pClientList[iClientH] == 0)
    return;
  if ((dwMsgSize) <= 0)
    return;

  if (m_pClientList[iClientH]->m_iAdminUserLevel <
      m_iAdminLevelReserveFightzone) {
    // Admin user level脌脤 鲁路戮脝录颅 脌脤 卤芒麓脡脌禄 禄莽驴毛脟脪 录枚
    // 戮酶麓脵.
    SendNotifyMsg(0, iClientH, DEF_NOTIFY_ADMINUSERLEVELLOW, 0, 0, 0, 0);
    return;
  }

  ZeroMemory(cBuff, sizeof(cBuff));
  memcpy(cBuff, pData, dwMsgSize);

  pStrTok = new class CStrTok(cBuff, seps);
  token = pStrTok->pGet();
  token = pStrTok->pGet();

  if (m_iFightzoneNoForceRecall == 0) {
    m_iFightzoneNoForceRecall = 1;
    SendNotifyMsg(0, iClientH, DEF_NOTIFY_FIGHTZONERESERVE, -5, 0, 0, 0);
  } else {
    m_iFightzoneNoForceRecall = 0;
    SendNotifyMsg(0, iClientH, DEF_NOTIFY_FIGHTZONERESERVE, -4, 0, 0, 0);
  }

  if (token == 0) {
    delete pStrTok;
    return;
  }

  iNum = atoi(token) - 1;

  if (m_iFightZoneReserve[iNum] != -1) {
    // Admin Log
    wsprintf(G_cTxt, "Admin Order(%s):  %d FightzoneReserved",
             m_pClientList[iClientH]->m_cCharName, iNum);
    PutAdminLogFileList(G_cTxt);

    m_iFightZoneReserve[iNum] =
        -1; // 驴卯驴碌脌脷掳隆 驴鹿戮脿脟脩 禄莽脜玫脌氓脌潞 -1 掳陋脌脤
            // 碌茅戮卯掳拢麓脵. 脌脤脕娄潞脦脜脥 掳猫录脫 麓脵赂楼 脌炉脌煤麓脗
            // 驴鹿戮脿脌脤 潞脪掳隆麓脡脟脧麓脵.
    // 驴卯驴碌脌脷掳隆 禄莽脜玫脌氓 驴鹿戮脿驴隆 录潞掳酶脟脧麓脗 掳忙驴矛
    SendNotifyMsg(0, iClientH, DEF_NOTIFY_FIGHTZONERESERVE, iNum + 1, 0, 0, 0);

  } else { // 驴卯驴碌脌脷掳隆 驴鹿戮脿脟脩 禄莽脜玫脌氓脌禄 麓脵陆脙
           // 驴鹿戮脿脟脧赂茅 驴鹿戮脿脌脤 脙毛录脪碌脠麓脵.
    wsprintf(G_cTxt, "Admin Order(%s):  %d Cancel FightzoneReserved",
             m_pClientList[iClientH]->m_cCharName, iNum);
    PutAdminLogFileList(G_cTxt);

    m_iFightZoneReserve[iNum] = 0;
    // 驴卯驴碌脌脷掳隆 禄莽脜玫脌氓 驴鹿戮脿脌禄 脙毛录脪脟脧麓脗 掳忙驴矛 -3
    // 掳陋脌禄 鲁脩掳脺脕脴麓脵.
    SendNotifyMsg(0, iClientH, DEF_NOTIFY_FIGHTZONERESERVE, -3, 0, 0, 0);
  }

  return;
}

void CGame::AdminOrder_CloseConn(int iClientH, char *pData, DWORD dwMsgSize) {
  char seps[] = "= \t\n";
  char *token, cTargetName[11], cBuff[256];
  class CStrTok *pStrTok;
  int i;

  if (m_pClientList[iClientH] == 0)
    return;
  if ((dwMsgSize) <= 0)
    return;

  if (m_pClientList[iClientH]->m_iAdminUserLevel < m_iAdminLevelGMCloseconn) {
    SendNotifyMsg(0, iClientH, DEF_NOTIFY_ADMINUSERLEVELLOW, 0, 0, 0, 0);
    return;
  }

  ZeroMemory(cTargetName, sizeof(cTargetName));
  ZeroMemory(cBuff, sizeof(cBuff));
  memcpy(cBuff, pData, dwMsgSize);

  pStrTok = new class CStrTok(cBuff, seps);
  token = pStrTok->pGet();
  token = pStrTok->pGet();
  if (token != 0) {
    if (strlen(token) > 10)
      memcpy(cTargetName, token, 10);
    else
      memcpy(cTargetName, token, strlen(token));

    for (i = 1; i < DEF_MAXCLIENTS; i++)
      if ((m_pClientList[i] != 0) &&
          (memcmp(m_pClientList[i]->m_cCharName, cTargetName, 10) == 0)) {
        if (m_pClientList[i]->m_bIsInitComplete) {
          DeleteClient(i, true, true, true, true);
        }

        // Admin Log
        wsprintf(G_cTxt, "Admin Order(%s): Close Conn",
                 m_pClientList[iClientH]->m_cCharName);
        PutAdminLogFileList(G_cTxt);

        delete pStrTok;
        return;
      }
    SendNotifyMsg(0, iClientH, DEF_NOTIFY_PLAYERNOTONGAME, 0, 0, 0,
                  cTargetName);
  }

  delete pStrTok;
  return;
}

void CGame::UserCommand_BanGuildsman(int iClientH, char *pData,
                                     DWORD dwMsgSize) {
  char seps[] = "= \t\n";
  char *token, cTargetName[11], cBuff[256];
  class CStrTok *pStrTok;
  int i;

  if (m_pClientList[iClientH] == 0)
    return;
  if ((dwMsgSize) <= 0)
    return;

  if (m_pClientList[iClientH]->m_iGuildRank != 0) {
    SendNotifyMsg(0, iClientH, DEF_NOTIFY_NOGUILDMASTERLEVEL, 0, 0, 0, 0);
    return;
  }

  ZeroMemory(cTargetName, sizeof(cTargetName));
  ZeroMemory(cBuff, sizeof(cBuff));
  memcpy(cBuff, pData, dwMsgSize);

  pStrTok = new class CStrTok(cBuff, seps);
  token = pStrTok->pGet();
  token = pStrTok->pGet();

  if (token != 0) {
    if (strlen(token) > 10)
      memcpy(cTargetName, token, 10);
    else
      memcpy(cTargetName, token, strlen(token));

    for (i = 1; i < DEF_MAXCLIENTS; i++)
      if ((m_pClientList[i] != 0) &&
          (memcmp(m_pClientList[i]->m_cCharName, cTargetName, 10) == 0)) {

        if (memcmp(m_pClientList[iClientH]->m_cGuildName,
                   m_pClientList[i]->m_cGuildName, 20) != 0) {

          SendNotifyMsg(0, iClientH, DEF_NOTIFY_CANNOTBANGUILDMAN, 0, 0, 0, 0);
          delete pStrTok;
          return;
        }
        // bSendMsgToLS(MSGID_REQUEST_UPDATEGUILDINFO_DELGUILDSMAN, i);

        SendGuildMsg(i, DEF_NOTIFY_DISMISSGUILDSMAN, 0, 0, 0);

        ZeroMemory(m_pClientList[i]->m_cGuildName,
                   sizeof(m_pClientList[i]->m_cGuildName));
        strcpy(m_pClientList[i]->m_cGuildName, "NONE");
        m_pClientList[i]->m_iGuildRank = -1;
        m_pClientList[i]->m_iGuildGUID = -1;

        SendNotifyMsg(0, iClientH, DEF_NOTIFY_SUCCESSBANGUILDMAN, 0, 0, 0, 0);

        SendNotifyMsg(iClientH, i, DEF_COMMONTYPE_BANGUILD, 0, 0, 0, 0);

        SendEventToNearClient_TypeA(i, DEF_OWNERTYPE_PLAYER, MSGID_EVENT_MOTION,
                                    DEF_OBJECTNULLACTION, 0, 0, 0);

        delete pStrTok;
        return;
      }
    SendNotifyMsg(0, iClientH, DEF_NOTIFY_PLAYERNOTONGAME, 0, 0, 0,
                  cTargetName);
  }

  delete pStrTok;
  return;
}

void CGame::UserCommand_DissmissGuild(int iClientH, char *pData,
                                      DWORD dwMsgSize) {}

void CGame::RequestCreateNewGuild(int iClientH, char *pData) {
  char cFileName[255], cData[512];
  char cTxt[500];
  char cTxt2[100];
  char cGuildMasterName[11], cGuildLocation[11], cDir[255], cGuildName[21];
  char *cp;
  DWORD *dwp, dwGuildGUID;
  WORD *wp;
  int iRet;
  SYSTEMTIME SysTime;
  FILE *pFile;

  if (m_pClientList[iClientH] == 0)
    return;
  ZeroMemory(cFileName, sizeof(cFileName));
  ZeroMemory(cTxt, sizeof(cTxt));
  ZeroMemory(cTxt2, sizeof(cTxt2));
  ZeroMemory(cDir, sizeof(cDir));
  ZeroMemory(cData, sizeof(cData));
  ZeroMemory(cGuildMasterName, sizeof(cGuildMasterName));
  ZeroMemory(cGuildName, sizeof(cGuildName));
  ZeroMemory(cGuildLocation, sizeof(cGuildLocation));

  cp = (char *)pData;

  memcpy(cGuildMasterName, cp, 10);
  cp += 10;

  memcpy(cGuildName, cp, 20);
  cp += 20;

  memcpy(cGuildLocation, cp, 10);
  cp += 10;

  dwp = (DWORD *)cp;
  dwGuildGUID = *dwp;
  cp += 4;

  strcat(cFileName, "Guilds");
  strcat(cFileName, "\\");
  wsprintf(cTxt2, "AscII%d", *cGuildName);
  strcat(cFileName, cTxt2);
  strcat(cDir, cFileName);
  strcat(cFileName, "\\");
  strcat(cFileName, "\\");
  strcat(cFileName, cGuildName);
  strcat(cFileName, ".txt");

  _mkdir("Guilds");
  _mkdir(cDir);

  pFile = fopen(cFileName, "rt");
  if (pFile != 0) {
    wsprintf(
        cTxt2,
        "(X) Cannot create new guild - Already existing guild name: Name(%s)",
        cFileName);
    PutLogList(cTxt2);

    ResponseCreateNewGuildHandler(
        cGuildMasterName,
        0); // iRet = m_pClientList[iClientH]->m_pXSock->iSendMsg(cData, 16);
    fclose(pFile);
  } else {
    pFile = fopen(cFileName, "wt");
    if (pFile == 0) {
      wsprintf(cTxt2,
               "(X) Cannot create new guild - cannot create file : Name(%s)",
               cFileName);
      PutLogList(cTxt2);

      ResponseCreateNewGuildHandler(
          cGuildMasterName,
          0); // iRet = m_pClientList[iClientH]->m_pXSock->iSendMsg(cData, 16);
    } else {
      wsprintf(cTxt2, "(O) New guild created : Name(%s)", cFileName);
      PutLogList(cTxt2);

      ZeroMemory(cTxt2, sizeof(cTxt2));
      ZeroMemory(cTxt, sizeof(cTxt));
      GetLocalTime(&SysTime);

      wsprintf(cTxt, ";Guild file - Updated %4d/%2d/%2d/%2d/%2d", SysTime.wYear,
               SysTime.wMonth, SysTime.wDay, SysTime.wHour, SysTime.wMinute);
      strcat(cTxt, "\n");
      strcat(cTxt, ";Just created\n\n");

      strcat(cTxt, "[GUILD-INFO]\n\n");

      strcat(cTxt, "guildmaster-name     = ");
      strcat(cTxt, cGuildMasterName);
      strcat(cTxt, "\n");

      strcat(cTxt, "guild-GUID           = ");
      wsprintf(cTxt2, "%d", dwGuildGUID);
      strcat(cTxt, cTxt2);
      strcat(cTxt, "\n");

      strcat(cTxt, "guild-location       = ");
      strcat(cTxt, cGuildLocation);
      strcat(cTxt, "\n\n");

      strcat(cTxt, "[GUILDSMAN]\n\n");

      fwrite(cTxt, 1, strlen(cTxt), pFile);

      ResponseCreateNewGuildHandler(
          cGuildMasterName,
          1); // iRet = m_pClientList[iClientH]->m_pXSock->iSendMsg(cData, 16);
      fclose(pFile);
    }
  }
  /*switch (iRet) {
  case DEF_XSOCKEVENT_QUENEFULL:
  case DEF_XSOCKEVENT_SOCKETERROR:
  case DEF_XSOCKEVENT_CRITICALERROR:
  case DEF_XSOCKEVENT_SOCKETCLOSED:
          DeleteClient(iClientH, 0);
          delete m_pClientList[iClientH];
          m_pClientList[iClientH] = 0;
          return;
  }*/
}

