int CGame::iCreateFish(char cMapIndex, short sX, short sY, short sType,
                       class CItem *pItem, int iDifficulty, DWORD dwLastTime) {
  int i, iDynamicHandle;

  // 赂脢脌脟 脌搂脛隆掳隆 鹿掳脌脦脕枚 脠庐脌脦脟脩麓脵.
  if ((cMapIndex < 0) || (cMapIndex >= DEF_MAXMAPS))
    return 0;
  if (m_pMapList[cMapIndex] == 0)
    return 0;
  if (m_pMapList[cMapIndex]->bGetIsWater(sX, sY) == false)
    return 0;

  for (i = 1; i < DEF_MAXFISHS; i++)
    if (m_pFish[i] == 0) {
      // 潞贸 掳酶掳拢驴隆 鹿掳掳铆卤芒赂娄 赂赂碌莽麓脵.
      m_pFish[i] =
          new class CFish(cMapIndex, sX, sY, sType, pItem, iDifficulty);
      if (m_pFish[i] == 0)
        return 0;

      // Dynamic Object赂娄 鹿脽禄媒陆脙脜虏麓脵. Owner驴隆 Fish
      // 脌脦碌娄陆潞赂娄 鲁脰麓脗麓脵.
      switch (pItem->m_sIDnum) {
      case 101: // 禄隆掳颅鹿掳掳铆卤芒
      case 102: // 脙脢路脧鹿掳掳铆卤芒
      case 103: // 鲁毛露没鹿掳掳铆卤芒
      case 570:
      case 571:
      case 572:
      case 573:
      case 574:
      case 575:
      case 576:
      case 577:
        iDynamicHandle = iAddDynamicObjectList(i, 0, DEF_DYNAMICOBJECT_FISH,
                                               cMapIndex, sX, sY, dwLastTime);
        break;
      default:
        // 鹿掳掳铆卤芒掳隆 戮脝麓脩 麓脵赂楼 戮脝脌脤脜脹
        iDynamicHandle = iAddDynamicObjectList(
            i, 0, DEF_DYNAMICOBJECT_FISHOBJECT, cMapIndex, sX, sY, dwLastTime);
        break;
      }

      if (iDynamicHandle == 0) {
        delete m_pFish[i];
        m_pFish[i] = 0;
        return 0;
      }
      m_pFish[i]->m_sDynamicObjectHandle = iDynamicHandle;
      m_pMapList[cMapIndex]->m_iCurFish++;

      return i;
    }

  return 0;
}

bool CGame::bDeleteFish(int iHandle, int iDelMode) {
  int i, iH;
  DWORD dwTime;

  if (m_pFish[iHandle] == 0)
    return false;

  dwTime = timeGetTime();

  // 驴卢掳眉碌脟戮卯 脌脰麓脗 DynamicObject赂娄 禄猫脕娄脟脩麓脵.
  iH = m_pFish[iHandle]->m_sDynamicObjectHandle;

  if (m_pDynamicObjectList[iH] != 0) {
    SendEventToNearClient_TypeB(
        MSGID_DYNAMICOBJECT, DEF_MSGTYPE_REJECT,
        m_pDynamicObjectList[iH]->m_cMapIndex, m_pDynamicObjectList[iH]->m_sX,
        m_pDynamicObjectList[iH]->m_sY, m_pDynamicObjectList[iH]->m_sType, iH,
        0, (short)0);
    // 赂脢驴隆录颅 禄猫脕娄脟脩麓脵.
    m_pMapList[m_pDynamicObjectList[iH]->m_cMapIndex]->SetDynamicObject(
        0, 0, m_pDynamicObjectList[iH]->m_sX, m_pDynamicObjectList[iH]->m_sY,
        dwTime);
    m_pMapList[m_pDynamicObjectList[iH]->m_cMapIndex]->m_iCurFish--;

    delete m_pDynamicObjectList[iH];
    m_pDynamicObjectList[iH] = 0;
  }

  // 脌脤 鹿掳掳铆卤芒驴脥 驴卢掳谩碌脟戮卯 脌脰麓脗
  // 脟脙路鹿脌脤戮卯碌茅驴隆掳脭 鹿掳掳铆卤芒掳隆 禄莽露贸脕庐 鲁卢陆脙掳隆
  // 脙毛录脪碌脟戮煤脌陆脌禄 戮脣路脕脕脴麓脵.
  for (i = 1; i < DEF_MAXCLIENTS; i++) {
    if ((m_pClientList[i] != 0) && (m_pClientList[i]->m_bIsInitComplete) &&
        (m_pClientList[i]->m_iAllocatedFish == iHandle)) {
      // 赂脼陆脙脕枚 脌眉录脹
      SendNotifyMsg(0, i, DEF_NOTIFY_FISHCANCELED, iDelMode, 0, 0, 0);
      ClearSkillUsingStatus(
          i); // v1.4 鲁卢陆脙 陆潞脜鲁脌禄 脜卢赂庐戮卯脟脩麓脵.
    }
  }

  // 禄猫脕娄脟脩麓脵.
  delete m_pFish[iHandle];
  m_pFish[iHandle] = 0;

  return true;
}

int CGame::iCheckFish(int iClientH, char cMapIndex, short dX, short dY) {
  int i;
  short sDistX, sDistY;

  if (m_pClientList[iClientH] == 0)
    return 0;
  if (m_pClientList[iClientH]->m_bIsInitComplete == false)
    return 0;

  if ((cMapIndex < 0) || (cMapIndex >= DEF_MAXMAPS))
    return 0;

  // 赂脢脌脟 脝炉脕陇 脌搂脛隆 鲁禄驴隆 鹿掳掳铆卤芒 麓脵脌脤鲁陋鹿脥
  // 驴脌潞锚脕搂脝庐掳隆 脌脰麓脗脕枚 脝脟麓脺脟脩麓脵.
  for (i = 1; i < DEF_MAXDYNAMICOBJECTS; i++)
    if (m_pDynamicObjectList[i] != 0) {
      sDistX = abs(m_pDynamicObjectList[i]->m_sX - dX);
      sDistY = abs(m_pDynamicObjectList[i]->m_sY - dY);

      if ((m_pDynamicObjectList[i]->m_cMapIndex == cMapIndex) &&
          ((m_pDynamicObjectList[i]->m_sType == DEF_DYNAMICOBJECT_FISH) ||
           (m_pDynamicObjectList[i]->m_sType ==
            DEF_DYNAMICOBJECT_FISHOBJECT)) &&
          (sDistX <= 2) && (sDistY <= 2)) {
        // 鹿掳掳铆卤芒 麓脵脌脤鲁陋鹿脥 驴脌潞锚脕搂脝庐赂娄 脙拢戮脪麓脵.
        // 脌脤脕娄 脌脤 麓脵脌脤鲁陋鹿脥 驴脌潞锚脕搂脝庐 脌脦碌娄陆潞赂娄
        // 录脪脌炉脟脩 Fish脌脟 脌脦碌娄陆潞赂娄 鹿脻脠炉脟脩麓脵.

        if (m_pFish[m_pDynamicObjectList[i]->m_sOwner] == 0)
          return 0;
        if (m_pFish[m_pDynamicObjectList[i]->m_sOwner]->m_sEngagingCount >=
            DEF_MAXENGAGINGFISH)
          return 0;

        // 脌脤鹿脤 鲁卢陆脙赂冒碌氓驴隆 碌茅戮卯掳隆 脌脰麓脗 脛鲁赂炉脜脥麓脗
        // 脕脽潞鹿 碌驴脌脹脌脤 潞脪掳隆麓脡.
        if (m_pClientList[iClientH]->m_iAllocatedFish != 0)
          return 0;
        if (m_pClientList[iClientH]->m_cMapIndex != cMapIndex)
          return 0;
        // 脌脤脕娄 脛鲁赂炉脜脥驴隆掳脭 鲁卢陆脙 赂冒碌氓赂娄 陆脙脌脹脟脪
        // 掳脥脌禄 脟脪麓莽脟脩麓脵.
        m_pClientList[iClientH]->m_iAllocatedFish =
            m_pDynamicObjectList[i]->m_sOwner;
        m_pClientList[iClientH]->m_iFishChance = 1;
        // 脌脤 脛鲁赂炉脜脥麓脗 鲁卢陆脙 陆潞脜鲁脌禄 禄莽驴毛脕脽脌脫脌禄
        // 录鲁脕陇.
        m_pClientList[iClientH]->m_bSkillUsingStatus[1] = true;

        SendNotifyMsg(
            0, iClientH, DEF_NOTIFY_EVENTFISHMODE,
            (m_pFish[m_pDynamicObjectList[i]->m_sOwner]->m_pItem->m_wPrice / 2),
            m_pFish[m_pDynamicObjectList[i]->m_sOwner]->m_pItem->m_sSprite,
            m_pFish[m_pDynamicObjectList[i]->m_sOwner]->m_pItem->m_sSpriteFrame,
            m_pFish[m_pDynamicObjectList[i]->m_sOwner]->m_pItem->m_cName);

        // 脛芦驴卯脝庐 脕玫掳隆
        m_pFish[m_pDynamicObjectList[i]->m_sOwner]->m_sEngagingCount++;

        return i;
      }
    }

  return 0;
}

void CGame::FishProcessor() {
  int i, iSkillLevel, iResult, iChangeValue;

  // 捞亥飘 超矫 葛靛啊 且寸等 敲饭捞绢甸阑 贸府茄促.
  for (i = 1; i < DEF_MAXCLIENTS; i++) {
    if ((m_pClientList[i] != 0) && (m_pClientList[i]->m_bIsInitComplete) &&
        (m_pClientList[i]->m_iAllocatedFish != 0)) {

      if (m_pFish[m_pClientList[i]->m_iAllocatedFish] == 0)
        break;

      // 捞 敲饭捞绢俊霸 且寸等 拱绊扁啊 乐促. 超阑 犬伏阑 犁拌魂窍咯 烹焊秦
      // 霖促. 超矫 扁贱狼 胶懦
      iSkillLevel = m_pClientList[i]->m_cSkillMastery[1];
      // 拱绊扁狼 抄捞档俊 蝶扼 胶懦 饭骇捞 冻绢柳促.
      iSkillLevel -= m_pFish[m_pClientList[i]->m_iAllocatedFish]->m_iDifficulty;
      if (iSkillLevel <= 0)
        iSkillLevel = 1;

      iChangeValue = iSkillLevel / 10;
      if (iChangeValue <= 0)
        iChangeValue = 1;
      iChangeValue = iDice(1, iChangeValue);

      iResult = iDice(1, 100);
      if (iSkillLevel > iResult) {
        // 胶懦 林荤困 奔覆 己傍. 超阑 犬伏 刘啊.
        m_pClientList[i]->m_iFishChance += iChangeValue;
        if (m_pClientList[i]->m_iFishChance > 99)
          m_pClientList[i]->m_iFishChance = 99;

        SendNotifyMsg(0, i, DEF_NOTIFY_FISHCHANCE,
                      m_pClientList[i]->m_iFishChance, 0, 0, 0);
      } else if (iSkillLevel < iResult) {
        // 胶懦 林荤困 奔覆 角菩. 超阑 犬伏 皑家.
        m_pClientList[i]->m_iFishChance -= iChangeValue;
        if (m_pClientList[i]->m_iFishChance < 1)
          m_pClientList[i]->m_iFishChance = 1;

        SendNotifyMsg(0, i, DEF_NOTIFY_FISHCHANCE,
                      m_pClientList[i]->m_iFishChance, 0, 0, 0);
      }
    }
  }
}

void CGame::AdminOrder_CreateFish(int iClientH, char *pData, DWORD dwMsgSize) {
  char seps[] = "= \t\n";
  char *token, cBuff[256], cItemName[21];
  class CStrTok *pStrTok;
  class CItem *pItem;
  int tX, tY, iType;

  if (m_pClientList[iClientH] == 0)
    return;
  if ((dwMsgSize) <= 0)
    return;

  if (m_pClientList[iClientH]->m_iAdminUserLevel < m_iAdminLevelCreateFish) {
    // Admin user level脌脤 鲁路戮脝录颅 脌脤 卤芒麓脡脌禄 禄莽驴毛脟脪 录枚
    // 戮酶麓脵.
    SendNotifyMsg(0, iClientH, DEF_NOTIFY_ADMINUSERLEVELLOW, 0, 0, 0, 0);
    return;
  }

  tX = tY = iType = 0;

  ZeroMemory(cBuff, sizeof(cBuff));
  memcpy(cBuff, pData, dwMsgSize);

  pStrTok = new class CStrTok(cBuff, seps);
  token = pStrTok->pGet();

  token = pStrTok->pGet();
  if (token != 0) {
    tX = atoi(token);
  }

  token = pStrTok->pGet();
  if (token != 0) {
    tY = atoi(token);
  }

  token = pStrTok->pGet();
  if (token != 0) {
    iType = atoi(token);
  }

  if ((tX != 0) && (tY != 0) && (iType != 0)) {
    // 脌脤 脕脗脟楼驴隆 鹿掳掳铆卤芒赂娄 赂赂碌莽麓脵.
    pItem = new class CItem;
    if (pItem == 0) {
      delete pStrTok;
      return;
    }
    ZeroMemory(cItemName, sizeof(cItemName));
    strcpy(cItemName, "鹿掳掳铆卤芒");
    if (_bInitItemAttr(pItem, cItemName)) {
      iCreateFish(m_pClientList[iClientH]->m_cMapIndex, tX, tY, iType, pItem, 1,
                  60000 * 20);
    } else
      delete pItem;
  }

  delete pStrTok;
  return;
}

