void CGame::ReqGetFishThisTimeHandler(int iClientH) {
  int iResult, iFishH;
  class CItem *pItem;

  if (m_pClientList[iClientH] == 0)
    return;
  if (m_pClientList[iClientH]->m_bIsInitComplete == false)
    return;
  if (m_pClientList[iClientH]->m_iAllocatedFish == 0)
    return;
  if (m_pFish[m_pClientList[iClientH]->m_iAllocatedFish] == 0)
    return;

  // 超矫 胶懦 荤侩吝烙阑 秦力矫挪促.
  m_pClientList[iClientH]->m_bSkillUsingStatus[1] = false;

  iResult = iDice(1, 100);
  if (m_pClientList[iClientH]->m_iFishChance >= iResult) {
    // 捞 拱绊扁甫 超绰单 己傍窍看促!

    // 版氰摹 刘啊
    GetExp(
        iClientH,
        iDice(
            m_pFish[m_pClientList[iClientH]->m_iAllocatedFish]->m_iDifficulty,
            5)); // m_pClientList[iClientH]->m_iExpStock +=
                 // iDice(m_pFish[m_pClientList[iClientH]->m_iAllocatedFish]->m_iDifficulty,
                 // 5);
    // 胶懦 刘啊
    CalculateSSN_SkillIndex(
        iClientH, 1,
        m_pFish[m_pClientList[iClientH]->m_iAllocatedFish]->m_iDifficulty);

    // 酒捞袍 器牢磐甫 掘绢柯促.
    pItem = m_pFish[m_pClientList[iClientH]->m_iAllocatedFish]->m_pItem;
    m_pFish[m_pClientList[iClientH]->m_iAllocatedFish]->m_pItem = 0;

    // 超篮 酒捞袍阑 官蹿俊 冻绢哆赴促.
    m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->bSetItem(
        m_pClientList[iClientH]->m_sX, m_pClientList[iClientH]->m_sY, pItem);

    // 促弗 努扼捞攫飘俊霸 酒捞袍捞 冻绢柳 巴阑 舅赴促.
    SendEventToNearClient_TypeB(
        MSGID_EVENT_COMMON, DEF_COMMONTYPE_ITEMDROP,
        m_pClientList[iClientH]->m_cMapIndex, m_pClientList[iClientH]->m_sX,
        m_pClientList[iClientH]->m_sY, pItem->m_sIDnum, 0, pItem->m_cItemColor,
        pItem->m_dwAttribute); // v1.4 color

    // 超矫 己傍 皋矫瘤 傈价
    SendNotifyMsg(0, iClientH, DEF_NOTIFY_FISHSUCCESS, 0, 0, 0, 0);
    iFishH = m_pClientList[iClientH]->m_iAllocatedFish;
    m_pClientList[iClientH]->m_iAllocatedFish = 0;

    // 拱绊扁甫 瘤快绊 府畔
    bDeleteFish(iFishH,
                1); // <- 咯扁辑 促弗 超矫槽甸俊霸 皋矫瘤啊 傈价瞪 巴捞促.
    return;
  }

  // 超绰单 角菩!
  m_pFish[m_pClientList[iClientH]->m_iAllocatedFish]->m_sEngagingCount--;
  SendNotifyMsg(0, iClientH, DEF_NOTIFY_FISHFAIL, 0, 0, 0, 0);

  m_pClientList[iClientH]->m_iAllocatedFish = 0;
}

void CGame::FishGenerator() {
  int i, iP, tX, tY, iRet;
  char cItemName[21];
  short sDifficulty;
  DWORD dwLastTime;
  class CItem *pItem;

  for (i = 0; i < DEF_MAXMAPS; i++) {
    if ((iDice(1, 10) == 5) && (m_pMapList[i] != 0) &&
        (m_pMapList[i]->m_iCurFish < m_pMapList[i]->m_iMaxFish)) {

      iP = iDice(1, m_pMapList[i]->m_iTotalFishPoint) - 1;
      if ((m_pMapList[i]->m_FishPointList[iP].x == -1) ||
          (m_pMapList[i]->m_FishPointList[iP].y == -1))
        break;

      tX = m_pMapList[i]->m_FishPointList[iP].x + (iDice(1, 3) - 2);
      tY = m_pMapList[i]->m_FishPointList[iP].y + (iDice(1, 3) - 2);

      pItem = new class CItem;
      if (pItem == 0)
        break;

      // 赂赂碌茅 鹿掳掳铆卤芒 脕戮路霉驴脥 鲁颅脌脤碌碌, 脕枚录脫 陆脙掳拢脌禄
      // 掳谩脕陇脟脩麓脵.
      ZeroMemory(cItemName, sizeof(cItemName));
      switch (iDice(1, 9)) {
      case 1:
        strcpy(cItemName, "RedCarp");
        sDifficulty = iDice(1, 10) + 20;
        break;
      case 2:
        strcpy(cItemName, "GreenCarp");
        sDifficulty = iDice(1, 5) + 10;
        break;
      case 3:
        strcpy(cItemName, "GoldCarp");
        sDifficulty = iDice(1, 10) + 1;
        break;
      case 4:
        strcpy(cItemName, "CrucianCarp");
        sDifficulty = 1;
        break;
      case 5:
        strcpy(cItemName, "BlueSeaBream");
        sDifficulty = iDice(1, 15) + 1;
        break;
      case 6:
        strcpy(cItemName, "RedSeaBream");
        sDifficulty = iDice(1, 18) + 1;
        break;
      case 7:
        strcpy(cItemName, "Salmon");
        sDifficulty = iDice(1, 12) + 1;
        break;
      case 8:
        strcpy(cItemName, "GrayMullet");
        sDifficulty = iDice(1, 10) + 1;
        break;
      case 9:
        // 掳隆虏没 掳隆麓脵 鲁卢脌禄 录枚 脌脰麓脗 脝炉录枚 戮脝脌脤脜脹
        switch (iDice(1, 150)) {
        case 1:
        case 2:
        case 3:
          strcpy(cItemName, "PowerGreenPotion");
          sDifficulty = iDice(5, 4) + 30;
          break;

        case 10:
        case 11:
          strcpy(cItemName, "SuperPowerGreenPotion");
          sDifficulty = iDice(5, 4) + 50;
          break;

        case 20:
          strcpy(cItemName, "Dagger+2");
          sDifficulty = iDice(5, 4) + 30;
          break;

        case 30:
          strcpy(cItemName, "LongSword+2");
          sDifficulty = iDice(5, 4) + 40;
          break;

        case 40:
          strcpy(cItemName, "Scimitar+2");
          sDifficulty = iDice(5, 4) + 50;
          break;

        case 50:
          strcpy(cItemName, "Rapier+2");
          sDifficulty = iDice(5, 4) + 60;
          break;

        case 60:
          strcpy(cItemName, "Flameberge+2");
          sDifficulty = iDice(5, 4) + 60;
          break;

        case 70:
          strcpy(cItemName, "WarAxe+2");
          sDifficulty = iDice(5, 4) + 50;
          break;

        case 90:
          strcpy(cItemName, "Ruby");
          sDifficulty = iDice(5, 4) + 40;
          break;

        case 95:
          strcpy(cItemName, "Diamond");
          sDifficulty = iDice(5, 4) + 40;
          break;
        }
        break;
      }
      dwLastTime = (60000 * 10) + (iDice(1, 3) - 1) * (60000 * 10);

      if (_bInitItemAttr(pItem, cItemName)) {
        iRet = iCreateFish(i, tX, tY, 1, pItem, sDifficulty, dwLastTime);
      } else {
        delete pItem;
        pItem = 0;
      }
    }
  }
}

int CGame::_iCalcPlayerNum(char cMapIndex, short dX, short dY, char cRadius) {
  int ix, iy, iRet;
  class CTile *pTile;

  // 脙鲁赂庐 录脫碌碌赂娄 鲁么脌脤卤芒 脌搂脟脴 脟脭录枚赂娄 脛脻脟脧脕枚
  // 戮脢麓脗麓脵.
  if ((cMapIndex < 0) || (cMapIndex > DEF_MAXMAPS))
    return 0;
  if (m_pMapList[cMapIndex] == 0)
    return 0;

  iRet = 0;
  for (ix = dX - cRadius; ix <= dX + cRadius; ix++)
    for (iy = dY - cRadius; iy <= dY + cRadius; iy++) {
      if ((ix < 0) || (ix >= m_pMapList[cMapIndex]->m_sSizeX) || (iy < 0) ||
          (iy >= m_pMapList[cMapIndex]->m_sSizeY)) {
        // 脕脗脟楼赂娄 鹿镁戮卯鲁陋鹿脟路脦 脙鲁赂庐脟脧脕枚 戮脢麓脗麓脵.
      } else {
        pTile = (class CTile *)(m_pMapList[cMapIndex]->m_pTile + ix +
                                iy * m_pMapList[cMapIndex]->m_sSizeY);
        if ((pTile->m_sOwner != 0) &&
            (pTile->m_cOwnerClass == DEF_OWNERTYPE_PLAYER))
          iRet++;
      }
    }

  return iRet;
}

void CGame::WhetherProcessor() {
  char cPrevMode;
  int i, j;
  DWORD dwTime;

  dwTime = timeGetTime();

  for (i = 0; i < DEF_MAXMAPS; i++) {
    if ((m_pMapList[i] != 0) && (m_pMapList[i]->m_bIsFixedDayMode == false)) {
      cPrevMode = m_pMapList[i]->m_cWhetherStatus;
      if (m_pMapList[i]->m_cWhetherStatus != 0) {
        if ((dwTime - m_pMapList[i]->m_dwWhetherStartTime) >
            m_pMapList[i]->m_dwWhetherLastTime)
          m_pMapList[i]->m_cWhetherStatus = 0;
      } else {
        if (iDice(1, 300) == 13) {
          m_pMapList[i]->m_cWhetherStatus =
              iDice(1, 3); // This looks better or else we only get snow :(
          // m_pMapList[i]->m_cWhetherStatus = iDice(1,3)+3; <- This original
          // code looks fucked
          m_pMapList[i]->m_dwWhetherStartTime = dwTime;
          m_pMapList[i]->m_dwWhetherLastTime = 60000 * 3 + 60000 * iDice(1, 7);
        }
      }

      if (m_pMapList[i]->m_bIsSnowEnabled) {
        m_pMapList[i]->m_cWhetherStatus = iDice(1, 3) + 3;
        m_pMapList[i]->m_dwWhetherStartTime = dwTime;
        m_pMapList[i]->m_dwWhetherLastTime = 60000 * 3 + 60000 * iDice(1, 7);
      }

      if (cPrevMode != m_pMapList[i]->m_cWhetherStatus) {
        for (j = 1; j < DEF_MAXCLIENTS; j++)
          if ((m_pClientList[j] != 0) &&
              (m_pClientList[j]->m_bIsInitComplete) &&
              (m_pClientList[j]->m_cMapIndex == i))
            SendNotifyMsg(0, j, DEF_NOTIFY_WHETHERCHANGE,
                          m_pMapList[i]->m_cWhetherStatus, 0, 0, 0);
      }
    } // If
  } // for Loop
}

void CGame::FightzoneReserveProcessor() {}

/*********************************************************************************************************************
**  int CGame::iGetWhetherMagicBonusEffect(short sType, char cWheatherStatus)
*									**
**  description			:: checks for a weather bonus when magic is cast
*											**
**  last updated		:: November 20, 2004; 10:34 PM; Hypnotoad
*												**
**	return value		:: int
*																**
*********************************************************************************************************************/
int CGame::iGetWhetherMagicBonusEffect(short sType, char cWheatherStatus) {
  int iWheatherBonus;

  iWheatherBonus = 0;
  switch (cWheatherStatus) {
  case 0:
    break;
  case 1:
  case 2:
  case 3:
    switch (sType) {
    case 10:
    case 37:
    case 43:
    case 51:
      iWheatherBonus = 1;
      break;

    case 20:
    case 30:
      iWheatherBonus = -1;
      break;
    }
    break;
  }
  return iWheatherBonus;
}

int CGame::iGetPlayerRelationship(int iClientH, int iOpponentH) {
  int iRet;

  if (m_pClientList[iClientH] == 0)
    return 0;
  if (m_pClientList[iClientH]->m_bIsInitComplete == false)
    return 0;

  if (m_pClientList[iOpponentH] == 0)
    return 0;
  if (m_pClientList[iOpponentH]->m_bIsInitComplete == false)
    return 0;

  iRet = 0;

  if (m_pClientList[iClientH]->m_iPKCount != 0) {
    // 潞禄脌脦脌脤 鹿眉脕脣脌脷脌脤脟脧赂茅 禄贸麓毛鹿忙脌脤 赂露脌禄脌脤
    // 掳掳脌潞 掳忙驴矛 脌搂脟霉. 麓脵赂拢赂茅 脌没
    if ((memcmp(m_pClientList[iClientH]->m_cLocation,
                m_pClientList[iOpponentH]->m_cLocation, 10) == 0) &&
        (memcmp(m_pClientList[iClientH]->m_cLocation, "NONE", 4) != 0) &&
        (memcmp(m_pClientList[iOpponentH]->m_cLocation, "NONE", 4) != 0)) {
      iRet = 7; // 脌搂脟霉
    } else
      iRet = 2; // 脌没
  } else if (m_pClientList[iOpponentH]->m_iPKCount != 0) {
    // 禄贸麓毛鹿忙脌脤 鹿眉脕脣脌脷脌脤脟脧赂茅
    if ((memcmp(m_pClientList[iClientH]->m_cLocation,
                m_pClientList[iOpponentH]->m_cLocation, 10) == 0) &&
        (memcmp(m_pClientList[iClientH]->m_cLocation, "NONE", 4) != 0))
      iRet = 6; // 赂露脌禄脌脤 掳掳脌赂赂茅 PK
    else
      iRet = 2; // 麓脵赂拢赂茅 卤脳鲁脡 脌没
  } else {
    if (m_pClientList[iClientH]->m_cSide !=
        m_pClientList[iOpponentH]->m_cSide) {
      if ((m_pClientList[iClientH]->m_cSide != 0) &&
          (m_pClientList[iOpponentH]->m_cSide != 0)) {
        // 碌脩 麓脵 0(Traveler)脌脤 戮脝麓脧赂茅 脌没脌脤麓脵.
        iRet = 2;
      } else {
        iRet = 0;
      }
    } else {
      // 戮脝卤潞脌脤麓脵. 卤忙碌氓驴酶驴漏潞脦赂娄 脝脟麓脺.
      if ((memcmp(m_pClientList[iClientH]->m_cGuildName,
                  m_pClientList[iOpponentH]->m_cGuildName, 20) == 0) &&
          (memcmp(m_pClientList[iClientH]->m_cGuildName, "NONE", 4) != 0)) {
        // 卤忙碌氓 脌脤赂搂脌脤 掳掳麓脵.
        if (m_pClientList[iOpponentH]->m_iGuildRank == 0)
          iRet = 5; // 卤忙碌氓 路漏脜漏掳隆 0. 卤忙碌氓赂露陆潞脜脥脌脤麓脵.
        else
          iRet = 3; // 掳掳脌潞 卤忙碌氓驴酶
      } else if ((memcmp(m_pClientList[iClientH]->m_cLocation,
                         m_pClientList[iOpponentH]->m_cLocation, 10) == 0) &&
                 (memcmp(m_pClientList[iClientH]->m_cGuildName, "NONE", 4) !=
                  0) &&
                 (memcmp(m_pClientList[iOpponentH]->m_cGuildName, "NONE", 4) !=
                  0) &&
                 (memcmp(m_pClientList[iClientH]->m_cGuildName,
                         m_pClientList[iOpponentH]->m_cGuildName, 20) != 0)) {
        // 卤忙碌氓 脌搂脛隆麓脗 掳掳掳铆 卤忙碌氓 脌脤赂搂脌脤 麓脵赂拢麓脵.
        iRet = 4; // 麓脵赂楼 卤忙碌氓驴酶
      } else
        iRet = 1; // 卤脳鲁脡 掳掳脌潞脝铆
    }
  }

  return iRet;
}

int CGame::iGetPlayerABSStatus(int iWhatH, int iRecvH) {
  int iRet;

  if (m_pClientList[iWhatH] == 0)
    return 0;
  if (m_pClientList[iRecvH] == 0)
    return 0;

  iRet = 0;

  /*if (m_pMapList[m_pClientList[iRecvH]->m_cMapIndex]->m_bIsFightZone  &&
          m_pClientList[iWhatH]->m_iGuildRank != -1 &&
     m_pClientList[iRecvH]->m_iGuildRank != -1 &&
          memcmp(m_pClientList[iWhatH]->m_cGuildName,m_pClientList[iRecvH]->m_cGuildName,20)
     != 0) { iRet = 8;
          }*/

  if (m_pClientList[iWhatH]->m_iPKCount != 0) {
    iRet = 8;
  }

  if (m_pClientList[iWhatH]->m_cSide != 0) {
    iRet = iRet | 4;
  }

  if (m_pClientList[iWhatH]->m_cSide == 1) {
    iRet = iRet | 2;
  }

  if (m_pClientList[iWhatH]->m_bIsPlayerCivil)
    iRet = iRet | 1;

  return iRet;
}

int CGame::iGetNpcRelationship(int iWhatH, int iRecvH) {
  int iRet;

  if (m_pClientList[iRecvH] == 0)
    return 0;
  if (m_pNpcList[iWhatH] == 0)
    return 0;

  iRet = 0;
  switch (m_pNpcList[iWhatH]->m_cSide) {
  case 10:
    iRet |= 8; // Fixed, Original 15
  case 1:
    iRet = (iRet | 4) | 2; // Fixed, Original 1
  case 2:
    iRet |= 4; // Fixed, Orignal 8
  }

  return iRet;
}

int CGame::iGetNpcRelationship_SendEvent(int iNpcH, int iOpponentH) {
  int iRet;

  if (m_pClientList[iOpponentH] == 0)
    return 0;
  if (m_pClientList[iOpponentH]->m_bIsInitComplete == false)
    return 0;

  if (m_pNpcList[iNpcH] == 0)
    return 0;

  iRet = 0;

  if (m_pClientList[iOpponentH]->m_iPKCount != 0) {
    if (m_pNpcList[iNpcH]->m_cSide == m_pClientList[iOpponentH]->m_cSide)
      iRet = 7;
    else
      iRet = 2;
  } else {
    if (m_pNpcList[iNpcH]->m_cSide != m_pClientList[iOpponentH]->m_cSide) {
      if (m_pNpcList[iNpcH]->m_cSide == 10)
        iRet = 2;
      else if (m_pNpcList[iNpcH]->m_cSide == 0)
        iRet = 0;
      else if (m_pClientList[iOpponentH]->m_cSide == 0)
        iRet = 0;
      else
        iRet = 2;

    } else
      iRet = 1; // 掳掳脌潞 脝铆
  }

  return iRet;
}

int CGame::iGetMapIndex(char *pMapName) {
  int i, iMapIndex;
  char cTmpName[256];

  ZeroMemory(cTmpName, sizeof(cTmpName));
  strcpy(cTmpName, pMapName);

  iMapIndex = -1;
  for (i = 0; i < DEF_MAXMAPS; i++)
    if (m_pMapList[i] != 0) {
      if (memcmp(m_pMapList[i]->m_cName, pMapName, 10) == 0)
        iMapIndex = i;
    }

  return iMapIndex;
}

int CGame::_iForcePlayerDisconect(int iNum) {
  int i, iCnt;

  iCnt = 0;
  for (i = 1; i < DEF_MAXCLIENTS; i++)
    if (m_pClientList[i] != 0) {
      if (m_pClientList[i]->m_bIsInitComplete)
        DeleteClient(i, true, true);
      else
        DeleteClient(i, false, false);
      iCnt++;
      if (iCnt >= iNum)
        break;
    }

  return iCnt;
}

void CGame::SpecialEventHandler() {
  DWORD dwTime;

  // 脝炉潞掳脟脩 脌脤潞楼脝庐赂娄 禄媒录潞脟脩麓脵.
  dwTime = timeGetTime();

  if ((dwTime - m_dwSpecialEventTime) < DEF_SPECIALEVENTTIME)
    return; // DEF_SPECIALEVENTTIME
  m_dwSpecialEventTime = dwTime;
  m_bIsSpecialEventTime = true;

  switch (iDice(1, 180)) {
  case 98:
    m_cSpecialEventType = 2;
    break; // 碌楼赂贸 脠陇脌潞 脌炉麓脧脛脺脌脤 鲁陋驴脙 掳隆麓脡录潞脌潞
           // 30潞脨驴隆 1鹿酶 1/30
  default:
    m_cSpecialEventType = 1;
    break;
  }
}

void CGame::AdminOrder_CheckIP(int iClientH, char *pData, DWORD dwMsgSize) {
  char seps[] = "= \t\n";
  char *token, cBuff[256], cIP[21], cInfoString[500];
  class CStrTok *pStrTok;
  int i;

  if (m_pClientList[iClientH] == 0)
    return;
  if ((dwMsgSize) <= 0)
    return;

  if (m_pClientList[iClientH]->m_iAdminUserLevel < m_iAdminLevelCheckIP) {
    // Admin user level脌脤 鲁路戮脝录颅 脌脤 卤芒麓脡脌禄 禄莽驴毛脟脪 录枚
    // 戮酶麓脵.
    SendNotifyMsg(0, iClientH, DEF_NOTIFY_ADMINUSERLEVELLOW, 0, 0, 0, 0);
    return;
  }

  ZeroMemory(cBuff, sizeof(cBuff));
  memcpy(cBuff, pData, dwMsgSize);

  pStrTok = new class CStrTok(cBuff, seps);
  token = pStrTok->pGet();
  token = pStrTok->pGet();

  if (token != 0) {
    // token脌脤 IP address脌脤麓脵.
    ZeroMemory(cIP, sizeof(cIP));
    strcpy(cIP, token);

    for (i = 1; i < DEF_MAXCLIENTS; i++)
      if ((m_pClientList[i] != 0) &&
          (memcmp(m_pClientList[i]->m_cIPaddress, cIP, strlen(cIP)) == 0)) {
        // 驴盲卤赂脟脩 脕脰录脪驴脥 脌脧脛隆脟脧麓脗 脜卢露贸脌脤戮冒脝庐
        // 鹿脽掳脽.
        ZeroMemory(cInfoString, sizeof(cInfoString));
        wsprintf(cInfoString,
                 "Name(%s/%s) Loc(%s: %d %d) Level(%d:%d) Init(%d) IP(%s)",
                 m_pClientList[i]->m_cAccountName,
                 m_pClientList[i]->m_cCharName, m_pClientList[i]->m_cMapName,
                 m_pClientList[i]->m_sX, m_pClientList[i]->m_sY,
                 m_pClientList[i]->m_iLevel,
                 0 /*m_pClientList[i]->m_cAccountStatus*/,
                 m_pClientList[i]->m_bIsInitComplete,
                 m_pClientList[i]->m_cIPaddress);

        SendNotifyMsg(0, iClientH, DEF_NOTIFY_IPACCOUNTINFO, 0, 0, 0,
                      cInfoString);
      }
  }

  delete pStrTok;
}

void CGame::ToggleSafeAttackModeHandler(int iClientH) // v1.1
{
  if (m_pClientList[iClientH] == 0)
    return;
  if (m_pClientList[iClientH]->m_bIsInitComplete == false)
    return;
  if (m_pClientList[iClientH]->m_bIsKilled)
    return;

  // 戮脠脌眉 掳酶掳脻 赂冒碌氓赂娄 脜盲卤脹脟脩麓脵.
  if (m_pClientList[iClientH]->m_bIsSafeAttackMode)
    m_pClientList[iClientH]->m_bIsSafeAttackMode = false;
  else
    m_pClientList[iClientH]->m_bIsSafeAttackMode = true;

  SendNotifyMsg(0, iClientH, DEF_NOTIFY_SAFEATTACKMODE, 0, 0, 0, 0);
}

void CGame::NpcRequestAssistance(int iNpcH) {
  int ix, iy, sX, sY;
  short sOwnerH;
  char cOwnerType;

  // iNpc 卤脵鹿忙驴隆 脌脰麓脗 脌眉脜玫脕脽脌脤 戮脝麓脩 NPC驴隆掳脭
  // 碌碌驴貌脌禄 驴盲脙禄脟脩麓脵.
  if (m_pNpcList[iNpcH] == 0)
    return;

  sX = m_pNpcList[iNpcH]->m_sX;
  sY = m_pNpcList[iNpcH]->m_sY;

  for (ix = sX - 8; ix <= sX + 8; ix++)
    for (iy = sY - 8; iy <= sY + 8; iy++) {
      m_pMapList[m_pNpcList[iNpcH]->m_cMapIndex]->GetOwner(&sOwnerH,
                                                           &cOwnerType, ix, iy);
      if ((sOwnerH != 0) && (m_pNpcList[sOwnerH] != 0) &&
          (cOwnerType == DEF_OWNERTYPE_NPC) && (iNpcH != sOwnerH) &&
          (m_pNpcList[sOwnerH]->m_cSide == m_pNpcList[iNpcH]->m_cSide) &&
          (m_pNpcList[sOwnerH]->m_bIsPermAttackMode == false) &&
          (m_pNpcList[sOwnerH]->m_cBehavior == DEF_BEHAVIOR_MOVE)) {

        // 脕露掳脟驴隆 潞脦脟脮脟脧麓脗 NPC赂娄 脙拢戮脪麓脵.
        m_pNpcList[sOwnerH]->m_cBehavior = DEF_BEHAVIOR_ATTACK;
        m_pNpcList[sOwnerH]->m_sBehaviorTurnCount = 0;
        m_pNpcList[sOwnerH]->m_iTargetIndex = m_pNpcList[iNpcH]->m_iTargetIndex;
        m_pNpcList[sOwnerH]->m_cTargetType = m_pNpcList[iNpcH]->m_cTargetType;

        return;
      }
    }
}

void CGame::ForceDisconnectAccount(char *pAccountName, WORD wCount) {
  int i;

  // 脕脽潞鹿碌脠 掳猫脕陇脌禄 掳庐掳铆脌脰麓脗 脛鲁赂炉脜脥赂娄
  // 禄猫脕娄脟脩麓脵.
  for (i = 1; i < DEF_MAXCLIENTS; i++)
    if ((m_pClientList[i] != 0) &&
        (memcmp(m_pClientList[i]->m_cAccountName, pAccountName, 10) == 0)) {
      wsprintf(
          G_cTxt,
          "<%d> Force disconnect account: CharName(%s) AccntName(%s) Count(%d)",
          i, m_pClientList[i]->m_cCharName, m_pClientList[i]->m_cAccountName,
          wCount);
      PutLogList(G_cTxt);

      // v1.42 脛芦驴卯脝脙 脟脙路隆卤脳赂娄 脠掳录潞脠颅 脟脴戮脽 脟脩麓脵.
      // DeleteClient(i, true, true);

      // v1.4312
      SendNotifyMsg(0, i, DEF_NOTIFY_FORCEDISCONN, wCount, 0, 0, 0);
    }
}

