void CGame::AdminOrder_SetInvi(int iClientH, char *pData, DWORD dwMsgSize) {
  char seps[] = "= \t\n";
  char *token, cBuff[256];
  class CStrTok *pStrTok;

  if (m_pClientList[iClientH] == 0)
    return;
  if ((dwMsgSize) <= 0)
    return;

  if (m_pClientList[iClientH]->m_iAdminUserLevel < m_iAdminLevelSetInvis) {
    // Admin user level脌脤 鲁路戮脝录颅 脌脤 卤芒麓脡脌禄 禄莽驴毛脟脪 录枚
    // 戮酶麓脵.
    SendNotifyMsg(0, iClientH, DEF_NOTIFY_ADMINUSERLEVELLOW, 0, 0, 0, 0);
    return;
  }

  ZeroMemory(cBuff, sizeof(cBuff));
  memcpy(cBuff, pData, dwMsgSize);

  pStrTok = new class CStrTok(cBuff, seps);
  token = pStrTok->pGet();
  token = pStrTok->pGet();

  if (token != 0) {
    // 脌脤 掳陋脌脤 鹿庐脌脷 '1'脌脤赂茅 脜玫赂铆脌赂路脦 录录脝庐. '0'脌脤赂茅
    // 脟脴脕娄
    if (token[0] == '1')
      SetInvisibilityFlag(iClientH, DEF_OWNERTYPE_PLAYER, true);
    else if (token[0] == '0')
      SetInvisibilityFlag(iClientH, DEF_OWNERTYPE_PLAYER, false);
  }

  delete pStrTok;
}

bool CGame::bOnClose() {
  if (m_bIsServerShutdowned == false)
    if (MessageBox(0, "Player data not saved! Shutdown server now?",
                   m_cServerName, MB_ICONEXCLAMATION | MB_YESNO) == IDYES)
      return true;
    else
      return false;
  else
    return true;

  return false;
}

