// 05/24/2004 - Hypnotoad - Hammer and Wand train to 100% fixed
void CGame::_CheckAttackType(int iClientH, short *spType) {
  WORD wType;

  if (m_pClientList[iClientH] == 0)
    return;
  wType = ((m_pClientList[iClientH]->m_sAppr2 & 0x0FF0) >> 4);

  switch (*spType) {
  case 2:
    // 脙藛脗颅脗禄脙卢脙鈧�兣� 脗戮脙赂脗麓脙鈩⒚偮该兟� 脙藛脗颅脗禄脙卢
    // Effect脗麓脙鈥� 脗鲁脙鈥撁兟伱兟� 脗戮脙艩脗麓脙鈥毭偮疵冣劉.
    if (m_pClientList[iClientH]->m_cArrowIndex == -1)
      *spType = 0;
    // 脙藛脗掳 脗掳脙赂脗掳脙聺脙鈧�兣矫偮得偮� 脙鈧�兟ッ冣€毭兟该冣€∶冣€�
    // 脗鹿脗芦脗卤脙垄脗掳脗隆 脙藛脗掳脙鈧�兣� 脗戮脙鈥犆偮疵兟徝偮疵冣劉.
    // 脙鈧�兟徝偮姑兟� 脗掳脙赂脗掳脙聺脙鈧�偮该偮访兣� 脙鈧�兟济兯喢偮�.
    if (wType < 40)
      *spType = 1;
    break;

  case 20:
    // 脗赂脙鈥∶偮济冣€� 脙鈥∶兣犆偮幻兟�偮泵兟�
    if (m_pClientList[iClientH]->m_iSuperAttackLeft <= 0)
      *spType = 1;
    if (m_pClientList[iClientH]->m_cSkillMastery[5] < 100)
      *spType = 1;
    break;

  case 21:
    // 脗麓脙艙脗掳脙鈥� 脙鈥∶兣犆偮幻兟�偮泵兟�
    if (m_pClientList[iClientH]->m_iSuperAttackLeft <= 0)
      *spType = 1;
    if (m_pClientList[iClientH]->m_cSkillMastery[7] < 100)
      *spType = 1;
    break;

  case 22:
    // 脙鈥犆兟γ偮矫兣� 脙鈥∶兣犆偮幻兟�偮泵兟�
    if (m_pClientList[iClientH]->m_iSuperAttackLeft <= 0)
      *spType = 1;
    if (m_pClientList[iClientH]->m_cSkillMastery[9] < 100)
      *spType = 1;
    break;

  case 23:
    // 脙鈧�兟ッ偮懊冣€� 脙鈥∶兣犆偮幻兟�偮泵兟�
    if (m_pClientList[iClientH]->m_iSuperAttackLeft <= 0)
      *spType = 1;
    if (m_pClientList[iClientH]->m_cSkillMastery[8] < 100)
      *spType = 1;
    break;

  case 24:
    // 脗碌脗碌脗鲁脗垄 脙鈥∶兣犆偮幻兟�偮泵兟�
    if (m_pClientList[iClientH]->m_iSuperAttackLeft <= 0)
      *spType = 1;
    if (m_pClientList[iClientH]->m_cSkillMastery[10] < 100)
      *spType = 1;
    break;

  case 25:
    // 脙藛脗掳 脙鈥∶兣犆偮幻兟�偮泵兟�
    if (m_pClientList[iClientH]->m_iSuperAttackLeft <= 0)
      *spType = 2;
    if (m_pClientList[iClientH]->m_cSkillMastery[6] < 100)
      *spType = 2;
    if (m_pClientList[iClientH]->m_cArrowIndex == -1)
      *spType = 0;
    // 脙藛脗掳 脗掳脙赂脗掳脙聺脙鈧�兣矫偮得偮� 脙鈧�兟ッ冣€毭兟该冣€∶冣€�
    // 脗鹿脗芦脗卤脙垄脗掳脗隆 脙藛脗掳脙鈧�兣� 脗戮脙鈥犆偮疵兟徝偮疵冣劉.
    // 脙鈧�兟徝偮姑兟� 脗掳脙赂脗掳脙聺脙鈧�偮该偮访兣� 脙鈧�兟济兯喢偮�.
    if (wType < 40)
      *spType = 1;
    break;

  case 26:
    // v2.16 2002-5-27 脟脴赂脫 脟脢禄矛卤芒
    if (m_pClientList[iClientH]->m_iSuperAttackLeft <= 0)
      *spType = 1;
    if (m_pClientList[iClientH]->m_cSkillMastery[14] < 100)
      *spType = 1;
    break;

  case 27:
    // v2.16 2002-5-27 脕枚脝脦脌脤 脟脢禄矛卤芒
    if (m_pClientList[iClientH]->m_iSuperAttackLeft <= 0)
      *spType = 1;
    if (m_pClientList[iClientH]->m_cSkillMastery[21] < 100)
      *spType = 1;
    break;
  }
}

void CGame::ReqCreatePortionHandler(int iClientH, char *pData) {
  DWORD *dwp;
  WORD *wp;
  char *cp, cI[6], cPortionName[21], cData[120];
  int iRet, i, j, iEraseReq, iSkillLimit, iSkillLevel, iResult, iDifficulty;
  short *sp, sItemIndex[6], sTemp;
  short sItemNumber[6], sItemArray[12];
  bool bDup, bFlag;
  class CItem *pItem;

  if (m_pClientList[iClientH] == 0)
    return;
  m_pClientList[iClientH]->m_iSkillMsgRecvCount++;

  for (i = 0; i < 6; i++) {
    cI[i] = -1;
    sItemIndex[i] = -1;
    sItemNumber[i] = 0;
  }

  cp = (char *)(pData + 11);
  cI[0] = *cp;
  cp++;
  cI[1] = *cp;
  cp++;
  cI[2] = *cp;
  cp++;
  cI[3] = *cp;
  cp++;
  cI[4] = *cp;
  cp++;
  cI[5] = *cp;
  cp++;
  // 脝梅录脟脌脟 脌莽路谩 脌脦碌娄陆潞赂娄 鹿脼戮脪麓脵. 脌脤 脌莽路谩掳隆
  // 脝梅录脟脌禄 赂赂碌茅 录枚 脌脰麓脗 脕露脟脮脌脦脕枚 脠庐脌脦脟脩麓脵.

  // 碌楼脌脤脜脥掳隆 脌炉脠驴脟脩 戮脝脌脤脜脹 脌脦碌娄陆潞脌脦脕枚
  // 脙录脜漏脟脩麓脵.
  for (i = 0; i < 6; i++) {
    if (cI[i] >= DEF_MAXITEMS)
      return;
    if ((cI[i] >= 0) && (m_pClientList[iClientH]->m_pItemList[cI[i]] == 0))
      return;
  }

  for (i = 0; i < 6; i++)
    if (cI[i] >= 0) {
      // 赂脮脌煤 脌脤鹿脤 脌脰麓脗 赂庐陆潞脝庐脌脦脕枚 掳脣禄枚
      bDup = false;
      for (j = 0; j < 6; j++)
        if (sItemIndex[j] == cI[i]) {
          // 脌脰麓脵. 脛芦驴卯脝庐 脕玫掳隆
          sItemNumber[j]++;
          bDup = true;
        }
      if (bDup == false) {
        // 戮酶麓脵. 禄玫路脦 脙脽掳隆脟脩麓脵.
        for (j = 0; j < 6; j++)
          if (sItemIndex[j] == -1) {
            sItemIndex[j] = cI[i];
            sItemNumber[j]++;
            goto RCPH_LOOPBREAK;
          }
      RCPH_LOOPBREAK:;
      }
    }

  // 戮脝脌脤脜脹 赂庐陆潞脝庐掳隆 赂赂碌茅戮卯 脕鲁麓脵. 录脪潞帽碌脟麓脗
  // 戮脝脌脤脜脹脌脤露贸赂茅 掳鹿录枚赂娄 脠庐脌脦脟脩麓脵.
  for (i = 0; i < 6; i++)
    if (sItemIndex[i] != -1) {
      if (sItemIndex[i] < 0)
        return;
      if ((sItemIndex[i] >= 0) && (sItemIndex[i] >= DEF_MAXITEMS))
        return;
      if (m_pClientList[iClientH]->m_pItemList[sItemIndex[i]] == 0)
        return;
      // 戮脝脌脤脜脹脌脤 掳鹿录枚掳隆 驴脌鹿枚脟脴碌碌 赂庐脜脧.
      if (m_pClientList[iClientH]->m_pItemList[sItemIndex[i]]->m_dwCount <
          sItemNumber[i])
        return;
    }

  // 戮脝脌脤脜脹脌禄 戮脝脌脤脜脹 戮脝脌脤碌冒 鹿酶脠拢掳隆 脜芦
  // 录酶录颅潞脦脜脥 脕陇路脛脟脩麓脵. Bubble Sort
  bFlag = true;
  while (bFlag) {
    bFlag = false;
    for (i = 0; i < 5; i++)
      if ((sItemIndex[i] != -1) && (sItemIndex[i + 1] != -1)) {
        if ((m_pClientList[iClientH]->m_pItemList[sItemIndex[i]]->m_sIDnum) <
            (m_pClientList[iClientH]
                 ->m_pItemList[sItemIndex[i + 1]]
                 ->m_sIDnum)) {
          // 鹿脵虏脹麓脵.
          sTemp = sItemIndex[i + 1];
          sItemIndex[i + 1] = sItemIndex[i];
          sItemIndex[i] = sTemp;
          sTemp = sItemNumber[i + 1];
          sItemNumber[i + 1] = sItemNumber[i];
          sItemNumber[i] = sTemp;
          bFlag = true;
        }
      }
  }

  j = 0;
  for (i = 0; i < 6; i++) {
    if (sItemIndex[i] != -1)
      sItemArray[j] =
          m_pClientList[iClientH]->m_pItemList[sItemIndex[i]]->m_sIDnum;
    else
      sItemArray[j] = sItemIndex[i];
    sItemArray[j + 1] = sItemNumber[i];
    j += 2;
  }

  ZeroMemory(cPortionName, sizeof(cPortionName));

  for (i = 0; i < DEF_MAXPORTIONTYPES; i++)
    if (m_pPortionConfigList[i] != 0) {
      bFlag = false;
      for (j = 0; j < 12; j++)
        if (m_pPortionConfigList[i]->m_sArray[j] != sItemArray[j])
          bFlag = true;

      if (bFlag == false) {
        ZeroMemory(cPortionName, sizeof(cPortionName));
        memcpy(cPortionName, m_pPortionConfigList[i]->m_cName, 20);
        iSkillLimit = m_pPortionConfigList[i]->m_iSkillLimit;
        iDifficulty = m_pPortionConfigList[i]->m_iDifficulty;
      }
    }

  if (strlen(cPortionName) == 0) {
    SendNotifyMsg(0, iClientH, DEF_NOTIFY_NOMATCHINGPORTION, 0, 0, 0, 0);
    return;
  }

  iSkillLevel = m_pClientList[iClientH]->m_cSkillMastery[12];
  if (iSkillLimit > iSkillLevel) {
    SendNotifyMsg(0, iClientH, DEF_NOTIFY_LOWPORTIONSKILL, 0, 0, 0,
                  cPortionName);
    return;
  }

  iSkillLevel -= iDifficulty;
  if (iSkillLevel <= 0)
    iSkillLevel = 1;

  iResult = iDice(1, 100);
  if (iResult > iSkillLevel) {
    SendNotifyMsg(0, iClientH, DEF_NOTIFY_PORTIONFAIL, 0, 0, 0, cPortionName);
    return;
  }

  CalculateSSN_SkillIndex(iClientH, 12, 1);

  if (strlen(cPortionName) != 0) {
    pItem = 0;
    pItem = new class CItem;
    if (pItem == 0)
      return;

    for (i = 0; i < 6; i++)
      if (sItemIndex[i] != -1) {
        if (m_pClientList[iClientH]->m_pItemList[sItemIndex[i]]->m_cItemType ==
            DEF_ITEMTYPE_CONSUME)
          // v1.41 !!!
          SetItemCount(
              iClientH,
              sItemIndex
                  [i], //     m_pClientList[iClientH]->m_pItemList[sItemIndex[i]]->m_cName,
              m_pClientList[iClientH]->m_pItemList[sItemIndex[i]]->m_dwCount -
                  sItemNumber[i]);
        else
          ItemDepleteHandler(iClientH, sItemIndex[i], false);
      }

    SendNotifyMsg(0, iClientH, DEF_NOTIFY_PORTIONSUCCESS, 0, 0, 0,
                  cPortionName);
    m_pClientList[iClientH]->m_iExpStock += iDice(1, (iDifficulty / 3));

    if ((_bInitItemAttr(pItem, cPortionName))) {
      if (_bAddClientItemList(iClientH, pItem, &iEraseReq)) {
        ZeroMemory(cData, sizeof(cData));
        dwp = (DWORD *)(cData + DEF_INDEX4_MSGID);
        *dwp = MSGID_NOTIFY;
        wp = (WORD *)(cData + DEF_INDEX2_MSGTYPE);
        *wp = DEF_NOTIFY_ITEMOBTAINED;

        cp = (char *)(cData + DEF_INDEX2_MSGTYPE + 2);

        *cp = 1;
        cp++;

        memcpy(cp, pItem->m_cName, 20);
        cp += 20;

        dwp = (DWORD *)cp;
        *dwp = pItem->m_dwCount; // 录枚路庐脌禄 脌脭路脗
        cp += 4;

        *cp = pItem->m_cItemType;
        cp++;

        *cp = pItem->m_cEquipPos;
        cp++;

        *cp = (char)0;
        cp++;

        sp = (short *)cp;
        *sp = pItem->m_sLevelLimit;
        cp += 2;

        *cp = pItem->m_cGenderLimit;
        cp++;

        wp = (WORD *)cp;
        *wp = pItem->m_wCurLifeSpan;
        cp += 2;

        wp = (WORD *)cp;
        *wp = pItem->m_wWeight;
        cp += 2;

        sp = (short *)cp;
        *sp = pItem->m_sSprite;
        cp += 2;

        sp = (short *)cp;
        *sp = pItem->m_sSpriteFrame;
        cp += 2;

        *cp = pItem->m_cItemColor;
        cp++;

        *cp = (char)pItem->m_sItemSpecEffectValue2; // v1.41
        cp++;

        dwp = (DWORD *)cp;
        *dwp = pItem->m_dwAttribute;
        cp += 4;
        /*
        *cp = (char)(pItem->m_dwAttribute & 0x00000001); //
        Custom-Item脌脦脕枚脌脟 驴漏潞脦 cp++;
        */

        if (iEraseReq == 1)
          delete pItem;

        iRet = m_pClientList[iClientH]->m_pXSock->iSendMsg(cData, 53);
        switch (iRet) {
        case DEF_XSOCKEVENT_QUENEFULL:
        case DEF_XSOCKEVENT_SOCKETERROR:
        case DEF_XSOCKEVENT_CRITICALERROR:
        case DEF_XSOCKEVENT_SOCKETCLOSED:
          DeleteClient(iClientH, true, true);
          break;
        }

        // if ((pItem->m_wPrice * pItem->m_dwCount) > 1000)
        //	SendMsgToLS(MSGID_REQUEST_SAVEPLAYERDATA, iClientH);
      } else {
        m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->bSetItem(
            m_pClientList[iClientH]->m_sX, m_pClientList[iClientH]->m_sY,
            pItem);

        SendEventToNearClient_TypeB(
            MSGID_EVENT_COMMON, DEF_COMMONTYPE_ITEMDROP,
            m_pClientList[iClientH]->m_cMapIndex, m_pClientList[iClientH]->m_sX,
            m_pClientList[iClientH]->m_sY, pItem->m_sIDnum, 0,
            pItem->m_cItemColor, pItem->m_dwAttribute); // v1.4

        dwp = (DWORD *)(cData + DEF_INDEX4_MSGID);
        *dwp = MSGID_NOTIFY;
        wp = (WORD *)(cData + DEF_INDEX2_MSGTYPE);
        *wp = DEF_NOTIFY_CANNOTCARRYMOREITEM;

        iRet = m_pClientList[iClientH]->m_pXSock->iSendMsg(cData, 6);
        switch (iRet) {
        case DEF_XSOCKEVENT_QUENEFULL:
        case DEF_XSOCKEVENT_SOCKETERROR:
        case DEF_XSOCKEVENT_CRITICALERROR:
        case DEF_XSOCKEVENT_SOCKETCLOSED:
          DeleteClient(iClientH, true, true);
          break;
        }
      }
    } else {
      delete pItem;
      pItem = 0;
    }
  }
}

