void CGame::SendItemNotifyMsg(int iClientH, WORD wMsgType, CItem *pItem,
                              int iV1) {
  char *cp, cData[512];
  DWORD *dwp;
  WORD *wp;
  short *sp;
  int iRet;

  if (m_pClientList[iClientH] == 0)
    return;

  dwp = (DWORD *)(cData + DEF_INDEX4_MSGID);
  *dwp = MSGID_NOTIFY;
  wp = (WORD *)(cData + DEF_INDEX2_MSGTYPE);
  *wp = wMsgType;
  cp = (char *)(cData + DEF_INDEX2_MSGTYPE + 2);

  switch (wMsgType) {
  case DEF_NOTIFY_ITEMOBTAINED:
    *cp = 1; // 1掳鲁 脠鹿碌忙脟脽麓脵. <- 驴漏卤芒录颅 1掳鲁露玫 录枚路庐
             // 脛芦驴卯脝庐赂娄 赂禄脟脧麓脗 掳脥脌脤 戮脝麓脧麓脵
    cp++;

    memcpy(cp, pItem->m_cName, 20);
    cp += 20;

    dwp = (DWORD *)cp;
    *dwp = pItem->m_dwCount;
    cp += 4;

    *cp = pItem->m_cItemType;
    cp++;

    *cp = pItem->m_cEquipPos;
    cp++;

    *cp = (char)0; // 戮貌脌潞 戮脝脌脤脜脹脌脤鹿脟路脦 脌氓脗酶碌脟脕枚
                   // 戮脢戮脪麓脵.
    cp++;

    sp = (short *)cp;
    *sp = pItem->m_sLevelLimit;
    cp += 2;

    *cp = pItem->m_cGenderLimit;
    cp++;

    wp = (WORD *)cp;
    *wp = pItem->m_wCurLifeSpan;
    cp += 2;

    wp = (WORD *)cp;
    *wp = pItem->m_wWeight;
    cp += 2;

    sp = (short *)cp;
    *sp = pItem->m_sSprite;
    cp += 2;

    sp = (short *)cp;
    *sp = pItem->m_sSpriteFrame;
    cp += 2;

    *cp = pItem->m_cItemColor; // v1.4
    cp++;

    *cp = (char)pItem->m_sItemSpecEffectValue2; // v1.41
    cp++;

    dwp = (DWORD *)cp;
    *dwp = pItem->m_dwAttribute;
    cp += 4;
    /*
    *cp = (char)(pItem->m_dwAttribute & 0x00000001); // Custom-Item脌脦脕枚脌脟
    驴漏潞脦 cp++;
    */

    iRet = m_pClientList[iClientH]->m_pXSock->iSendMsg(cData, 53);
    break;

  case DEF_NOTIFY_ITEMPURCHASED:
    *cp = 1;
    cp++;

    memcpy(cp, pItem->m_cName, 20);
    cp += 20;

    dwp = (DWORD *)cp;
    *dwp = pItem->m_dwCount;
    cp += 4;

    *cp = pItem->m_cItemType;
    cp++;

    *cp = pItem->m_cEquipPos;
    cp++;

    *cp = (char)0; // 戮貌脌潞 戮脝脌脤脜脹脌脤鹿脟路脦 脌氓脗酶碌脟脕枚
                   // 戮脢戮脪麓脵.
    cp++;

    sp = (short *)cp;
    *sp = pItem->m_sLevelLimit;
    cp += 2;

    *cp = pItem->m_cGenderLimit;
    cp++;

    wp = (WORD *)cp;
    *wp = pItem->m_wCurLifeSpan;
    cp += 2;

    wp = (WORD *)cp;
    *wp = pItem->m_wWeight;
    cp += 2;

    sp = (short *)cp;
    *sp = pItem->m_sSprite;
    cp += 2;

    sp = (short *)cp;
    *sp = pItem->m_sSpriteFrame;
    cp += 2;

    *cp = pItem->m_cItemColor;
    cp++;

    wp = (WORD *)cp;
    *wp = iV1; // (iCost - iDiscountCost);

    iRet = m_pClientList[iClientH]->m_pXSock->iSendMsg(cData, 48);
    break;

  case DEF_NOTIFY_CANNOTCARRYMOREITEM:
    iRet = m_pClientList[iClientH]->m_pXSock->iSendMsg(cData, 6);
    break;
  }
}

bool CGame::_bCheckItemReceiveCondition(int iClientH, CItem *pItem) {
  int i;

  if (m_pClientList[iClientH] == 0)
    return false;

  if (m_pClientList[iClientH]->m_iCurWeightLoad +
          iGetItemWeight(pItem, pItem->m_dwCount) >
      (DWORD)_iCalcMaxLoad(iClientH))
    return false;

  for (i = 0; i < DEF_MAXITEMS; i++)
    if (m_pClientList[iClientH]->m_pItemList[i] == 0)
      return true;

  return false;
}

void CGame::_ClearQuestStatus(int iClientH) {
  if (m_pClientList[iClientH] == 0)
    return;

  m_pClientList[iClientH]->m_iQuest = 0;
  m_pClientList[iClientH]->m_iQuestID = 0;
  m_pClientList[iClientH]->m_iQuestRewardType = 0;
  m_pClientList[iClientH]->m_iQuestRewardAmount = 0;
  m_pClientList[iClientH]->m_bIsQuestCompleted = false;
}

int CGame::iGetMaxHP(int iClientH) {
  int iRet;

  if (m_pClientList[iClientH] == 0)
    return 0;

  iRet = m_pClientList[iClientH]->m_iVit * 3 +
         m_pClientList[iClientH]->m_iLevel * 2 +
         (m_pClientList[iClientH]->m_iStr +
          m_pClientList[iClientH]->m_iAngelicStr) /
             2;

  if (m_pClientList[iClientH]->m_iSideEffect_MaxHPdown != 0)
    iRet = iRet - (iRet / m_pClientList[iClientH]->m_iSideEffect_MaxHPdown);

  return iRet;
}

int CGame::iGetMaxMP(int iClientH) {
  int iRet;

  if (m_pClientList[iClientH] == 0)
    return 0;

  iRet = (2 * (m_pClientList[iClientH]->m_iMag +
               m_pClientList[iClientH]->m_iAngelicMag)) +
         (2 * m_pClientList[iClientH]->m_iLevel) +
         ((m_pClientList[iClientH]->m_iInt +
           m_pClientList[iClientH]->m_iAngelicInt) /
          2);

  return iRet;
}

int CGame::iGetMaxSP(int iClientH) {
  int iRet;

  if (m_pClientList[iClientH] == 0)
    return 0;

  iRet = (2 * (m_pClientList[iClientH]->m_iStr +
               m_pClientList[iClientH]->m_iAngelicStr)) +
         (2 * m_pClientList[iClientH]->m_iLevel);

  return iRet;
}

void CGame::GetMapInitialPoint(int iMapIndex, short *pX, short *pY,
                               char *pPlayerLocation) {
  int i, iTotalPoint;
  POINT pList[DEF_MAXINITIALPOINT];

  if (m_pMapList[iMapIndex] == 0)
    return;

  // 赂庐陆潞脝庐赂娄 脌脹录潞脟脩麓脵.
  iTotalPoint = 0;
  for (i = 0; i < DEF_MAXINITIALPOINT; i++)
    if (m_pMapList[iMapIndex]->m_pInitialPoint[i].x != -1) {
      pList[iTotalPoint].x = m_pMapList[iMapIndex]->m_pInitialPoint[i].x;
      pList[iTotalPoint].y = m_pMapList[iMapIndex]->m_pInitialPoint[i].y;
      iTotalPoint++;
    }

  if (iTotalPoint == 0)
    return;

  // v1.42 录脪录脫脌脤 脕脽赂鲁脌脤赂茅 鹿芦脕露掳脟 Initial Point脌脟
  // 脙鲁脌陆脌赂路脦 掳拢麓脵.
  if ((pPlayerLocation != 0) && (memcmp(pPlayerLocation, "NONE", 4) == 0))
    i = 0;
  else
    i = iDice(1, iTotalPoint) - 1;

  *pX = pList[i].x;
  *pY = pList[i].y;
}

void CGame::_CheckStrategicPointOccupyStatus(char cMapIndex) {
  class CTile *pTile;
  int i, iX, iY, iSide, iValue;

  m_iStrategicStatus = 0;

  for (i = 0; i < DEF_MAXSTRATEGICPOINTS; i++)
    if (m_pMapList[cMapIndex]->m_pStrategicPointList[i] != 0) {

      iSide = m_pMapList[cMapIndex]->m_pStrategicPointList[i]->m_iSide;
      iValue = m_pMapList[cMapIndex]->m_pStrategicPointList[i]->m_iValue;
      iX = m_pMapList[cMapIndex]->m_pStrategicPointList[i]->m_iX;
      iY = m_pMapList[cMapIndex]->m_pStrategicPointList[i]->m_iY;

      pTile = (class CTile *)(m_pMapList[cMapIndex]->m_pTile + iX +
                              iY * m_pMapList[cMapIndex]->m_sSizeY);

      // 脌眉路芦脌没 脕枚脕隆脌脟 掳隆脕脽脛隆赂娄 掳枚脟脴录颅 麓玫脟脩麓脵.
      m_iStrategicStatus += pTile->m_iOccupyStatus * iValue;
    }
}

