void CGame::CheckSpecialEvent(int iClientH) {
  class CItem *pItem;
  char cItemName[21];
  int iEraseReq;

  if (m_pClientList[iClientH] == 0)
    return;

  // v1.42 脌脤潞楼脝庐 戮脝脌脤脜脹脌禄 脕脴麓脵. 2000.8.1脌脧 1脕脰鲁芒
  // 鹿脻脕枚 录枚驴漏
  if (m_pClientList[iClientH]->m_iSpecialEventID == 200081) {

    // 脌煤路戮脌潞 脕脰脕枚 戮脢麓脗麓脵.
    if (m_pClientList[iClientH]->m_iLevel < 11) {
      m_pClientList[iClientH]->m_iSpecialEventID = 0;
      return;
    }

    ZeroMemory(cItemName, sizeof(cItemName));
    strcpy(cItemName, "MemorialRing");

    pItem = new class CItem;
    if (_bInitItemAttr(pItem, cItemName) == false) {
      // 卤赂脌脭脟脧掳铆脌脷 脟脧麓脗 戮脝脌脤脜脹脌脤 戮脝脌脤脜脹
      // 赂庐陆潞脝庐禄贸驴隆 戮酶麓脵. 卤赂脌脭脌脤 潞脪掳隆麓脡脟脧麓脵.
      delete pItem;
    } else {
      if (_bAddClientItemList(iClientH, pItem, &iEraseReq)) {
        // 驴隆路炉 鹿忙脕枚驴毛 脛脷碌氓
        if (m_pClientList[iClientH]->m_iCurWeightLoad < 0)
          m_pClientList[iClientH]->m_iCurWeightLoad = 0;

        // testcode 路脦卤脳脝脛脌脧驴隆 卤芒路脧脟脩麓脵.
        wsprintf(G_cTxt, "(*) Get MemorialRing  : Char(%s)",
                 m_pClientList[iClientH]->m_cCharName);
        PutLogFileList(G_cTxt);

        // 戮脝脌脤脜脹驴隆 禄莽驴毛脌脷 掳铆脌炉 鹿酶脠拢赂娄 脌脭路脗脟脩麓脵.
        // 麓脵赂楼 脛鲁赂炉脜脥麓脗 脌脤 戮脝脌脤脜脹脌禄 禄莽驴毛脟脪 录枚掳隆
        // 戮酶麓脵.
        pItem->m_sTouchEffectType = DEF_ITET_UNIQUE_OWNER;
        pItem->m_sTouchEffectValue1 = m_pClientList[iClientH]->m_sCharIDnum1;
        pItem->m_sTouchEffectValue2 = m_pClientList[iClientH]->m_sCharIDnum2;
        pItem->m_sTouchEffectValue3 = m_pClientList[iClientH]->m_sCharIDnum3;
        pItem->m_cItemColor = 9;

        // 戮脝脌脤脜脹 鹿脼戮脪脌赂鹿脟路脦 脜卢赂庐戮卯.
        m_pClientList[iClientH]->m_iSpecialEventID = 0;
      }
    }
  }
}

