bool CGame::_bDecodeDupItemIDFileContents(char *pData, DWORD dwMsgSize) {
  char *pContents, *token, cTxt[120];
  char seps[] = "= \t\n";
  char cReadModeA = 0;
  char cReadModeB = 0;
  int iIndex = 0;
  class CStrTok *pStrTok;

  char cData[50000] = {};
  DWORD lpNumberOfBytesRead;
  HANDLE hFile = CreateFile(pData, GENERIC_READ, 0, 0, OPEN_EXISTING, 0, 0);
  DWORD dwFileSize = GetFileSize(hFile, 0);
  if (dwFileSize == -1) {
    wsprintf(G_cTxt, "(X) CRITICAL ERROR! Cannot open configuration file(%s)!",
             pData);
    PutLogList(pData);
    return false;
  }

  SetFilePointer(hFile, 0, 0, FILE_BEGIN);

  ReadFile(hFile, cData, dwFileSize, &lpNumberOfBytesRead, 0);
  CloseHandle(hFile);

  pContents = new char[dwFileSize + 1];
  ZeroMemory(pContents, dwFileSize + 1);
  memcpy(pContents, cData, dwFileSize);

  pStrTok = new class CStrTok(pContents, seps);
  token = pStrTok->pGet();

  while (token != 0) {
    if (cReadModeA != 0) {
      switch (cReadModeA) {
      case 1:
        switch (cReadModeB) {
        case 1:
          // 胶懦 锅龋
          if (_bGetIsStringIsNumber(token) == false) {
            PutLogList("(!!!) ERROR! DupItemID configuration file error - "
                       "Wrong Data format.");
            delete[] pContents;
            delete pStrTok;
            return false;
          }

          if (m_pDupItemIDList[atoi(token)] != 0) {
            // 捞固 且寸等 锅龋啊 乐促. 俊矾捞促.
            PutLogList("(!!!) ERROR! DupItemID configuration file error - "
                       "Duplicate magic number.");
            delete[] pContents;
            delete pStrTok;
            return false;
          }
          m_pDupItemIDList[atoi(token)] = new class CItem;
          iIndex = atoi(token);

          cReadModeB = 2;
          break;

        case 2:
          // m_sTouchEffectType
          if (_bGetIsStringIsNumber(token) == false) {
            PutLogList("(!!!) ERROR! DupItemID configuration file error - "
                       "Wrong Data format.");
            delete[] pContents;
            delete pStrTok;
            return false;
          }
          m_pDupItemIDList[iIndex]->m_sTouchEffectType = atoi(token);
          cReadModeB = 3;
          break;

        case 3:
          // m_sTouchEffectValue1
          if (_bGetIsStringIsNumber(token) == false) {
            PutLogList("(!!!) ERROR! DupItemID configuration file error - "
                       "Wrong Data format.");
            delete[] pContents;
            delete pStrTok;
            return false;
          }
          m_pDupItemIDList[iIndex]->m_sTouchEffectValue1 = atoi(token);
          cReadModeB = 4;
          break;

        case 4:
          // m_sTouchEffectValue2
          if (_bGetIsStringIsNumber(token) == false) {
            PutLogList("(!!!) ERROR! DupItemID configuration file error - "
                       "Wrong Data format.");
            delete[] pContents;
            delete pStrTok;
            return false;
          }
          m_pDupItemIDList[iIndex]->m_sTouchEffectValue2 = atoi(token);
          cReadModeB = 5;
          break;

        case 5:
          // m_sTouchEffectValue3
          if (_bGetIsStringIsNumber(token) == false) {
            PutLogList("(!!!) ERROR! DupItemID configuration file error - "
                       "Wrong Data format.");
            delete[] pContents;
            delete pStrTok;
            return false;
          }
          m_pDupItemIDList[iIndex]->m_sTouchEffectValue3 = atoi(token);
          cReadModeB = 6;
          break;

        case 6:
          // m_wPrice
          if (_bGetIsStringIsNumber(token) == false) {
            PutLogList("(!!!) ERROR! DupItemID configuration file error - "
                       "Wrong Data format.");
            delete[] pContents;
            delete pStrTok;
            return false;
          }
          m_pDupItemIDList[iIndex]->m_wPrice = (WORD)atoi(token);
          cReadModeA = 0;
          cReadModeB = 0;

          // testcode
          // wsprintf(G_cTxt, "(%d) %d %d %d %d", iIndex,
          // m_pDupItemIDList[iIndex]->m_sTouchEffectType,
          // m_pDupItemIDList[iIndex]->m_sTouchEffectValue1,
          // m_pDupItemIDList[iIndex]->m_sTouchEffectValue2,
          // m_pDupItemIDList[iIndex]->m_sTouchEffectValue3);
          // PutLogList(G_cTxt);
          break;
        }
        break;

      default:
        break;
      }
    } else {
      if (memcmp(token, "DupItemID", 9) == 0) {
        cReadModeA = 1;
        cReadModeB = 1;
      }
    }
    token = pStrTok->pGet();
  }

  delete pStrTok;
  delete[] pContents;

  if ((cReadModeA != 0) || (cReadModeB != 0)) {
    PutLogList("(!!!) ERROR! DupItemID configuration file contents error!");
    return false;
  }

  wsprintf(cTxt, "(!) DupItemID(Total:%d) configuration - success!", iIndex);
  PutLogList(cTxt);

  return true;
}

bool CGame::_bCheckDupItemID(CItem *pItem) {
  int i;

  for (i = 0; i < DEF_MAXDUPITEMID; i++)
    if (m_pDupItemIDList[i] != 0) {
      if ((pItem->m_sTouchEffectType ==
           m_pDupItemIDList[i]->m_sTouchEffectType) &&
          (pItem->m_sTouchEffectValue1 ==
           m_pDupItemIDList[i]->m_sTouchEffectValue1) &&
          (pItem->m_sTouchEffectValue2 ==
           m_pDupItemIDList[i]->m_sTouchEffectValue2) &&
          (pItem->m_sTouchEffectValue3 ==
           m_pDupItemIDList[i]->m_sTouchEffectValue3)) {
        // 掳隆掳脻 脕陇潞赂赂娄 掳禄陆脜脟脧掳铆 赂庐脜脧.
        pItem->m_wPrice = m_pDupItemIDList[i]->m_wPrice;
        return true;
      }
    }

  return false;
}

void CGame::_AdjustRareItemValue(CItem *pItem) {
  DWORD dwSWEType, dwSWEValue;
  double dV1, dV2, dV3;

  if ((pItem->m_dwAttribute & 0x00F00000) != 0) {
    dwSWEType = (pItem->m_dwAttribute & 0x00F00000) >> 20;
    dwSWEValue = (pItem->m_dwAttribute & 0x000F0000) >> 16;
    // 脠帽卤脥 戮脝脌脤脜脹 脠驴掳煤 脕戮路霉:
    // 0-None 1-脟脢禄矛卤芒麓毛鹿脤脕枚脙脽掳隆 2-脕脽碌露脠驴掳煤
    // 3-脕陇脌脟脌脟 5-鹿脦脙赂脌脟 6-掳隆潞颅驴卯 7-驴鹿赂庐脟脩
    // 8-掳颅脠颅碌脠 9-掳铆麓毛鹿庐赂铆脌脟
    switch (dwSWEType) {
    case 0:
      break;

    case 5: // 鹿脦脙赂脌脟
      pItem->m_cSpeed--;
      if (pItem->m_cSpeed < 0)
        pItem->m_cSpeed = 0;
      break;

    case 6: // 掳隆潞颅驴卯
      dV2 = (double)pItem->m_wWeight;
      dV3 = (double)(dwSWEValue * 4);
      dV1 = (dV3 / 100.0f) * dV2;
      pItem->m_wWeight -= (int)dV1;

      if (pItem->m_wWeight < 1)
        pItem->m_wWeight = 1;
      break;

    case 8: // 掳颅脠颅碌脠
    case 9: // 掳铆麓毛鹿庐赂铆脌脟
      dV2 = (double)pItem->m_wMaxLifeSpan;
      dV3 = (double)(dwSWEValue * 7);
      dV1 = (dV3 / 100.0f) * dV2;
      pItem->m_wMaxLifeSpan += (int)dV1;
      break;
    }
  }
}

void CGame::RequestNoticementHandler(int iClientH, char *pData) {
  char *cp, cData[120];
  int *ip, iRet, iClientSize;
  DWORD *dwp;
  WORD *wp;

  if (m_pClientList[iClientH] == 0)
    return;
  if (m_dwNoticementDataSize < 10)
    return;

  ip = (int *)(pData + DEF_INDEX2_MSGTYPE + 2);
  iClientSize = *ip;

  if (iClientSize != m_dwNoticementDataSize) {
    // 脜卢露贸脌脤戮冒脝庐掳隆 掳庐掳铆 脌脰麓脗 脝脛脌脧 禄莽脌脤脕卯驴脥
    // 麓脵赂拢赂茅 鲁禄驴毛脌禄 赂冒碌脦 潞赂鲁陆麓脵.
    cp = new char[m_dwNoticementDataSize + 2 + DEF_INDEX2_MSGTYPE + 2];
    ZeroMemory(cp, m_dwNoticementDataSize + 2 + DEF_INDEX2_MSGTYPE + 2);
    memcpy((cp + DEF_INDEX2_MSGTYPE + 2), m_pNoticementData,
           m_dwNoticementDataSize);

    dwp = (DWORD *)(cp + DEF_INDEX4_MSGID);
    *dwp = MSGID_RESPONSE_NOTICEMENT;
    wp = (WORD *)(cp + DEF_INDEX2_MSGTYPE);
    *wp = DEF_MSGTYPE_REJECT;

    iRet = m_pClientList[iClientH]->m_pXSock->iSendMsg(
        cp, m_dwNoticementDataSize + 2 + DEF_INDEX2_MSGTYPE + 2);

    delete cp;
  } else {
    ZeroMemory(cData, sizeof(cData));

    dwp = (DWORD *)(cData + DEF_INDEX4_MSGID);
    *dwp = MSGID_RESPONSE_NOTICEMENT;
    wp = (WORD *)(cData + DEF_INDEX2_MSGTYPE);
    *wp = DEF_MSGTYPE_CONFIRM;

    iRet = m_pClientList[iClientH]->m_pXSock->iSendMsg(cData, 6);
  }
  // 驴隆路炉 鹿脽禄媒脟脴碌碌 虏梅脕枚 戮脢麓脗麓脵.
}

void CGame::RequestNoticementHandler(int iClientH) {
  DWORD *dwp, lpNumberOfBytesRead;
  WORD *wp;

  if (m_pClientList[iClientH] == 0)
    return;

  HANDLE hFile = CreateFile("GameConfigs\\Noticement.txt", GENERIC_READ, 0, 0,
                            OPEN_EXISTING, 0, 0);
  DWORD dwFileSize = GetFileSize(hFile, 0);
  if (dwFileSize == -1) {
    return;
  }

  ZeroMemory(G_cData50000, sizeof(G_cData50000));

  SetFilePointer(hFile, 0, 0, FILE_BEGIN);

  ReadFile(hFile, G_cData50000 + 6, dwFileSize, &lpNumberOfBytesRead, 0);
  CloseHandle(hFile);

  dwp = (DWORD *)(G_cData50000);
  *dwp = MSGID_RESPONSE_NOTICEMENT;

  wp = (WORD *)(G_cData50000 + DEF_INDEX2_MSGTYPE);
  *wp = DEF_MSGTYPE_CONFIRM;

  int iRet =
      m_pClientList[iClientH]->m_pXSock->iSendMsg(G_cData50000, dwFileSize + 8);

  switch (iRet) {
  case DEF_XSOCKEVENT_QUENEFULL:
  case DEF_XSOCKEVENT_SOCKETERROR:
  case DEF_XSOCKEVENT_CRITICALERROR:
  case DEF_XSOCKEVENT_SOCKETCLOSED:
    return;
  }
}

void CGame::_bDecodeNoticementFileContents(char *pData, DWORD dwMsgSize) {
  char *cp;

  cp = (pData);

  if (m_pNoticementData != 0) {
    delete m_pNoticementData;
    m_pNoticementData = 0;
  }

  m_pNoticementData = new char[strlen(cp) + 2];
  ZeroMemory(m_pNoticementData, strlen(cp) + 2);

  memcpy(m_pNoticementData, cp, strlen(cp));
  m_dwNoticementDataSize = strlen(cp);

  wsprintf(G_cTxt, "(!) Noticement Data Size: %d", m_dwNoticementDataSize);
  PutLogList(G_cTxt);
}

void CGame::RequestCheckAccountPasswordHandler(char *pData, DWORD dwMsgSize) {
  int *ip, i, iLevel;
  char *cp, cAccountName[11], cAccountPassword[11];

  cp = (char *)(pData + 6);

  ZeroMemory(cAccountName, sizeof(cAccountName));
  ZeroMemory(cAccountPassword, sizeof(cAccountPassword));

  memcpy(cAccountName, cp, 10);
  cp += 10;

  memcpy(cAccountPassword, cp, 10);
  cp += 10;

  ip = (int *)cp;
  iLevel = *ip;
  cp += 4;

  for (i = 0; i < DEF_MAXCLIENTS; i++)
    if ((m_pClientList[i] != 0) &&
        (strcmp(m_pClientList[i]->m_cAccountName, cAccountName) == 0)) {
      // 掳掳脌潞 掳猫脕陇脌禄 脙拢戮脪麓脵. 赂赂戮脿 脝脨陆潞驴枚碌氓鲁陋
      // 路鹿潞搂脌脤 麓脵赂拢赂茅 碌楼脌脤脜脥 脌煤脌氓脌禄 脟脧脕枚 戮脢掳铆
      // 脕垄录脫脌禄 虏梅麓脗麓脵.
      if ((strcmp(m_pClientList[i]->m_cAccountPassword, cAccountPassword) !=
           0) ||
          (m_pClientList[i]->m_iLevel != iLevel)) {
        wsprintf(G_cTxt,
                 "(TestLog) Error! Account(%s)-Level(%d) password(or level) "
                 "mismatch! Disconnect.",
                 cAccountName, iLevel);
        PutLogList(G_cTxt);
        // 碌楼脌脤脜脥 脌煤脌氓脌禄 脟脧脕枚 戮脢掳铆 虏梅麓脗麓脵.
        DeleteClient(i, false, true);
        return;
      }
    }
}

void CGame::_TamingHandler(int iClientH, int iSkillNum, char cMapIndex, int dX,
                           int dY) {
  int iSkillLevel, iRange, iTamingLevel, iResult, iX, iY;
  short sOwnerH;
  char cOwnerType;

  if (m_pClientList[iClientH] == 0)
    return;
  if (m_pMapList[cMapIndex] == 0)
    return;

  iSkillLevel = (int)m_pClientList[iClientH]->m_cSkillMastery[iSkillNum];
  iRange = iSkillLevel / 12; // 脙脰麓毛 鹿眉脌搂麓脗 8

  for (iX = dX - iRange; iX <= dX + iRange; iX++)
    for (iY = dY - iRange; iY <= dY + iRange; iY++) {
      sOwnerH = 0;
      if ((iX > 0) && (iY > 0) && (iX < m_pMapList[cMapIndex]->m_sSizeX) &&
          (iY < m_pMapList[cMapIndex]->m_sSizeY))
        m_pMapList[cMapIndex]->GetOwner(&sOwnerH, &cOwnerType, iX, iY);

      if (sOwnerH != 0) {
        switch (cOwnerType) {
        case DEF_OWNERTYPE_PLAYER:
          if (m_pClientList[sOwnerH] == 0)
            break;
          break;

        case DEF_OWNERTYPE_NPC:
          if (m_pNpcList[sOwnerH] == 0)
            break;
          // 赂贸陆潞脜脥脌脟 脕戮路霉驴隆 碌没露贸 卤忙碌茅驴漏脕煤
          // 掳脥脌脦脕枚赂娄 掳谩脕陇脟脩麓脵.
          iTamingLevel = 10;
          switch (m_pNpcList[sOwnerH]->m_sType) {
          case 10: // 陆陆露贸脌脫
          case 16:
            iTamingLevel = 1;
            break; // 掳鲁鹿脤
          case 22:
            iTamingLevel = 2;
            break; // 鹿矛
          case 17: // 脌眉掳楼
          case 14:
            iTamingLevel = 3;
            break; // 驴脌脜漏
          case 18:
            iTamingLevel = 4;
            break; // 脕禄潞帽
          case 11:
            iTamingLevel = 5;
            break; // 陆潞脛脤路鹿脜忙
          case 23:
          case 12:
            iTamingLevel = 6;
            break; // 掳帽路陆
          case 28:
            iTamingLevel = 7;
            break; // 脝庐路脩
          case 13: // 陆脦脌脤脜卢路脫陆潞
          case 27:
            iTamingLevel = 8;
            break; // 脟茂脟脧驴卯碌氓
          case 29:
            iTamingLevel = 9;
            break; // 驴脌驴矛掳脜
          case 33:
            iTamingLevel = 9;
            break; // 驴镁戮卯驴茂脟脕
          case 30:
            iTamingLevel = 9;
            break; // 赂庐脛隆
          case 31:
          case 32:
            iTamingLevel = 10;
            break; // 碌楼赂贸, 脌炉麓脧脛脺
          }

          iResult = (iSkillLevel / 10);

          // 陆潞脜鲁脌脟 碌卯卤脼驴隆 碌没露贸 卤忙碌茅脌脧 录枚 脌脰麓脗
          // 掳鹿录枚掳隆 麓脼露贸脕酶麓脵.
          if (iResult < iTamingLevel)
            break;

          break;
        }
      }
    }
}

void CGame::GetMagicAbilityHandler(int iClientH) {
  if (m_pClientList[iClientH] == 0)
    return;
  if (m_pClientList[iClientH]->m_cSkillMastery[4] != 0)
    return;

  // 赂露鹿媒 麓脡路脗 陆潞脜鲁脌禄 20脌赂路脦 潞炉掳忙脠脛 戮脣路脕脕脺
  m_pClientList[iClientH]->m_cSkillMastery[4] = 20;
  SendNotifyMsg(0, iClientH, DEF_NOTIFY_SKILL, 4,
                m_pClientList[iClientH]->m_cSkillMastery[4], 0, 0);
  // v1.4311 陆潞脜鲁脌脟 脙脩 脟脮脌禄 脙录脜漏
  bCheckTotalSkillMasteryPoints(iClientH, 4);
}

int CGame::iRequestPanningMapDataRequest(int iClientH, char *pData) {
  char *cp, cDir, cData[3000];
  DWORD *dwp;
  WORD *wp;
  short *sp, dX, dY;
  int iRet, iSize;

  if (m_pClientList[iClientH] == 0)
    return 0;
  if (m_pClientList[iClientH]->m_bIsObserverMode == false)
    return 0;
  if (m_pClientList[iClientH]->m_bIsKilled)
    return 0;
  if (m_pClientList[iClientH]->m_bIsInitComplete == false)
    return 0;

  dX = m_pClientList[iClientH]->m_sX;
  dY = m_pClientList[iClientH]->m_sY;

  cDir = *(pData + DEF_INDEX2_MSGTYPE + 2);
  if ((cDir <= 0) || (cDir > 8))
    return 0;

  switch (cDir) {
  case 1:
    dY--;
    break; // responding when mouse is placed north
  case 2:
    dX++;
    dY--;
    break;
  case 3:
    dX++;
    break;
  case 4:
    dX++;
    dY++;
    break;
  case 5:
    dY++;
    break;
  case 6:
    dX--;
    dY++;
    break;
  case 7:
    dX--;
    break; // responding when mouse placed at west side of screen
  case 8:
    dX--;
    dY--;
    break; // responding when mouse is placed north west
           /*
           player is in the center, and is trying to pan,
           directions not responding or causing a break will be kept as X,
           others are the cDir case...
                           8	1	X
       
                           7	_	X
       
                           X	X	X
           */
  }

  m_pClientList[iClientH]->m_sX = dX;
  m_pClientList[iClientH]->m_sY = dY;
  m_pClientList[iClientH]->m_cDir = cDir;

  dwp = (DWORD *)(cData + DEF_INDEX4_MSGID);
  *dwp = MSGID_RESPONSE_PANNING;
  wp = (WORD *)(cData + DEF_INDEX2_MSGTYPE);
  *wp = DEF_OBJECTMOVE_CONFIRM;

  cp = (char *)(cData + DEF_INDEX2_MSGTYPE + 2);

  sp = (short *)cp;
  *sp = (short)(dX - 12);
  cp += 2;

  sp = (short *)cp;
  *sp = (short)(dY - 9);
  cp += 2;

  *cp = cDir;
  cp++;

  iSize = iComposeMoveMapData((short)(dX - 12), (short)(dY - 9), iClientH, cDir,
                              cp);
  iRet = m_pClientList[iClientH]->m_pXSock->iSendMsg(cData, iSize + 12 + 1 + 4);
  switch (iRet) {
  case DEF_XSOCKEVENT_QUENEFULL:
  case DEF_XSOCKEVENT_SOCKETERROR:
  case DEF_XSOCKEVENT_CRITICALERROR:
  case DEF_XSOCKEVENT_SOCKETCLOSED:
    // 赂脼陆脙脕枚赂娄 潞赂鲁戮露搂 驴隆路炉掳隆 鹿脽禄媒脟脽麓脵赂茅
    // 脕娄掳脜脟脩麓脵.
    DeleteClient(iClientH, true, true);
    return 0;
  }

  return 1;
}

void CGame::AdminOrder_SetObserverMode(int iClientH) {

  if (m_pClientList[iClientH] == 0)
    return;

  if (m_pClientList[iClientH]->m_bIsObserverMode) {
    // 禄玫 脌搂脛隆驴隆 脟楼陆脙脟脩麓脵.
    m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->SetOwner(
        iClientH, DEF_OWNERTYPE_PLAYER, m_pClientList[iClientH]->m_sX,
        m_pClientList[iClientH]->m_sY);
    SendEventToNearClient_TypeA(iClientH, DEF_OWNERTYPE_PLAYER, MSGID_EVENT_LOG,
                                DEF_MSGTYPE_CONFIRM, 0, 0, 0);
    SendNotifyMsg(0, iClientH, DEF_NOTIFY_OBSERVERMODE, 0, 0, 0, 0);
    m_pClientList[iClientH]->m_bIsObserverMode = false;
  } else {
    // 脟枚脌莽 脌搂脛隆驴隆录颅 脕枚驴卯麓脵. 戮酶戮卯脕酶 脟脿脌搂赂娄
    // 戮脣路脕脕脿戮脽 脟脩麓脵. 戮脝脕梅 鹿脤卤赂脟枚
    m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->ClearOwner(
        1, iClientH, DEF_OWNERTYPE_PLAYER, m_pClientList[iClientH]->m_sX,
        m_pClientList[iClientH]->m_sY);
    SendEventToNearClient_TypeA(iClientH, DEF_OWNERTYPE_PLAYER, MSGID_EVENT_LOG,
                                DEF_MSGTYPE_REJECT, 0, 0, 0);
    // iRequestPanningMapDataRequest(iClientH, pData)
    SendNotifyMsg(0, iClientH, DEF_NOTIFY_OBSERVERMODE, 1, 0, 0, 0);
    m_pClientList[iClientH]->m_bIsObserverMode = true;
  }
}

void CGame::RequestRestartHandler(int iClientH) {
  char cTmpMap[32];

  if (m_pClientList[iClientH] == 0)
    return;

  if (m_pClientList[iClientH]->m_bIsKilled) {

    strcpy(cTmpMap, m_pClientList[iClientH]->m_cMapName);
    ZeroMemory(m_pClientList[iClientH]->m_cMapName,
               sizeof(m_pClientList[iClientH]->m_cMapName));

    if (strcmp(m_pClientList[iClientH]->m_cLocation, "NONE") == 0) {
      // 咯青磊扼搁  default甘栏肺 埃促.
      strcpy(m_pClientList[iClientH]->m_cMapName, "default");
    } else {
      // 家加捞 乐促搁 家加 付阑狼 何劝粮栏肺 埃促.
      if ((strcmp(m_pClientList[iClientH]->m_cLocation, "aresden") == 0) ||
          (strcmp(m_pClientList[iClientH]->m_cLocation, "arehunter") == 0)) {
        if (m_bIsCrusadeMode) {
          // 农风技捞靛 葛靛俊辑 荤噶茄 版快: 付阑 甘俊辑 老沥矫埃 唱哎 荐 绝促.
          if (m_pClientList[iClientH]->m_iDeadPenaltyTime > 0) {
            ZeroMemory(m_pClientList[iClientH]->m_cLockedMapName,
                       sizeof(m_pClientList[iClientH]->m_cLockedMapName));
            strcpy(m_pClientList[iClientH]->m_cLockedMapName, "aresden");
            m_pClientList[iClientH]->m_iLockedMapTime = 60 * 5;
            m_pClientList[iClientH]->m_iDeadPenaltyTime = 60 * 10; // v2.04
          } else {
            memcpy(m_pClientList[iClientH]->m_cMapName, "resurr1", 7);
            m_pClientList[iClientH]->m_iDeadPenaltyTime =
                60 * 10; // v2.04 10盒 救俊 肚 磷栏搁 付阑俊 爱腮促.
          }
        }
        // v2.16 2002-5-31
        if (strcmp(cTmpMap, "elvine") == 0) {
          memcpy(m_pClientList[iClientH]->m_cMapName, "elvjail", 7);
          strcpy(m_pClientList[iClientH]->m_cLockedMapName, "elvjail");
          m_pClientList[iClientH]->m_iLockedMapTime = 60 * 3; // 3盒
        } else if (m_pClientList[iClientH]->m_iLevel > 80)
          memcpy(m_pClientList[iClientH]->m_cMapName, "resurr1", 7);
        else
          memcpy(m_pClientList[iClientH]->m_cMapName, "arefarm", 7);
      } else {
        if (m_bIsCrusadeMode) {
          // 农风技捞靛 葛靛俊辑 荤噶茄 版快: 付阑 甘俊辑 老沥矫埃 唱哎 荐 绝促.
          if (m_pClientList[iClientH]->m_iDeadPenaltyTime > 0) {
            ZeroMemory(m_pClientList[iClientH]->m_cLockedMapName,
                       sizeof(m_pClientList[iClientH]->m_cLockedMapName));
            strcpy(m_pClientList[iClientH]->m_cLockedMapName, "elvine");
            m_pClientList[iClientH]->m_iLockedMapTime = 60 * 5;
            m_pClientList[iClientH]->m_iDeadPenaltyTime = 60 * 10; // v2.04
          } else {
            memcpy(m_pClientList[iClientH]->m_cMapName, "resurr2", 7);
            m_pClientList[iClientH]->m_iDeadPenaltyTime =
                60 * 10; // v2.04 10盒 救俊 肚 磷栏搁 付阑俊 爱腮促.
          }
        }
        if (strcmp(cTmpMap, "aresden") == 0) {
          memcpy(m_pClientList[iClientH]->m_cMapName, "arejail", 7);
          strcpy(m_pClientList[iClientH]->m_cLockedMapName, "arejail");
          m_pClientList[iClientH]->m_iLockedMapTime = 60 * 3; // 3盒

        } else if (m_pClientList[iClientH]->m_iLevel > 80)
          memcpy(m_pClientList[iClientH]->m_cMapName, "resurr2", 7);
        else
          memcpy(m_pClientList[iClientH]->m_cMapName, "elvfarm", 7);
      }
    }

    // v2.04 促矫 混府绰 贸府甫 茄促. HP, 硅绊悄 瘤荐 父顶
    m_pClientList[iClientH]->m_bIsKilled = false;
    m_pClientList[iClientH]->m_iHP = iGetMaxHP(iClientH);
    m_pClientList[iClientH]->m_iHungerStatus = 100;

    ZeroMemory(cTmpMap, sizeof(cTmpMap));
    strcpy(cTmpMap, m_pClientList[iClientH]->m_cMapName);
    // !!! RequestTeleportHandler郴俊辑 m_cMapName阑 静扁 锭巩俊 弊措肺
    // 颇扼固磐肺 逞败林搁 坷悼累
    RequestTeleportHandler(iClientH, "2   ", cTmpMap, -1, -1);
  }
}

void CGame::AdminOrder_EnableAdminCommand(int iClientH, char *pData,
                                          DWORD dwMsgSize) {
  char *token, cBuff[256], len;
  char seps[] = "= \t\n";
  class CStrTok *pStrTok;

  if (m_pClientList[iClientH] == 0)
    return;
  if ((dwMsgSize) <= 0)
    return;

  ZeroMemory(cBuff, sizeof(cBuff));
  memcpy(cBuff, pData, dwMsgSize);
  pStrTok = new class CStrTok(cBuff, seps);
  token = pStrTok->pGet();
  token = pStrTok->pGet();

  if (token != 0) {
    len = strlen(token);
    if (len > 10)
      len = 10;
    if (memcmp(token, m_cSecurityNumber, len) == 0) {
      m_pClientList[iClientH]->m_bIsAdminCommandEnabled = true;
    } else {
      try {
        wsprintf(
            G_cTxt,
            "(%s) Player(%s) attempts to access /enableadmincommand with %s",
            m_pClientList[iClientH]->m_cIPaddress,
            m_pClientList[iClientH]->m_cCharName, token);
        PutHackLogFileList(G_cTxt);
      } catch (...) {
      }
      return;
    }
  }
}

void CGame::AdminOrder_CreateItem(int iClientH, char *pData, DWORD dwMsgSize) {
  char seps[] = "= \t\n";
  char *cp, *token, cBuff[256], cItemName[256], cData[256], cTemp[256],
      cAttribute[256], cValue[256];
  SYSTEMTIME SysTime;
  class CStrTok *pStrTok;
  class CItem *pItem;
  short *sp;
  int iRet, iTemp, iEraseReq, iValue;
  DWORD *dwp;
  WORD *wp, wTemp;
  double dV1, dV2, dV3;

  // if the client doesnt exist than no effect.
  if (m_pClientList[iClientH] == 0)
    return;
  if (m_pClientList[iClientH]->m_bIsAdminCommandEnabled == false)
    return;

  // if the command is just "/createitem " than no effect.
  if ((dwMsgSize) <= 0)
    return;

  // if client's admin level is less than 4 no effect.
  if (m_pClientList[iClientH]->m_iAdminUserLevel < m_iAdminLevelCreateItem) {
    // if the admin user level is not 0 and less than 4 send message
    if (m_pClientList[iClientH]->m_iAdminUserLevel != 0)
      SendNotifyMsg(0, iClientH, DEF_NOTIFY_ADMINUSERLEVELLOW, 0, 0, 0, 0);
    return;
  } // close if (m_pClientList[iClientH]->m_iAdminUserLevel < 4) {

  // IP address not able to create item
  // DISABLED: if (memcmp(m_pClientList[iClientH]->m_cIPaddress, "192.168.1.",
  // 12) != 0) return;

  // check if the client has typed "/enableadmincreateitem"
  // if (m_pClientList[iClientH]->m_bIsAdminCreateItemEnabled == false) return;

  ZeroMemory(cBuff, sizeof(cBuff));
  memcpy(cBuff, pData, dwMsgSize);
  pStrTok = new class CStrTok(cBuff, seps);
  token = pStrTok->pGet();
  token = pStrTok->pGet();

  // if the token is something it is an item name
  if (token != 0) {
    ZeroMemory(cItemName, sizeof(cItemName));
    strcpy(cItemName, token);
  } // close if (token != 0) {

  // if the 2nd token is true it is the item attribute
  ZeroMemory(cAttribute, sizeof(cAttribute));
  token = pStrTok->pGet();
  if (token != 0) {
    ZeroMemory(cAttribute, sizeof(cAttribute));
    strcpy(cAttribute, token);
  } // close if (token != 0) {

  // if the 3rd token is true it is the item value
  ZeroMemory(cValue, sizeof(cValue));
  iValue = 0;
  token = pStrTok->pGet();
  if (token != 0) {
    ZeroMemory(cValue, sizeof(cValue));
    strcpy(cValue, token);
    iValue = atoi(cValue);
  } // close if (token != 0) {

  pItem = new class CItem;
  // if the given itemname doesnt exist delete item
  if (_bInitItemAttr(pItem, cItemName) == false) {
    delete pItem;
    return;
  } // close if (_bInitItemAttr(pItem, cItemName) == false) {

  if (strlen(cAttribute) != 0) {
    pItem->m_dwAttribute = atoi(cAttribute);
    if (pItem->m_dwAttribute == 1) {
      if ((iValue >= 1) && (iValue <= 200)) {
        pItem->m_cItemColor = 2;
        pItem->m_sItemSpecEffectValue2 = iValue - 100;

        dV2 = (double)pItem->m_sItemSpecEffectValue2;
        dV3 = (double)pItem->m_wMaxLifeSpan;
        dV1 = (dV2 / 100.0f) * dV3;

        iTemp = (int)pItem->m_wMaxLifeSpan;
        iTemp += (int)dV1;

        if (iTemp <= 0)
          wTemp = 1;
        else
          wTemp = (WORD)iTemp;

        if (wTemp <= pItem->m_wMaxLifeSpan * 2) {
          pItem->m_wMaxLifeSpan = wTemp;
          pItem->m_sItemSpecEffectValue1 = (short)wTemp;
          pItem->m_wCurLifeSpan = pItem->m_wMaxLifeSpan;
        } // close if (wTemp <= pItem->m_wMaxLifeSpan*2) {
        else
          pItem->m_sItemSpecEffectValue1 = (short)pItem->m_wMaxLifeSpan;
      } // close if ((iValue >= 1) && (iValue <= 200)) {
      else
        pItem->m_dwAttribute = 0;
    } // close if (pItem->m_dwAttribute == 1) {
    else {
      if (pItem->m_sItemEffectType == DEF_ITEMEFFECTTYPE_ATTACK) {
        switch ((pItem->m_dwAttribute & 0xF00000) >> 20) {
        case 6:
          pItem->m_cItemColor = 2;
          break;
        case 8:
          pItem->m_cItemColor = 3;
          break;
        case 1:
          pItem->m_cItemColor = 5;
          break;
        case 5:
          pItem->m_cItemColor = 1;
          break;
        case 3:
          pItem->m_cItemColor = 7;
          break;
        case 2:
          pItem->m_cItemColor = 4;
          break;
        case 7:
          pItem->m_cItemColor = 6;
          break;
        case 9:
          pItem->m_cItemColor = 8;
          break;
        } // close switch ((pItem->m_dwAttribute & 0xF00000) >> 20) {
      } // close if (pItem->m_sItemEffectType == DEF_ITEMEFFECTTYPE_ATTACK) {
      else if (pItem->m_sItemEffectType == DEF_ITEMEFFECTTYPE_ATTACK_MANASAVE) {
        switch ((pItem->m_dwAttribute & 0xF00000) >> 20) {
        case 10:
          pItem->m_cItemColor = 5;
          break;
        } // close switch ((pItem->m_dwAttribute & 0xF00000) >> 20) {
      } // close else if (pItem->m_sItemEffectType ==
        // DEF_ITEMEFFECTTYPE_ATTACK_MANASAVE) {
    } // close else {
  } // close if (strlen(cAttribute) != 0) {

  // if the item id is
  switch (pItem->m_sIDnum) {
  case 511: // ArenaTicket
  case 513: // ArenaTicket(2)
  case 515: // ArenaTicket(3)
  case 517: // ArenaTicket(4)
  case 530: // ArenaTicket(5)
  case 531: // ArenaTicket(6)
  case 532: // ArenaTicket(7)
  case 533: // ArenaTicket(8)
  case 534: // ArenaTicket(9)
    GetLocalTime(&SysTime);
    pItem->m_sTouchEffectType = DEF_ITET_DATE;
    // v1.4311-3 函版 款康磊啊 惯鞭茄 涝厘鼻篮 弊朝篮 亲惑 涝厘 啊瓷 ..
    pItem->m_sTouchEffectValue1 = (short)SysTime.wMonth;
    pItem->m_sTouchEffectValue2 = (short)SysTime.wDay;
    pItem->m_sTouchEffectValue3 = 24;
    break;

  default:
    GetLocalTime(&SysTime);
    pItem->m_sTouchEffectType = DEF_ITET_ID;
    pItem->m_sTouchEffectValue1 = iDice(1, 100000);
    pItem->m_sTouchEffectValue2 = iDice(1, 100000);
    // 付瘤阜 箭磊绰 酒捞袍 积己 岿, 老
    ZeroMemory(cTemp, sizeof(cTemp));
    wsprintf(cTemp, "%d%2d", (short)SysTime.wMonth, (short)SysTime.wDay);
    pItem->m_sTouchEffectValue3 = atoi(cTemp);
    break;
  }

  ZeroMemory(cData, sizeof(cData));
  if (_bAddClientItemList(iClientH, pItem, &iEraseReq)) {
    // 酒捞袍阑 裙垫沁促.
    dwp = (DWORD *)(cData + DEF_INDEX4_MSGID);
    *dwp = MSGID_NOTIFY;
    wp = (WORD *)(cData + DEF_INDEX2_MSGTYPE);
    *wp = DEF_NOTIFY_ITEMOBTAINED;

    cp = (char *)(cData + DEF_INDEX2_MSGTYPE + 2);

    // 1俺 裙垫沁促. Amount啊 酒聪促!
    *cp = 1;
    cp++;

    memcpy(cp, pItem->m_cName, 20);
    cp += 20;

    dwp = (DWORD *)cp;
    *dwp = pItem->m_dwCount; // 荐樊阑 涝仿
    cp += 4;

    *cp = pItem->m_cItemType;
    cp++;

    *cp = pItem->m_cEquipPos;
    cp++;

    *cp = (char)0; // 掘篮 酒捞袍捞骨肺 厘馒登瘤 臼疽促.
    cp++;

    sp = (short *)cp;
    *sp = pItem->m_sLevelLimit;
    cp += 2;

    *cp = pItem->m_cGenderLimit;
    cp++;

    wp = (WORD *)cp;
    *wp = pItem->m_wCurLifeSpan;
    cp += 2;

    wp = (WORD *)cp;
    *wp = pItem->m_wWeight;
    cp += 2;

    sp = (short *)cp;
    *sp = pItem->m_sSprite;
    cp += 2;

    sp = (short *)cp;
    *sp = pItem->m_sSpriteFrame;
    cp += 2;

    *cp = pItem->m_cItemColor;
    cp++;

    *cp = (char)pItem->m_sItemSpecEffectValue2; // v1.41
    cp++;

    dwp = (DWORD *)cp;
    *dwp = pItem->m_dwAttribute;
    cp += 4;

    // v2.15 肺弊 包访 荐沥
    if (iEraseReq == 1) {
      delete pItem;
      pItem = 0;
    }

    // 酒捞袍 沥焊 傈价
    iRet = m_pClientList[iClientH]->m_pXSock->iSendMsg(cData, 53);

    // v2.14 Admin Log
    wsprintf(G_cTxt, "(%s) GM Order(%s): Create ItemName(%s)",
             m_pClientList[iClientH]->m_cIPaddress,
             m_pClientList[iClientH]->m_cCharName, cItemName);
    bSendMsgToLS(MSGID_GAMEMASTERLOG, iClientH, 0, G_cTxt);

    return;
  } else {
    // 酒捞袍阑 家瘤且 荐 绝绰 惑炔捞促.
    delete pItem;
    return;
  }
}

void CGame::RequestSellItemListHandler(int iClientH, char *pData) {
  int i, *ip, iAmount;
  char *cp, cIndex;
  struct {
    char cIndex;
    int iAmount;
  } stTemp[12];

  if (m_pClientList[iClientH] == 0)
    return;

  cp = (char *)(pData + 6);
  for (i = 0; i < 12; i++) {
    stTemp[i].cIndex = *cp;
    cp++;

    ip = (int *)cp;
    stTemp[i].iAmount = *ip;
    cp += 4;
  }

  // 鲁禄驴毛脌禄 麓脵 脌脨戮煤麓脵. 录酶录颅麓毛路脦 脝脠戮脝脛隆驴卯麓脵.
  for (i = 0; i < 12; i++) {
    cIndex = stTemp[i].cIndex;
    iAmount = stTemp[i].iAmount;

    if ((cIndex == -1) || (cIndex < 0) || (cIndex >= DEF_MAXITEMS))
      return;
    if (m_pClientList[iClientH]->m_pItemList[cIndex] == 0)
      return;

    // cIndex驴隆 脟脴麓莽脟脧麓脗 戮脝脌脤脜脹脌禄 脝脟麓脵.
    ReqSellItemConfirmHandler(iClientH, cIndex, iAmount, 0);
    // 脌脤 路莽脝戮脌禄 录枚脟脿脟脩 麓脵脌陆 脜卢露贸脌脤戮冒脝庐掳隆
    // 禄猫脕娄碌脟戮煤脌禄 录枚 脌脰脌赂麓脧 脕脰脌脟!
    if (m_pClientList[iClientH] == 0)
      return;
  }
}

void CGame::_DeleteRandomOccupyFlag(int iMapIndex) {
  int i, iCount, iTotalFlags, iTargetFlag, iDynamicObjectIndex;
  int tx, ty, fx, fy, iLocalSide, iLocalEKNum, iPrevStatus;
  class CTile *pTile;
  DWORD dwTime;

  if (m_pMapList[iMapIndex] == 0)
    return;

  dwTime = timeGetTime();

  // 脙脩 卤锚鹿脽 掳鹿录枚赂娄 卤赂脟脩麓脵.
  iTotalFlags = 0;
  for (i = 1; i < DEF_MAXOCCUPYFLAG; i++)
    if (m_pMapList[iMapIndex]->m_pOccupyFlag[i] != 0) {
      iTotalFlags++;
    }

  // 路拢麓媒脟脧掳脭 脟脧鲁陋 脕陇脟脩麓脵.
  iTargetFlag = iDice(1, iTotalFlags);

  iCount = 0;
  for (i = 1; i < DEF_MAXOCCUPYFLAG; i++)
    if (m_pMapList[iMapIndex]->m_pOccupyFlag[i] != 0) {
      iCount++;
      if ((iCount == iTotalFlags) &&
          (m_pMapList[iMapIndex]->m_pOccupyFlag[i] != 0)) {
        // m_pMapList[iMapIndex]->m_pOccupyFlag[i] : 脌脤 卤锚鹿脽脌禄
        // 戮酶戮脴麓脵.

        // testcode
        wsprintf(G_cTxt, "(*)Delete OccupyFlag: Side(%d) XY(%d, %d)",
                 m_pMapList[iMapIndex]->m_pOccupyFlag[i]->m_cSide,
                 m_pMapList[iMapIndex]->m_pOccupyFlag[i]->m_sX,
                 m_pMapList[iMapIndex]->m_pOccupyFlag[i]->m_sY);
        PutLogList(G_cTxt);

        fx = m_pMapList[iMapIndex]->m_pOccupyFlag[i]->m_sX;
        fy = m_pMapList[iMapIndex]->m_pOccupyFlag[i]->m_sY;
        iLocalSide = m_pMapList[iMapIndex]->m_pOccupyFlag[i]->m_cSide;
        iLocalEKNum = m_pMapList[iMapIndex]->m_pOccupyFlag[i]->m_iEKCount;

        pTile = (class CTile *)(m_pMapList[iMapIndex]->m_pTile +
                                m_pMapList[iMapIndex]->m_pOccupyFlag[i]->m_sX +
                                m_pMapList[iMapIndex]->m_pOccupyFlag[i]->m_sY *
                                    m_pMapList[iMapIndex]->m_sSizeY);
        // 卤锚鹿脽 掳麓脙录 掳篓录脪
        m_pMapList[iMapIndex]->m_iTotalOccupyFlags--;

        iDynamicObjectIndex =
            m_pMapList[iMapIndex]->m_pOccupyFlag[i]->m_iDynamicObjectIndex;
        // 脜卢露贸脌脤戮冒脝庐驴隆掳脭 卤锚鹿脽脌脤 禄莽露贸脕眉脌禄
        // 戮脣赂庐掳铆
        SendEventToNearClient_TypeB(
            MSGID_DYNAMICOBJECT, DEF_MSGTYPE_REJECT,
            m_pDynamicObjectList[iDynamicObjectIndex]->m_cMapIndex,
            m_pDynamicObjectList[iDynamicObjectIndex]->m_sX,
            m_pDynamicObjectList[iDynamicObjectIndex]->m_sY,
            m_pDynamicObjectList[iDynamicObjectIndex]->m_sType,
            iDynamicObjectIndex, 0, (short)0);
        // 赂脢驴隆录颅 卤锚鹿脽 碌驴脌没 掳麓脙录赂娄 禄猫脕娄脟脩麓脵.
        m_pMapList[m_pDynamicObjectList[iDynamicObjectIndex]->m_cMapIndex]
            ->SetDynamicObject(
                0, 0, m_pDynamicObjectList[iDynamicObjectIndex]->m_sX,
                m_pDynamicObjectList[iDynamicObjectIndex]->m_sY, dwTime);

        // 卤锚鹿脽 掳麓脙录赂娄 禄猫脕娄
        delete m_pMapList[iMapIndex]->m_pOccupyFlag[i];
        m_pMapList[iMapIndex]->m_pOccupyFlag[i] = 0;

        // 脜赂脌脧 禄贸脌脟 卤锚鹿脽 脌脦碌娄陆潞赂娄 禄猫脕娄
        pTile->m_iOccupyFlagIndex = 0;

        // 碌驴脌没 掳麓脙录 禄猫脕娄
        delete m_pDynamicObjectList[iDynamicObjectIndex];
        m_pDynamicObjectList[iDynamicObjectIndex] = 0;

        // 脌脤 卤锚鹿脽脌禄 禄猫脕娄脟脧鹿脟路脦 驴碌脟芒卤脟 鲁禄脌脟 掳陋脌禄
        // 潞炉掳忙陆脙脛脩戮脽 脟脩麓脵. *** 赂脟 赂露脕枚赂路驴隆
        // 脙鲁赂庐脟脴戮脽 脟脩麓脵.
        for (tx = fx - 12; tx <= fx + 12; tx++)
          for (ty = fy - 10; ty <= fy + 10; ty++) {
            if ((tx < 0) || (tx >= m_pMapList[iMapIndex]->m_sSizeX) ||
                (ty < 0) || (ty >= m_pMapList[iMapIndex]->m_sSizeY)) {
              // 鹿芦陆脙脟脴戮脽 脟脧麓脗 脕脗脟楼
            } else {
              pTile = (class CTile *)(m_pMapList[iMapIndex]->m_pTile + tx +
                                      ty * m_pMapList[iMapIndex]->m_sSizeY);
              iPrevStatus = pTile->m_iOccupyStatus;
              // Side: 戮脝路鹿陆潞碌搂(1)  驴陇鹿脵脌脦(2)
              switch (iLocalSide) {
              case 1:
                pTile->m_iOccupyStatus += iLocalEKNum;
                if (pTile->m_iOccupyStatus > 0)
                  pTile->m_iOccupyStatus = 0;
                break;
              case 2:
                pTile->m_iOccupyStatus -= iLocalEKNum;
                if (pTile->m_iOccupyStatus < 0)
                  pTile->m_iOccupyStatus = 0;
                break;
              }
            }
          }
        //
        return;
      }
    }
}

void CGame::CreateNewPartyHandler(int iClientH) {
  bool bFlag;

  if (m_pClientList[iClientH] == 0)
    return;

  bFlag = m_pClientList[iClientH]->bCreateNewParty();
  SendNotifyMsg(0, iClientH, DEF_NOTIFY_RESPONSE_CREATENEWPARTY, (int)bFlag, 0,
                0, 0);
}

void CGame::JoinPartyHandler(int iClientH, int iV1, char *pMemberName) {
  char *cp, cData[120];
  short sAppr2;
  DWORD *dwp;
  WORD *wp;
  int i;

  if (m_pClientList[iClientH] == 0)
    return;
  if ((m_bAdminSecurity) && (m_pClientList[iClientH]->m_iAdminUserLevel > 0))
    return;

  switch (iV1) {
  case 0: // 脝脛脝录 脜禄脜冒 陆脜脙禄
    RequestDeletePartyHandler(iClientH);
    break;

  case 1: // 脝脛脝录 掳隆脌脭 陆脜脙禄
    // testcode
    wsprintf(
        G_cTxt,
        "Join Party Req: %s(%d) ID(%d) Stat(%d) ReqJoinH(%d) ReqJoinName(%s)",
        m_pClientList[iClientH]->m_cCharName, iClientH,
        m_pClientList[iClientH]->m_iPartyID,
        m_pClientList[iClientH]->m_iPartyStatus,
        m_pClientList[iClientH]->m_iReqJoinPartyClientH,
        m_pClientList[iClientH]->m_cReqJoinPartyName);
    PutLogList(G_cTxt);

    if ((m_pClientList[iClientH]->m_iPartyID != 0) ||
        (m_pClientList[iClientH]->m_iPartyStatus != DEF_PARTYSTATUS_NULL)) {
      // 脌脤鹿脤 脝脛脝录驴隆 掳隆脌脭脟脴 脌脰麓脵赂茅 脝脛脝录 掳隆脌脭
      // 陆脜脙禄脌禄 脟脪 录枚 戮酶麓脵.
      SendNotifyMsg(0, iClientH, DEF_NOTIFY_PARTY, 7, 0, 0, 0);
      m_pClientList[iClientH]->m_iReqJoinPartyClientH = 0;
      ZeroMemory(m_pClientList[iClientH]->m_cReqJoinPartyName,
                 sizeof(m_pClientList[iClientH]->m_cReqJoinPartyName));
      m_pClientList[iClientH]->m_iPartyStatus = DEF_PARTYSTATUS_NULL;
      // testcode
      PutLogList("Join Party Reject (1)");
      return;
    }

    for (i = 1; i < DEF_MAXCLIENTS; i++)
      if ((m_pClientList[i] != 0) &&
          (strcmp(m_pClientList[i]->m_cCharName, pMemberName) == 0)) {
        // 掳掳脌潞 脌脤赂搂脌禄 掳隆脕酶 脟脙路鹿脌脤戮卯赂娄 脙拢戮脪麓脵.
        sAppr2 = (short)((m_pClientList[i]->m_sAppr2 & 0xF000) >> 12);
        if (sAppr2 != 0) {
          // 脌眉脜玫 赂冒碌氓 禄贸脜脗脌脟 禄贸麓毛驴隆掳脭麓脗 脝脛脝录
          // 掳隆脌脭 陆脜脙禄脌禄 脟脪 录枚 戮酶麓脵.
          SendNotifyMsg(0, iClientH, DEF_NOTIFY_PARTY, 7, 0, 0, 0);
          // testcode
          PutLogList("Join Party Reject (2)");
        } else if (m_pClientList[i]->m_cSide !=
                   m_pClientList[iClientH]->m_cSide) {
          // 脝铆脌脤 麓脵赂拢赂茅 脝脛脝录驴隆 碌茅 录枚 戮酶麓脵.
          SendNotifyMsg(0, iClientH, DEF_NOTIFY_PARTY, 7, 0, 0, 0);
          // testcode
          PutLogList("Join Party Reject (3)");
        } else if (m_pClientList[i]->m_iPartyStatus ==
                   DEF_PARTYSTATUS_PROCESSING) {
          // 脝脛脝录 掳隆脌脭脌禄 陆脜脙禄脟脩 麓毛禄贸脌脤 脌脤鹿脤 麓脵赂楼
          // 脝脛脝录 掳隆脌脭 掳眉路脙 脙鲁赂庐赂娄 脟脧掳铆 脌脰麓脵. 陆脜脙禄
          // 潞脪掳隆.
          SendNotifyMsg(0, iClientH, DEF_NOTIFY_PARTY, 7, 0, 0, 0);
          // testcode
          PutLogList("Join Party Reject (4)");
          // testcode
          wsprintf(G_cTxt, "Party join reject(2) ClientH:%d ID:%d JoinName:%d",
                   i, m_pClientList[i]->m_iPartyID,
                   m_pClientList[i]->m_cReqJoinPartyName);
          PutLogList(G_cTxt);

          m_pClientList[iClientH]->m_iReqJoinPartyClientH = 0;
          ZeroMemory(m_pClientList[iClientH]->m_cReqJoinPartyName,
                     sizeof(m_pClientList[iClientH]->m_cReqJoinPartyName));
          m_pClientList[iClientH]->m_iPartyStatus = DEF_PARTYSTATUS_NULL;
        } else {
          // 掳隆脌脭 陆脗脌脦 驴漏潞脦赂娄 鹿炉麓脗麓脵.
          m_pClientList[i]->m_iReqJoinPartyClientH = iClientH;
          ZeroMemory(m_pClientList[i]->m_cReqJoinPartyName,
                     sizeof(m_pClientList[i]->m_cReqJoinPartyName));
          strcpy(m_pClientList[i]->m_cReqJoinPartyName,
                 m_pClientList[iClientH]->m_cCharName);
          SendNotifyMsg(0, i, DEF_NOTIFY_QUERY_JOINPARTY, 0, 0, 0,
                        m_pClientList[iClientH]->m_cCharName);

          // 陆脜脙禄脟脩 脙酶驴隆麓脗 脝脛脝录 赂露陆潞脜脥掳隆 碌脡
          // 脛鲁赂炉脜脥脌脟 脌脦碌娄陆潞赂娄 鲁脰戮卯脕脺. 脙毛录脪脟脪露搂
          // 脙鲁赂庐脟脧卤芒 脌搂脟脭脌脫.
          m_pClientList[iClientH]->m_iReqJoinPartyClientH = i;
          ZeroMemory(m_pClientList[iClientH]->m_cReqJoinPartyName,
                     sizeof(m_pClientList[iClientH]->m_cReqJoinPartyName));
          strcpy(m_pClientList[iClientH]->m_cReqJoinPartyName,
                 m_pClientList[i]->m_cCharName);
          // 脝脛脝录 禄贸脜脗 录录脝庐
          m_pClientList[iClientH]->m_iPartyStatus = DEF_PARTYSTATUS_PROCESSING;
        }
        return;
      }
    break;

  case 2: // 脝脛脝录 赂芒鹿枚 脠庐脌脦 赂铆路脡
    if (m_pClientList[iClientH]->m_iPartyStatus == DEF_PARTYSTATUS_CONFIRM) {
      ZeroMemory(cData, sizeof(cData));
      cp = (char *)cData;
      dwp = (DWORD *)cp;
      *dwp = MSGID_PARTYOPERATION;
      cp += 4;
      wp = (WORD *)cp;
      *wp = 6; // 脝脛脝录 赂芒鹿枚 赂庐陆潞脝庐 驴盲脙禄
      cp += 2;
      wp = (WORD *)cp;
      *wp = iClientH;
      cp += 2;
      memcpy(cp, m_pClientList[iClientH]->m_cCharName, 10);
      cp += 10;
      wp = (WORD *)cp;
      *wp = m_pClientList[iClientH]->m_iPartyID;
      cp += 2;
      SendMsgToGateServer(MSGID_PARTYOPERATION, iClientH, cData);
    }
    break;
  }
}

bool CGame::bCheckEnergySphereDestination(int iNpcH, short sAttackerH,
                                          char cAttackerType) {
  int i, sX, sY, dX, dY, iGoalMapIndex;
  char cResult;

  if (m_pNpcList[iNpcH] == 0)
    return false;
  if (m_pMapList[m_pNpcList[iNpcH]->m_cMapIndex]
          ->m_iCurEnergySphereGoalPointIndex == -1)
    return false;

  if (m_pNpcList[iNpcH]->m_cMapIndex != m_iMiddlelandMapIndex) {
    // 禄莽脜玫脌氓脌脟 驴隆鲁脢脕枚 陆潞脟脟戮卯
    iGoalMapIndex = m_pNpcList[iNpcH]->m_cMapIndex;

    sX = m_pNpcList[iNpcH]->m_sX;
    sY = m_pNpcList[iNpcH]->m_sY;

    cResult =
        m_pMapList[iGoalMapIndex]
            ->m_stEnergySphereGoalList[m_pMapList[iGoalMapIndex]
                                           ->m_iCurEnergySphereGoalPointIndex]
            .cResult;
    dX = m_pMapList[iGoalMapIndex]
             ->m_stEnergySphereGoalList[m_pMapList[iGoalMapIndex]
                                            ->m_iCurEnergySphereGoalPointIndex]
             .aresdenX;
    dY = m_pMapList[iGoalMapIndex]
             ->m_stEnergySphereGoalList[m_pMapList[iGoalMapIndex]
                                            ->m_iCurEnergySphereGoalPointIndex]
             .aresdenY;
    if ((sX >= dX - 2) && (sX <= dX + 2) && (sY >= dY - 2) && (sY <= dY + 2)) {
      // 戮脝路鹿陆潞碌搂 赂帽脟楼脕枚脕隆驴隆 碌碌脗酶脟脽麓脵.
      // 脟枚脌莽 驴隆鲁脢脕枚 陆潞脟脟戮卯 掳帽 脌脦碌娄陆潞 脌煤脌氓
      m_pMapList[iGoalMapIndex]->m_iCurEnergySphereGoalPointIndex = -1;

      if ((cAttackerType == DEF_OWNERTYPE_PLAYER) &&
          (m_pClientList[sAttackerH] != 0)) {
        if (m_pClientList[sAttackerH]->m_cSide == 1) { // Aresden (Side:1)
          // 脌脷陆脜脌脟 卤鹿掳隆 脝梅脜禄驴隆 掳帽脌禄 鲁脰脌潞 掳忙驴矛
          // 掳酶脟氓碌碌 +5
          m_pClientList[sAttackerH]->m_iContribution += 5;
          // 路脦卤脳 脌脹录潞
          wsprintf(G_cTxt, "(!) EnergySphere Hit By Aresden Player (%s)",
                   m_pClientList[sAttackerH]->m_cCharName);
          PutLogFileList(G_cTxt);
        } else {
          // 麓脵赂楼 卤鹿掳隆驴隆 掳帽脌禄 鲁脰戮煤脌禄 掳忙驴矛
          // 掳酶脟氓碌碌掳隆 10 露鲁戮卯脕酶麓脵.
          m_pClientList[sAttackerH]->m_iContribution -= 10;
        }

        // 驴隆鲁脢脕枚 陆潞脟脟戮卯掳隆 掳帽脌脦 碌脝脌陆脌禄 赂冒碌莽
        // 脜卢露贸脌脤戮冒脝庐驴隆掳脭 戮脣路脕脕脴麓脵.
        for (i = 1; i < DEF_MAXCLIENTS; i++)
          if ((m_pClientList[i] != 0) &&
              (m_pClientList[i]->m_bIsInitComplete)) {
            // 脜卢露贸脌脤戮冒脝庐驴脥脌脟 赂脼陆脙脕枚 脗酶驴脌路脦
            SendNotifyMsg(0, i, DEF_NOTIFY_ENERGYSPHEREGOALIN, cResult,
                          m_pClientList[sAttackerH]->m_cSide, 2,
                          m_pClientList[sAttackerH]->m_cCharName);
          }
      }
      return true;
    }

    dX = m_pMapList[iGoalMapIndex]
             ->m_stEnergySphereGoalList[m_pMapList[iGoalMapIndex]
                                            ->m_iCurEnergySphereGoalPointIndex]
             .elvineX;
    dY = m_pMapList[iGoalMapIndex]
             ->m_stEnergySphereGoalList[m_pMapList[iGoalMapIndex]
                                            ->m_iCurEnergySphereGoalPointIndex]
             .elvineY;
    if ((sX >= dX - 2) && (sX <= dX + 2) && (sY >= dY - 2) && (sY <= dY + 2)) {
      // 驴陇鹿脵脌脦 赂帽脟楼脕枚脕隆驴隆 碌碌脗酶脟脽麓脵.
      // 脟枚脌莽 驴隆鲁脢脕枚 陆潞脟脟戮卯 掳帽 脌脦碌娄陆潞 脌煤脌氓
      m_pMapList[iGoalMapIndex]->m_iCurEnergySphereGoalPointIndex = -1;

      if ((cAttackerType == DEF_OWNERTYPE_PLAYER) &&
          (m_pClientList[sAttackerH] != 0)) {
        if (m_pClientList[sAttackerH]->m_cSide == 2) { // Elvine (Side:2)
          // 脌脷陆脜脌脟 卤鹿掳隆 脝梅脜禄驴隆 掳帽脌禄 鲁脰脌潞 掳忙驴矛
          // 掳酶脟氓碌碌 +5
          m_pClientList[sAttackerH]->m_iContribution += 5;
          // 路脦卤脳 脌脹录潞
          wsprintf(G_cTxt, "(!) EnergySphere Hit By Elvine Player (%s)",
                   m_pClientList[sAttackerH]->m_cCharName);
          PutLogFileList(G_cTxt);
        } else {
          // 麓脵赂楼 卤鹿掳隆驴隆 掳帽脌禄 鲁脰戮煤脌禄 掳忙驴矛
          // 掳酶脟氓碌碌掳隆 10 露鲁戮卯脕酶麓脵.
          m_pClientList[sAttackerH]->m_iContribution -= 10;
        }

        // 驴隆鲁脢脕枚 陆潞脟脟戮卯掳隆 掳帽脌脦 碌脝脌陆脌禄 赂冒碌莽
        // 脜卢露贸脌脤戮冒脝庐驴隆掳脭 戮脣路脕脕脴麓脵.
        for (i = 1; i < DEF_MAXCLIENTS; i++)
          if ((m_pClientList[i] != 0) &&
              (m_pClientList[i]->m_bIsInitComplete)) {
            //
            SendNotifyMsg(0, i, DEF_NOTIFY_ENERGYSPHEREGOALIN, cResult,
                          m_pClientList[sAttackerH]->m_cSide, 1,
                          m_pClientList[sAttackerH]->m_cCharName);
          }
      }
    }
    return false;
  } else {
    // 鹿脤碌茅路拢碌氓 驴隆鲁脢脕枚 陆潞脟脟戮卯.

    // 驴隆鲁脢脕枚 陆潞脟脟戮卯脌脟 脟枚脌莽 脌搂脛隆掳隆 掳帽掳煤 掳脜脌脟
    // 脌炉禄莽脟脧赂茅
    sX = m_pNpcList[iNpcH]->m_sX;
    sY = m_pNpcList[iNpcH]->m_sY;

    cResult =
        m_pMapList[m_iMiddlelandMapIndex]
            ->m_stEnergySphereGoalList[m_pMapList[m_iMiddlelandMapIndex]
                                           ->m_iCurEnergySphereGoalPointIndex]
            .cResult;
    dX = m_pMapList[m_iMiddlelandMapIndex]
             ->m_stEnergySphereGoalList[m_pMapList[m_iMiddlelandMapIndex]
                                            ->m_iCurEnergySphereGoalPointIndex]
             .aresdenX;
    dY = m_pMapList[m_iMiddlelandMapIndex]
             ->m_stEnergySphereGoalList[m_pMapList[m_iMiddlelandMapIndex]
                                            ->m_iCurEnergySphereGoalPointIndex]
             .aresdenY;
    if ((sX >= dX - 4) && (sX <= dX + 4) && (sY >= dY - 4) && (sY <= dY + 4)) {
      // 戮脝路鹿陆潞碌搂 赂帽脟楼脕枚脕隆驴隆 碌碌脗酶脟脽麓脵.
      // 脟枚脌莽 驴隆鲁脢脕枚 陆潞脟脟戮卯 掳帽 脌脦碌娄陆潞 脌煤脌氓
      m_pMapList[m_iMiddlelandMapIndex]->m_iCurEnergySphereGoalPointIndex = -1;

      if ((cAttackerType == DEF_OWNERTYPE_PLAYER) &&
          (m_pClientList[sAttackerH] != 0)) {
        if (m_pClientList[sAttackerH]->m_cSide == 1) { // Aresden (Side:1)
          // 脌脷陆脜脌脟 卤鹿掳隆 脝梅脜禄驴隆 掳帽脌禄 鲁脰脌潞 掳忙驴矛
          // 掳酶脟氓碌碌 +5
          m_pClientList[sAttackerH]->m_iContribution += 5;
          // 路脦卤脳 脌脹录潞
          wsprintf(G_cTxt, "(!) EnergySphere Hit By Aresden Player (%s)",
                   m_pClientList[sAttackerH]->m_cCharName);
          PutLogFileList(G_cTxt);
        } else {
          // 麓脵赂楼 卤鹿掳隆驴隆 掳帽脌禄 鲁脰戮煤脌禄 掳忙驴矛
          // 掳酶脟氓碌碌掳隆 10 露鲁戮卯脕酶麓脵.
          m_pClientList[sAttackerH]->m_iContribution -= 10;
        }

        // 驴隆鲁脢脕枚 陆潞脟脟戮卯掳隆 掳帽脌脦 碌脝脌陆脌禄 赂冒碌莽
        // 脜卢露贸脌脤戮冒脝庐驴隆掳脭 戮脣路脕脕脴麓脵.
        for (i = 1; i < DEF_MAXCLIENTS; i++)
          if ((m_pClientList[i] != 0) &&
              (m_pClientList[i]->m_bIsInitComplete)) {
            // 脜卢露贸脌脤戮冒脝庐驴脥脌脟 赂脼陆脙脕枚 脗酶驴脌路脦
            SendNotifyMsg(0, i, DEF_NOTIFY_ENERGYSPHEREGOALIN, cResult,
                          m_pClientList[sAttackerH]->m_cSide, 2,
                          m_pClientList[sAttackerH]->m_cCharName);
          }
      }
      return true;
    }

    dX = m_pMapList[m_iMiddlelandMapIndex]
             ->m_stEnergySphereGoalList[m_pMapList[m_iMiddlelandMapIndex]
                                            ->m_iCurEnergySphereGoalPointIndex]
             .elvineX;
    dY = m_pMapList[m_iMiddlelandMapIndex]
             ->m_stEnergySphereGoalList[m_pMapList[m_iMiddlelandMapIndex]
                                            ->m_iCurEnergySphereGoalPointIndex]
             .elvineY;
    if ((sX >= dX - 4) && (sX <= dX + 4) && (sY >= dY - 4) && (sY <= dY + 4)) {
      // 驴陇鹿脵脌脦 赂帽脟楼脕枚脕隆驴隆 碌碌脗酶脟脽麓脵.
      // 脟枚脌莽 驴隆鲁脢脕枚 陆潞脟脟戮卯 掳帽 脌脦碌娄陆潞 脌煤脌氓
      m_pMapList[m_iMiddlelandMapIndex]->m_iCurEnergySphereGoalPointIndex = -1;

      if ((cAttackerType == DEF_OWNERTYPE_PLAYER) &&
          (m_pClientList[sAttackerH] != 0)) {
        if (m_pClientList[sAttackerH]->m_cSide == 2) { // Elvine (Side:2)
          // 脌脷陆脜脌脟 卤鹿掳隆 脝梅脜禄驴隆 掳帽脌禄 鲁脰脌潞 掳忙驴矛
          // 掳酶脟氓碌碌 +5
          m_pClientList[sAttackerH]->m_iContribution += 5;
          // 路脦卤脳 脌脹录潞
          wsprintf(G_cTxt, "(!) EnergySphere Hit By Aresden Player (%s)",
                   m_pClientList[sAttackerH]->m_cCharName);
          PutLogFileList(G_cTxt);
        } else {
          // 麓脵赂楼 卤鹿掳隆驴隆 掳帽脌禄 鲁脰戮煤脌禄 掳忙驴矛
          // 掳酶脟氓碌碌掳隆 10 露鲁戮卯脕酶麓脵.
          m_pClientList[sAttackerH]->m_iContribution -= 10;
        }

        // 驴隆鲁脢脕枚 陆潞脟脟戮卯掳隆 掳帽脌脦 碌脝脌陆脌禄 赂冒碌莽
        // 脜卢露贸脌脤戮冒脝庐驴隆掳脭 戮脣路脕脕脴麓脵.
        for (i = 1; i < DEF_MAXCLIENTS; i++)
          if ((m_pClientList[i] != 0) &&
              (m_pClientList[i]->m_bIsInitComplete)) {
            //
            SendNotifyMsg(0, i, DEF_NOTIFY_ENERGYSPHEREGOALIN, cResult,
                          m_pClientList[sAttackerH]->m_cSide, 1,
                          m_pClientList[sAttackerH]->m_cCharName);
          }
      }
      return true;
    }
    return false;
  }
}

void CGame::EnergySphereProcessor(bool bIsAdminCreate, int iClientH) {
  int i, iNamingValue, iCIndex, iTemp, pX, pY;
  char cSA, cName_Internal[31], cWaypoint[31];

  if (bIsAdminCreate != true) {

    if (m_iMiddlelandMapIndex < 0)
      return;
    if (m_pMapList[m_iMiddlelandMapIndex] == 0)
      return;
    // 驴隆鲁脢脕枚 陆潞脟脟戮卯掳隆 赂赂碌茅戮卯脕煤 脠庐路眉脌潞 3脙脢赂露麓脵
    // 2000潞脨脌脟 1
    if (iDice(1, 2000) != 123)
      return;
    // 驴隆鲁脢脕枚 陆潞脟脟戮卯麓脗 脙脩 禄莽驴毛脌脷 500赂铆
    // 脌脤禄贸脌脧露搂赂赂 赂赂碌茅戮卯 脕酶麓脵.
    if (m_iTotalGameServerClients < 500)
      return;

    // 赂赂戮脿 脌脤鹿脤 驴隆鲁脢脕枚 陆潞脟脟戮卯脌脟 掳帽脌脤 脟脪麓莽碌脟戮卯
    // 脌脰脌赂赂茅 赂赂碌茅赂茅 戮脠碌脠麓脵.
    if (m_pMapList[m_iMiddlelandMapIndex]->m_iCurEnergySphereGoalPointIndex >=
        0)
      return;

    // 驴隆鲁脢脕枚 陆潞脟脟戮卯赂娄 赂赂碌茅 脌搂脛隆赂娄 掳谩脕陇
    iCIndex = iDice(
        1,
        m_pMapList[m_iMiddlelandMapIndex]->m_iTotalEnergySphereCreationPoint);

    // 驴隆鲁脢脕枚 陆潞脟脟戮卯 陆脙脌脹 脌搂脛隆掳隆 脙脢卤芒脠颅掳隆 戮脠碌脠
    // 禄贸脜脗露贸赂茅
    if (m_pMapList[m_iMiddlelandMapIndex]
            ->m_stEnergySphereCreationList[iCIndex]
            .cType == 0)
      return;

    // 驴漏卤芒录颅 驴隆鲁脢脕枚 陆潞脟脟戮卯 禄媒录潞
    cSA = 0;
    pX = m_pMapList[m_iMiddlelandMapIndex]
             ->m_stEnergySphereCreationList[iCIndex]
             .sX;
    pY = m_pMapList[m_iMiddlelandMapIndex]
             ->m_stEnergySphereCreationList[iCIndex]
             .sY;
    ZeroMemory(cWaypoint, sizeof(cWaypoint));

    iNamingValue = m_pMapList[m_iMiddlelandMapIndex]->iGetEmptyNamingValue();
    if (iNamingValue != -1) {
      //
      ZeroMemory(cName_Internal, sizeof(cName_Internal));
      wsprintf(cName_Internal, "XX%d", iNamingValue);
      cName_Internal[0] = '_';
      cName_Internal[1] = m_iMiddlelandMapIndex + 65;

      if ((bCreateNewNpc("Energy-Sphere", cName_Internal,
                         m_pMapList[m_iMiddlelandMapIndex]->m_cName,
                         (rand() % 5), cSA, DEF_MOVETYPE_RANDOM, &pX, &pY,
                         cWaypoint, 0, 0, -1, false, false, false)) == false) {
        m_pMapList[m_iMiddlelandMapIndex]->SetNamingValueEmpty(iNamingValue);
        return;
      }
    }

    // 驴隆鲁脢脕枚 陆潞脟脟戮卯 掳帽 禄媒录潞
    iTemp = iDice(
        1, m_pMapList[m_iMiddlelandMapIndex]->m_iTotalEnergySphereGoalPoint);
    if (m_pMapList[m_iMiddlelandMapIndex]
            ->m_stEnergySphereGoalList[iTemp]
            .cResult == 0)
      return;

    // 脟枚脌莽 驴隆鲁脢脕枚 陆潞脟脟戮卯 掳帽 脌脦碌娄陆潞 脌煤脌氓
    m_pMapList[m_iMiddlelandMapIndex]->m_iCurEnergySphereGoalPointIndex = iTemp;

    // 驴隆鲁脢脕枚 陆潞脟脟戮卯掳隆 赂赂碌茅戮卯 脕鲁脌陆脌禄 赂冒碌莽
    // 脜卢露贸脌脤戮冒脝庐驴隆掳脭 戮脣路脕脕脴麓脵.
    for (i = 1; i < DEF_MAXCLIENTS; i++)
      if ((m_pClientList[i] != 0) && (m_pClientList[i]->m_bIsInitComplete)) {
        SendNotifyMsg(0, i, DEF_NOTIFY_ENERGYSPHERECREATED, pX, pY, 0, 0);
      }

    // testcode
    wsprintf(G_cTxt, "(!) Energy Sphere Created! (%d, %d)", pX, pY);
    PutLogList(G_cTxt);
    PutLogFileList(G_cTxt);
  } else {
    // 赂赂戮脿 脌脤鹿脤 驴隆鲁脢脕枚 陆潞脟脟戮卯脌脟 掳帽脌脤 脟脪麓莽碌脟戮卯
    // 脌脰脌赂赂茅 赂赂碌茅赂茅 戮脠碌脠麓脵.
    if (m_pMapList[m_pClientList[iClientH]->m_cMapIndex]
            ->m_iCurEnergySphereGoalPointIndex >= 0)
      return;

    // 驴隆鲁脢脕枚 陆潞脟脟戮卯赂娄 赂赂碌茅 脌搂脛隆赂娄 掳谩脕陇
    iCIndex = iDice(1, m_pMapList[m_pClientList[iClientH]->m_cMapIndex]
                           ->m_iTotalEnergySphereCreationPoint);

    // 驴隆鲁脢脕枚 陆潞脟脟戮卯 陆脙脌脹 脌搂脛隆掳隆 脙脢卤芒脠颅掳隆 戮脠碌脠
    // 禄贸脜脗露贸赂茅
    if (m_pMapList[m_pClientList[iClientH]->m_cMapIndex]
            ->m_stEnergySphereCreationList[iCIndex]
            .cType == 0)
      return;

    // 驴漏卤芒录颅 驴隆鲁脢脕枚 陆潞脟脟戮卯 禄媒录潞
    cSA = 0;
    pX = m_pMapList[m_pClientList[iClientH]->m_cMapIndex]
             ->m_stEnergySphereCreationList[iCIndex]
             .sX;
    pY = m_pMapList[m_pClientList[iClientH]->m_cMapIndex]
             ->m_stEnergySphereCreationList[iCIndex]
             .sY;
    ZeroMemory(cWaypoint, sizeof(cWaypoint));

    iNamingValue = m_pMapList[m_pClientList[iClientH]->m_cMapIndex]
                       ->iGetEmptyNamingValue();
    if (iNamingValue != -1) {
      //
      ZeroMemory(cName_Internal, sizeof(cName_Internal));
      wsprintf(cName_Internal, "XX%d", iNamingValue);
      cName_Internal[0] = '_';
      cName_Internal[1] = m_pClientList[iClientH]->m_cMapIndex + 65;

      if ((bCreateNewNpc(
              "Energy-Sphere", cName_Internal,
              m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->m_cName,
              (rand() % 5), cSA, DEF_MOVETYPE_RANDOM, &pX, &pY, cWaypoint, 0, 0,
              -1, false, false, false)) == false) {
        // 陆脟脝脨脟脽脌赂鹿脟路脦 驴鹿戮脿碌脠 NameValue赂娄
        // 脟脴脕娄陆脙脜虏麓脵.
        m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->SetNamingValueEmpty(
            iNamingValue);
        return;
      }
    }

    // 驴隆鲁脢脕枚 陆潞脟脟戮卯 掳帽 禄媒录潞
    iTemp = iDice(1, m_pMapList[m_pClientList[iClientH]->m_cMapIndex]
                         ->m_iTotalEnergySphereGoalPoint);
    if (m_pMapList[m_pClientList[iClientH]->m_cMapIndex]
            ->m_stEnergySphereGoalList[iTemp]
            .cResult == 0)
      return;

    // 脟枚脌莽 驴隆鲁脢脕枚 陆潞脟脟戮卯 掳帽 脌脦碌娄陆潞 脌煤脌氓
    m_pMapList[m_pClientList[iClientH]->m_cMapIndex]
        ->m_iCurEnergySphereGoalPointIndex = iTemp;

    // 驴隆鲁脢脕枚 陆潞脟脟戮卯掳隆 赂赂碌茅戮卯 脕鲁脌陆脌禄 赂冒碌莽
    // 脜卢露贸脌脤戮冒脝庐驴隆掳脭 戮脣路脕脕脴麓脵.
    for (i = 1; i < DEF_MAXCLIENTS; i++)
      if ((m_pClientList[i] != 0) && (m_pClientList[i]->m_bIsInitComplete)) {
        SendNotifyMsg(0, i, DEF_NOTIFY_ENERGYSPHERECREATED, pX, pY, 0, 0);
      }

    // testcode
    wsprintf(G_cTxt, "(!) Admin Energy Sphere Created! (%d, %d)", pX, pY);
    PutLogList(G_cTxt);
    PutLogFileList(G_cTxt);
  }
}

void CGame::ActivateSpecialAbilityHandler(int iClientH) {
  DWORD dwTime = timeGetTime();
  short sTemp;

  if (m_pClientList[iClientH] == 0)
    return;
  if (m_pClientList[iClientH]->m_iSpecialAbilityTime != 0)
    return;
  if (m_pClientList[iClientH]->m_iSpecialAbilityType == 0)
    return;
  if (m_pClientList[iClientH]->m_bIsSpecialAbilityEnabled)
    return;

  m_pClientList[iClientH]->m_bIsSpecialAbilityEnabled = true;
  m_pClientList[iClientH]->m_dwSpecialAbilityStartTime = dwTime;

  m_pClientList[iClientH]->m_iSpecialAbilityTime = DEF_SPECABLTYTIMESEC;

  sTemp = m_pClientList[iClientH]->m_sAppr4;
  sTemp = sTemp & 0xFF0F;
  switch (m_pClientList[iClientH]->m_iSpecialAbilityType) {
  case 1:
  case 2:
  case 3:
  case 4:
  case 5:
    sTemp = sTemp | 0x0010;
    break;
  case 50:
  case 51:
  case 52:
  case 53:
  case 54:
    sTemp = sTemp | 0x0020;
    break;
  }
  m_pClientList[iClientH]->m_sAppr4 = sTemp;

  SendNotifyMsg(0, iClientH, DEF_NOTIFY_SPECIALABILITYSTATUS, 1,
                m_pClientList[iClientH]->m_iSpecialAbilityType,
                m_pClientList[iClientH]->m_iSpecialAbilityLastSec, 0);
  SendEventToNearClient_TypeA(iClientH, DEF_OWNERTYPE_PLAYER,
                              MSGID_EVENT_MOTION, DEF_OBJECTNULLACTION, 0, 0,
                              0);
}

void CGame::CancelQuestHandler(int iClientH) {
  if (m_pClientList[iClientH] == 0)
    return;

  // 脛霉陆潞脝庐 禄贸脜脗赂娄 脜卢赂庐戮卯脟脩麓脵.
  _ClearQuestStatus(iClientH);
  // 脛霉陆潞脝庐掳隆 脙毛录脪碌脟戮煤脌陆脌禄 戮脣路脕脕脴麓脵.
  SendNotifyMsg(0, iClientH, DEF_NOTIFY_QUESTABORTED, 0, 0, 0, 0);
}

int CGame::iGetItemWeight(CItem *pItem, int iCount) {
  int iWeight;

  // 戮脝脌脤脜脹脌脟 录枚路庐驴隆 碌没赂楼 鹿芦掳脭赂娄 掳猫禄锚脟脩麓脵.
  // Gold脌脦 掳忙驴矛 鹿芦掳脭赂娄 20潞脨脌脟 1路脦 潞炉掳忙
  iWeight = (pItem->m_wWeight);
  if (iCount < 0)
    iCount = 1;
  iWeight = iWeight * iCount;
  if (pItem->m_sIDnum == 90)
    iWeight = iWeight / 20;
  if (iWeight <= 0)
    iWeight = 1;

  return iWeight;
}

void CGame::UpdateMapSectorInfo() {
  int i, ix, iy;
  int iMaxNeutralActivity, iMaxAresdenActivity, iMaxElvineActivity,
      iMaxMonsterActivity, iMaxPlayerActivity;

  for (i = 0; i < DEF_MAXMAPS; i++)
    if (m_pMapList[i] != 0) {

      iMaxNeutralActivity = iMaxAresdenActivity = iMaxElvineActivity =
          iMaxMonsterActivity = iMaxPlayerActivity = 0;
      m_pMapList[i]->m_iMaxNx = m_pMapList[i]->m_iMaxNy =
          m_pMapList[i]->m_iMaxAx = m_pMapList[i]->m_iMaxAy = 0;
      m_pMapList[i]->m_iMaxEx = m_pMapList[i]->m_iMaxEy =
          m_pMapList[i]->m_iMaxMx = m_pMapList[i]->m_iMaxMy = 0;
      m_pMapList[i]->m_iMaxPx = m_pMapList[i]->m_iMaxPy = 0;

      // 卤脳碌驴戮脠 脌煤脌氓脟脽麓酶 TempSectorInfo驴隆录颅 脕陇潞赂赂娄
      // 戮貌戮卯 SectorInfo驴隆 脌煤脌氓脟脩 麓脵脌陆 TempSectorInfo麓脗
      // 脕枚驴卯麓脵.
      for (ix = 0; ix < DEF_MAXSECTORS; ix++)
        for (iy = 0; iy < DEF_MAXSECTORS; iy++) {
          if (m_pMapList[i]->m_stTempSectorInfo[ix][iy].iNeutralActivity >
              iMaxNeutralActivity) {
            iMaxNeutralActivity =
                m_pMapList[i]->m_stTempSectorInfo[ix][iy].iNeutralActivity;
            m_pMapList[i]->m_iMaxNx = ix;
            m_pMapList[i]->m_iMaxNy = iy;
          }

          if (m_pMapList[i]->m_stTempSectorInfo[ix][iy].iAresdenActivity >
              iMaxAresdenActivity) {
            iMaxAresdenActivity =
                m_pMapList[i]->m_stTempSectorInfo[ix][iy].iAresdenActivity;
            m_pMapList[i]->m_iMaxAx = ix;
            m_pMapList[i]->m_iMaxAy = iy;
          }

          if (m_pMapList[i]->m_stTempSectorInfo[ix][iy].iElvineActivity >
              iMaxElvineActivity) {
            iMaxElvineActivity =
                m_pMapList[i]->m_stTempSectorInfo[ix][iy].iElvineActivity;
            m_pMapList[i]->m_iMaxEx = ix;
            m_pMapList[i]->m_iMaxEy = iy;
          }

          if (m_pMapList[i]->m_stTempSectorInfo[ix][iy].iMonsterActivity >
              iMaxMonsterActivity) {
            iMaxMonsterActivity =
                m_pMapList[i]->m_stTempSectorInfo[ix][iy].iMonsterActivity;
            m_pMapList[i]->m_iMaxMx = ix;
            m_pMapList[i]->m_iMaxMy = iy;
          }

          if (m_pMapList[i]->m_stTempSectorInfo[ix][iy].iPlayerActivity >
              iMaxPlayerActivity) {
            iMaxPlayerActivity =
                m_pMapList[i]->m_stTempSectorInfo[ix][iy].iPlayerActivity;
            m_pMapList[i]->m_iMaxPx = ix;
            m_pMapList[i]->m_iMaxPy = iy;
          }
        }

      // TempSectorInfo 鲁炉赂掳麓脵.
      m_pMapList[i]->ClearTempSectorInfo();

      // Sector Info驴隆 脌煤脌氓
      if (m_pMapList[i]->m_iMaxNx > 0)
        m_pMapList[i]
            ->m_stSectorInfo[m_pMapList[i]->m_iMaxNx][m_pMapList[i]->m_iMaxNy]
            .iNeutralActivity++;
      if (m_pMapList[i]->m_iMaxAx > 0)
        m_pMapList[i]
            ->m_stSectorInfo[m_pMapList[i]->m_iMaxAx][m_pMapList[i]->m_iMaxAy]
            .iAresdenActivity++;
      if (m_pMapList[i]->m_iMaxEx > 0)
        m_pMapList[i]
            ->m_stSectorInfo[m_pMapList[i]->m_iMaxEx][m_pMapList[i]->m_iMaxEy]
            .iElvineActivity++;
      if (m_pMapList[i]->m_iMaxMx > 0)
        m_pMapList[i]
            ->m_stSectorInfo[m_pMapList[i]->m_iMaxMx][m_pMapList[i]->m_iMaxMy]
            .iMonsterActivity++;
      if (m_pMapList[i]->m_iMaxPx > 0)
        m_pMapList[i]
            ->m_stSectorInfo[m_pMapList[i]->m_iMaxPx][m_pMapList[i]->m_iMaxPy]
            .iPlayerActivity++;
    }
}

void CGame::AgingMapSectorInfo() {
  int i, ix, iy;

  for (i = 0; i < DEF_MAXMAPS; i++)
    if (m_pMapList[i] != 0) {
      for (ix = 0; ix < DEF_MAXSECTORS; ix++)
        for (iy = 0; iy < DEF_MAXSECTORS; iy++) {
          m_pMapList[i]->m_stSectorInfo[ix][iy].iNeutralActivity--;
          m_pMapList[i]->m_stSectorInfo[ix][iy].iAresdenActivity--;
          m_pMapList[i]->m_stSectorInfo[ix][iy].iElvineActivity--;
          m_pMapList[i]->m_stSectorInfo[ix][iy].iMonsterActivity--;
          m_pMapList[i]->m_stSectorInfo[ix][iy].iPlayerActivity--;

          if (m_pMapList[i]->m_stSectorInfo[ix][iy].iNeutralActivity < 0)
            m_pMapList[i]->m_stSectorInfo[ix][iy].iNeutralActivity = 0;
          if (m_pMapList[i]->m_stSectorInfo[ix][iy].iAresdenActivity < 0)
            m_pMapList[i]->m_stSectorInfo[ix][iy].iAresdenActivity = 0;
          if (m_pMapList[i]->m_stSectorInfo[ix][iy].iElvineActivity < 0)
            m_pMapList[i]->m_stSectorInfo[ix][iy].iElvineActivity = 0;
          if (m_pMapList[i]->m_stSectorInfo[ix][iy].iMonsterActivity < 0)
            m_pMapList[i]->m_stSectorInfo[ix][iy].iMonsterActivity = 0;
          if (m_pMapList[i]->m_stSectorInfo[ix][iy].iPlayerActivity < 0)
            m_pMapList[i]->m_stSectorInfo[ix][iy].iPlayerActivity = 0;
        }
    }
}

bool CGame::__bSetConstructionKit(int iMapIndex, int dX, int dY, int iType,
                                  int iTimeCost, int iClientH) {
  int iNamingValue, ix, iy, tX, tY;
  char cNpcName[21], cName[21], cNpcWaypoint[11], cOwnerType;
  short sOwnerH;

  // 脜漏路莽录录脌脤碌氓 赂冒碌氓掳隆 戮脝麓脧掳脜鲁陋 掳脟录鲁脟脩
  // 禄莽露梅脌脤 掳酶潞麓脌脤 戮脝麓脧赂茅 鹿芦陆脙.
  if ((m_bIsCrusadeMode == false) ||
      (m_pClientList[iClientH]->m_iCrusadeDuty != 2))
    return false;
  if (m_pMapList[m_pClientList[iClientH]->m_cMapIndex]
          ->m_iTotalCrusadeStructures >= DEF_MAXCRUSADESTRUCTURES) {
    // 脟脴麓莽 赂脢驴隆 脜漏路莽录录脌脤碌氓 掳脟鹿掳 掳鲁录枚 脕娄脟脩驴隆
    // 掳脡赂庐脕枚 戮脢麓脗麓脵赂茅
    SendNotifyMsg(0, iClientH, DEF_NOTIFY_NOMORECRUSADESTRUCTURE, 0, 0, 0, 0);
    return false;
  }

  // 脟脴麓莽 脌搂脛隆驴隆 掳脟脙脿鹿掳 NPC赂娄 禄媒录潞.
  iNamingValue =
      m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->iGetEmptyNamingValue();
  if (iNamingValue == -1) {
    // 麓玫脌脤禄贸 脌脤 赂脢驴隆 NPC赂娄 赂赂碌茅录枚 戮酶麓脵. 脌脤赂搂脌禄
    // 脟脪麓莽脟脪 录枚 戮酶卤芒 露搂鹿庐.
  } else {

    // 赂脮脌煤 录鲁脛隆脟脧掳铆脌脷 脟脧麓脗 卤脵脙鲁驴隆 卤赂脕露鹿掳脌脤
    // 戮酶鲁陋 脠庐脌脦脟脩麓脵.
    for (ix = dX - 3; ix <= dX + 5; ix++)
      for (iy = dY - 3; iy <= dX + 5; iy++) {
        m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->GetOwner(
            &sOwnerH, &cOwnerType, ix, iy);
        if ((sOwnerH != 0) && (cOwnerType == DEF_OWNERTYPE_NPC) &&
            (m_pNpcList[sOwnerH]->m_cActionLimit == 5))
          return false;
      }

    // NPC赂娄 禄媒录潞脟脩麓脵.
    ZeroMemory(cNpcName, sizeof(cNpcName));
    if (m_pClientList[iClientH]->m_cSide == 1) {
      switch (iType) {
      case 1:
        strcpy(cNpcName, "AGT-Aresden");
        break;
      case 2:
        strcpy(cNpcName, "CGT-Aresen");
        break;
      case 3:
        strcpy(cNpcName, "MS-Aresden");
        break;
      case 4:
        strcpy(cNpcName, "DT-Aresden");
        break;
      }
    } else if (m_pClientList[iClientH]->m_cSide == 2) {
      switch (iType) {
      case 1:
        strcpy(cNpcName, "AGT-Elvine");
        break;
      case 2:
        strcpy(cNpcName, "CGT-Elvine");
        break;
      case 3:
        strcpy(cNpcName, "MS-Elvine");
        break;
      case 4:
        strcpy(cNpcName, "DT-Elvine");
        break;
      }
    } else
      return false;

    ZeroMemory(cName, sizeof(cName));
    wsprintf(cName, "XX%d", iNamingValue);
    cName[0] = '_';
    cName[1] = m_pClientList[iClientH]->m_cMapIndex + 65;

    ZeroMemory(cNpcWaypoint, sizeof(cNpcWaypoint));

    tX = (int)dX;
    tY = (int)dY;
    if (bCreateNewNpc(cNpcName, cName,
                      m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->m_cName,
                      0, (rand() % 9), DEF_MOVETYPE_RANDOM, &tX, &tY,
                      cNpcWaypoint, 0, 0, -1, false, false) == false) {
      // 陆脟脝脨脟脽脌赂鹿脟路脦 驴鹿戮脿碌脠 NameValue赂娄
      // 脟脴脕娄陆脙脜虏麓脵.
      m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->SetNamingValueEmpty(
          iNamingValue);
    } else {
      // 录潞掳酶
      wsprintf(G_cTxt, "Structure(%s) construction begin(%d,%d)!", cNpcName, tX,
               tY);
      PutLogList(G_cTxt);
      return true;
    }
  }

  return false;
}

void CGame::LocalStartCrusadeMode(DWORD dwCrusadeGUID) {
  int i;

  if (m_bIsCrusadeMode)
    return;
  m_bIsCrusadeMode = true;
  m_iCrusadeWinnerSide = 0;

  if (dwCrusadeGUID != 0) {
    // 脜漏路莽录录脌脤碌氓 GUID 脝脛脌脧脌禄 赂赂碌莽麓脵.
    _CreateCrusadeGUID(dwCrusadeGUID, 0);
    m_dwCrusadeGUID = dwCrusadeGUID;
  }

  for (i = 1; i < DEF_MAXCLIENTS; i++)
    if ((m_pClientList[i] != 0) && (m_pClientList[i]->m_bIsInitComplete)) {
      // 赂冒碌莽 脜卢露贸脌脤戮冒脝庐驴隆掳脭 脌眉赂茅脌眉 赂冒碌氓掳隆
      // 陆脙脌脹碌脟戮煤脌陆脌禄 戮脣路脕脕脴麓脵. 赂脙脌潞 脌脫鹿芦
      // 脜卢赂庐戮卯 脠脛 脜毛潞赂脟脭.
      m_pClientList[i]->m_iCrusadeDuty = 0;
      m_pClientList[i]->m_iConstructionPoint = 0;
      m_pClientList[i]->m_dwCrusadeGUID = m_dwCrusadeGUID;
      SendNotifyMsg(0, i, DEF_NOTIFY_CRUSADE, (DWORD)m_bIsCrusadeMode,
                    m_pClientList[i]->m_iCrusadeDuty, 0, 0);
    }

  // 陆潞脝庐露贸脌脤脜漏 脝梅脌脦脝庐 HP 脙脢卤芒脠颅.
  for (i = 0; i < DEF_MAXMAPS; i++)
    if (m_pMapList[i] != 0)
      m_pMapList[i]->RestoreStrikePoints();

  // 掳垄掳垄脌脟 赂脢驴隆 脙脢卤芒 掳脟鹿掳 录鲁脛隆. (赂露鲁陋 陆潞脜忙,
  // 驴隆鲁脢脕枚 陆脟碌氓 脕娄鲁脳路鹿脌脤脜脥, 卤脳路鹿脌脤脝庐 赂脜脕梅
  // 脕娄鲁脳路鹿脌脤脜脥, 掳隆碌氓脜赂驴枚碌卯碌卯)
  CreateCrusadeStructures();

  PutLogList("(!)Crusade Mode ON.");
  _bCrusadeLog(DEF_CRUSADELOG_STARTCRUSADE, 0, 0, 0);
}

void CGame::LocalEndCrusadeMode(int iWinnerSide) {
  int i;

  // testcode
  wsprintf(G_cTxt, "LocalEndCrusadeMode(%d)", iWinnerSide);
  PutLogList(G_cTxt);

  if (m_bIsCrusadeMode == false)
    return;
  m_bIsCrusadeMode = false;

  PutLogList("(!)Crusade Mode OFF.");

  // 录鲁脛隆碌脟戮煤麓酶 脜漏路莽录录脌脤碌氓 掳脟脙脿鹿掳 脕娄掳脜.
  RemoveCrusadeStructures();

  RemoveCrusadeNpcs();

  // 脌脤卤盲脗脢 禄莽脌脤碌氓赂娄 脌脭路脗.
  _CreateCrusadeGUID(m_dwCrusadeGUID, iWinnerSide);
  m_iCrusadeWinnerSide = iWinnerSide;
  m_iLastCrusadeWinner = iWinnerSide;

  for (i = 1; i < DEF_MAXCLIENTS; i++)
    if ((m_pClientList[i] != 0) && (m_pClientList[i]->m_bIsInitComplete)) {
      // 赂冒碌莽 脜卢露贸脌脤戮冒脝庐驴隆掳脭 脌眉赂茅脌眉 赂冒碌氓掳隆
      // 鲁隆鲁碌脌陆脌禄 戮脣路脕脕脴麓脵. 赂脙脌潞 脌脫鹿芦 脜卢赂庐戮卯 脠脛
      // 脜毛潞赂脟脭.
      m_pClientList[i]->m_iCrusadeDuty = 0;
      m_pClientList[i]->m_iConstructionPoint = 0;
      SendNotifyMsg(0, i, DEF_NOTIFY_CRUSADE, (DWORD)m_bIsCrusadeMode, 0, 0, 0,
                    m_iCrusadeWinnerSide);
    }
  RemoveCrusadeRecallTime();

  if (iWinnerSide == 2) {
    _bCrusadeLog(DEF_CRUSADELOG_ENDCRUSADE, false, false, "Elvine Win!");
  } else if (iWinnerSide == 1) {
    _bCrusadeLog(DEF_CRUSADELOG_ENDCRUSADE, false, false, "Aresden Win!");
  } else {
    _bCrusadeLog(DEF_CRUSADELOG_ENDCRUSADE, false, false, "Drawn!");
  }

  if (m_iMiddlelandMapIndex != -1) {
    // bSendMsgToLS(0x3D00123C, 0, true, 0);
  }
}

void CGame::SaveOccupyFlagData() {
  char *pData;
  int iSize;
  FILE *pFile;

  PutLogList("(!) Middleland OccupyFlag data saved.");

  pData = new char[1000000 + 1];
  if (pData == 0)
    return;
  ZeroMemory(pData, 1000000);

  iSize = _iComposeFlagStatusContents(pData);

  _mkdir("GameData");

  pFile = fopen("GameData\\OccupyFlag.txt", "wt");
  if (pFile == 0)
    return;

  fwrite(pData, 1, iSize, pFile);

  delete pData;
  fclose(pFile);
}

void CGame::CreateCrusadeStructures() {
  int i, z, tX, tY, iNamingValue;
  char cName[6], cNpcName[21], cNpcWayPoint[11];

  ZeroMemory(cName, sizeof(cName));
  ZeroMemory(cNpcName, sizeof(cNpcName));
  ZeroMemory(cNpcWayPoint, sizeof(cNpcWayPoint));

  for (i = 0; i < DEF_MAXCRUSADESTRUCTURES; i++)
    if (m_stCrusadeStructures[i].cType != 0) {
      for (z = 0; z < DEF_MAXMAPS; z++)
        if ((m_pMapList[z] != 0) &&
            (strcmp(m_pMapList[z]->m_cName,
                    m_stCrusadeStructures[i].cMapName) == 0)) {
          // 脌搂脛隆掳隆 脌脧脛隆脟脧麓脗 赂脢驴隆 掳脟脙脿鹿掳脌禄
          // 脌搂脛隆陆脙脜虏麓脵.
          iNamingValue = m_pMapList[z]->iGetEmptyNamingValue();
          if (iNamingValue == -1) {
            // 麓玫脌脤禄贸 脌脤 赂脢驴隆 NPC赂娄 赂赂碌茅录枚 戮酶麓脵.
            // 脌脤赂搂脌禄 脟脪麓莽脟脪 录枚 戮酶卤芒 露搂鹿庐. 脌脤路卤
            // 脌脧脌脤?
          } else {
            // NPC赂娄 禄媒录潞脟脩麓脵.
            wsprintf(cName, "XX%d", iNamingValue);
            cName[0] = '_';
            cName[1] = z + 65;

            switch (m_stCrusadeStructures[i].cType) {
            case 36:
              if (strcmp(m_pMapList[z]->m_cName, "aresden") == 0)
                strcpy(cNpcName, "AGT-Aresden");
              else if (strcmp(m_pMapList[z]->m_cName, "elvine") == 0)
                strcpy(cNpcName, "AGT-Elvine");
              break;

            case 37:
              if (strcmp(m_pMapList[z]->m_cName, "aresden") == 0)
                strcpy(cNpcName, "CGT-Aresden");
              else if (strcmp(m_pMapList[z]->m_cName, "elvine") == 0)
                strcpy(cNpcName, "CGT-Elvine");
              break;

            case 40:
              if (strcmp(m_pMapList[z]->m_cName, "aresden") == 0)
                strcpy(cNpcName, "ESG-Aresden");
              else if (strcmp(m_pMapList[z]->m_cName, "elvine") == 0)
                strcpy(cNpcName, "ESG-Elvine");
              break;

            case 41:
              if (strcmp(m_pMapList[z]->m_cName, "aresden") == 0)
                strcpy(cNpcName, "GMG-Aresden");
              else if (strcmp(m_pMapList[z]->m_cName, "elvine") == 0)
                strcpy(cNpcName, "GMG-Elvine");
              break;

            case 42:
              strcpy(cNpcName, "ManaStone");
              break;

            default:
              strcpy(
                  cNpcName,
                  m_pNpcConfigList[m_stCrusadeStructures[i].cType]->m_cNpcName);
              break;
            }

            tX = (int)m_stCrusadeStructures[i].dX;
            tY = (int)m_stCrusadeStructures[i].dY;
            if (bCreateNewNpc(cNpcName, cName, m_pMapList[z]->m_cName, 0, 0,
                              DEF_MOVETYPE_RANDOM, &tX, &tY, cNpcWayPoint, 0, 0,
                              -1, false) == false) {
              // 陆脟脝脨脟脽脌赂鹿脟路脦 驴鹿戮脿碌脠 NameValue赂娄
              // 脟脴脕娄陆脙脜虏麓脵.
              m_pMapList[z]->SetNamingValueEmpty(iNamingValue);
            } else {
              wsprintf(G_cTxt,
                       "(!) Creating Crusade Structure(%s) at %s(%d, %d)",
                       cNpcName, m_stCrusadeStructures[i].cMapName, tX, tY);
              PutLogList(G_cTxt);
            }
          }
        }
    }
}

void CGame::RequestSetGuildConstructLocHandler(int iClientH, int dX, int dY,
                                               int iGuildGUID, char *pMapName) {
  char *cp, cData[120];
  int i;
  int *ip, iIndex;
  DWORD dwTemp, dwTime;

  if (m_pClientList[iClientH] == 0)
    return;
  if (m_pClientList[iClientH]->m_bIsOnServerChange)
    return;

  // 掳脭脌脤脝庐 录颅鹿枚 赂脼陆脙脕枚 脌脹录潞
  /*ZeroMemory(cData, sizeof(cData));
  cp = (char *)cData;
  *cp = GSM_SETGUILDCONSTRUCTLOC;
  cp++;

  ip = (int *)cp;
  *ip = iGuildGUID;
  cp += 4;

  ip = (int *)cp;
  *ip = dX;
  cp += 4;

  ip = (int *)cp;
  *ip = dY;
  cp += 4;

  memcpy(cp, pMapName, 10);
  cp += 10;*/
  //

  dwTime = timeGetTime();

  // testcode
  wsprintf(G_cTxt, "SetGuildConstructLoc: %d %s %d %d", iGuildGUID, pMapName,
           dX, dY);
  PutLogList(G_cTxt);

  // 赂脮脌煤 掳掳脌潞 GUID赂娄 掳隆脕酶 卤忙碌氓 脛脕陆潞脝庐路掳脝庐
  // 脕脗脟楼掳隆 录鲁脕陇碌脟戮卯 脌脰麓脗脕枚 脙拢麓脗麓脵. 脜脷路鹿脝梅脝庐
  // 脌搂脛隆脌脟 2鹿酶 潞炉录枚碌茅脌禄 禄莽驴毛脟脩麓脵.
  for (i = 0; i < DEF_MAXGUILDS; i++)
    if (m_pGuildTeleportLoc[i].m_iV1 == iGuildGUID) {
      // 脌脤鹿脤 卤忙碌氓掳隆 脌脰麓脵.
      if ((m_pGuildTeleportLoc[i].m_sDestX2 == dX) &&
          (m_pGuildTeleportLoc[i].m_sDestY2 == dY) &&
          (strcmp(m_pGuildTeleportLoc[i].m_cDestMapName2, pMapName) == 0)) {
        // 鲁禄驴毛脌脤 脌脧脛隆脟脩麓脵. 脜赂脌脫 脌脭路脗脠脛 陆潞脜碌.
        m_pGuildTeleportLoc[i].m_dwTime2 = dwTime;
        return;
      } else {
        // 鲁禄驴毛 掳禄陆脜脠脛
        m_pGuildTeleportLoc[i].m_sDestX2 = dX;
        m_pGuildTeleportLoc[i].m_sDestY2 = dY;
        ZeroMemory(m_pGuildTeleportLoc[i].m_cDestMapName2,
                   sizeof(m_pGuildTeleportLoc[i].m_cDestMapName2));
        strcpy(m_pGuildTeleportLoc[i].m_cDestMapName2, pMapName);
        m_pGuildTeleportLoc[i].m_dwTime2 = dwTime;

        // 掳脭脌脤脝庐 录颅鹿枚赂娄 脜毛脟脴 麓脵赂楼 录颅鹿枚路脦 脕陇潞赂
        // 脌眉录脹 bStockMsgToGateServer(cData, 23);
        return;
      }
    }

  // 录鲁脕陇碌脠 鲁禄驴毛脌脤 戮酶麓脵. 禄玫路脦 录鲁脕陇脟脩麓脵.
  dwTemp = 0;
  iIndex = -1;
  for (i = 0; i < DEF_MAXGUILDS; i++) {
    if (m_pGuildTeleportLoc[i].m_iV1 == 0) {

      m_pGuildTeleportLoc[i].m_iV1 = iGuildGUID;
      m_pGuildTeleportLoc[i].m_sDestX2 = dX;
      m_pGuildTeleportLoc[i].m_sDestY2 = dY;
      ZeroMemory(m_pGuildTeleportLoc[i].m_cDestMapName2,
                 sizeof(m_pGuildTeleportLoc[i].m_cDestMapName2));
      strcpy(m_pGuildTeleportLoc[i].m_cDestMapName2, pMapName);
      m_pGuildTeleportLoc[i].m_dwTime2 = dwTime;

      // 掳脭脌脤脝庐 录颅鹿枚赂娄 脜毛脟脴 麓脵赂楼 录颅鹿枚路脦 脕陇潞赂
      // 脌眉录脹 bStockMsgToGateServer(cData, 23);
      return;
    } else {
      // 掳隆脌氓 驴脌路搂碌驴戮脠 脗眉脕露碌脟脕枚 戮脢脌潞 赂庐陆潞脝庐脌脟
      // 脌脦碌娄陆潞赂娄 脙拢麓脗麓脵.
      if (dwTemp < (dwTime - m_pGuildTeleportLoc[i].m_dwTime2)) {
        dwTemp = (dwTime - m_pGuildTeleportLoc[i].m_dwTime2);
        iIndex = i;
      }
    }
  }

  // 脛鲁陆脙 掳酶掳拢脌脤 麓脵 脙隆麓脵. 脌脤路卤 掳忙驴矛 赂庐陆潞脝庐 脕脽
  // 掳隆脌氓 驴脌路搂碌驴戮脠 禄莽驴毛脟脧脕枚 戮脢脌潞
  // 赂庐陆潞脝庐(iIndex)赂娄 禄猫脕娄脟脧掳铆 戮梅碌楼脌脤脝庐 脟脩麓脵.
  if (iIndex == -1)
    return;

  // testcode
  PutLogList("(X) No more GuildConstructLoc Space! Replaced.");

  m_pGuildTeleportLoc[i].m_iV1 = iGuildGUID;
  m_pGuildTeleportLoc[i].m_sDestX2 = dX;
  m_pGuildTeleportLoc[i].m_sDestY2 = dY;
  ZeroMemory(m_pGuildTeleportLoc[i].m_cDestMapName2,
             sizeof(m_pGuildTeleportLoc[i].m_cDestMapName2));
  strcpy(m_pGuildTeleportLoc[i].m_cDestMapName, pMapName);
  m_pGuildTeleportLoc[i].m_dwTime2 = dwTime;

  // 掳脭脌脤脝庐 录颅鹿枚赂娄 脜毛脟脴 麓脵赂楼 录颅鹿枚路脦 脕陇潞赂 脌眉录脹
  // bStockMsgToGateServer(cData, 23);
}

// New 14/05/2004 Changed
void CGame::RequestSummonWarUnitHandler(int iClientH, int dX, int dY,
                                        char cType, char cNum, char cMode) {
  char cName[6], cNpcName[21], cMapName[11], cNpcWayPoint[11], cOwnerType;
  int i, x;
  int iNamingValue, tX, tY, ix, iy;
  bool bRet;
  short sOwnerH;
  DWORD dwTime = timeGetTime();

  if (m_pClientList[iClientH] == 0)
    return;
  if (m_pClientList[iClientH]->m_bIsInitComplete == false)
    return;
  // hbest - crusade units summon mapcheck
  if (((strcmp(
            m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->m_cLocationName,
            "toh3") == 0) ||
       (strcmp(
            m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->m_cLocationName,
            "icebound") == 0)) &&
      (m_pClientList[iClientH]->m_iAdminUserLevel < 1)) {
    return;
  }

  ZeroMemory(cNpcWayPoint, sizeof(cNpcWayPoint));
  ZeroMemory(cNpcName, sizeof(cNpcName));
  ZeroMemory(cMapName, sizeof(cMapName));

  // 驴隆路炉 脙录脜漏驴毛
  if (cType < 0)
    return;
  if (cType >= DEF_MAXNPCTYPES)
    return;
  if (cNum > 10)
    return;

  // 掳脟录鲁脟脧卤芒驴隆 脝梅脌脦脝庐掳隆 赂冒脌脷露玫麓脵.
  if (m_pClientList[iClientH]->m_iConstructionPoint <
      m_iNpcConstructionPoint[cType])
    return;
  // 掳脟鹿掳 鲁禄潞脦赂茅 脌眉脌茂 脌炉麓脧脝庐 录脪脠炉 潞脪掳隆.
  if ((m_pMapList[m_pClientList[iClientH]->m_cMapIndex] != 0) &&
      (m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->m_bIsFixedDayMode))
    return;

  // 脌脧麓脺 驴隆路炉鹿忙脕枚驴毛
  cNum = 1;

  // ConstructionPoint 脕娄脟脩脌禄 掳猫禄锚脟脧掳铆 脌炉麓脧脝庐
  // 掳鲁录枚赂赂脜颅 脕脵脌脦麓脵.
  for (x = 1; x <= cNum; x++) {
    // 掳鲁录枚赂赂脜颅  脌眉脌茂 脌炉麓脧脝庐 禄媒录潞
    iNamingValue = m_pMapList[m_pClientList[iClientH]->m_cMapIndex]
                       ->iGetEmptyNamingValue();
    if (iNamingValue == -1) {
      // 麓玫脌脤禄贸 脌脤 赂脢驴隆 NPC赂娄 赂赂碌茅录枚 戮酶麓脵. 脌脤赂搂脌禄
      // 脟脪麓莽脟脪 录枚 戮酶卤芒 露搂鹿庐. 脌脤路卤 脌脧脌脤?
    } else {
      // NPC赂娄 禄媒录潞脟脩麓脵.
      ZeroMemory(cName, sizeof(cName));
      wsprintf(cName, "XX%d", iNamingValue);
      cName[0] = '_';
      cName[1] = m_pClientList[iClientH]->m_cMapIndex + 65;

      // 碌驴脌脧脟脩 脜赂脌脭脌禄 掳庐脕枚赂赂 麓脵赂楼 禄莽脌脤碌氓赂娄
      // 掳庐麓脗 掳忙驴矛

      switch (cType) {
      case 43: // Light War Beetle
        switch (m_pClientList[iClientH]->m_cSide) {
        case 1:
          strcpy(cNpcName, "LWB-Aresden");
          break;
        case 2:
          strcpy(cNpcName, "LWB-Elvine");
          break;
        }
        break;

      case 36: // Arrow Guard Tower
        switch (m_pClientList[iClientH]->m_cSide) {
        case 1:
          strcpy(cNpcName, "AGT-Aresden");
          break;
        case 2:
          strcpy(cNpcName, "AGT-Elvine");
          break;
        }
        break;

      case 37: // Cannon Guard Tower
        switch (m_pClientList[iClientH]->m_cSide) {
        case 1:
          strcpy(cNpcName, "CGT-Aresden");
          break;
        case 2:
          strcpy(cNpcName, "CGT-Elvine");
          break;
        }
        break;

      case 38: // Mana Collector
        switch (m_pClientList[iClientH]->m_cSide) {
        case 1:
          strcpy(cNpcName, "MS-Aresden");
          break;
        case 2:
          strcpy(cNpcName, "MS-Elvine");
          break;
        }
        break;

      case 39: // Detector
        switch (m_pClientList[iClientH]->m_cSide) {
        case 1:
          strcpy(cNpcName, "DT-Aresden");
          break;
        case 2:
          strcpy(cNpcName, "DT-Elvine");
          break;
        }
        break;

      case 51: // Catapult
        switch (m_pClientList[iClientH]->m_cSide) {
        case 1:
          strcpy(cNpcName, "CP-Aresden");
          break;
        case 2:
          strcpy(cNpcName, "CP-Elvine");
          break;
        }
        break;

      case 44:
        strcpy(cNpcName, "GHK");
        break;

      case 45:
        strcpy(cNpcName, "GHKABS");
        break;

      case 46:
        strcpy(cNpcName, "TK");
        break;

      case 47:
        strcpy(cNpcName, "BG");
        break;

      case 82:
        switch (m_pClientList[iClientH]->m_cSide) {
        case 1:
          strcpy(cNpcName, "Sor-Aresden");
          break;
        case 2:
          strcpy(cNpcName, "Sor-Elvine");
          break;
        }
        break;

      case 83:
        switch (m_pClientList[iClientH]->m_cSide) {
        case 1:
          strcpy(cNpcName, "ATK-Aresden");
          break;
        case 2:
          strcpy(cNpcName, "ATK-Elvine");
          break;
        }
        break;

      case 84:
        switch (m_pClientList[iClientH]->m_cSide) {
        case 1:
          strcpy(cNpcName, "Elf-Aresden");
          break;
        case 2:
          strcpy(cNpcName, "Elf-Elvine");
          break;
        }
        break;

      case 85:
        switch (m_pClientList[iClientH]->m_cSide) {
        case 1:
          strcpy(cNpcName, "DSK-Aresden");
          break;
        case 2:
          strcpy(cNpcName, "DSK-Elvine");
          break;
        }
        break;

      case 86:
        switch (m_pClientList[iClientH]->m_cSide) {
        case 1:
          strcpy(cNpcName, "HBT-Aresden");
          break;
        case 2:
          strcpy(cNpcName, "HBT-Elvine");
          break;
        }
        break;

      case 87:
        switch (m_pClientList[iClientH]->m_cSide) {
        case 1:
          strcpy(cNpcName, "CT-Aresden");
          break;
        case 2:
          strcpy(cNpcName, "CT-Elvine");
          break;
        }
        break;

      case 88:
        switch (m_pClientList[iClientH]->m_cSide) {
        case 1:
          strcpy(cNpcName, "Bar-Aresden");
          break;
        case 2:
          strcpy(cNpcName, "Bar-Elvine");
          break;
        }
        break;

      case 89:
        switch (m_pClientList[iClientH]->m_cSide) {
        case 1:
          strcpy(cNpcName, "AGC-Aresden");
          break;
        case 2:
          strcpy(cNpcName, "AGC-Elvine");
          break;
        }
        break;
      }

      // testcode
      wsprintf(G_cTxt, "(!) Request Summon War Unit (%d) (%s)", cType,
               cNpcName);
      PutLogList(G_cTxt);

      tX = (int)dX;
      tY = (int)dY;

      // 赂赂戮脿 脌眉脌茂 掳脟脙脿鹿掳脌脤露贸赂茅 掳脟脙脿
      // 脌搂脛隆路脦潞脦脜脥 脌脦脕垄脟脴戮脽 脟脩麓脵.
      bRet = false;
      switch (cType) {
      case 36:
      case 37:
      case 38:
      case 39:
        // 掳脟录鲁 脌搂脛隆赂娄 潞帽卤鲁
        if (strcmp(m_pClientList[iClientH]->m_cConstructMapName,
                   m_pClientList[iClientH]->m_cMapName) != 0)
          bRet = true;
        if (abs(m_pClientList[iClientH]->m_sX -
                m_pClientList[iClientH]->m_iConstructLocX) > 10)
          bRet = true;
        if (abs(m_pClientList[iClientH]->m_sY -
                m_pClientList[iClientH]->m_iConstructLocY) > 10)
          bRet = true;

        if (bRet) {
          // 掳脟录鲁 脌搂脛隆驴脥 鲁脢鹿芦 赂脰赂庐 鹿镁戮卯鲁陋 脌脰脌赂赂茅
          // 掳脟脙脿 潞脪掳隆.
          m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->SetNamingValueEmpty(
              iNamingValue);
          SendNotifyMsg(0, iClientH, DEF_NOTIFY_CANNOTCONSTRUCT, 2, 0, 0, 0);
          return;
        }

        // 卤忙碌氓驴隆录颅 掳脟录鲁脟脩 掳脟脙脿鹿掳脌脟 掳鹿录枚赂娄
        // 脛芦驴卯脝庐脟脩麓脵. 脌脧脕陇 掳鹿录枚 脌脤禄贸脌潞 脕枚脌禄 录枚
        // 戮酶麓脵.
        /////
        for (i = 0; i < DEF_MAXGUILDS; i++)
          if (m_pGuildTeleportLoc[i].m_iV1 ==
              m_pClientList[iClientH]->m_iGuildGUID) {
            m_pGuildTeleportLoc[i].m_dwTime = dwTime;
            if (m_pGuildTeleportLoc[i].m_iV2 >= DEF_MAXCONSTRUCTNUM) {
              // 卤忙碌氓 掳脟录鲁 掳鲁录枚 脙脢掳煤. 脕枚脌禄录枚 戮酶麓脵.
              m_pMapList[m_pClientList[iClientH]->m_cMapIndex]
                  ->SetNamingValueEmpty(iNamingValue);
              SendNotifyMsg(0, iClientH, DEF_NOTIFY_CANNOTCONSTRUCT, 3, 0, 0,
                            0);
              return;
            } else {
              // 掳脟录鲁碌脠 掳脟鹿掳 掳鹿录枚 脕玫掳隆.
              m_pGuildTeleportLoc[i].m_iV2++;
              goto RSWU_LOOPBREAK;
            }
          }

        // 卤忙碌氓 录鲁脕陇碌脟戮卯 脌脰脕枚 戮脢脌陆. 脕枚脌禄录枚 戮酶麓脵.
        m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->SetNamingValueEmpty(
            iNamingValue);
        SendNotifyMsg(0, iClientH, DEF_NOTIFY_CANNOTCONSTRUCT, 3, 0, 0, 0);
        return;
        /////
        break;
      case 43:
      case 44:
      case 45:
      case 46:
      case 47:
      case 51:
        break;

      case 40:
      case 41:
      case 42:
      case 48:
      case 49:
      case 50:
        break;
      }

    RSWU_LOOPBREAK:

      // 赂赂戮脿 脌眉脌茂 掳脟脙脿鹿掳脕脽 掳隆碌氓脜赂驴枚掳掳脌脤
      // 掳酶掳脻脟眉脌脤露贸赂茅 鲁脢鹿芦 脌脦脕垄脟脴录颅 掳脟录鲁脟脪 录枚
      // 戮酶麓脵.
      bRet = false;
      switch (cType) {
      case 36:
      case 37:
        for (ix = tX - 2; ix <= tX + 2; ix++)
          for (iy = tY - 2; iy <= tY + 2; iy++) {
            m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->GetOwner(
                &sOwnerH, &cOwnerType, ix, iy);
            if ((sOwnerH != 0) && (cOwnerType == DEF_OWNERTYPE_NPC)) {
              switch (m_pNpcList[sOwnerH]->m_sType) {
              case 36:
              case 37:
                bRet = true;
                break;
              }
            }
          }

        // 脕枚脌禄 录枚 戮酶麓脗 禄贸脌搂脕脗脟楼
        if ((dY <= 32) || (dY >= 783))
          bRet = true;
        break;
      }

      if (bRet) {
        // 卤脵脙鲁驴隆 掳隆碌氓脜赂驴枚碌茅脌脤 脌脰戮卯录颅 掳脟脙脿潞脪掳隆.
        m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->SetNamingValueEmpty(
            iNamingValue);
        SendNotifyMsg(0, iClientH, DEF_NOTIFY_CANNOTCONSTRUCT, 1, 0, 0, 0);
        return;
      }

      // 掳隆碌氓 赂冒碌氓脌脦掳隆 脙脽脕戮 赂冒碌氓脌脦掳隆 录卤脜脙
      if (cMode == 0) {
        bRet = bCreateNewNpc(
            cNpcName, cName,
            m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->m_cName, 0, 0,
            DEF_MOVETYPE_FOLLOW, &tX, &tY, cNpcWayPoint, 0, 0, -1, false, false,
            false, false, m_pClientList[iClientH]->m_iGuildGUID);
        bSetNpcFollowMode(cName, m_pClientList[iClientH]->m_cCharName,
                          DEF_OWNERTYPE_PLAYER);
      } else
        bRet = bCreateNewNpc(
            cNpcName, cName,
            m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->m_cName, 0, 0,
            DEF_MOVETYPE_GUARD, &tX, &tY, cNpcWayPoint, 0, 0, -1, false, false,
            false, false, m_pClientList[iClientH]->m_iGuildGUID);

      if (bRet == false) {
        // 陆脟脝脨脟脽脌赂鹿脟路脦 驴鹿戮脿碌脠 NameValue赂娄
        // 脟脴脕娄陆脙脜虏麓脵.
        m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->SetNamingValueEmpty(
            iNamingValue);
      } else {
        // 掳脟录鲁驴隆 录潞掳酶脟脽脌赂鹿脟路脦 掳脟录鲁 脝梅脌脦脝庐 掳篓录脪
        // 陆脙脜虏麓脵.
        m_pClientList[iClientH]->m_iConstructionPoint -=
            m_iNpcConstructionPoint[cType];
        if (m_pClientList[iClientH]->m_iConstructionPoint < 0)
          m_pClientList[iClientH]->m_iConstructionPoint = 0;
        // 脕枚脠脰掳眉驴隆掳脭 鹿脵路脦 脜毛潞赂.
        SendNotifyMsg(0, iClientH, DEF_NOTIFY_CONSTRUCTIONPOINT,
                      m_pClientList[iClientH]->m_iConstructionPoint,
                      m_pClientList[iClientH]->m_iWarContribution, 0, 0);
      }
    }
  }
}

void CGame::CheckConnectionHandler(int iClientH, char *pData) {
  char *cp;
  DWORD *dwp, dwTimeRcv, dwTime, dwTimeGapClient, dwTimeGapServer;

  if (m_pClientList[iClientH] == 0)
    return;
  // m_pClientList[iClientH]->m_cConnectionCheck = 0;

  dwTime = timeGetTime();
  cp = (char *)(pData + DEF_INDEX2_MSGTYPE + 2);
  dwp = (DWORD *)cp;
  dwTimeRcv = *dwp;

  if (m_pClientList[iClientH]->m_dwInitCCTimeRcv == 0) {
    m_pClientList[iClientH]->m_dwInitCCTimeRcv = dwTimeRcv;
    m_pClientList[iClientH]->m_dwInitCCTime = dwTime;
  } else {
    dwTimeGapClient = (dwTimeRcv - m_pClientList[iClientH]->m_dwInitCCTimeRcv);
    dwTimeGapServer = (dwTime - m_pClientList[iClientH]->m_dwInitCCTime);

    if (dwTimeGapClient < dwTimeGapServer)
      return;
    if ((dwTimeGapClient - dwTimeGapServer) >= (DEF_CLIENTTIMEOUT)) {
      DeleteClient(iClientH, true, true);
      return;
    }
  }
}

void CGame::SelectCrusadeDutyHandler(int iClientH, int iDuty) {

  if (m_pClientList[iClientH] == 0)
    return;
  if ((m_pClientList[iClientH]->m_iGuildRank != 0) && (iDuty == 3))
    return;

  if (m_iLastCrusadeWinner == m_pClientList[iClientH]->m_cSide &&
      m_pClientList[iClientH]->m_dwCrusadeGUID == 0 && iDuty == 3) {
    m_pClientList[iClientH]->m_iConstructionPoint = 3000;
  }
  m_pClientList[iClientH]->m_iCrusadeDuty = iDuty;

  SendNotifyMsg(0, iClientH, DEF_NOTIFY_CRUSADE, (DWORD)m_bIsCrusadeMode,
                m_pClientList[iClientH]->m_iCrusadeDuty, 0, 0);
  if (iDuty == 1)
    _bCrusadeLog(DEF_CRUSADELOG_SELECTDUTY, iClientH, 0, "Fighter");
  else if (iDuty == 2)
    _bCrusadeLog(DEF_CRUSADELOG_SELECTDUTY, iClientH, 0, "Constructor");
  else
    _bCrusadeLog(DEF_CRUSADELOG_SELECTDUTY, iClientH, 0, "Commander");
}

void CGame::MapStatusHandler(int iClientH, int iMode, char *pMapName) {
  int i;

  if (m_pClientList[iClientH] == 0)
    return;

  switch (iMode) {
  case 1:
    if (m_pClientList[iClientH]->m_iCrusadeDuty == 0)
      return;

    for (i = 0; i < DEF_MAXGUILDS; i++)
      if ((m_pGuildTeleportLoc[i].m_iV1 != 0) &&
          (m_pGuildTeleportLoc[i].m_iV1 ==
           m_pClientList[iClientH]->m_iGuildGUID)) {
        SendNotifyMsg(
            0, iClientH, DEF_NOTIFY_TCLOC, m_pGuildTeleportLoc[i].m_sDestX,
            m_pGuildTeleportLoc[i].m_sDestY, 0,
            m_pGuildTeleportLoc[i].m_cDestMapName,
            m_pGuildTeleportLoc[i].m_sDestX2, m_pGuildTeleportLoc[i].m_sDestY2,
            0, 0, 0, 0, m_pGuildTeleportLoc[i].m_cDestMapName2);
        // 扒汲 困摹甫 历厘秦 初绰促.
        ZeroMemory(m_pClientList[iClientH]->m_cConstructMapName,
                   sizeof(m_pClientList[iClientH]->m_cConstructMapName));
        memcpy(m_pClientList[iClientH]->m_cConstructMapName,
               m_pGuildTeleportLoc[i].m_cDestMapName2, 10);
        m_pClientList[iClientH]->m_iConstructLocX =
            m_pGuildTeleportLoc[i].m_sDestX2;
        m_pClientList[iClientH]->m_iConstructLocY =
            m_pGuildTeleportLoc[i].m_sDestY2;
        return;
      }

    // 辨靛 家加捞 酒囱 焙牢狼 夸没捞促.
    break;

  case 3:
    // if (m_pClientList[iClientH]->m_iCrusadeDuty != 3) return;
    //  单捞磐 某矫 备炼眉 檬扁拳
    for (i = 0; i < DEF_MAXCRUSADESTRUCTURES; i++) {
      m_pClientList[iClientH]->m_stCrusadeStructureInfo[i].cType = 0;
      m_pClientList[iClientH]->m_stCrusadeStructureInfo[i].cSide = 0;
      m_pClientList[iClientH]->m_stCrusadeStructureInfo[i].sX = 0;
      m_pClientList[iClientH]->m_stCrusadeStructureInfo[i].sY = 0;
    }
    m_pClientList[iClientH]->m_iCSIsendPoint = 0;
    ZeroMemory(m_pClientList[iClientH]->m_cSendingMapName,
               sizeof(m_pClientList[iClientH]->m_cSendingMapName));

    if (strcmp(pMapName,
               m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->m_cName) ==
        0) {
      // 泅犁 荤侩磊啊 困摹茄 甘狼 沥焊甫 夸备沁促.
      // 甘 单捞磐甫 夸没且 寸矫狼 郴侩阑 弊措肺 墨乔茄促.
      for (i = 0; i < m_pMapList[m_pClientList[iClientH]->m_cMapIndex]
                          ->m_iTotalCrusadeStructures;
           i++) {
        // v2.15 荤侩磊啊 Commander 啊 酒聪绢档 扒拱狼 困摹甫 焊咯霖促.
        if (m_pClientList[iClientH]->m_iCrusadeDuty == 3) {
          m_pClientList[iClientH]->m_stCrusadeStructureInfo[i].cType =
              m_pMapList[m_pClientList[iClientH]->m_cMapIndex]
                  ->m_stCrusadeStructureInfo[i]
                  .cType;
          m_pClientList[iClientH]->m_stCrusadeStructureInfo[i].cSide =
              m_pMapList[m_pClientList[iClientH]->m_cMapIndex]
                  ->m_stCrusadeStructureInfo[i]
                  .cSide;
          m_pClientList[iClientH]->m_stCrusadeStructureInfo[i].sX =
              m_pMapList[m_pClientList[iClientH]->m_cMapIndex]
                  ->m_stCrusadeStructureInfo[i]
                  .sX;
          m_pClientList[iClientH]->m_stCrusadeStructureInfo[i].sY =
              m_pMapList[m_pClientList[iClientH]->m_cMapIndex]
                  ->m_stCrusadeStructureInfo[i]
                  .sY;
        } else if (m_pMapList[m_pClientList[iClientH]->m_cMapIndex]
                       ->m_stCrusadeStructureInfo[i]
                       .cType == 42) {
          m_pClientList[iClientH]->m_stCrusadeStructureInfo[i].cType =
              m_pMapList[m_pClientList[iClientH]->m_cMapIndex]
                  ->m_stCrusadeStructureInfo[i]
                  .cType;
          m_pClientList[iClientH]->m_stCrusadeStructureInfo[i].cSide =
              m_pMapList[m_pClientList[iClientH]->m_cMapIndex]
                  ->m_stCrusadeStructureInfo[i]
                  .cSide;
          m_pClientList[iClientH]->m_stCrusadeStructureInfo[i].sX =
              m_pMapList[m_pClientList[iClientH]->m_cMapIndex]
                  ->m_stCrusadeStructureInfo[i]
                  .sX;
          m_pClientList[iClientH]->m_stCrusadeStructureInfo[i].sY =
              m_pMapList[m_pClientList[iClientH]->m_cMapIndex]
                  ->m_stCrusadeStructureInfo[i]
                  .sY;
        }
      }
      memcpy(m_pClientList[iClientH]->m_cSendingMapName,
             m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->m_cName, 10);
    } else {
      // 促弗 甘狼 惑炔阑 夸没沁促. 固甸罚靛狼 版快绰 啊瓷
      if (strcmp(pMapName, "middleland") == 0) {
        for (i = 0; i < m_iTotalMiddleCrusadeStructures; i++) {
          // v2.15 荤侩磊啊 Commander 啊 酒聪绢档 扒拱狼 困摹甫 焊咯霖促.
          if (m_pClientList[iClientH]->m_iCrusadeDuty == 3) {
            m_pClientList[iClientH]->m_stCrusadeStructureInfo[i].cType =
                m_stMiddleCrusadeStructureInfo[i].cType;
            m_pClientList[iClientH]->m_stCrusadeStructureInfo[i].cSide =
                m_stMiddleCrusadeStructureInfo[i].cSide;
            m_pClientList[iClientH]->m_stCrusadeStructureInfo[i].sX =
                m_stMiddleCrusadeStructureInfo[i].sX;
            m_pClientList[iClientH]->m_stCrusadeStructureInfo[i].sY =
                m_stMiddleCrusadeStructureInfo[i].sY;
          } else if (m_stMiddleCrusadeStructureInfo[i].cType == 42) {
            m_pClientList[iClientH]->m_stCrusadeStructureInfo[i].cType =
                m_stMiddleCrusadeStructureInfo[i].cType;
            m_pClientList[iClientH]->m_stCrusadeStructureInfo[i].cSide =
                m_stMiddleCrusadeStructureInfo[i].cSide;
            m_pClientList[iClientH]->m_stCrusadeStructureInfo[i].sX =
                m_stMiddleCrusadeStructureInfo[i].sX;
            m_pClientList[iClientH]->m_stCrusadeStructureInfo[i].sY =
                m_stMiddleCrusadeStructureInfo[i].sY;
          }
        }
        strcpy(m_pClientList[iClientH]->m_cSendingMapName, "middleland");
      } else {
        // 酒流 瘤盔登瘤 臼绰 扁瓷捞促.
      }
    }

    _SendMapStatus(iClientH);
    break;
  }
}

void CGame::_SendMapStatus(int iClientH) {
  int i, iDataSize;
  char *cp, cData[DEF_MAXCRUSADESTRUCTURES * 6];
  short *sp;

  ZeroMemory(cData, sizeof(cData));
  cp = (char *)(cData);

  memcpy(cp, m_pClientList[iClientH]->m_cSendingMapName, 10);
  cp += 10;

  sp = (short *)cp;
  *sp = (short)m_pClientList[iClientH]->m_iCSIsendPoint;
  cp += 2;

  // 脙脩 赂卯掳鲁脌脟 碌楼脌脤脜脥掳隆 脌脰麓脗脕枚 戮脣赂庐麓脗 掳梅 露莽驴貌.
  cp++;

  if (m_pClientList[iClientH]->m_iCSIsendPoint == 0)
    m_pClientList[iClientH]->m_bIsSendingMapStatus = true;

  // 100掳鲁戮驴 脕陇潞赂赂娄 潞赂鲁陆麓脵.
  iDataSize = 0;
  for (i = 0; i < 100; i++) {
    if (m_pClientList[iClientH]->m_iCSIsendPoint >= DEF_MAXCRUSADESTRUCTURES)
      goto SMS_ENDOFDATA;
    if (m_pClientList[iClientH]
            ->m_stCrusadeStructureInfo[m_pClientList[iClientH]->m_iCSIsendPoint]
            .cType == 0)
      goto SMS_ENDOFDATA;

    *cp =
        m_pClientList[iClientH]
            ->m_stCrusadeStructureInfo[m_pClientList[iClientH]->m_iCSIsendPoint]
            .cType;
    cp++;
    sp = (short *)cp;
    *sp =
        m_pClientList[iClientH]
            ->m_stCrusadeStructureInfo[m_pClientList[iClientH]->m_iCSIsendPoint]
            .sX;
    cp += 2;
    sp = (short *)cp;
    *sp =
        m_pClientList[iClientH]
            ->m_stCrusadeStructureInfo[m_pClientList[iClientH]->m_iCSIsendPoint]
            .sY;
    cp += 2;
    *cp =
        m_pClientList[iClientH]
            ->m_stCrusadeStructureInfo[m_pClientList[iClientH]->m_iCSIsendPoint]
            .cSide;
    cp++;

    iDataSize += 6;
    m_pClientList[iClientH]->m_iCSIsendPoint++;
  }

  // 驴漏卤芒卤卯脕枚 驴脭麓脵赂茅 麓玫 潞赂鲁戮 赂脼陆脙脕枚掳隆 脌脰麓脵麓脗
  // 脌脟鹿脤.
  cp = (char *)(cData + 12);
  *cp = (iDataSize / 6);
  SendNotifyMsg(0, iClientH, DEF_NOTIFY_MAPSTATUSNEXT, iDataSize + 13, 0, 0,
                cData);
  return;

SMS_ENDOFDATA:

  // 碌楼脌脤脜脥掳隆 麓脵 脌眉录脹 碌脟戮煤脌陆脌禄 脌脟鹿脤.
  cp = (char *)(cData + 12);
  *cp = (iDataSize / 6);
  SendNotifyMsg(0, iClientH, DEF_NOTIFY_MAPSTATUSLAST, iDataSize + 13, 0, 0,
                cData);
  m_pClientList[iClientH]->m_bIsSendingMapStatus = false;

  return;
}

void CGame::RemoveCrusadeStructures() {
  int i;

  for (i = 0; i < DEF_MAXNPCS; i++)
    if (m_pNpcList[i] != 0) {
      switch (m_pNpcList[i]->m_sType) {
      case 36:
      case 37:
      case 38:
      case 39:
      case 40:
      case 41:
      case 42:
        DeleteNpc(i);
        break;
      }
    }
}

void CGame::RequestHelpHandler(int iClientH) {
  // 脟茂脟脕 驴盲脙禄脌脤麓脵. 卤忙碌氓 赂露陆潞脜脥驴隆掳脭 脕脗脟楼赂娄
  // 脌眉麓脼脟脴 脕脴麓脵.
  int i;

  if (m_pClientList[iClientH] == 0)
    return;
  if (m_pClientList[iClientH]->m_iGuildRank == -1)
    return;
  if (m_pClientList[iClientH]->m_iCrusadeDuty != 1)
    return;

  for (i = 1; i < DEF_MAXCLIENTS; i++)
    if ((m_pClientList[i] != 0) && (m_pClientList[i]->m_iGuildRank == 0) &&
        (m_pClientList[i]->m_iCrusadeDuty == 3) &&
        (m_pClientList[i]->m_iGuildGUID ==
         m_pClientList[iClientH]->m_iGuildGUID)) {
      // 掳掳脌潞 卤忙碌氓 赂露陆潞脜脥脌脤掳铆 脕枚脠脰掳眉 驴陋脠掳脌禄
      // 赂脙脌潞 禄贸脜脗脌脤麓脵.
      SendNotifyMsg(0, i, DEF_NOTIFY_HELP, m_pClientList[iClientH]->m_sX,
                    m_pClientList[iClientH]->m_sY,
                    m_pClientList[iClientH]->m_iHP,
                    m_pClientList[iClientH]->m_cCharName);
      return;
    }

  // 脟枚脌莽 赂脢驴隆 脕枚脠脰掳眉脌脤 戮酶脌陆脌禄 脜毛潞赂脟脴 脕脴麓脵.
  SendNotifyMsg(0, iClientH, DEF_NOTIFY_HELPFAILED, 0, 0, 0, 0);
}

