void CGame::GSM_SetGuildConstructLoc(int iGuildGUID, int dX, int dY,
                                     char *pMapName) {
  int i, iIndex;
  DWORD dwTemp, dwTime;

  // 脜卢露贸脌脤戮冒脝庐路脦潞脦脜脥脌脟 驴盲脙禄脌脤 戮脝麓脧露贸 麓脵赂楼
  // 录颅鹿枚路脦潞脦脜脥脌脟 脜脷路鹿脝梅脝庐 脕脗脟楼 录鲁脕陇 驴盲脙禄脌脫.
  // 脌脌麓盲脟脪 脟脢驴盲 戮酶脌陆.

  // testcode
  wsprintf(G_cTxt, "SetGuildConstructLoc: %d %s %d %d", iGuildGUID, pMapName,
           dX, dY);
  PutLogList(G_cTxt);

  dwTime = timeGetTime();

  // 赂脮脌煤 掳掳脌潞 GUID赂娄 掳隆脕酶 卤忙碌氓 脜脷路鹿脝梅脝庐 脕脗脟楼掳隆
  // 录鲁脕陇碌脟戮卯 脌脰麓脗脕枚 脙拢麓脗麓脵.
  for (i = 0; i < DEF_MAXGUILDS; i++)
    if (m_pGuildTeleportLoc[i].m_iV1 == iGuildGUID) {
      // 脌脤鹿脤 卤忙碌氓掳隆 脌脰麓脵.
      if ((m_pGuildTeleportLoc[i].m_sDestX2 == dX) &&
          (m_pGuildTeleportLoc[i].m_sDestY2 == dY) &&
          (strcmp(m_pGuildTeleportLoc[i].m_cDestMapName2, pMapName) == 0)) {
        // 鲁禄驴毛脌脤 脌脧脛隆脟脩麓脵. 脜赂脌脫 脌脭路脗脠脛 陆潞脜碌.
        m_pGuildTeleportLoc[i].m_dwTime2 = dwTime;
        return;
      } else {
        // 鲁禄驴毛 掳禄陆脜
        m_pGuildTeleportLoc[i].m_sDestX2 = dX;
        m_pGuildTeleportLoc[i].m_sDestY2 = dY;
        ZeroMemory(m_pGuildTeleportLoc[i].m_cDestMapName2,
                   sizeof(m_pGuildTeleportLoc[i].m_cDestMapName2));
        strcpy(m_pGuildTeleportLoc[i].m_cDestMapName2, pMapName);
        m_pGuildTeleportLoc[i].m_dwTime2 = dwTime;
        return;
      }
    }

  // 录鲁脕陇碌脠 鲁禄驴毛脌脤 戮酶麓脵. 禄玫路脦 录鲁脕陇脟脩麓脵.
  dwTemp = 0;
  iIndex = -1;
  for (i = 0; i < DEF_MAXGUILDS; i++) {
    if (m_pGuildTeleportLoc[i].m_iV1 == 0) {

      m_pGuildTeleportLoc[i].m_iV1 = iGuildGUID;
      m_pGuildTeleportLoc[i].m_sDestX2 = dX;
      m_pGuildTeleportLoc[i].m_sDestY2 = dY;
      ZeroMemory(m_pGuildTeleportLoc[i].m_cDestMapName2,
                 sizeof(m_pGuildTeleportLoc[i].m_cDestMapName));
      strcpy(m_pGuildTeleportLoc[i].m_cDestMapName2, pMapName);
      m_pGuildTeleportLoc[i].m_dwTime2 = dwTime;
      return;
    } else {
      // 掳隆脌氓 驴脌路搂碌驴戮脠 脗眉脕露碌脟脕枚 戮脢脌潞 赂庐陆潞脝庐脌脟
      // 脌脦碌娄陆潞赂娄 脙拢麓脗麓脵.
      if (dwTemp < (dwTime - m_pGuildTeleportLoc[i].m_dwTime2)) {
        dwTemp = (dwTime - m_pGuildTeleportLoc[i].m_dwTime2);
        iIndex = i;
      }
    }
  }

  // 脛鲁陆脙 掳酶掳拢脌脤 麓脵 脙隆麓脵. 脌脤路卤 掳忙驴矛 赂庐陆潞脝庐 脕脽
  // 掳隆脌氓 驴脌路搂碌驴戮脠 禄莽驴毛脟脧脕枚 戮脢脌潞
  // 赂庐陆潞脝庐(iIndex)赂娄 禄猫脕娄脟脧掳铆 戮梅碌楼脌脤脝庐 脟脩麓脵.
  if (iIndex == -1)
    return;

  // testcode
  PutLogList("(X) No more GuildConstLocuct Space! Replaced.");

  m_pGuildTeleportLoc[i].m_iV1 = iGuildGUID;
  m_pGuildTeleportLoc[i].m_sDestX2 = dX;
  m_pGuildTeleportLoc[i].m_sDestY2 = dY;
  ZeroMemory(m_pGuildTeleportLoc[i].m_cDestMapName2,
             sizeof(m_pGuildTeleportLoc[i].m_cDestMapName2));
  strcpy(m_pGuildTeleportLoc[i].m_cDestMapName2, pMapName);
  m_pGuildTeleportLoc[i].m_dwTime2 = dwTime;
}

void CGame::CheckCommanderConstructionPoint(int iClientH) {
  char *cp, cData[120];
  int *ip, i;

  if (m_pClientList[iClientH] == 0)
    return;
  if (m_bIsCrusadeMode == false)
    return;
  if (m_pClientList[iClientH]->m_iConstructionPoint <= 0)
    return;

  switch (m_pClientList[iClientH]->m_iCrusadeDuty) {
  case 1: // 脝脛脌脤脜脥
  case 2: // 掳脟录鲁脌脷: 赂冒戮脝 鲁玫脌潞 脝梅脌脦脝庐赂娄
          // 卤忙碌氓赂露陆潞脜脥 脕枚脠脰掳眉驴隆掳脭 脌眉麓脼脟脩麓脵.
    for (i = 0; i < DEF_MAXCLIENTS; i++)
      if ((m_pClientList[i] != 0) && (m_pClientList[i]->m_iCrusadeDuty == 3) &&
          (m_pClientList[i]->m_iGuildGUID ==
           m_pClientList[iClientH]->m_iGuildGUID)) {
        // 脟枚脌莽 录颅鹿枚 鲁禄驴隆 卤忙碌氓赂露陆潞脜脥 脕枚脠脰掳眉脌脤
        // 脌脰麓脵. 脕枚脠脰掳眉脌脟 脝梅脌脦脝庐赂娄 鲁么脌脦 脠脛
        m_pClientList[i]->m_iConstructionPoint +=
            m_pClientList[iClientH]->m_iConstructionPoint;
        m_pClientList[i]->m_iWarContribution +=
            (m_pClientList[iClientH]->m_iConstructionPoint / 10);

        if (m_pClientList[i]->m_iConstructionPoint > DEF_MAXCONSTRUCTIONPOINT)
          m_pClientList[i]->m_iConstructionPoint = DEF_MAXCONSTRUCTIONPOINT;

        if (m_pClientList[i]->m_iWarContribution > DEF_MAXWARCONTRIBUTION)
          m_pClientList[i]->m_iWarContribution = DEF_MAXWARCONTRIBUTION;

        SendNotifyMsg(0, i, DEF_NOTIFY_CONSTRUCTIONPOINT,
                      m_pClientList[i]->m_iConstructionPoint,
                      m_pClientList[i]->m_iWarContribution, 0, 0);
        m_pClientList[iClientH]->m_iConstructionPoint = 0; // 掳陋 脙脢卤芒脠颅
        return;
      }

    // 麓脵赂楼 录颅鹿枚脌脟 脕枚脠脰掳眉驴隆掳脭 戮脣路脕戮脽 脟脩麓脵.
    /*ZeroMemory(cData, sizeof(cData));
    cp = (char *)cData;
    *cp = GSM_CONSTRUCTIONPOINT;
    cp++;
    ip = (int*)cp;
    *ip = m_pClientList[iClientH]->m_iGuildGUID;
    cp += 4;
    ip = (int*)cp;
    *ip = m_pClientList[iClientH]->m_iConstructionPoint;
    cp += 4;
    bStockMsgToGateServer(cData, 9);*/

    m_pClientList[iClientH]->m_iConstructionPoint = 0; // 掳陋 脙脢卤芒脠颅
    break;

  case 3: // 脕枚脠脰掳眉: 潞赂鲁戮 脟脢驴盲 戮酶脌陆

    break;
  }
}

void CGame::GSM_ConstructionPoint(int iGuildGUID, int iPoint) {
  int i;

  for (i = 1; i < DEF_MAXCLIENTS; i++)
    if ((m_pClientList[i] != 0) && (m_pClientList[i]->m_iCrusadeDuty == 3) &&
        (m_pClientList[i]->m_iGuildGUID == iGuildGUID)) {
      // 脟脴麓莽 卤忙碌氓赂露陆潞脜脥 脕枚脠脰掳眉脌禄 脙拢戮脪麓脵.
      m_pClientList[i]->m_iConstructionPoint += iPoint;
      m_pClientList[i]->m_iWarContribution += iPoint / 10;

      if (m_pClientList[i]->m_iConstructionPoint > DEF_MAXCONSTRUCTIONPOINT)
        m_pClientList[i]->m_iConstructionPoint = DEF_MAXCONSTRUCTIONPOINT;

      if (m_pClientList[i]->m_iWarContribution > DEF_MAXWARCONTRIBUTION)
        m_pClientList[i]->m_iWarContribution = DEF_MAXWARCONTRIBUTION;

      SendNotifyMsg(0, i, DEF_NOTIFY_CONSTRUCTIONPOINT,
                    m_pClientList[i]->m_iConstructionPoint,
                    m_pClientList[i]->m_iWarContribution, 0, 0);
      // testcode
      wsprintf(G_cTxt, "GSM_ConstructionPoint: %d %d", iGuildGUID, iPoint);
      PutLogList(G_cTxt);
      return;
    }
}

bool CGame::bAddClientShortCut(int iClientH) {
  int i;

  // 赂脮脌煤 碌驴脌脧脟脩 鹿酶脠拢掳隆 脕赂脌莽脟脧麓脗脕枚 掳脣禄枚

  for (i = 0; i < DEF_MAXCLIENTS; i++)
    if (m_iClientShortCut[i] == iClientH)
      return false;

  for (i = 0; i < DEF_MAXCLIENTS; i++)
    if (m_iClientShortCut[i] == 0) {
      m_iClientShortCut[i] = iClientH;
      return true;
    }

  return false;
}

void CGame::RemoveClientShortCut(int iClientH) {
  int i;

  for (i = 0; i < DEF_MAXCLIENTS + 1; i++)
    if (m_iClientShortCut[i] == iClientH) {
      m_iClientShortCut[i] = 0;
      goto RCSC_LOOPBREAK;
    }

RCSC_LOOPBREAK:

  // 潞贸 驴漏鹿茅脌禄 赂脼虏脹麓脵.
  // m_iClientShortCut[i] = m_iClientShortCut[m_iTotalClients+1];
  // m_iClientShortCut[m_iTotalClients+1] = 0;
  for (i = 0; i < DEF_MAXCLIENTS; i++)
    if ((m_iClientShortCut[i] == 0) && (m_iClientShortCut[i + 1] != 0)) {
      m_iClientShortCut[i] = m_iClientShortCut[i + 1];
      m_iClientShortCut[i + 1] = 0;
    }
}

void CGame::_CreateCrusadeGUID(DWORD dwCrusadeGUID, int iWinnerSide) {
  char *cp, cTxt[256], cFn[256], cTemp[1024];
  FILE *pFile;

  _mkdir("GameData");
  ZeroMemory(cFn, sizeof(cFn));

  strcat(cFn, "GameData");
  strcat(cFn, "\\");
  strcat(cFn, "\\");
  strcat(cFn, "CrusadeGUID.Txt");

  pFile = fopen(cFn, "wt");
  if (pFile == 0) {
    // 脝脛脌脧脌禄 赂赂碌茅 录枚 戮酶掳脜鲁陋 禄莽脌脤脕卯掳隆 脕枚鲁陋脛隆掳脭
    // 脌脹脌潞 掳忙驴矛麓脗 .
    wsprintf(cTxt, "(!) Cannot create CrusadeGUID(%d) file", dwCrusadeGUID);
    PutLogList(cTxt);
  } else {
    ZeroMemory(cTemp, sizeof(cTemp));

    ZeroMemory(cTxt, sizeof(cTxt));
    wsprintf(cTxt, "CrusadeGUID = %d\n", dwCrusadeGUID);
    strcat(cTemp, cTxt);

    ZeroMemory(cTxt, sizeof(cTxt));
    wsprintf(cTxt, "winner-side = %d\n", iWinnerSide);
    strcat(cTemp, cTxt);

    cp = (char *)cTemp;
    fwrite(cp, strlen(cp), 1, pFile);

    wsprintf(cTxt, "(O) CrusadeGUID(%d) file created", dwCrusadeGUID);
    PutLogList(cTxt);
  }
  if (pFile != 0)
    fclose(pFile);
}

bool CGame::bReadCrusadeGUIDFile(char *cFn) {
  FILE *pFile;
  HANDLE hFile;
  DWORD dwFileSize;
  char *cp, *token, cReadMode;
  char seps[] = "= \t\n";
  class CStrTok *pStrTok;

  cReadMode = 0;

  hFile = CreateFile(cFn, GENERIC_READ, 0, 0, OPEN_EXISTING, 0, 0);
  dwFileSize = GetFileSize(hFile, 0);
  if (hFile != INVALID_HANDLE_VALUE)
    CloseHandle(hFile);

  pFile = fopen(cFn, "rt");
  if (pFile == 0) {
    // 掳脭脌脫录颅鹿枚脌脟 脙脢卤芒脠颅 脝脛脌脧脌禄 脌脨脌禄 录枚 戮酶麓脵.
    PutLogList("(!) Cannot open CrusadeGUID file.");
    return false;
  } else {
    PutLogList("(!) Reading CrusadeGUID file...");
    cp = new char[dwFileSize + 2];
    ZeroMemory(cp, dwFileSize + 2);
    fread(cp, dwFileSize, 1, pFile);

    pStrTok = new class CStrTok(cp, seps);
    token = pStrTok->pGet();

    while (token != 0) {

      if (cReadMode != 0) {
        switch (cReadMode) {
        case 1:
          m_dwCrusadeGUID = atoi(token);
          wsprintf(G_cTxt, "CrusadeGUID = %d", m_dwCrusadeGUID);
          PutLogList(G_cTxt);
          cReadMode = 0;
          break;

        case 2:
          // New 13/05/2004 Changed
          m_iLastCrusadeWinner = atoi(token);
          wsprintf(G_cTxt, "CrusadeWinnerSide = %d", m_iLastCrusadeWinner);
          PutLogList(G_cTxt);
          cReadMode = 0;
          break;
        }
      } else {
        if (memcmp(token, "CrusadeGUID", 11) == 0)
          cReadMode = 1;
        if (memcmp(token, "winner-side", 11) == 0)
          cReadMode = 2;
      }

      token = pStrTok->pGet();
    }

    delete pStrTok;
    delete cp;
  }
  if (pFile != 0)
    fclose(pFile);

  return true;
}

