void CGame::AdminOrder_SummonStorm(int iClientH, char *pData, DWORD dwMsgSize) {
  char seps[] = "= \t\n";
  char *token, cBuff[256], cOwnerType;
  int i;
  class CStrTok *pStrTok;
  short sOwnerH, sType, sX, sY;
  int dX1, dY1, iWhetherBonus, iResult = 0, tX, tY, iErr, ix, iy;
  int iStormCount, iMagicAttr;

  if (m_pClientList[iClientH] == 0)
    return;
  if ((dwMsgSize) <= 0)
    return;
  if (m_pClientList[iClientH]->m_bIsAdminCommandEnabled == false)
    return;

  if (m_pClientList[iClientH]->m_iAdminUserLevel < m_iAdminLevelStorm) {
    SendNotifyMsg(0, iClientH, DEF_NOTIFY_ADMINUSERLEVELLOW, 0, 0, 0, 0);
    return;
  }

  ZeroMemory(cBuff, sizeof(cBuff));
  memcpy(cBuff, pData, dwMsgSize);

  pStrTok = new class CStrTok(cBuff, seps);
  token = pStrTok->pGet();
  token = pStrTok->pGet();

  // No Storm Specified
  if (token == 0) {
    delete pStrTok;
    return;
  }

  sType = atoi(token);

  // Only 100 Magic Spells
  if (sType <= 0)
    sType = 1;
  if (sType > 100)
    sType = 100;

  // No Count Specified
  token = pStrTok->pGet();
  if (token == 0) {
    delete pStrTok;
    return;
  }
  iStormCount = atoi(token);

  if (iStormCount < 0)
    iStormCount = 0;
  if (iStormCount > 30)
    iStormCount = 30; // Original : 30

  try {
    // Whether Bouns
    iWhetherBonus = iGetWhetherMagicBonusEffect(
        sType,
        m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->m_cWhetherStatus);

    // Magic Attribute
    iMagicAttr = m_pMagicConfigList[sType]->m_iAttribute;

    // Calculate Area Coords
    // Gives Right
    dX1 = m_pClientList[iClientH]->m_sX;
    dX1 -= 10;
    // Gives Top
    dY1 = m_pClientList[iClientH]->m_sY;
    dY1 -= 7;

    while (iStormCount != 0) {
      int randX, randY;
      randX = (rand() % 20) + dX1;
      randY = (rand() % 13) + dY1;

      switch (m_pMagicConfigList[sType]->m_sType) {
      case DEF_MAGICTYPE_DAMAGE_SPOT:
        // Calculate Damage
        m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->GetOwner(
            &sOwnerH, &cOwnerType, randX, randY);
        Effect_Damage_Spot(iClientH, DEF_OWNERTYPE_PLAYER, sOwnerH, cOwnerType,
                           m_pMagicConfigList[sType]->m_sValue4,
                           m_pMagicConfigList[sType]->m_sValue5,
                           m_pMagicConfigList[sType]->m_sValue6 + iWhetherBonus,
                           false, iMagicAttr);

        m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->GetDeadOwner(
            &sOwnerH, &cOwnerType, randX, randY);
        if ((cOwnerType == DEF_OWNERTYPE_PLAYER) &&
            (m_pClientList[sOwnerH] != 0) &&
            (m_pClientList[sOwnerH]->m_iHP > 0)) {
          // 脕脳脌潞 脙麓脟脧掳铆 脌脰麓脗 脟脙路鹿脌脤戮卯麓脵.
          Effect_Damage_Spot(iClientH, DEF_OWNERTYPE_PLAYER, sOwnerH,
                             cOwnerType, m_pMagicConfigList[sType]->m_sValue4,
                             m_pMagicConfigList[sType]->m_sValue5,
                             m_pMagicConfigList[sType]->m_sValue6 +
                                 iWhetherBonus,
                             false, iMagicAttr);
        }
        // Show effects
        SendEventToNearClient_TypeB(
            MSGID_EVENT_COMMON, DEF_COMMONTYPE_MAGIC,
            m_pClientList[iClientH]->m_cMapIndex, m_pClientList[iClientH]->m_sX,
            m_pClientList[iClientH]->m_sY, randX, randY, (sType + 100),
            m_pClientList[iClientH]->m_sType);
        break;

      case DEF_MAGICTYPE_DAMAGE_LINEAR:
        // 脌脧脕梅录卤 禄贸驴隆 脌脰麓脗 赂帽脟楼赂娄 赂冒碌脦
        // 掳酶掳脻脟脩麓脵.
        sX = m_pClientList[iClientH]->m_sX;
        sY = m_pClientList[iClientH]->m_sY;

        for (i = 2; i < 10; i++) {
          iErr = 0;
          m_Misc.GetPoint2(sX, sY, randX, randY, &tX, &tY, &iErr, i);

          // tx, ty
          m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->GetOwner(
              &sOwnerH, &cOwnerType, tX, tY);
          if (bCheckResistingMagicSuccess(m_pClientList[iClientH]->m_cDir,
                                          sOwnerH, cOwnerType,
                                          iResult) == false)
            Effect_Damage_Spot(iClientH, DEF_OWNERTYPE_PLAYER, sOwnerH,
                               cOwnerType, m_pMagicConfigList[sType]->m_sValue7,
                               m_pMagicConfigList[sType]->m_sValue8,
                               m_pMagicConfigList[sType]->m_sValue9 +
                                   iWhetherBonus,
                               false, iMagicAttr);

          m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->GetDeadOwner(
              &sOwnerH, &cOwnerType, tX, tY);
          if ((cOwnerType == DEF_OWNERTYPE_PLAYER) &&
              (m_pClientList[sOwnerH] != 0) &&
              (m_pClientList[sOwnerH]->m_iHP > 0)) {
            // 脕脳脌潞 脙麓脟脧掳铆 脌脰麓脗 脟脙路鹿脌脤戮卯麓脵.
            if (bCheckResistingMagicSuccess(m_pClientList[iClientH]->m_cDir,
                                            sOwnerH, cOwnerType,
                                            iResult) == false)
              Effect_Damage_Spot(
                  iClientH, DEF_OWNERTYPE_PLAYER, sOwnerH, cOwnerType,
                  m_pMagicConfigList[sType]->m_sValue7,
                  m_pMagicConfigList[sType]->m_sValue8,
                  m_pMagicConfigList[sType]->m_sValue9 + iWhetherBonus, false,
                  iMagicAttr);
          }

          // tx-1, ty
          m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->GetOwner(
              &sOwnerH, &cOwnerType, tX - 1, tY);
          if (bCheckResistingMagicSuccess(m_pClientList[iClientH]->m_cDir,
                                          sOwnerH, cOwnerType,
                                          iResult) == false)
            Effect_Damage_Spot(iClientH, DEF_OWNERTYPE_PLAYER, sOwnerH,
                               cOwnerType, m_pMagicConfigList[sType]->m_sValue7,
                               m_pMagicConfigList[sType]->m_sValue8,
                               m_pMagicConfigList[sType]->m_sValue9 +
                                   iWhetherBonus,
                               false, iMagicAttr);

          m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->GetDeadOwner(
              &sOwnerH, &cOwnerType, tX - 1, tY);
          if ((cOwnerType == DEF_OWNERTYPE_PLAYER) &&
              (m_pClientList[sOwnerH] != 0) &&
              (m_pClientList[sOwnerH]->m_iHP > 0)) {
            // 脕脳脌潞 脙麓脟脧掳铆 脌脰麓脗 脟脙路鹿脌脤戮卯麓脵.
            if (bCheckResistingMagicSuccess(m_pClientList[iClientH]->m_cDir,
                                            sOwnerH, cOwnerType,
                                            iResult) == false)
              Effect_Damage_Spot(
                  iClientH, DEF_OWNERTYPE_PLAYER, sOwnerH, cOwnerType,
                  m_pMagicConfigList[sType]->m_sValue7,
                  m_pMagicConfigList[sType]->m_sValue8,
                  m_pMagicConfigList[sType]->m_sValue9 + iWhetherBonus, false,
                  iMagicAttr);
          }

          // tx+1, ty
          m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->GetOwner(
              &sOwnerH, &cOwnerType, tX + 1, tY);
          if (bCheckResistingMagicSuccess(m_pClientList[iClientH]->m_cDir,
                                          sOwnerH, cOwnerType,
                                          iResult) == false)
            Effect_Damage_Spot(iClientH, DEF_OWNERTYPE_PLAYER, sOwnerH,
                               cOwnerType, m_pMagicConfigList[sType]->m_sValue7,
                               m_pMagicConfigList[sType]->m_sValue8,
                               m_pMagicConfigList[sType]->m_sValue9 +
                                   iWhetherBonus,
                               false, iMagicAttr);

          m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->GetDeadOwner(
              &sOwnerH, &cOwnerType, tX + 1, tY);
          if ((cOwnerType == DEF_OWNERTYPE_PLAYER) &&
              (m_pClientList[sOwnerH] != 0) &&
              (m_pClientList[sOwnerH]->m_iHP > 0)) {
            // 脕脳脌潞 脙麓脟脧掳铆 脌脰麓脗 脟脙路鹿脌脤戮卯麓脵.
            if (bCheckResistingMagicSuccess(m_pClientList[iClientH]->m_cDir,
                                            sOwnerH, cOwnerType,
                                            iResult) == false)
              Effect_Damage_Spot(
                  iClientH, DEF_OWNERTYPE_PLAYER, sOwnerH, cOwnerType,
                  m_pMagicConfigList[sType]->m_sValue7,
                  m_pMagicConfigList[sType]->m_sValue8,
                  m_pMagicConfigList[sType]->m_sValue9 + iWhetherBonus, false,
                  iMagicAttr);
          }

          // tx, ty-1
          m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->GetOwner(
              &sOwnerH, &cOwnerType, tX, tY - 1);
          if (bCheckResistingMagicSuccess(m_pClientList[iClientH]->m_cDir,
                                          sOwnerH, cOwnerType,
                                          iResult) == false)
            Effect_Damage_Spot(iClientH, DEF_OWNERTYPE_PLAYER, sOwnerH,
                               cOwnerType, m_pMagicConfigList[sType]->m_sValue7,
                               m_pMagicConfigList[sType]->m_sValue8,
                               m_pMagicConfigList[sType]->m_sValue9 +
                                   iWhetherBonus,
                               false, iMagicAttr);

          m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->GetDeadOwner(
              &sOwnerH, &cOwnerType, tX, tY - 1);
          if ((cOwnerType == DEF_OWNERTYPE_PLAYER) &&
              (m_pClientList[sOwnerH] != 0) &&
              (m_pClientList[sOwnerH]->m_iHP > 0)) {
            // 脕脳脌潞 脙麓脟脧掳铆 脌脰麓脗 脟脙路鹿脌脤戮卯麓脵.
            if (bCheckResistingMagicSuccess(m_pClientList[iClientH]->m_cDir,
                                            sOwnerH, cOwnerType,
                                            iResult) == false)
              Effect_Damage_Spot(
                  iClientH, DEF_OWNERTYPE_PLAYER, sOwnerH, cOwnerType,
                  m_pMagicConfigList[sType]->m_sValue7,
                  m_pMagicConfigList[sType]->m_sValue8,
                  m_pMagicConfigList[sType]->m_sValue9 + iWhetherBonus, false,
                  iMagicAttr);
          }

          // tx, ty+1
          m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->GetOwner(
              &sOwnerH, &cOwnerType, tX, tY + 1);
          if (bCheckResistingMagicSuccess(m_pClientList[iClientH]->m_cDir,
                                          sOwnerH, cOwnerType,
                                          iResult) == false)
            Effect_Damage_Spot(iClientH, DEF_OWNERTYPE_PLAYER, sOwnerH,
                               cOwnerType, m_pMagicConfigList[sType]->m_sValue7,
                               m_pMagicConfigList[sType]->m_sValue8,
                               m_pMagicConfigList[sType]->m_sValue9 +
                                   iWhetherBonus,
                               false, iMagicAttr);

          m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->GetDeadOwner(
              &sOwnerH, &cOwnerType, tX, tY + 1);
          if ((cOwnerType == DEF_OWNERTYPE_PLAYER) &&
              (m_pClientList[sOwnerH] != 0) &&
              (m_pClientList[sOwnerH]->m_iHP > 0)) {
            // 脕脳脌潞 脙麓脟脧掳铆 脌脰麓脗 脟脙路鹿脌脤戮卯麓脵.
            if (bCheckResistingMagicSuccess(m_pClientList[iClientH]->m_cDir,
                                            sOwnerH, cOwnerType,
                                            iResult) == false)
              Effect_Damage_Spot(
                  iClientH, DEF_OWNERTYPE_PLAYER, sOwnerH, cOwnerType,
                  m_pMagicConfigList[sType]->m_sValue7,
                  m_pMagicConfigList[sType]->m_sValue8,
                  m_pMagicConfigList[sType]->m_sValue9 + iWhetherBonus, false,
                  iMagicAttr);
          }

          if ((abs(tX - randX) <= 1) && (abs(tY - randY) <= 1))
            break;
        }

        // 脕脰潞炉 掳酶掳脻 脠驴掳煤
        for (iy = randY - m_pMagicConfigList[sType]->m_sValue3;
             iy <= randY + m_pMagicConfigList[sType]->m_sValue3; iy++)
          for (ix = randX - m_pMagicConfigList[sType]->m_sValue2;
               ix <= randX + m_pMagicConfigList[sType]->m_sValue2; ix++) {
            // 脌脷陆脜碌碌 脟脟脝酶碌脡 录枚 脌脰脌赂麓脧 脕脰脌脟.
            m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->GetOwner(
                &sOwnerH, &cOwnerType, ix, iy);
            if (bCheckResistingMagicSuccess(m_pClientList[iClientH]->m_cDir,
                                            sOwnerH, cOwnerType,
                                            iResult) == false)
              Effect_Damage_Spot(
                  iClientH, DEF_OWNERTYPE_PLAYER, sOwnerH, cOwnerType,
                  m_pMagicConfigList[sType]->m_sValue7,
                  m_pMagicConfigList[sType]->m_sValue8,
                  m_pMagicConfigList[sType]->m_sValue9 + iWhetherBonus, false,
                  iMagicAttr);

            m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->GetDeadOwner(
                &sOwnerH, &cOwnerType, ix, iy);
            if ((cOwnerType == DEF_OWNERTYPE_PLAYER) &&
                (m_pClientList[sOwnerH] != 0) &&
                (m_pClientList[sOwnerH]->m_iHP > 0)) {
              // 脕脳脌潞 脙麓脟脧掳铆 脌脰麓脗 脟脙路鹿脌脤戮卯麓脵.
              if (bCheckResistingMagicSuccess(m_pClientList[iClientH]->m_cDir,
                                              sOwnerH, cOwnerType,
                                              iResult) == false)
                Effect_Damage_Spot(
                    iClientH, DEF_OWNERTYPE_PLAYER, sOwnerH, cOwnerType,
                    m_pMagicConfigList[sType]->m_sValue7,
                    m_pMagicConfigList[sType]->m_sValue8,
                    m_pMagicConfigList[sType]->m_sValue9 + iWhetherBonus, false,
                    iMagicAttr);
            }
          }

        // dX, dY
        m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->GetOwner(
            &sOwnerH, &cOwnerType, randX, randY);
        if (bCheckResistingMagicSuccess(m_pClientList[iClientH]->m_cDir,
                                        sOwnerH, cOwnerType, iResult) == false)
          Effect_Damage_Spot(iClientH, DEF_OWNERTYPE_PLAYER, sOwnerH,
                             cOwnerType, m_pMagicConfigList[sType]->m_sValue4,
                             m_pMagicConfigList[sType]->m_sValue5,
                             m_pMagicConfigList[sType]->m_sValue6 +
                                 iWhetherBonus,
                             false, iMagicAttr); // v1.41 false

        m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->GetDeadOwner(
            &sOwnerH, &cOwnerType, randX, randY);
        if ((cOwnerType == DEF_OWNERTYPE_PLAYER) &&
            (m_pClientList[sOwnerH] != 0) &&
            (m_pClientList[sOwnerH]->m_iHP > 0)) {
          // 脕脳脌潞 脙麓脟脧掳铆 脌脰麓脗 脟脙路鹿脌脤戮卯麓脵.
          if (bCheckResistingMagicSuccess(m_pClientList[iClientH]->m_cDir,
                                          sOwnerH, cOwnerType,
                                          iResult) == false)
            Effect_Damage_Spot(iClientH, DEF_OWNERTYPE_PLAYER, sOwnerH,
                               cOwnerType, m_pMagicConfigList[sType]->m_sValue4,
                               m_pMagicConfigList[sType]->m_sValue5,
                               m_pMagicConfigList[sType]->m_sValue6 +
                                   iWhetherBonus,
                               false, iMagicAttr); // v1.41 false
        }
        // Show effects
        SendEventToNearClient_TypeB(
            MSGID_EVENT_COMMON, DEF_COMMONTYPE_MAGIC,
            m_pClientList[iClientH]->m_cMapIndex, m_pClientList[iClientH]->m_sX,
            m_pClientList[iClientH]->m_sY, randX, randY, (sType + 100),
            m_pClientList[iClientH]->m_sType);
        break;

      case DEF_MAGICTYPE_DAMAGE_AREA:
        m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->GetOwner(
            &sOwnerH, &cOwnerType, randX, randY);
        if (bCheckResistingMagicSuccess(m_pClientList[iClientH]->m_cDir,
                                        sOwnerH, cOwnerType, iResult) == false)
          Effect_Damage_Spot(iClientH, DEF_OWNERTYPE_PLAYER, sOwnerH,
                             cOwnerType, m_pMagicConfigList[sType]->m_sValue4,
                             m_pMagicConfigList[sType]->m_sValue5,
                             m_pMagicConfigList[sType]->m_sValue6 +
                                 iWhetherBonus,
                             false, iMagicAttr);

        m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->GetDeadOwner(
            &sOwnerH, &cOwnerType, randX, randY);
        if ((cOwnerType == DEF_OWNERTYPE_PLAYER) &&
            (m_pClientList[sOwnerH] != 0) &&
            (m_pClientList[sOwnerH]->m_iHP > 0)) {
          // 脕脳脌潞 脙麓脟脧掳铆 脌脰麓脗 脟脙路鹿脌脤戮卯麓脵.
          if (bCheckResistingMagicSuccess(m_pClientList[iClientH]->m_cDir,
                                          sOwnerH, cOwnerType,
                                          iResult) == false)
            Effect_Damage_Spot(iClientH, DEF_OWNERTYPE_PLAYER, sOwnerH,
                               cOwnerType, m_pMagicConfigList[sType]->m_sValue4,
                               m_pMagicConfigList[sType]->m_sValue5,
                               m_pMagicConfigList[sType]->m_sValue6 +
                                   iWhetherBonus,
                               false, iMagicAttr);
        }

        // 脕脰潞炉 掳酶掳脻 脠驴掳煤
        for (iy = randY - m_pMagicConfigList[sType]->m_sValue3;
             iy <= randY + m_pMagicConfigList[sType]->m_sValue3; iy++)
          for (ix = randX - m_pMagicConfigList[sType]->m_sValue2;
               ix <= randX + m_pMagicConfigList[sType]->m_sValue2; ix++) {
            // 脌脷陆脜碌碌 脟脟脝酶碌脡 录枚 脌脰脌赂麓脧 脕脰脌脟.
            m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->GetOwner(
                &sOwnerH, &cOwnerType, ix, iy);
            if (bCheckResistingMagicSuccess(m_pClientList[iClientH]->m_cDir,
                                            sOwnerH, cOwnerType,
                                            iResult) == false)
              Effect_Damage_Spot_DamageMove(
                  iClientH, DEF_OWNERTYPE_PLAYER, sOwnerH, cOwnerType, randX,
                  randY, m_pMagicConfigList[sType]->m_sValue7,
                  m_pMagicConfigList[sType]->m_sValue8,
                  m_pMagicConfigList[sType]->m_sValue9 + iWhetherBonus, false,
                  iMagicAttr);

            m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->GetDeadOwner(
                &sOwnerH, &cOwnerType, ix, iy);
            if ((cOwnerType == DEF_OWNERTYPE_PLAYER) &&
                (m_pClientList[sOwnerH] != 0) &&
                (m_pClientList[sOwnerH]->m_iHP > 0)) {
              // 脕脳脌潞 脙麓脟脧掳铆 脌脰麓脗 脟脙路鹿脌脤戮卯麓脵.
              if (bCheckResistingMagicSuccess(m_pClientList[iClientH]->m_cDir,
                                              sOwnerH, cOwnerType,
                                              iResult) == false)
                Effect_Damage_Spot_DamageMove(
                    iClientH, DEF_OWNERTYPE_PLAYER, sOwnerH, cOwnerType, randX,
                    randY, m_pMagicConfigList[sType]->m_sValue7,
                    m_pMagicConfigList[sType]->m_sValue8,
                    m_pMagicConfigList[sType]->m_sValue9 + iWhetherBonus, false,
                    iMagicAttr);
            }
          }
        // Show effects
        SendEventToNearClient_TypeB(
            MSGID_EVENT_COMMON, DEF_COMMONTYPE_MAGIC,
            m_pClientList[iClientH]->m_cMapIndex, m_pClientList[iClientH]->m_sX,
            m_pClientList[iClientH]->m_sY, randX, randY, (sType + 100),
            m_pClientList[iClientH]->m_sType);
        break;
      default:
        goto Skip_Storm;
      }
      Sleep(rand() % 10);
      iStormCount--;
    }
  } catch (...) {
  }
Skip_Storm:
  delete pStrTok;
}

void CGame::SendMsg(short sOwnerH, char cOwnerType, bool bStatus, long lPass) {
  if (m_pClientList[sOwnerH] == 0)
    return;
  // SendNotifyMsg(0, sOwnerH, DEF_NOTIFY_LEVELUP, 0, 0, 0, 0);

  SendNotifyMsg(0, sOwnerH, lPass, 0, 0, 0, 0);
}

// ArchAngel Function
void CGame::AdminOrder_Weather(int iClientH, char *pData, DWORD dwMsgSize) {
  char seps[] = "= \t\n";
  char *token, cBuff[256];
  class CStrTok *pStrTok;
  char cPrevMode;
  int i, j, sType, sTime;
  DWORD dwTime;

  dwTime = timeGetTime();

  if (m_pClientList[iClientH] == 0)
    return;
  if ((dwMsgSize) <= 0)
    return;

  if (m_pClientList[iClientH]->m_iAdminUserLevel < m_iAdminLevelWeather) {
    SendNotifyMsg(0, iClientH, DEF_NOTIFY_ADMINUSERLEVELLOW, 0, 0, 0, 0);
    return;
  }

  ZeroMemory(cBuff, sizeof(cBuff));
  memcpy(cBuff, pData, dwMsgSize);

  pStrTok = new class CStrTok(cBuff, seps);
  token = pStrTok->pGet();
  token = pStrTok->pGet();

  if (token == 0) {
    delete pStrTok;
    return;
  }

  sType = atoi(token);

  token = pStrTok->pGet();

  if (token == 0) {
    delete pStrTok;
    return;
  }

  sTime = atoi(token);

  delete pStrTok;

  for (i = 0; i < DEF_MAXMAPS; i++) {
    if ((m_pMapList[i] != 0) && (m_pMapList[i]->m_bIsFixedDayMode == false)) {
      cPrevMode = m_pMapList[i]->m_cWhetherStatus;
      if (m_pMapList[i]->m_cWhetherStatus != 0) {
        if ((dwTime - m_pMapList[i]->m_dwWhetherStartTime) >
            m_pMapList[i]->m_dwWhetherLastTime)
          m_pMapList[i]->m_cWhetherStatus = 0;
      } else {
        sTime *= 1000;
        m_pMapList[i]->m_cWhetherStatus = sType;
        m_pMapList[i]->m_dwWhetherStartTime = dwTime;
        m_pMapList[i]->m_dwWhetherLastTime = sTime;
      }
      if (cPrevMode != m_pMapList[i]->m_cWhetherStatus) {
        for (j = 1; j < DEF_MAXCLIENTS; j++)
          if ((m_pClientList[j] != 0) &&
              (m_pClientList[j]->m_bIsInitComplete) &&
              (m_pClientList[j]->m_cMapIndex == i))
            SendNotifyMsg(0, j, DEF_NOTIFY_WHETHERCHANGE,
                          m_pMapList[i]->m_cWhetherStatus, 0, 0, 0);
      }
    }
  }
}

void CGame::RequestChangePlayMode(int iClientH) {

  if (m_pClientList[iClientH] == 0)
    return;
  if (m_pClientList[iClientH]->m_iPKCount > 0)
    return;
  if (m_pClientList[iClientH]->m_bIsInitComplete == false)
    return;

  if (memcmp(m_pClientList[iClientH]->m_cMapName, "cityhall", 8) != 0)
    return;

  if (m_pClientList[iClientH]->m_iLevel < 100 ||
      m_pClientList[iClientH]->m_bIsPlayerCivil) {
    if (memcmp(m_pClientList[iClientH]->m_cLocation, "aresden", 7) == 0)
      strcpy(m_pClientList[iClientH]->m_cLocation, "arehunter");
    else if (memcmp(m_pClientList[iClientH]->m_cLocation, "elvine", 6) == 0)
      strcpy(m_pClientList[iClientH]->m_cLocation, "elvhunter");
    else if (memcmp(m_pClientList[iClientH]->m_cLocation, "arehunter", 9) == 0)
      strcpy(m_pClientList[iClientH]->m_cLocation, "aresden");
    else if (memcmp(m_pClientList[iClientH]->m_cLocation, "elvhunter", 9) == 0)
      strcpy(m_pClientList[iClientH]->m_cLocation, "elvine");

    if (m_pClientList[iClientH]->m_bIsPlayerCivil)
      m_pClientList[iClientH]->m_bIsPlayerCivil = false;
    else
      m_pClientList[iClientH]->m_bIsPlayerCivil = true;

    SendNotifyMsg(0, iClientH, DEF_NOTIFY_CHANGEPLAYMODE, 0, 0, 0,
                  m_pClientList[iClientH]->m_cLocation);
    SendEventToNearClient_TypeA(iClientH, DEF_OWNERTYPE_PLAYER,
                                MSGID_EVENT_MOTION, 100, 0, 0, 0);
  }

  g_login->LocalSavePlayerData(iClientH);
}

void CGame::AdminOrder_SetStatus(int iClientH, char *pData, DWORD dwMsgSize) {
  char seps[] = "= \t\n";
  char *token, *token2, cBuff[256];
  int iPass;
  class CStrTok *pStrTok;

  if (m_pClientList[iClientH] == 0)
    return;
  if ((dwMsgSize) <= 0)
    return;

  if (m_pClientList[iClientH]->m_iAdminUserLevel < m_iAdminLevelSetStatus) {
    // Admin user level脌脤 鲁路戮脝录颅 脌脤 卤芒麓脡脌禄 禄莽驴毛脟脪 录枚
    // 戮酶麓脵.
    SendNotifyMsg(0, iClientH, DEF_NOTIFY_ADMINUSERLEVELLOW, 0, 0, 0, 0);
    return;
  }

  ZeroMemory(cBuff, sizeof(cBuff));
  memcpy(cBuff, pData, dwMsgSize);

  pStrTok = new class CStrTok(cBuff, seps);
  token = pStrTok->pGet();
  token2 = pStrTok->pGet();

  iPass = (int)token;
  if (token != 0) {
    // 脌脤 掳陋脌脤 鹿庐脌脷 '1'脌脤赂茅 脜玫赂铆脌赂路脦 录录脝庐. '0'脌脤赂茅
    // 脟脴脕娄

    if (token[0] == '0') {
      SetPoisonFlag(iClientH, DEF_OWNERTYPE_PLAYER, false);
      SetIllusionFlag(iClientH, DEF_OWNERTYPE_PLAYER, false);
      SetDefenseShieldFlag(iClientH, DEF_OWNERTYPE_PLAYER, false);
      SetMagicProtectionFlag(iClientH, DEF_OWNERTYPE_PLAYER, false);
      SetProtectionFromArrowFlag(iClientH, DEF_OWNERTYPE_PLAYER, false);
      SetIllusionMovementFlag(iClientH, DEF_OWNERTYPE_PLAYER, false);
      SetInhibitionCastingFlag(iClientH, DEF_OWNERTYPE_PLAYER, false);
      SetHeroFlag(iClientH, DEF_OWNERTYPE_PLAYER, false);
    }
    if (token[0] == '1') {
      SetPoisonFlag(iClientH, DEF_OWNERTYPE_PLAYER, true);
    }
    if (token[0] == '2') {
      SetIllusionFlag(iClientH, DEF_OWNERTYPE_PLAYER, true);
    }
    if (token[0] == '3') {
      SetDefenseShieldFlag(iClientH, DEF_OWNERTYPE_PLAYER, true);
    }
    if (token[0] == '4') {
      SetMagicProtectionFlag(iClientH, DEF_OWNERTYPE_PLAYER, true);
    }
    if (token[0] == '5') {
      SetProtectionFromArrowFlag(iClientH, DEF_OWNERTYPE_PLAYER, true);
    }
    if (token[0] == '6') {
      SetIllusionMovementFlag(iClientH, DEF_OWNERTYPE_PLAYER, true);
    }
    if (token[0] == '7') {
      SetInhibitionCastingFlag(iClientH, DEF_OWNERTYPE_PLAYER, true);
    }
    if (token[0] == '8') {
      SetHeroFlag(iClientH, DEF_OWNERTYPE_PLAYER, true);
    }
  }
  delete pStrTok;
}

/*********************************************************************************************************************
**  void CGame::SetInvisibilityFlag(short sOwnerH, char cOwnerType, bool
* bStatus) 	**
**  description			:: changes the status of the player to show
* invisibility aura 	**
**  last updated		:: November 20, 2004; 9:30 PM; Hypnotoad
*												**
**	return value		:: void
*																**
*********************************************************************************************************************/
void CGame::SetInvisibilityFlag(short sOwnerH, char cOwnerType, bool bStatus) {
  switch (cOwnerType) {
  case DEF_OWNERTYPE_PLAYER:
    if (m_pClientList[sOwnerH] == 0)
      return;
    if (bStatus)
      m_pClientList[sOwnerH]->m_iStatus =
          m_pClientList[sOwnerH]->m_iStatus | 0x00000010;
    else
      m_pClientList[sOwnerH]->m_iStatus =
          m_pClientList[sOwnerH]->m_iStatus & 0xFFFFFFEF;
    SendEventToNearClient_TypeA(sOwnerH, DEF_OWNERTYPE_PLAYER,
                                MSGID_EVENT_MOTION, DEF_OBJECTNULLACTION, 0, 0,
                                0);
    break;

  case DEF_OWNERTYPE_NPC:
    if (m_pNpcList[sOwnerH] == 0)
      return;
    if (bStatus)
      m_pNpcList[sOwnerH]->m_iStatus =
          m_pNpcList[sOwnerH]->m_iStatus | 0x00000010;
    else
      m_pNpcList[sOwnerH]->m_iStatus =
          m_pNpcList[sOwnerH]->m_iStatus & 0xFFFFFFEF;
    SendEventToNearClient_TypeA(sOwnerH, DEF_OWNERTYPE_NPC, MSGID_EVENT_MOTION,
                                DEF_OBJECTNULLACTION, 0, 0, 0);
    break;
  }
}

