// New 07/05/2004
void CGame::RequestGuildNameHandler(int iClientH, int iObjectID, int iIndex) {
  if (m_pClientList[iClientH] == 0)
    return;
  if ((iObjectID <= 0) || (iObjectID >= DEF_MAXCLIENTS))
    return;

  if (m_pClientList[iObjectID] == 0) {
    // 驴盲脙禄 鹿脼脌潞 Object掳隆 戮酶麓脵.

  } else {
    SendNotifyMsg(0, iClientH, DEF_NOTIFY_REQGUILDNAMEANSWER,
                  m_pClientList[iObjectID]->m_iGuildRank, iIndex, 0,
                  m_pClientList[iObjectID]->m_cGuildName);
  }
}

// Item Logging
bool CGame::_bItemLog(int iAction, int iGiveH, int iRecvH, class CItem *pItem,
                      bool bForceItemLog) {
  char cTxt[1024], cTemp1[120], cTemp2[120];
  int iItemCount;
  if (pItem == 0)
    return false;

  // !!脕脰脌脟 脟脩卤鹿驴隆 脌没驴毛脟脪露搂  New Item 脌脤 禄媒卤忙露搂麓脗
  // iGive掳隆 鲁脦脌脧录枚 脌脰麓脵.
  if (m_pClientList[iGiveH]->m_cCharName == 0)
    return false;

  if (iAction == DEF_ITEMLOG_DUPITEMID) {
    // 潞鹿禄莽碌脠 戮脝脌脤脜脹 脌煤脌氓 驴盲脙禄脌脤麓脵.
    if (m_pClientList[iGiveH] == 0)
      return false;
    if (m_pClientList[iGiveH]->m_cCharName == 0)
      return false;
    wsprintf(G_cTxt, "(!) Delete-DupItem(%s %d %d %d %d) Owner(%s)",
             pItem->m_cName, pItem->m_dwCount, pItem->m_sTouchEffectValue1,
             pItem->m_sTouchEffectValue2, pItem->m_sTouchEffectValue3,
             m_pClientList[iGiveH]->m_cCharName);
    //	PutItemLogFileList(iGiveH,G_cTxt);
    bSendMsgToLS(MSGID_GAMEITEMLOG, iGiveH, 0, G_cTxt);
    return true;
  }

  ZeroMemory(cTxt, sizeof(cTxt));
  ZeroMemory(cTemp1, sizeof(cTemp1));
  ZeroMemory(cTemp2, sizeof(cTemp2));

  switch (iAction) {

  case DEF_ITEMLOG_EXCHANGE:
    if (m_pClientList[iRecvH]->m_cCharName == 0)
      return false;
    wsprintf(
        cTxt, "(%s) PC(%s)\tExchange\t%s(%d %d %d %d %x)\t%s(%d %d)\tPC(%s)",
        m_pClientList[iGiveH]->m_cIPaddress, m_pClientList[iGiveH]->m_cCharName,
        pItem->m_cName, pItem->m_dwCount, pItem->m_sTouchEffectValue1,
        pItem->m_sTouchEffectValue2, pItem->m_sTouchEffectValue3,
        pItem->m_dwAttribute, m_pClientList[iGiveH]->m_cMapName,
        m_pClientList[iGiveH]->m_sX, m_pClientList[iGiveH]->m_sY,
        m_pClientList[iRecvH]->m_cCharName);
    PutItemLogFileList(cTxt);
    break;

  case DEF_ITEMLOG_GIVE:
    if (m_pClientList[iRecvH]->m_cCharName == 0)
      return false;
    wsprintf(cTxt, "(%s) PC(%s)\tGive\t%s(%d %d %d %d %x)\t%s(%d %d)\tPC(%s)",
             m_pClientList[iGiveH]->m_cIPaddress,
             m_pClientList[iGiveH]->m_cCharName, pItem->m_cName,
             pItem->m_dwCount, pItem->m_sTouchEffectValue1,
             pItem->m_sTouchEffectValue2, pItem->m_sTouchEffectValue3,
             pItem->m_dwAttribute, m_pClientList[iGiveH]->m_cMapName,
             m_pClientList[iGiveH]->m_sX, m_pClientList[iGiveH]->m_sY,
             m_pClientList[iRecvH]->m_cCharName);
    PutItemLogFileList(cTxt);
    break;

  case DEF_ITEMLOG_DROP:
    wsprintf(cTxt, "(%s) PC(%s)\tDrop\t%s(%d %d %d %d %x)\t%s(%d %d)",
             m_pClientList[iGiveH]->m_cIPaddress,
             m_pClientList[iGiveH]->m_cCharName, pItem->m_cName,
             pItem->m_dwCount, pItem->m_sTouchEffectValue1,
             pItem->m_sTouchEffectValue2, pItem->m_sTouchEffectValue3,
             pItem->m_dwAttribute, m_pClientList[iGiveH]->m_cMapName,
             m_pClientList[iGiveH]->m_sX, m_pClientList[iGiveH]->m_sY);
    PutItemLogFileList(cTxt);
    break;

  case DEF_ITEMLOG_GET:
    wsprintf(cTxt, "(%s) PC(%s)\tGet\t%s(%d %d %d %d %x)\t%s(%d %d)",
             m_pClientList[iGiveH]->m_cIPaddress,
             m_pClientList[iGiveH]->m_cCharName, pItem->m_cName,
             pItem->m_dwCount, pItem->m_sTouchEffectValue1,
             pItem->m_sTouchEffectValue2, pItem->m_sTouchEffectValue3,
             pItem->m_dwAttribute, m_pClientList[iGiveH]->m_cMapName,
             m_pClientList[iGiveH]->m_sX, m_pClientList[iGiveH]->m_sY);
    PutItemLogFileList(cTxt);
    break;

  case DEF_ITEMLOG_MAKE:
    wsprintf(cTxt, "(%s) PC(%s)\tMake\t%s(%d %d %d %d %x)\t%s(%d %d)",
             m_pClientList[iGiveH]->m_cIPaddress,
             m_pClientList[iGiveH]->m_cCharName, pItem->m_cName,
             pItem->m_dwCount, pItem->m_sTouchEffectValue1,
             pItem->m_sTouchEffectValue2, pItem->m_sTouchEffectValue3,
             pItem->m_dwAttribute, m_pClientList[iGiveH]->m_cMapName,
             m_pClientList[iGiveH]->m_sX, m_pClientList[iGiveH]->m_sY);
    PutItemLogFileList(cTxt);
    break;

  case DEF_ITEMLOG_DEPLETE:
    wsprintf(cTxt, "(%s) PC(%s)\tDeplete\t%s(%d %d %d %d %x)\t%s(%d %d)",
             m_pClientList[iGiveH]->m_cIPaddress,
             m_pClientList[iGiveH]->m_cCharName, pItem->m_cName,
             pItem->m_dwCount, pItem->m_sTouchEffectValue1,
             pItem->m_sTouchEffectValue2, pItem->m_sTouchEffectValue3,
             pItem->m_dwAttribute, m_pClientList[iGiveH]->m_cMapName,
             m_pClientList[iGiveH]->m_sX, m_pClientList[iGiveH]->m_sY);
    PutItemLogFileList(cTxt);
    break;

  case DEF_ITEMLOG_BUY:
    iItemCount = iRecvH;
    wsprintf(cTxt, "(%s) PC(%s)\tBuy\t%s(%d %d %d %d %x)\t%s(%d %d)",
             m_pClientList[iGiveH]->m_cIPaddress,
             m_pClientList[iGiveH]->m_cCharName, pItem->m_cName, iItemCount,
             pItem->m_sTouchEffectValue1, pItem->m_sTouchEffectValue2,
             pItem->m_sTouchEffectValue3, pItem->m_dwAttribute,
             m_pClientList[iGiveH]->m_cMapName, m_pClientList[iGiveH]->m_sX,
             m_pClientList[iGiveH]->m_sY);
    PutItemLogFileList(cTxt);
    break;

  case DEF_ITEMLOG_SELL:
    wsprintf(cTxt, "(%s) PC(%s)\tSell\t%s(%d %d %d %d %x)\t%s(%d %d)",
             m_pClientList[iGiveH]->m_cIPaddress,
             m_pClientList[iGiveH]->m_cCharName, pItem->m_cName,
             pItem->m_dwCount, pItem->m_sTouchEffectValue1,
             pItem->m_sTouchEffectValue2, pItem->m_sTouchEffectValue3,
             pItem->m_dwAttribute, m_pClientList[iGiveH]->m_cMapName,
             m_pClientList[iGiveH]->m_sX, m_pClientList[iGiveH]->m_sY);
    PutItemLogFileList(cTxt);
    break;

  case DEF_ITEMLOG_RETRIEVE:
    wsprintf(cTxt, "(%s) PC(%s)\tRetrieve\t%s(%d %d %d %d %x)\t%s(%d %d)",
             m_pClientList[iGiveH]->m_cIPaddress,
             m_pClientList[iGiveH]->m_cCharName, pItem->m_cName,
             pItem->m_dwCount, pItem->m_sTouchEffectValue1,
             pItem->m_sTouchEffectValue2, pItem->m_sTouchEffectValue3,
             pItem->m_dwAttribute, m_pClientList[iGiveH]->m_cMapName,
             m_pClientList[iGiveH]->m_sX, m_pClientList[iGiveH]->m_sY);
    PutItemLogFileList(cTxt);
    break;

  case DEF_ITEMLOG_DEPOSIT:
    wsprintf(cTxt, "(%s) PC(%s)\tDeposit\t%s(%d %d %d %d %x)\t%s(%d %d)",
             m_pClientList[iGiveH]->m_cIPaddress,
             m_pClientList[iGiveH]->m_cCharName, pItem->m_cName,
             pItem->m_dwCount, pItem->m_sTouchEffectValue1,
             pItem->m_sTouchEffectValue2, pItem->m_sTouchEffectValue3,
             pItem->m_dwAttribute, m_pClientList[iGiveH]->m_cMapName,
             m_pClientList[iGiveH]->m_sX, m_pClientList[iGiveH]->m_sY);
    PutItemLogFileList(cTxt);
    break;

  case DEF_ITEMLOG_UPGRADEFAIL:
    wsprintf(cTxt, "(%s) PC(%s)\tUpgrade Fail\t%s(%d %d %d %d %x)\t%s(%d %d)",
             m_pClientList[iGiveH]->m_cIPaddress,
             m_pClientList[iGiveH]->m_cCharName, pItem->m_cName,
             pItem->m_dwCount, pItem->m_sTouchEffectValue1,
             pItem->m_sTouchEffectValue2, pItem->m_sTouchEffectValue3,
             pItem->m_dwAttribute, m_pClientList[iGiveH]->m_cMapName,
             m_pClientList[iGiveH]->m_sX, m_pClientList[iGiveH]->m_sY);
    PutItemLogFileList(cTxt);
    break;

  case DEF_ITEMLOG_UPGRADESUCCESS:
    wsprintf(
        cTxt, "(%s) PC(%s)\tUpgrade Success\t%s(%d %d %d %d %x)\t%s(%d %d)",
        m_pClientList[iGiveH]->m_cIPaddress, m_pClientList[iGiveH]->m_cCharName,
        pItem->m_cName, pItem->m_dwCount, pItem->m_sTouchEffectValue1,
        pItem->m_sTouchEffectValue2, pItem->m_sTouchEffectValue3,
        pItem->m_dwAttribute, m_pClientList[iGiveH]->m_cMapName,
        m_pClientList[iGiveH]->m_sX, m_pClientList[iGiveH]->m_sY);
    PutItemLogFileList(cTxt);
    break;
  default:
    return false;
  }
  bSendMsgToLS(MSGID_GAMEITEMLOG, iGiveH, 0, cTxt);
  return true;
}

bool CGame::_bItemLog(int iAction, int iClientH, char *cName,
                      class CItem *pItem) {
  if (pItem == 0)
    return false;
  if (_bCheckGoodItem(pItem) == false)
    return false;
  if (iAction != DEF_ITEMLOG_NEWGENDROP) {
    if (m_pClientList[iClientH] == 0)
      return false;
  }
  char cTxt[200], cTemp1[120];
  //  路脦卤脳 鲁虏卤盲麓脵.
  ZeroMemory(cTxt, sizeof(cTxt));
  ZeroMemory(cTemp1, sizeof(cTemp1));
  if (m_pClientList[iClientH] != 0)
    m_pClientList[iClientH]->m_pXSock->iGetPeerAddress(cTemp1);

  switch (iAction) {

  case DEF_ITEMLOG_NEWGENDROP:
    if (pItem == 0)
      return false;
    wsprintf(cTxt, "NPC(%s)\tDrop\t%s(%d %d %d %d)", cName, pItem->m_cName,
             pItem->m_dwCount, pItem->m_sTouchEffectValue1,
             pItem->m_sTouchEffectValue2, pItem->m_sTouchEffectValue3);
    PutItemLogFileList(cTxt);
    break;
  case DEF_ITEMLOG_SKILLLEARN:
  case DEF_ITEMLOG_MAGICLEARN:
    if (cName == 0)
      return false;
    if (m_pClientList[iClientH] == 0)
      return false;
    wsprintf(cTxt, "PC(%s)\tLearn\t(%s)\t%s(%d %d)\t \tIP(%s)",
             m_pClientList[iClientH]->m_cCharName, cName,
             m_pClientList[iClientH]->m_cMapName, m_pClientList[iClientH]->m_sX,
             m_pClientList[iClientH]->m_sY, cTemp1);
    PutItemLogFileList(cTxt);
    break;
  case DEF_ITEMLOG_SUMMONMONSTER:
    if (cName == 0)
      return false;
    if (m_pClientList[iClientH] == 0)
      return false;
    wsprintf(cTxt, "PC(%s)\tSummon\t(%s)\t%s(%d %d)\t \tIP(%s)",
             m_pClientList[iClientH]->m_cCharName, cName,
             m_pClientList[iClientH]->m_cMapName, m_pClientList[iClientH]->m_sX,
             m_pClientList[iClientH]->m_sY, cTemp1);
    break;
  case DEF_ITEMLOG_POISONED:
    if (m_pClientList[iClientH] == 0)
      return false;
    wsprintf(cTxt, "PC(%s)\tBe Poisoned\t \t%s(%d %d)\t \tIP(%s)",
             m_pClientList[iClientH]->m_cCharName,
             m_pClientList[iClientH]->m_cMapName, m_pClientList[iClientH]->m_sX,
             m_pClientList[iClientH]->m_sY, cTemp1);
    break;

  case DEF_ITEMLOG_REPAIR:
    if (cName == 0)
      return false;
    if (m_pClientList[iClientH] == 0)
      return false;
    wsprintf(cTxt, "PC(%s)\tRepair\t(%s)\t%s(%d %d)\t \tIP(%s)",
             m_pClientList[iClientH]->m_cCharName, cName,
             m_pClientList[iClientH]->m_cMapName, m_pClientList[iClientH]->m_sX,
             m_pClientList[iClientH]->m_sY, cTemp1);
    break;

  default:
    return false;
  }
  bSendMsgToLS(MSGID_GAMEITEMLOG, iClientH, 0, cTxt);
  return true;
}

