void CGame::GetExp(int iClientH, DWORD iExp, bool bIsAttackerOwn) {
  double dV1, dV2, dV3;
  int i, iH;
  DWORD dwTime = timeGetTime(), iUnitValue;
  int iTotalPartyMembers;

  if (m_pClientList[iClientH] == 0)
    return;
  if (iExp <= 0)
    return;

  if (m_pClientList[iClientH]->m_iLevel <= 80) {
    dV1 = (double)(80 - m_pClientList[iClientH]->m_iLevel);
    dV2 = dV1 * 0.025f;
    dV3 = (double)iExp;
    dV1 = (dV2 + 1.025f) * dV3;
    iExp = (DWORD)dV1;
  } else { // Lower exp
    if ((m_pClientList[iClientH]->m_iLevel >= 80) &&
        ((strcmp(m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->m_cName,
                 "aresdend1") == 0) ||
         (strcmp(m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->m_cName,
                 "elvined1") == 0))) {
      iExp = (iExp / 10);
    } else if ((strcmp(
                    m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->m_cName,
                    "aresdend1") == 0) ||
               (strcmp(
                    m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->m_cName,
                    "elvined1") == 0)) {
      iExp = (iExp * 1 / 4);
    }
  }

  // Check for party status, else give exp to player
  if ((m_pClientList[iClientH]->m_iPartyID != 0) &&
      (m_pClientList[iClientH]->m_iPartyStatus == DEF_PARTYSTATUS_CONFIRM)) {
    // Only divide exp if >= 1 person
    if (m_stPartyInfo[m_pClientList[iClientH]->m_iPartyID].iTotalMembers > 0) {

      // Calc total ppl in party
      iTotalPartyMembers = 0;
      for (i = 0;
           i < m_stPartyInfo[m_pClientList[iClientH]->m_iPartyID].iTotalMembers;
           i++) {
        iH = m_stPartyInfo[m_pClientList[iClientH]->m_iPartyID].iIndex[i];
        if ((m_pClientList[iH] != 0) && (m_pClientList[iH]->m_iHP > 0)) {
          // Newly added, Only players on same map get exp :}
          if ((strlen(m_pMapList[m_pClientList[iH]->m_cMapIndex]->m_cName)) ==
              (strlen(
                  m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->m_cName))) {
            if (memcmp(
                    m_pMapList[m_pClientList[iH]->m_cMapIndex]->m_cName,
                    m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->m_cName,
                    strlen(m_pMapList[m_pClientList[iClientH]->m_cMapIndex]
                               ->m_cName)) == 0) {
              iTotalPartyMembers++;
            }
          }
        }
      }

      // Check for party bug
      if (iTotalPartyMembers > DEF_MAXPARTYMEMBERS) {
        wsprintf(G_cTxt, "(X) Party Bug !! partyMember %d XXXXXXXXXX",
                 iTotalPartyMembers);
        PutLogFileList(G_cTxt);
        iTotalPartyMembers = DEF_MAXPARTYMEMBERS;
      }

      // Figure out how much exp a player gets
      dV1 = (double)iExp;
      dV2 = dV1;

      if (iTotalPartyMembers > 1) {
        dV2 =
            (dV1 + (dV1 * (double)(iTotalPartyMembers / DEF_MAXPARTYMEMBERS))) /
            (double)iTotalPartyMembers;
      }

      dV3 = dV2 + 5.0e-1;
      iUnitValue = (DWORD)dV3;

      // Divide exp among party members
      for (i = 0; i < iTotalPartyMembers; i++) {

        iH = m_stPartyInfo[m_pClientList[iClientH]->m_iPartyID].iIndex[i];
        if ((m_pClientList[iH] != 0) &&
            (m_pClientList[iH]->m_bSkillUsingStatus[19] != 1) &&
            (m_pClientList[iH]->m_iHP > 0)) { // Is player alive ??
          if ((m_pClientList[iH]->m_iStatus & 0x10000) != 0)
            iUnitValue *= 3;
          m_pClientList[iH]->m_iExpStock += iUnitValue;
        }
      }
    }
  } else {
    if ((m_pClientList[iClientH] != 0) &&
        (m_pClientList[iClientH]->m_bSkillUsingStatus[19] != 1) &&
        (m_pClientList[iClientH]->m_iHP > 0)) { // Is player alive ??
      if ((m_pClientList[iClientH]->m_iStatus & 0x10000) != 0)
        iExp *= 3;
      m_pClientList[iClientH]->m_iExpStock += iExp;
    }
  }
}

