void CGame::AdminOrder_SummonGuild(int iClientH, char *pData, DWORD dwMsgSize) {
  char seps[] = "= \t\n";
  char *cBuff[256], cLocation[11];
  int pX, pY, i;
  // class  CStrTok * pStrTok;
  char buff[100];
  if (m_pClientList[iClientH] == 0)
    return;
  if ((dwMsgSize) <= 0)
    return;

  // if (m_pClientList[iClientH]->m_iAdminUserLevel < 3) {
  //  Admin user level+a+t T-T��+奣-T� +a+t T-+?T++U+aTC TC+譚C+c+�+n T-+T
  //  T�+琓++�.
  //  SendNotifyMsg(0, iClientH, DEF_NOTIFY_ADMINUSERLEVELLOW, 0, 0, 0, 0);
  // return;
  //}

  ZeroMemory(cBuff, sizeof(cBuff));
  memcpy(cBuff, pData, dwMsgSize);

  pX = m_pClientList[iClientH]->m_sX;
  pY = m_pClientList[iClientH]->m_sY;
  memcpy(cLocation, m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->m_cName,
         11);
  wsprintf(buff, "Summon-Guild: %s (%s) %s %d %d",
           m_pClientList[iClientH]->m_cCharName,
           m_pClientList[iClientH]->m_cGuildName, cLocation, pX, pY);
  PutLogList(buff);
  for (i = 0; i < DEF_MAXCLIENTS; i++)

    if ((m_pClientList[i] != 0) &&
        (strcmp(m_pClientList[i]->m_cGuildName,
                m_pClientList[iClientH]->m_cGuildName) == 0) &&
        (i != iClientH)) {
      RequestTeleportHandler(i, "2   ", cLocation, pX, pY);
    } // m_pClientList[i]->m_cCharName
  // delete pStrTok;
}

