void CGame::Command_RedBall(int iClientH, char *pData, DWORD dwMsgSize) {
  char seps[] = "= \t\n", cName[21], cNpcName[21], cNpcWaypoint[11];
  int iNamingValue, tX, tY, i, x, iNpcID;
  int iSoxH, iSoX;

  if (m_pClientList[iClientH] == 0)
    return;
  if ((memcmp(m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->m_cName,
              "huntzone1", 9) != 0) &&
      (memcmp(m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->m_cName,
              "huntzone2", 9) != 0) &&
      (memcmp(m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->m_cName,
              "huntzone3", 9) != 0) &&
      (memcmp(m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->m_cName,
              "huntzone4", 9) != 0))
    return;

  iSoX = 0;
  for (i = 0; i < DEF_MAXITEMS; i++)
    if (m_pClientList[iClientH]->m_pItemList[i] != 0) {
      switch (m_pClientList[iClientH]->m_pItemList[i]->m_sIDnum) {
      case 652:
        iSoX++;
        iSoxH = i;
        break; // 胶沛 坷宏 力府付
      }
    }
  if (iSoX > 0) {
    iNamingValue = m_pMapList[m_pClientList[iClientH]->m_cMapIndex]
                       ->iGetEmptyNamingValue();
    if (iNamingValue == -1) {

    } else {

      ZeroMemory(cNpcName, sizeof(cNpcName));
      switch (iDice(1, 5)) {
      case 1:
        strcpy(cNpcName, "Wyvern");
        iNpcID = 66;
        break;
      case 2:
        strcpy(cNpcName, "Hellclaw");
        iNpcID = 49;
        break;
      case 3:
        strcpy(cNpcName, "Fire-Wyvern");
        iNpcID = 73;
        break;
      case 4:
        strcpy(cNpcName, "Tigerworm");
        iNpcID = 50;
        break;
      case 5:
        strcpy(cNpcName, "Gagoyle");
        iNpcID = 52;
        break;
      }
      ZeroMemory(cName, sizeof(cName));
      wsprintf(cName, "XX%d", iNamingValue);
      cName[0] = '_';
      cName[1] = m_pClientList[iClientH]->m_cMapIndex + 65;

      ZeroMemory(cNpcWaypoint, sizeof(cNpcWaypoint));

      tX = (int)m_pClientList[iClientH]->m_sX;
      tY = (int)m_pClientList[iClientH]->m_sY;
      if (bCreateNewNpc(
              cNpcName, cName,
              m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->m_cName, 0,
              (rand() % 9), DEF_MOVETYPE_RANDOM, &tX, &tY, cNpcWaypoint, 0, 0,
              -1, false, false) == false) {
        m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->SetNamingValueEmpty(
            iNamingValue);
      } else {
        wsprintf(G_cTxt, "(%s) Player: (%s) - RedBall used %s [%s(%d, %d)] ",
                 m_pClientList[iClientH]->m_cIPaddress,
                 m_pClientList[iClientH]->m_cCharName, cNpcName,
                 m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->m_cName, tX,
                 tY);
        PutItemLogFileList(G_cTxt);
      }
    }

    for (x = 1; x < DEF_MAXCLIENTS; x++)
      if ((m_pClientList[x] != 0) && (m_pClientList[x]->m_bIsInitComplete)) {
        SendNotifyMsg(0, x, DEF_NOTIFY_SPAWNEVENT, tX, tY, iNpcID, 0, 0, 0);
      }
    ItemDepleteHandler(iClientH, iSoxH, true);
  }
}

