// Party Code
void CGame::RequestCreatePartyHandler(int iClientH) {
  char *cp, cData[120];
  DWORD *dwp;
  WORD *wp;

  if (m_pClientList[iClientH] == 0)
    return;
  if (m_pClientList[iClientH]->m_bIsInitComplete == false)
    return;

  if (m_pClientList[iClientH]->m_iPartyStatus != DEF_PARTYSTATUS_NULL) {
    // 脝脛脝录 禄贸脜脗掳隆 脌脤鹿脤 脕赂脌莽脟脧赂茅 脝脛脝录赂娄 赂赂碌茅
    // 录枚 戮酶麓脵.
    return;
  }

  m_pClientList[iClientH]->m_iPartyStatus = DEF_PARTYSTATUS_PROCESSING;

  // Gate Server驴隆 脝脛脝录 禄媒录潞脠脛 PartyID赂娄 戮脣路脕脕脵 掳脥脌禄
  // 驴盲脙禄脟脩麓脵.
  ZeroMemory(cData, sizeof(cData));
  cp = (char *)cData;

  /*dwp = (DWORD *)cp;
  *dwp = MSGID_PARTYOPERATION;
  cp += 4;*/
  wp = (WORD *)cp;
  *wp = 1; // 1, request
  cp += 2;

  wp = (WORD *)cp;
  *wp = iClientH;
  cp += 2;

  memcpy(cp, m_pClientList[iClientH]->m_cCharName, 10);
  cp += 10;

  PartyOperation(
      cData); // SendMsgToGateServer(MSGID_PARTYOPERATION, iClientH, cData);

  // testcode
  wsprintf(G_cTxt, "Request Create Party: %d", iClientH);
  PutLogList(G_cTxt);
}

// Last Updated October 28, 2004 - 3.51 translation
void CGame::PartyOperationResultHandler(char *pData) {
  char *cp, cResult, cName[12];
  WORD *wp;
  int i, iClientH, iPartyID, iTotal;

  cp = (char *)(pData);
  wp = (WORD *)cp;
  cp += 2;

  switch (*wp) {
  case 1:
    cResult = *cp;
    cp++;

    wp = (WORD *)cp;
    iClientH = (int)*wp;
    cp += 2;

    ZeroMemory(cName, sizeof(cName));
    memcpy(cName, cp, 10);
    cp += 10;

    wp = (WORD *)cp;
    iPartyID = (int)*wp;
    cp += 2;

    PartyOperationResult_Create(iClientH, cName, cResult, iPartyID);

    wsprintf(G_cTxt, "party Operation Result: Create(ClientH:%d PartyID:%d)",
             iClientH, iPartyID);
    PutLogList(G_cTxt);
    break;

  case 2:
    wp = (WORD *)cp;
    iPartyID = *wp;
    cp += 2;

    PartyOperationResult_Delete(iPartyID);

    wsprintf(G_cTxt, "party Operation Result: Delete(PartyID:%d)", iPartyID);
    PutLogList(G_cTxt);
    break;

  case 3:
    wp = (WORD *)cp;
    iClientH = *wp;
    cp += 2;

    ZeroMemory(cName, sizeof(cName));
    memcpy(cName, cp, 10);
    cp += 10;

    if ((iClientH < 0) && (iClientH > DEF_MAXCLIENTS))
      return;
    if (m_pClientList[iClientH] == 0)
      return;
    if (strcmp(m_pClientList[iClientH]->m_cCharName, cName) != 0)
      return;

    for (i = 0; i < DEF_MAXPARTYMEMBERS; i++)
      if (m_stPartyInfo[m_pClientList[iClientH]->m_iPartyID].iIndex[i] ==
          iClientH) {
        m_stPartyInfo[m_pClientList[iClientH]->m_iPartyID].iIndex[i] = 0;
        m_stPartyInfo[m_pClientList[iClientH]->m_iPartyID].iTotalMembers--;

        wsprintf(
            G_cTxt, "PartyID:%d member:%d Out(Clear) Total:%d",
            m_pClientList[iClientH]->m_iPartyID, iClientH,
            m_stPartyInfo[m_pClientList[iClientH]->m_iPartyID].iTotalMembers);
        PutLogList(G_cTxt);
        goto PORH_LOOPBREAK1;
      }
  PORH_LOOPBREAK1:

    for (i = 0; i < DEF_MAXPARTYMEMBERS - 1; i++)
      if ((m_stPartyInfo[m_pClientList[iClientH]->m_iPartyID].iIndex[i] == 0) &&
          (m_stPartyInfo[m_pClientList[iClientH]->m_iPartyID].iIndex[i + 1] !=
           0)) {
        m_stPartyInfo[m_pClientList[iClientH]->m_iPartyID].iIndex[i] =
            m_stPartyInfo[m_pClientList[iClientH]->m_iPartyID].iIndex[i + 1];
        m_stPartyInfo[m_pClientList[iClientH]->m_iPartyID].iIndex[i + 1] = 0;
      }

    m_pClientList[iClientH]->m_iPartyID = 0;
    m_pClientList[iClientH]->m_iPartyStatus = DEF_PARTYSTATUS_NULL;

    wsprintf(G_cTxt, "Party Status 0: %s",
             m_pClientList[iClientH]->m_cCharName);
    PutLogList(G_cTxt);

    SendNotifyMsg(0, iClientH, DEF_NOTIFY_PARTY, 8, 0, 0, 0);
    break;

  case 4:
    cResult = *cp;
    cp++;

    wp = (WORD *)cp;
    iClientH = (int)*wp;
    cp += 2;

    ZeroMemory(cName, sizeof(cName));
    memcpy(cName, cp, 10);
    cp += 10;

    wp = (WORD *)cp;
    iPartyID = (int)*wp;
    cp += 2;

    PartyOperationResult_Join(iClientH, cName, cResult, iPartyID);

    wsprintf(G_cTxt, "party Operation Result: Join(ClientH:%d PartyID:%d)",
             iClientH, iPartyID);
    PutLogList(G_cTxt);
    break;

  case 5:
    wp = (WORD *)cp;
    iClientH = (int)*wp;
    cp += 2;

    ZeroMemory(cName, sizeof(cName));
    memcpy(cName, cp, 10);
    cp += 10;

    wp = (WORD *)cp;
    iTotal = (int)*wp;
    cp += 2;

    PartyOperationResult_Info(iClientH, cName, iTotal, cp);

    wsprintf(G_cTxt, "party Operation Result: Info(ClientH:%d Total:%d)",
             iClientH, iTotal);
    PutLogList(G_cTxt);
    break;

  case 6:
    cResult = *cp;
    cp++;

    wp = (WORD *)cp;
    iClientH = (int)*wp;
    cp += 2;

    ZeroMemory(cName, sizeof(cName));
    memcpy(cName, cp, 10);
    cp += 10;

    wp = (WORD *)cp;
    iPartyID = (int)*wp;
    cp += 2;

    PartyOperationResult_Dismiss(iClientH, cName, cResult, iPartyID);

    wsprintf(G_cTxt, "party Operation Result: Dismiss(ClientH:%d PartyID:%d)",
             iClientH, iPartyID);
    PutLogList(G_cTxt);
    break;
  }
}

void CGame::PartyOperationResult_Create(int iClientH, char *pName, int iResult,
                                        int iPartyID) {
  char *cp, cData[120];
  DWORD *dwp;
  WORD *wp;
  int i;

  if (m_pClientList[iClientH] == 0)
    return;
  if (strcmp(m_pClientList[iClientH]->m_cCharName, pName) != 0)
    return;

  switch (iResult) {
  case 0: // 脝脛脝录 禄媒录潞 陆脟脝脨
    if (m_pClientList[iClientH]->m_iPartyStatus != DEF_PARTYSTATUS_PROCESSING)
      return;
    if (strcmp(m_pClientList[iClientH]->m_cCharName, pName) != 0)
      return;

    m_pClientList[iClientH]->m_iPartyID = 0;
    m_pClientList[iClientH]->m_iPartyStatus = DEF_PARTYSTATUS_NULL;
    m_pClientList[iClientH]->m_iReqJoinPartyClientH = 0;
    SendNotifyMsg(0, iClientH, DEF_NOTIFY_PARTY, 1, 0, 0, 0);
    break;

  case 1: // 脝脛脝录 禄媒录潞 录潞掳酶
    if (m_pClientList[iClientH]->m_iPartyStatus != DEF_PARTYSTATUS_PROCESSING)
      return;
    if (strcmp(m_pClientList[iClientH]->m_cCharName, pName) != 0)
      return;

    m_pClientList[iClientH]->m_iPartyID = iPartyID;
    m_pClientList[iClientH]->m_iPartyStatus = DEF_PARTYSTATUS_CONFIRM;
    SendNotifyMsg(0, iClientH, DEF_NOTIFY_PARTY, 1, 1, 0, 0);

    // 掳脭脌脫 录颅鹿枚脌脟 脝脛脝录 赂庐陆潞脝庐驴隆 碌卯路脧.
    for (i = 0; i < DEF_MAXPARTYMEMBERS; i++)
      if (m_stPartyInfo[m_pClientList[iClientH]->m_iPartyID].iIndex[i] == 0) {
        m_stPartyInfo[m_pClientList[iClientH]->m_iPartyID].iIndex[i] = iClientH;
        m_stPartyInfo[m_pClientList[iClientH]->m_iPartyID].iTotalMembers++;
        // testcode
        wsprintf(
            G_cTxt, "PartyID:%d member:%d New Total:%d",
            m_pClientList[iClientH]->m_iPartyID, iClientH,
            m_stPartyInfo[m_pClientList[iClientH]->m_iPartyID].iTotalMembers);
        PutLogList(G_cTxt);
        goto PORC_LOOPBREAK1;
      }
  PORC_LOOPBREAK1:

    // 赂赂戮脿 脝脛脝录 掳隆脌脭脌禄 陆脜脙禄脟脩 脟脙路鹿脌脤戮卯掳隆
    // 脌脰麓脵赂茅
    if ((m_pClientList[iClientH]->m_iReqJoinPartyClientH != 0) &&
        (strlen(m_pClientList[iClientH]->m_cReqJoinPartyName) != 0)) {
      ZeroMemory(cData, sizeof(cData));
      cp = (char *)cData;
      /*dwp = (DWORD *)cp;
      *dwp = MSGID_PARTYOPERATION;
      cp += 4;*/
      wp = (WORD *)cp;
      *wp = 3; // 脝脛脝录 赂芒鹿枚 脙脽掳隆 驴盲脙禄
      cp += 2;
      wp = (WORD *)cp;
      *wp = m_pClientList[iClientH]->m_iReqJoinPartyClientH;
      cp += 2;
      memcpy(cp, m_pClientList[iClientH]->m_cReqJoinPartyName, 10);
      cp += 10;
      wp = (WORD *)cp;
      *wp = m_pClientList[iClientH]->m_iPartyID;
      cp += 2;
      PartyOperation(
          cData); // SendMsgToGateServer(MSGID_PARTYOPERATION, iClientH, cData);
      // 赂脼陆脙脕枚赂娄 潞赂鲁脗脌赂麓脧 脜卢赂庐戮卯
      m_pClientList[iClientH]->m_iReqJoinPartyClientH = 0;
      ZeroMemory(m_pClientList[iClientH]->m_cReqJoinPartyName,
                 sizeof(m_pClientList[iClientH]->m_cReqJoinPartyName));
    }
    break;
  }
}

// Last Updated October 28, 2004 - 3.51 translation
void CGame::PartyOperationResult_Join(int iClientH, char *pName, int iResult,
                                      int iPartyID) {
  int i;

  if (m_pClientList[iClientH] == 0)
    return;

  switch (iResult) {
  case 0:
    if (m_pClientList[iClientH]->m_iPartyStatus != DEF_PARTYSTATUS_PROCESSING)
      return;
    if (strcmp(m_pClientList[iClientH]->m_cCharName, pName) != 0)
      return;

    m_pClientList[iClientH]->m_iPartyID = 0;
    m_pClientList[iClientH]->m_iPartyStatus = DEF_PARTYSTATUS_NULL;
    SendNotifyMsg(0, iClientH, DEF_NOTIFY_PARTY, 4, 0, 0, pName);

    m_pClientList[iClientH]->m_iReqJoinPartyClientH = 0;
    ZeroMemory(m_pClientList[iClientH]->m_cReqJoinPartyName,
               sizeof(m_pClientList[iClientH]->m_cReqJoinPartyName));
    break;

  case 1:
    if (m_pClientList[iClientH]->m_iPartyStatus != DEF_PARTYSTATUS_PROCESSING)
      return;
    if (strcmp(m_pClientList[iClientH]->m_cCharName, pName) != 0)
      return;

    m_pClientList[iClientH]->m_iPartyID = iPartyID;
    m_pClientList[iClientH]->m_iPartyStatus = DEF_PARTYSTATUS_CONFIRM;
    SendNotifyMsg(0, iClientH, DEF_NOTIFY_PARTY, 4, 1, 0, pName);

    m_pClientList[iClientH]->m_iReqJoinPartyClientH = 0;
    ZeroMemory(m_pClientList[iClientH]->m_cReqJoinPartyName,
               sizeof(m_pClientList[iClientH]->m_cReqJoinPartyName));

    for (i = 0; i < DEF_MAXPARTYMEMBERS; i++)
      if (m_stPartyInfo[m_pClientList[iClientH]->m_iPartyID].iIndex[i] == 0) {
        m_stPartyInfo[m_pClientList[iClientH]->m_iPartyID].iIndex[i] = iClientH;
        m_stPartyInfo[m_pClientList[iClientH]->m_iPartyID].iTotalMembers++;

        wsprintf(
            G_cTxt, "PartyID:%d member:%d In(Join) Total:%d",
            m_pClientList[iClientH]->m_iPartyID, iClientH,
            m_stPartyInfo[m_pClientList[iClientH]->m_iPartyID].iTotalMembers);
        PutLogList(G_cTxt);
        goto PORC_LOOPBREAK1;
      }
  PORC_LOOPBREAK1:

    for (i = 1; i < DEF_MAXCLIENTS; i++)
      if ((i != iClientH) && (m_pClientList[i] != 0) &&
          (m_pClientList[i]->m_iPartyID != 0) &&
          (m_pClientList[i]->m_iPartyID == iPartyID)) {
        SendNotifyMsg(0, i, DEF_NOTIFY_PARTY, 4, 1, 0, pName);
      }
    break;
  }
}

void CGame::PartyOperationResult_Dismiss(int iClientH, char *pName, int iResult,
                                         int iPartyID) {
  int i;
  // iClientH麓脗 脌脤鹿脤 禄莽露贸脕枚掳铆 戮酶麓脗 脛鲁赂炉脜脥脌脧录枚碌碌
  // 脌脰麓脵.

  switch (iResult) {
  case 0: // 脝脛脝录 脜禄脜冒 陆脟脝脨 ? 脌脤路卤 脌脧脌脤?
    break;

  case 1: // 脝脛脝录 脜禄脜冒 录潞掳酶
    if (iClientH == 0) {
      // iClientH 掳隆 NULL脌脤赂茅 录颅鹿枚 脌脤碌驴脕脽 脕垄录脫
      // 脕戮路谩碌脟戮卯 掳颅脕娄 脕娄掳脜 驴盲脙禄碌脠 掳脥脌脫.
      for (i = 1; i < DEF_MAXCLIENTS; i++)
        if ((m_pClientList[i] != 0) &&
            (strcmp(m_pClientList[i]->m_cCharName, pName) == 0)) {
          iClientH = i;
          goto PORD_LOOPBREAK;
        }
    PORD_LOOPBREAK:

      // 掳脭脌脫 录颅鹿枚脌脟 脝脛脝录 赂庐陆潞脝庐驴隆录颅 脟脴脕娄.
      for (i = 0; i < DEF_MAXPARTYMEMBERS; i++)
        if (m_stPartyInfo[iPartyID].iIndex[i] == iClientH) {
          m_stPartyInfo[iPartyID].iIndex[i] = 0;
          m_stPartyInfo[iPartyID].iTotalMembers--;
          // testcode
          wsprintf(G_cTxt, "PartyID:%d member:%d Out Total:%d", iPartyID,
                   iClientH, m_stPartyInfo[iPartyID].iTotalMembers);
          PutLogList(G_cTxt);
          goto PORC_LOOPBREAK1;
        }
    PORC_LOOPBREAK1:
      // 赂庐陆潞脝庐 脌脦碌娄陆潞脌脟 潞贸掳酶掳拢脌禄 脕娄掳脜脟脩麓脵.
      for (i = 0; i < DEF_MAXPARTYMEMBERS - 1; i++)
        if ((m_stPartyInfo[iPartyID].iIndex[i] == 0) &&
            (m_stPartyInfo[iPartyID].iIndex[i + 1] != 0)) {
          m_stPartyInfo[iPartyID].iIndex[i] =
              m_stPartyInfo[iPartyID].iIndex[i + 1];
          m_stPartyInfo[iPartyID].iIndex[i + 1] = 0;
        }

      if (m_pClientList[iClientH] != 0) {
        m_pClientList[iClientH]->m_iPartyID = 0;
        m_pClientList[iClientH]->m_iPartyStatus = DEF_PARTYSTATUS_NULL;
        m_pClientList[iClientH]->m_iReqJoinPartyClientH = 0;
      }

      // 赂冒碌莽 脝脛脝录驴酶碌茅驴隆掳脭 戮脣路脕脕脴麓脵.
      for (i = 1; i < DEF_MAXCLIENTS; i++)
        if ((m_pClientList[i] != 0) && (m_pClientList[i]->m_iPartyID != 0) &&
            (m_pClientList[i]->m_iPartyID == iPartyID)) {
          SendNotifyMsg(0, i, DEF_NOTIFY_PARTY, 6, 1, 0, pName);
        }
      return;
    }

    if ((m_pClientList[iClientH] != 0) &&
        (m_pClientList[iClientH]->m_iPartyStatus != DEF_PARTYSTATUS_PROCESSING))
      return;
    if ((m_pClientList[iClientH] != 0) &&
        (strcmp(m_pClientList[iClientH]->m_cCharName, pName) != 0))
      return;

    // 赂冒碌莽 脝脛脝录驴酶碌茅驴隆掳脭 戮脣路脕脕脴麓脵.
    for (i = 1; i < DEF_MAXCLIENTS; i++)
      if ((m_pClientList[i] != 0) && (m_pClientList[i]->m_iPartyID != 0) &&
          (m_pClientList[i]->m_iPartyID == iPartyID)) {
        SendNotifyMsg(0, i, DEF_NOTIFY_PARTY, 6, 1, 0, pName);
      }

    // 掳脭脌脫 录颅鹿枚脌脟 脝脛脝录 赂庐陆潞脝庐驴隆录颅 脟脴脕娄.
    for (i = 0; i < DEF_MAXPARTYMEMBERS; i++)
      if (m_stPartyInfo[iPartyID].iIndex[i] == iClientH) {
        m_stPartyInfo[iPartyID].iIndex[i] = 0;
        m_stPartyInfo[iPartyID].iTotalMembers--;
        // testcode
        wsprintf(G_cTxt, "PartyID:%d member:%d Out Total:%d", iPartyID,
                 iClientH, m_stPartyInfo[iPartyID].iTotalMembers);
        PutLogList(G_cTxt);
        goto PORC_LOOPBREAK2;
      }
  PORC_LOOPBREAK2:
    // 赂庐陆潞脝庐 脌脦碌娄陆潞脌脟 潞贸掳酶掳拢脌禄 脕娄掳脜脟脩麓脵.
    for (i = 0; i < DEF_MAXPARTYMEMBERS - 1; i++)
      if ((m_stPartyInfo[iPartyID].iIndex[i] == 0) &&
          (m_stPartyInfo[iPartyID].iIndex[i + 1] != 0)) {
        m_stPartyInfo[iPartyID].iIndex[i] =
            m_stPartyInfo[iPartyID].iIndex[i + 1];
        m_stPartyInfo[iPartyID].iIndex[i + 1] = 0;
      }

    if (m_pClientList[iClientH] != 0) {
      m_pClientList[iClientH]->m_iPartyID = 0;
      m_pClientList[iClientH]->m_iPartyStatus = DEF_PARTYSTATUS_NULL;
      m_pClientList[iClientH]->m_iReqJoinPartyClientH = 0;
    }
    break;
  }
}

void CGame::PartyOperationResult_Delete(int iPartyID) {
  int i;

  for (i = 0; i < DEF_MAXPARTYMEMBERS; i++) {
    m_stPartyInfo[iPartyID].iIndex[i] = 0;
    m_stPartyInfo[iPartyID].iTotalMembers = 0;
  }

  // 脝脛脝录 脟脴禄锚碌脢
  for (i = 1; i < DEF_MAXCLIENTS; i++)
    if ((m_pClientList[i] != 0) && (m_pClientList[i]->m_iPartyID == iPartyID)) {
      SendNotifyMsg(0, i, DEF_NOTIFY_PARTY, 2, 0, 0, 0);
      m_pClientList[i]->m_iPartyID = 0;
      m_pClientList[i]->m_iPartyStatus = DEF_PARTYSTATUS_NULL;
      m_pClientList[i]->m_iReqJoinPartyClientH = 0;
      // testcode
      wsprintf(G_cTxt, "Notify delete party: %d", i);
      PutLogList(G_cTxt);
    }
}

void CGame::RequestJoinPartyHandler(int iClientH, char *pData,
                                    DWORD dwMsgSize) {
  char seps[] = "= \t\n";
  char *cp, *token, cBuff[256], cData[120], cName[12];
  class CStrTok *pStrTok;
  DWORD *dwp;
  WORD *wp;
  int i;

  // 脝脛脝录 掳隆脌脭 驴漏潞脦赂娄 鹿炉掳铆 脌脰麓脵.
  if (m_pClientList[iClientH] == 0)
    return;
  if (m_pClientList[iClientH]->m_iPartyStatus != DEF_PARTYSTATUS_NULL)
    return;
  if ((dwMsgSize) <= 0)
    return;
  if ((m_bAdminSecurity) && (m_pClientList[iClientH]->m_iAdminUserLevel > 0))
    return;

  ZeroMemory(cBuff, sizeof(cBuff));
  memcpy(cBuff, pData, dwMsgSize);

  pStrTok = new class CStrTok(cBuff, seps);
  token = pStrTok->pGet();

  token = pStrTok->pGet();
  if (token != 0) {
    ZeroMemory(cName, sizeof(cName));
    strcpy(cName, token);
  } else
    return;

  for (i = 1; i < DEF_MAXCLIENTS; i++)
    if ((m_pClientList[i] != 0) &&
        (strcmp(m_pClientList[i]->m_cCharName, cName) == 0)) {
      // 掳脭脌脤脝庐 录颅鹿枚路脦 脝脛脝录 赂芒鹿枚 掳隆脌脭脌禄
      // 陆脜脙禄脟脩麓脵.
      if ((m_pClientList[i]->m_iPartyID == 0) ||
          (m_pClientList[i]->m_iPartyStatus != DEF_PARTYSTATUS_CONFIRM)) {
        // 脝脛脝录驴隆 掳隆脌脭脟脧掳铆脌脷 脟脩 脛鲁赂炉脜脥掳隆 脝脛脝录
        // 赂露陆潞脜脥掳隆 戮脝麓脧麓脵.
        return;
      }

      ZeroMemory(cData, sizeof(cData));

      cp = (char *)cData;
      /*dwp = (DWORD *)cp;
      *dwp = MSGID_PARTYOPERATION;
      cp += 4;*/
      wp = (WORD *)cp;
      *wp = 3; // 脝脛脝录 赂芒鹿枚 脙脽掳隆 驴盲脙禄
      cp += 2;
      wp = (WORD *)cp;
      *wp = iClientH;
      cp += 2;
      memcpy(cp, m_pClientList[iClientH]->m_cCharName, 10);
      cp += 10;
      wp = (WORD *)cp;
      *wp = m_pClientList[i]->m_iPartyID;
      cp += 2;
      PartyOperation(
          cData); // SendMsgToGateServer(MSGID_PARTYOPERATION, iClientH, cData);
      return;
    }

  // 掳隆脌脭脟脧掳铆脌脷 脟脧麓脗 脝脛脝录 赂露陆潞脜脥掳隆 脟枚脌莽
  // 录颅鹿枚驴隆 脕赂脌莽脟脧脕枚 戮脢麓脗麓脵.
  SendNotifyMsg(0, iClientH, DEF_NOTIFY_PLAYERNOTONGAME, 0, 0, 0, cName);
}

