bool CGame::bPlantSeedBag(int iMapIndex, int dX, int dY, int iItemEffectValue1,
                          int iItemEffectValue2, int iClientH) {
  int iNamingValue, tX, tY;
  short sOwnerH;
  char cOwnerType, cNpcName[21], cName[21], cNpcWaypointIndex[11];
  bool bRet;

  if (m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->m_iTotalAgriculture >=
      200) {
    SendNotifyMsg(0, iClientH, DEF_NOTIFY_NOMOREAGRICULTURE, 0, 0, 0, 0);
    return false;
  }

  if (iItemEffectValue2 > m_pClientList[iClientH]->m_cSkillMastery[2]) {
    SendNotifyMsg(0, iClientH, DEF_NOTIFY_AGRICULTURESKILLLIMIT, 0, 0, 0, 0);
    return false;
  }

  iNamingValue =
      m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->iGetEmptyNamingValue();

  if (iNamingValue == -1) {
  } else {
    m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->GetOwner(
        &sOwnerH, &cOwnerType, dX, dY);
    if (sOwnerH != 0 && sOwnerH == DEF_OWNERTYPE_NPC &&
        m_pNpcList[sOwnerH]->m_cActionLimit == 5) {
      SendNotifyMsg(0, iClientH, DEF_NOTIFY_AGRICULTURENOAREA, 0, 0, 0, 0);
      return false;
    } else {
      if (m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->bGetIsFarm(
              dX, dY) == false) {
        SendNotifyMsg(0, iClientH, DEF_NOTIFY_AGRICULTURENOAREA, 0, 0, 0, 0);
        return false;
      }

      ZeroMemory(cNpcName, sizeof(cNpcName));
      strcpy(cNpcName, "Crops");
      ZeroMemory(cName, sizeof(cName));
      wsprintf(cName, "XX%d", iNamingValue);
      cName[0] = '_';
      cName[1] = iMapIndex + 65;

      ZeroMemory(cNpcWaypointIndex, sizeof(cNpcWaypointIndex));
      tX = dX;
      tY = dY;

      bRet = bCreateNewNpc(
          cNpcName, cName,
          m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->m_cName, 0, 0,
          DEF_MOVETYPE_RANDOM, &tX, &tY, cNpcWaypointIndex, 0, 0, 0, false,
          true);
      if (bRet == false) {
        m_pMapList[iMapIndex]->SetNamingValueEmpty(iNamingValue);
      } else {
        m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->GetOwner(
            &sOwnerH, &cOwnerType, tX, tY);
        if (m_pNpcList[sOwnerH] == 0)
          return 0;
        m_pNpcList[sOwnerH]->m_cCropType = iItemEffectValue1;
        switch (iItemEffectValue1) {
        case 1:
          m_pNpcList[sOwnerH]->m_cCropSkill = iItemEffectValue2;
          break;
        case 2:
          m_pNpcList[sOwnerH]->m_cCropSkill = iItemEffectValue2;
          break;
        case 3:
          m_pNpcList[sOwnerH]->m_cCropSkill = iItemEffectValue2;
          break;
        case 4:
          m_pNpcList[sOwnerH]->m_cCropSkill = iItemEffectValue2;
          break;
        case 5:
          m_pNpcList[sOwnerH]->m_cCropSkill = iItemEffectValue2;
          break;
        case 6:
          m_pNpcList[sOwnerH]->m_cCropSkill = iItemEffectValue2;
          break;
        case 7:
          m_pNpcList[sOwnerH]->m_cCropSkill = iItemEffectValue2;
          break;
        case 8:
          m_pNpcList[sOwnerH]->m_cCropSkill = iItemEffectValue2;
          break;
        case 9:
          m_pNpcList[sOwnerH]->m_cCropSkill = iItemEffectValue2;
          break;
        case 10:
          m_pNpcList[sOwnerH]->m_cCropSkill = iItemEffectValue2;
          break;
        case 11:
          m_pNpcList[sOwnerH]->m_cCropSkill = iItemEffectValue2;
          break;
        case 12:
          m_pNpcList[sOwnerH]->m_cCropSkill = iItemEffectValue2;
          break;
        case 13:
          m_pNpcList[sOwnerH]->m_cCropSkill = iItemEffectValue2;
          break;
        default:
          m_pNpcList[sOwnerH]->m_cCropSkill = 100;
          break;
        }
        m_pNpcList[sOwnerH]->m_sAppr2 = 1;
        SendEventToNearClient_TypeA(sOwnerH, DEF_OWNERTYPE_NPC, MSGID_EVENT_LOG,
                                    DEF_MSGTYPE_CONFIRM, 0, 0, 0);
        wsprintf(
            G_cTxt,
            "(skill:%d type:%d)plant(%s) Agriculture begin(%d,%d) sum(%d)!",
            m_pNpcList[sOwnerH]->m_cCropSkill, m_pNpcList[sOwnerH]->m_cCropType,
            cNpcName, tX, tY,
            m_pMapList[m_pClientList[iClientH]->m_cMapIndex]
                ->m_iTotalAgriculture);
        PutLogList(G_cTxt);
        return true;
      }
    }
  }
  return false;
}

void CGame::_CheckFarmingAction(short sAttackerH, short sTargetH, bool bType) {
  char cCropType;
  int iItemID;
  class CItem *pItem;

  iItemID = 0;
  cCropType = 0;

  cCropType = m_pNpcList[sTargetH]->m_cCropType;
  switch (cCropType) {
  case 1:
    GetExp(sAttackerH, iDice(3, 10));
    iItemID = 820;
    break; // WaterMelon
  case 2:
    GetExp(sAttackerH, iDice(3, 10));
    iItemID = 821;
    break; // Pumpkin
  case 3:
    GetExp(sAttackerH, iDice(4, 10));
    iItemID = 822;
    break; // Garlic
  case 4:
    GetExp(sAttackerH, iDice(4, 10));
    iItemID = 823;
    break; // Barley
  case 5:
    GetExp(sAttackerH, iDice(5, 10));
    iItemID = 824;
    break; // Carrot
  case 6:
    GetExp(sAttackerH, iDice(5, 10));
    iItemID = 825;
    break; // Radish
  case 7:
    GetExp(sAttackerH, iDice(6, 10));
    iItemID = 826;
    break; // Corn
  case 8:
    GetExp(sAttackerH, iDice(6, 10));
    iItemID = 827;
    break; // ChineseBellflower
  case 9:
    GetExp(sAttackerH, iDice(7, 10));
    iItemID = 828;
    break; // Melone
  case 10:
    GetExp(sAttackerH, iDice(7, 10));
    iItemID = 829;
    break; // Tommato
  case 11:
    GetExp(sAttackerH, iDice(8, 10));
    iItemID = 830;
    break; // Grapes
  case 12:
    GetExp(sAttackerH, iDice(8, 10));
    iItemID = 831;
    break; // BlueGrapes
  case 13:
    GetExp(sAttackerH, iDice(9, 10));
    iItemID = 832;
    break; // Mushroom
  default:
    GetExp(sAttackerH, iDice(10, 10));
    iItemID = 721;
    break; // Ginseng
  }

  pItem = new class CItem;
  if (_bInitItemAttr(pItem, iItemID) == false) {
    delete pItem;
  }
  if (bType == 0) {
    m_pMapList[m_pClientList[sAttackerH]->m_cMapIndex]->bSetItem(
        m_pClientList[sAttackerH]->m_sX, m_pClientList[sAttackerH]->m_sY,
        pItem);
    SendEventToNearClient_TypeB(
        MSGID_EVENT_COMMON, DEF_COMMONTYPE_ITEMDROP,
        m_pClientList[sAttackerH]->m_cMapIndex, m_pClientList[sAttackerH]->m_sX,
        m_pClientList[sAttackerH]->m_sY, pItem->m_sIDnum, 0,
        pItem->m_cItemColor, pItem->m_dwAttribute);
  } else if (bType == 1) {
    m_pMapList[m_pNpcList[sTargetH]->m_cMapIndex]->bSetItem(
        m_pNpcList[sTargetH]->m_sX, m_pNpcList[sTargetH]->m_sY, pItem);
    SendEventToNearClient_TypeB(MSGID_EVENT_COMMON, DEF_COMMONTYPE_ITEMDROP,
                                m_pNpcList[sTargetH]->m_cMapIndex,
                                m_pNpcList[sTargetH]->m_sX,
                                m_pNpcList[sTargetH]->m_sY, pItem->m_sIDnum, 0,
                                pItem->m_cItemColor, pItem->m_dwAttribute);
  }
}

