bool CGame::bCalculateEnduranceDecrement(short sTargetH, short sAttackerH,
                                         char cTargetType, int iArmorType) {
  int iDownValue = 1, iHammerChance = 100, iItemIndex;
  WORD wWeaponType;

  if (m_pClientList[sTargetH] == 0)
    return false;
  if ((cTargetType == DEF_OWNERTYPE_PLAYER) && (m_pClientList[sAttackerH] == 0))
    return false;
  wWeaponType = ((m_pClientList[sAttackerH]->m_sAppr2 & 0x0FF0) >> 4);
  if ((cTargetType == DEF_OWNERTYPE_PLAYER) &&
      (m_pClientList[sTargetH]->m_cSide !=
       m_pClientList[sAttackerH]->m_cSide)) {
    switch (m_pClientList[sAttackerH]->m_sUsingWeaponSkill) {
    case 14:
      if ((wWeaponType == 31) || (wWeaponType == 32)) {
        iItemIndex = m_pClientList[sAttackerH]
                         ->m_sItemEquipmentStatus[DEF_EQUIPPOS_TWOHAND];
        if ((iItemIndex != -1) &&
            (m_pClientList[sAttackerH]->m_pItemList[iItemIndex] != 0)) {
          if (m_pClientList[sAttackerH]->m_pItemList[iItemIndex]->m_sIDnum ==
              761) { // BattleHammer
            iDownValue = 30;
          }
          if (m_pClientList[sAttackerH]->m_pItemList[iItemIndex]->m_sIDnum ==
              762) { // GiantBattleHammer
            iDownValue = 35;
          }
          if (m_pClientList[sAttackerH]->m_pItemList[iItemIndex]->m_sIDnum ==
              843) { // BarbarianHammer
            iDownValue = 30;
          }
          if (m_pClientList[sAttackerH]->m_pItemList[iItemIndex]->m_sIDnum ==
              745) { // MasterBattleHammer
            iDownValue = 30;
          }
          break;
        }
      } else {
        iDownValue = 20;
      }
      break;
    case 10:
      iDownValue = 3;
      break;
    default:
      iDownValue = 1;
      break;
    }
  }
  if (m_pClientList[sTargetH]->m_bIsSpecialAbilityEnabled) {
    switch (m_pClientList[sTargetH]->m_iSpecialAbilityType) {
    case 52:
      iDownValue = 0;
      iHammerChance = 0;
      break;
    }
  }
  if ((m_pClientList[sTargetH]->m_cSide != 0) &&
      (m_pClientList[sTargetH]->m_pItemList[iArmorType]->m_wCurLifeSpan > 0)) {
    m_pClientList[sTargetH]->m_pItemList[iArmorType]->m_wCurLifeSpan -=
        iDownValue;
    SendNotifyMsg(
        0, sTargetH, DEF_NOTIFY_CURLIFESPAN, iArmorType,
        m_pClientList[sTargetH]->m_pItemList[iArmorType]->m_wCurLifeSpan, 0, 0);
  }
  if (m_pClientList[sTargetH]->m_pItemList[iArmorType]->m_wCurLifeSpan <= 0) {
    m_pClientList[sTargetH]->m_pItemList[iArmorType]->m_wCurLifeSpan = 0;
    SendNotifyMsg(0, sTargetH, DEF_NOTIFY_ITEMLIFESPANEND,
                  m_pClientList[sTargetH]->m_pItemList[iArmorType]->m_cEquipPos,
                  iArmorType, 0, 0);
    ReleaseItemHandler(sTargetH, iArmorType, true);
    return true;
  }
  if ((cTargetType == DEF_OWNERTYPE_PLAYER) &&
      (m_pClientList[sAttackerH]->m_sUsingWeaponSkill == 14) &&
      (iHammerChance == 100)) {
    if (m_pClientList[sTargetH]->m_pItemList[iArmorType]->m_wMaxLifeSpan <
        2000) {
      iHammerChance = iDice(
          6,
          (m_pClientList[sTargetH]->m_pItemList[iArmorType]->m_wMaxLifeSpan -
           m_pClientList[sTargetH]->m_pItemList[iArmorType]->m_wCurLifeSpan));
    } else {
      iHammerChance = iDice(
          4,
          (m_pClientList[sTargetH]->m_pItemList[iArmorType]->m_wMaxLifeSpan -
           m_pClientList[sTargetH]->m_pItemList[iArmorType]->m_wCurLifeSpan));
    }
    if ((wWeaponType == 31) || (wWeaponType == 32)) {
      iItemIndex = m_pClientList[sAttackerH]
                       ->m_sItemEquipmentStatus[DEF_EQUIPPOS_TWOHAND];
      if ((iItemIndex != -1) &&
          (m_pClientList[sAttackerH]->m_pItemList[iItemIndex] != 0)) {
        if (m_pClientList[sAttackerH]->m_pItemList[iItemIndex]->m_sIDnum ==
            761) { // BattleHammer
          iHammerChance -= iHammerChance >> 1;
        }
        if (m_pClientList[sAttackerH]->m_pItemList[iItemIndex]->m_sIDnum ==
            762) { // GiantBattleHammer
          iHammerChance = (((iHammerChance * 5) + 7) >> 3);
        }
        if (m_pClientList[sAttackerH]->m_pItemList[iItemIndex]->m_sIDnum ==
            843) { // BarbarianHammer
          iHammerChance = (((iHammerChance * 5) + 7) >> 3);
        }
        if (m_pClientList[sAttackerH]->m_pItemList[iItemIndex]->m_sIDnum ==
            745) { // MasterBattleHammer
          iHammerChance = (((iHammerChance * 5) + 7) >> 3);
        }
      } else {
        iHammerChance = ((iHammerChance + 3) >> 2);
      }
      switch (m_pClientList[sTargetH]->m_pItemList[iArmorType]->m_sIDnum) {
      case 621:
      case 622:
        iHammerChance = 0;
        break;
      }
      if (m_pClientList[sTargetH]->m_pItemList[iArmorType]->m_wCurLifeSpan <
          iHammerChance) {
        ReleaseItemHandler(sTargetH, iArmorType, true);
        SendNotifyMsg(
            0, sTargetH, DEF_NOTIFY_ITEMRELEASED,
            m_pClientList[sTargetH]->m_pItemList[iArmorType]->m_cEquipPos,
            iArmorType, 0, 0);
      }
    }
  }
  return true;
}

DWORD CGame::iCalculateAttackEffect(short sTargetH, char cTargetType,
                                    short sAttackerH, char cAttackerType,
                                    int tdX, int tdY, int iAttackMode,
                                    bool bNearAttack, bool bIsDash,
                                    bool bArrowUse) {
  int iAP_SM, iAP_L, iAttackerHitRatio, iTargetDefenseRatio, iDestHitRatio,
      iResult, iAP_Abs_Armor, iAP_Abs_Shield;
  char cAttackerName[21], cAttackerDir, cAttackerSide, cTargetDir, cProtect,
      cCropSkill, cFarmingSkill;
  short sWeaponIndex, sAttackerWeapon, dX, dY, sX, sY, sAtkX, sAtkY, sTgtX,
      sTgtY;
  DWORD dwTime;
  WORD wWeaponType;
  double dTmp1, dTmp2, dTmp3;
  bool bKilled;
  bool bNormalMissileAttack;
  bool bIsAttackerBerserk;
  int iKilledDice, iDamage, iExp, iWepLifeOff, iSideCondition, iMaxSuperAttack,
      iWeaponSkill, iComboBonus, iTemp;
  int iAttackerHP, iMoveDamage, iRepDamage;
  char cAttackerSA;
  int iAttackerSAvalue, iHitPoint;
  char cDamageMoveDir;
  int iPartyID, iConstructionPoint, iWarContribution, tX, tY, iDst1, iDst2;
  short sItemIndex;
  short sSkillUsed;

  dwTime = timeGetTime();
  bKilled = false;
  iExp = 0;
  iPartyID = 0;
  bNormalMissileAttack = false;
  ZeroMemory(cAttackerName, sizeof(cAttackerName));
  cAttackerSA = 0;
  iAttackerSAvalue = 0;
  wWeaponType = 0;

  switch (cAttackerType) {
  case DEF_OWNERTYPE_PLAYER:

    if (m_pClientList[sAttackerH] == 0)
      return 0;
    if ((m_bAdminSecurity) &&
        (m_pClientList[sAttackerH]->m_iAdminUserLevel > 0))
      return 0;
    if ((m_pMapList[m_pClientList[sAttackerH]->m_cMapIndex]
             ->m_bIsAttackEnabled == false) &&
        (m_pClientList[sAttackerH]->m_iAdminUserLevel == 0))
      return 0;
    if ((m_pMapList[m_pClientList[sAttackerH]->m_cMapIndex] == 0) &&
        (m_pMapList[m_pClientList[sAttackerH]->m_cMapIndex]
             ->m_bIsHeldenianMap) &&
        (m_bIsHeldenianMode))
      return 0;
    if ((m_bIsCrusadeMode == false) &&
        (m_pClientList[sAttackerH]->m_bIsPlayerCivil) &&
        (cTargetType == DEF_OWNERTYPE_PLAYER))
      return 0;

    if ((m_pClientList[sAttackerH]->m_iStatus & 0x10) != 0) {
      SetInvisibilityFlag(sAttackerH, DEF_OWNERTYPE_PLAYER, false);
      bRemoveFromDelayEventList(sAttackerH, DEF_OWNERTYPE_PLAYER,
                                DEF_MAGICTYPE_INVISIBILITY);
      m_pClientList[sAttackerH]
          ->m_cMagicEffectStatus[DEF_MAGICTYPE_INVISIBILITY] = 0;
    }

    if ((m_pClientList[sAttackerH]->m_sAppr2 & 0xF000) == 0)
      return 0;

    iAP_SM = 0;
    iAP_L = 0;

    wWeaponType = ((m_pClientList[sAttackerH]->m_sAppr2 & 0x0FF0) >> 4);

    sSkillUsed = m_pClientList[sAttackerH]->m_sUsingWeaponSkill;
    if ((bIsDash) &&
        (m_pClientList[sAttackerH]->m_cSkillMastery[sSkillUsed] != 100) &&
        (wWeaponType != 25) && (wWeaponType != 27)) {
      try {
        wsprintf(G_cTxt,
                 "TSearch Fullswing Hack: (%s) Player: (%s) - dashing with "
                 "only (%d) weapon skill.",
                 m_pClientList[sAttackerH]->m_cIPaddress,
                 m_pClientList[sAttackerH]->m_cCharName,
                 m_pClientList[sAttackerH]->m_cSkillMastery[sSkillUsed]);
        PutHackLogFileList(G_cTxt);
        DeleteClient(sAttackerH, true, true);
      } catch (...) {
      }
      return 0;
    }

    cAttackerSide = m_pClientList[sAttackerH]->m_cSide;

    if (wWeaponType == 0) {
      iAP_SM = iAP_L = iDice(1, ((m_pClientList[sAttackerH]->m_iStr +
                                  m_pClientList[sAttackerH]->m_iAngelicStr) /
                                 12));
      if (iAP_SM <= 0)
        iAP_SM = 1;
      if (iAP_L <= 0)
        iAP_L = 1;
      iAttackerHitRatio = m_pClientList[sAttackerH]->m_iHitRatio +
                          m_pClientList[sAttackerH]->m_cSkillMastery[5];
      m_pClientList[sAttackerH]->m_sUsingWeaponSkill = 5;

    } else if ((wWeaponType >= 1) && (wWeaponType < 40)) {
      iAP_SM = iDice(m_pClientList[sAttackerH]->m_cAttackDiceThrow_SM,
                     m_pClientList[sAttackerH]->m_cAttackDiceRange_SM);
      iAP_L = iDice(m_pClientList[sAttackerH]->m_cAttackDiceThrow_L,
                    m_pClientList[sAttackerH]->m_cAttackDiceRange_L);

      iAP_SM += m_pClientList[sAttackerH]->m_cAttackBonus_SM;
      iAP_L += m_pClientList[sAttackerH]->m_cAttackBonus_L;

      iAttackerHitRatio = m_pClientList[sAttackerH]->m_iHitRatio;

      dTmp1 = (double)iAP_SM;
      dTmp2 = (double)(m_pClientList[sAttackerH]->m_iStr +
                       m_pClientList[sAttackerH]->m_iAngelicStr);

      dTmp2 = dTmp2 / 5.0f;
      dTmp3 = dTmp1 + (dTmp1 * (dTmp2 / 100.0f));
      iAP_SM = (int)(dTmp3 + 0.5f);

      dTmp1 = (double)iAP_L;
      dTmp2 = (double)(m_pClientList[sAttackerH]->m_iStr +
                       m_pClientList[sAttackerH]->m_iAngelicStr);

      dTmp2 = dTmp2 / 5.0f;
      dTmp3 = dTmp1 + (dTmp1 * (dTmp2 / 100.0f));
      iAP_L = (int)(dTmp3 + 0.5f);
    } else if (wWeaponType >= 40) {
      iAP_SM = iDice(m_pClientList[sAttackerH]->m_cAttackDiceThrow_SM,
                     m_pClientList[sAttackerH]->m_cAttackDiceRange_SM);
      iAP_L = iDice(m_pClientList[sAttackerH]->m_cAttackDiceThrow_L,
                    m_pClientList[sAttackerH]->m_cAttackDiceRange_L);

      iAP_SM += m_pClientList[sAttackerH]->m_cAttackBonus_SM;
      iAP_L += m_pClientList[sAttackerH]->m_cAttackBonus_L;

      iAttackerHitRatio = m_pClientList[sAttackerH]->m_iHitRatio;
      bNormalMissileAttack = true;

      iAP_SM += iDice(1, ((m_pClientList[sAttackerH]->m_iStr +
                           m_pClientList[sAttackerH]->m_iAngelicStr) /
                          20));
      iAP_L += iDice(1, ((m_pClientList[sAttackerH]->m_iStr +
                          m_pClientList[sAttackerH]->m_iAngelicStr) /
                         20));
    }

    iAttackerHitRatio += 50;
    if (iAP_SM <= 0)
      iAP_SM = 1;
    if (iAP_L <= 0)
      iAP_L = 1;

    if (m_pClientList[sAttackerH]->m_iCustomItemValue_Attack != 0) {
      if ((m_pClientList[sAttackerH]->m_iMinAP_SM != 0) &&
          (iAP_SM < m_pClientList[sAttackerH]->m_iMinAP_SM)) {
        iAP_SM = m_pClientList[sAttackerH]->m_iMinAP_SM;
      }
      if ((m_pClientList[sAttackerH]->m_iMinAP_L != 0) &&
          (iAP_L < m_pClientList[sAttackerH]->m_iMinAP_L)) {
        iAP_L = m_pClientList[sAttackerH]->m_iMinAP_L;
      }
      if ((m_pClientList[sAttackerH]->m_iMaxAP_SM != 0) &&
          (iAP_SM > m_pClientList[sAttackerH]->m_iMaxAP_SM)) {
        iAP_SM = m_pClientList[sAttackerH]->m_iMaxAP_SM;
      }
      if ((m_pClientList[sAttackerH]->m_iMaxAP_L != 0) &&
          (iAP_L > m_pClientList[sAttackerH]->m_iMaxAP_L)) {
        iAP_L = m_pClientList[sAttackerH]->m_iMaxAP_L;
      }
    }

    if (m_pClientList[sAttackerH]->m_cHeroArmourBonus == 1) {
      iAttackerHitRatio += 100;
      iAP_SM += 5;
      iAP_L += 5;
    }

    sItemIndex =
        m_pClientList[sAttackerH]->m_sItemEquipmentStatus[DEF_EQUIPPOS_RHAND];
    if ((sItemIndex != -1) &&
        (m_pClientList[sAttackerH]->m_pItemList[sItemIndex] != 0)) {
      if ((m_pClientList[sAttackerH]->m_pItemList[sItemIndex]->m_sIDnum ==
           851) || // KlonessEsterk
          (m_pClientList[sAttackerH]->m_pItemList[sItemIndex]->m_sIDnum ==
           863) || // KlonessWand(MS.20)
          (m_pClientList[sAttackerH]->m_pItemList[sItemIndex]->m_sIDnum ==
           864)) { // KlonessWand(MS.10)
        if (m_pClientList[sAttackerH]->m_iRating > 0) {
          iRepDamage = m_pClientList[sAttackerH]->m_iRating / 100;
          if (iRepDamage < 5)
            iRepDamage = 5;
          if (iRepDamage > 15)
            iRepDamage = 15;
          iAP_SM += iRepDamage;
          iAP_L += iRepDamage;
        }
        if (cTargetType == DEF_OWNERTYPE_PLAYER) {
          if (m_pClientList[sTargetH] == 0)
            return 0;
          if (m_pClientList[sTargetH]->m_iRating < 0) {
            iRepDamage = (abs(m_pClientList[sTargetH]->m_iRating) / 10);
            if (iRepDamage > 10)
              iRepDamage = 10;
            iAP_SM += iRepDamage;
            iAP_L += iRepDamage;
          }
        }
      }
      if ((m_pClientList[sAttackerH]->m_pItemList[sItemIndex]->m_sIDnum ==
           732) || // BerserkWand(MS.20)
          (m_pClientList[sAttackerH]->m_pItemList[sItemIndex]->m_sIDnum ==
           738)) { // BerserkWand(MS.10)
        iAP_SM += 1;
        iAP_L += 1;
      }
    }

    sItemIndex =
        m_pClientList[sAttackerH]->m_sItemEquipmentStatus[DEF_EQUIPPOS_TWOHAND];
    if ((sItemIndex != -1) &&
        (m_pClientList[sAttackerH]->m_pItemList[sItemIndex] != 0)) {
      if ((m_pClientList[sAttackerH]->m_pItemList[sItemIndex]->m_sIDnum ==
           847) &&
          (m_cDayOrNight == 2)) {
        iAP_SM += 4;
        iAP_L += 4;
      }
      if ((m_pClientList[sAttackerH]->m_pItemList[sItemIndex]->m_sIDnum ==
           848) &&
          (m_cDayOrNight == 1)) {
        iAP_SM += 4;
        iAP_L += 4;
      }
      if ((m_pClientList[sAttackerH]->m_pItemList[sItemIndex]->m_sIDnum ==
           849) || // KlonessBlade
          (m_pClientList[sAttackerH]->m_pItemList[sItemIndex]->m_sIDnum ==
           850)) { // KlonessAxe
        if (m_pClientList[sAttackerH]->m_iRating > 0) {
          iRepDamage = m_pClientList[sAttackerH]->m_iRating / 100;
          if (iRepDamage < 5)
            iRepDamage = 5;
          if (iRepDamage > 15)
            iRepDamage = 15;
          iAP_SM += iRepDamage;
          iAP_L += iRepDamage;
        }
        if (cTargetType == DEF_OWNERTYPE_PLAYER) {
          if (m_pClientList[sTargetH] == 0)
            return 0;
          if (m_pClientList[sTargetH]->m_iRating < 0) {
            iRepDamage = (abs(m_pClientList[sTargetH]->m_iRating) / 10);
            if (iRepDamage > 10)
              iRepDamage = 10;
            iAP_SM += iRepDamage;
            iAP_L += iRepDamage;
          }
        }
      }
    }

    sItemIndex =
        m_pClientList[sAttackerH]->m_sItemEquipmentStatus[DEF_EQUIPPOS_NECK];
    if ((sItemIndex != -1) &&
        (m_pClientList[sAttackerH]->m_pItemList[sItemIndex] != 0)) {
      if (m_pClientList[sAttackerH]->m_pItemList[sItemIndex]->m_sIDnum ==
          859) { // NecklaceOfKloness
        if (cTargetType == DEF_OWNERTYPE_PLAYER) {
          if (m_pClientList[sTargetH] == 0)
            return 0;
          iRepDamage = (abs(m_pClientList[sTargetH]->m_iRating) / 20);
          if (iRepDamage > 5)
            iRepDamage = 5;
          iAP_SM += iRepDamage;
          iAP_L += iRepDamage;
        }
      }
    }

    cAttackerDir = m_pClientList[sAttackerH]->m_cDir;
    strcpy(cAttackerName, m_pClientList[sAttackerH]->m_cCharName);

    if (m_pClientList[sAttackerH]
            ->m_cMagicEffectStatus[DEF_MAGICTYPE_BERSERK] != 0)
      bIsAttackerBerserk = true;
    else
      bIsAttackerBerserk = false;

    if ((bArrowUse != true) &&
        (m_pClientList[sAttackerH]->m_iSuperAttackLeft > 0) &&
        (iAttackMode >= 20)) {

      dTmp1 = (double)iAP_SM;
      dTmp2 = (double)m_pClientList[sAttackerH]->m_iLevel;
      dTmp3 = dTmp2 / 100.0f;
      dTmp2 = dTmp1 * dTmp3;
      iTemp = (int)(dTmp2 + 0.5f);
      iAP_SM += iTemp;

      dTmp1 = (double)iAP_L;
      dTmp2 = (double)m_pClientList[sAttackerH]->m_iLevel;
      dTmp3 = dTmp2 / 100.0f;
      dTmp2 = dTmp1 * dTmp3;
      iTemp = (int)(dTmp2 + 0.5f);
      iAP_L += iTemp;

      switch (m_pClientList[sAttackerH]->m_sUsingWeaponSkill) {
      case 6:
        iAP_SM += (iAP_SM / 10);
        iAP_L += (iAP_L / 10);
        iAttackerHitRatio += 30;
        break;

      case 7:
        iAP_SM *= 1;
        iAP_L *= 1;
        break;

      case 8:
        iAP_SM += (iAP_SM / 10);
        iAP_L += (iAP_L / 10);
        iAttackerHitRatio += 30;
        break;
      case 10:
        iAP_SM += (iAP_SM / 5);
        iAP_L += (iAP_L / 5);
        break;
      case 14:
        iAP_SM += (iAP_SM / 5);
        iAP_L += (iAP_L / 5);
        iAttackerHitRatio += 20;
        break;
      case 21:
        iAP_SM += (iAP_SM / 5);
        iAP_L += (iAP_L / 5);
        iAttackerHitRatio += 50;
        break;
      default:
        break;
      }
      iAttackerHitRatio += 100;
      iAttackerHitRatio += m_pClientList[sAttackerH]->m_iCustomItemValue_Attack;
    }

    if (bIsDash) {

      iAttackerHitRatio += 20;

      switch (m_pClientList[sAttackerH]->m_sUsingWeaponSkill) {
      case 8:
        iAP_SM += (iAP_SM / 10);
        iAP_L += (iAP_L / 10);
        break;
      case 10:
        iAP_SM += (iAP_SM / 5);
        iAP_L += (iAP_L / 5);
        break;
      case 14:
        iAP_SM += (iAP_SM / 5);
        iAP_L += (iAP_L / 5);
        break;
      default:
        break;
      }
    }

    iAttackerHP = m_pClientList[sAttackerH]->m_iHP;
    iAttackerHitRatio += m_pClientList[sAttackerH]->m_iAddAR;

    sAtkX = m_pClientList[sAttackerH]->m_sX;
    sAtkY = m_pClientList[sAttackerH]->m_sY;
    iPartyID = m_pClientList[sAttackerH]->m_iPartyID;
    break;

  case DEF_OWNERTYPE_NPC:

    if (m_pNpcList[sAttackerH] == 0)
      return 0;
    if (m_pMapList[m_pNpcList[sAttackerH]->m_cMapIndex]->m_bIsAttackEnabled ==
        false)
      return 0;

    if ((m_pNpcList[sAttackerH]->m_iStatus & 0x10) != 0) {
      SetInvisibilityFlag(sAttackerH, DEF_OWNERTYPE_NPC, false);
      bRemoveFromDelayEventList(sAttackerH, DEF_OWNERTYPE_NPC,
                                DEF_MAGICTYPE_INVISIBILITY);
      m_pNpcList[sAttackerH]->m_cMagicEffectStatus[DEF_MAGICTYPE_INVISIBILITY] =
          0;
    }

    cAttackerSide = m_pNpcList[sAttackerH]->m_cSide;
    iAP_SM = 0;
    iAP_L = 0;

    if (m_pNpcList[sAttackerH]->m_cAttackDiceThrow != 0)
      iAP_L = iAP_SM = iDice(m_pNpcList[sAttackerH]->m_cAttackDiceThrow,
                             m_pNpcList[sAttackerH]->m_cAttackDiceRange);

    iAttackerHitRatio = m_pNpcList[sAttackerH]->m_iHitRatio;

    cAttackerDir = m_pNpcList[sAttackerH]->m_cDir;
    memcpy(cAttackerName, m_pNpcList[sAttackerH]->m_cNpcName, 20);

    if (m_pNpcList[sAttackerH]->m_cMagicEffectStatus[DEF_MAGICTYPE_BERSERK] !=
        0)
      bIsAttackerBerserk = true;
    else
      bIsAttackerBerserk = false;

    iAttackerHP = m_pNpcList[sAttackerH]->m_iHP;
    cAttackerSA = m_pNpcList[sAttackerH]->m_cSpecialAbility;

    sAtkX = m_pNpcList[sAttackerH]->m_sX;
    sAtkY = m_pNpcList[sAttackerH]->m_sY;
    break;
  }

  switch (cTargetType) {
  case DEF_OWNERTYPE_PLAYER:

    if (m_pClientList[sTargetH] == 0)
      return 0;
    if (m_pClientList[sTargetH]->m_bIsKilled)
      return 0;
    if ((m_pClientList[sTargetH]->m_iStatus & 0x400000) != 0)
      return 0;

    if ((cAttackerType == DEF_OWNERTYPE_PLAYER) &&
        (m_bIsCrusadeMode == false) &&
        (m_pClientList[sTargetH]->m_iPKCount == 0) &&
        (m_pClientList[sTargetH]->m_bIsPlayerCivil))
      return 0;

    if ((cAttackerType == DEF_OWNERTYPE_PLAYER) &&
        (m_pClientList[sTargetH]->m_bIsNeutral) &&
        (m_pClientList[sTargetH]->m_iPKCount == 0) &&
        (m_pClientList[sTargetH]->m_bIsOwnLocation))
      return 0;

    if ((m_pClientList[sTargetH]->m_sX != tdX) ||
        (m_pClientList[sTargetH]->m_sY != tdY))
      return 0;

    if (m_pClientList[sTargetH]->m_iAdminUserLevel > 0)
      return 0;

    if ((cAttackerType == DEF_OWNERTYPE_PLAYER) &&
        (m_pClientList[sAttackerH]->m_bIsNeutral) &&
        (m_pClientList[sTargetH]->m_iPKCount == 0))
      return 0;

    if ((m_pClientList[sTargetH]->m_iPartyID != 0) &&
        (iPartyID == m_pClientList[sTargetH]->m_iPartyID))
      return 0;

    cTargetDir = m_pClientList[sTargetH]->m_cDir;
    iTargetDefenseRatio = m_pClientList[sTargetH]->m_iDefenseRatio;
    m_pClientList[sTargetH]->m_dwLogoutHackCheck = dwTime;
    if ((cAttackerType == DEF_OWNERTYPE_PLAYER) &&
        (m_pClientList[sAttackerH]->m_bIsSafeAttackMode)) {
      iSideCondition = iGetPlayerRelationship(sAttackerH, sTargetH);
      if ((iSideCondition == 7) || (iSideCondition == 2) ||
          (iSideCondition == 6)) {
        iAP_SM = iAP_SM / 2;
        iAP_L = iAP_L / 2;
      } else {
        if (m_pMapList[m_pClientList[sAttackerH]->m_cMapIndex]
                ->m_bIsFightZone) {
          if (m_pClientList[sAttackerH]->m_iGuildGUID ==
              m_pClientList[sTargetH]->m_iGuildGUID)
            return 0;
          else {
            iAP_SM = iAP_SM / 2;
            iAP_L = iAP_L / 2;
          }
        } else
          return 0;
      }
    }

    iTargetDefenseRatio += m_pClientList[sTargetH]->m_iAddDR;

    sTgtX = m_pClientList[sTargetH]->m_sX;
    sTgtY = m_pClientList[sTargetH]->m_sY;
    break;

  case DEF_OWNERTYPE_NPC:

    if (m_pNpcList[sTargetH] == 0)
      return 0;
    if (m_pNpcList[sTargetH]->m_iHP <= 0)
      return 0;

    if ((m_pNpcList[sTargetH]->m_sX != tdX) ||
        (m_pNpcList[sTargetH]->m_sY != tdY))
      return 0;

    cTargetDir = m_pNpcList[sTargetH]->m_cDir;
    iTargetDefenseRatio = m_pNpcList[sTargetH]->m_iDefenseRatio;

    if (cAttackerType == DEF_OWNERTYPE_PLAYER) {
      switch (m_pNpcList[sTargetH]->m_sType) {
      case 40:
      case 41:
        if ((m_pClientList[sAttackerH]->m_cSide == 0) ||
            (m_pNpcList[sTargetH]->m_cSide ==
             m_pClientList[sAttackerH]->m_cSide))
          return 0;
        break;
      }

      if ((wWeaponType == 25) && (m_pNpcList[sTargetH]->m_cActionLimit == 5) &&
          (m_pNpcList[sTargetH]->m_iBuildCount > 0)) {
        if ((m_pClientList[sAttackerH]->m_iCrusadeDuty != 2) &&
            (m_pClientList[sAttackerH]->m_iAdminUserLevel == 0))
          break;

        switch (m_pNpcList[sTargetH]->m_sType) {
        case 36:
        case 37:
        case 38:
        case 39:
          // administrators instantly build crusade structures
          if (m_pClientList[sAttackerH]->m_iAdminUserLevel > 0) {
            m_pNpcList[sTargetH]->m_sAppr2 = 0;
            SendEventToNearClient_TypeA(sTargetH, DEF_OWNERTYPE_NPC,
                                        MSGID_EVENT_MOTION,
                                        DEF_OBJECTNULLACTION, 0, 0, 0);
          }

          switch (m_pNpcList[sTargetH]->m_iBuildCount) {
          case 1:
            m_pNpcList[sTargetH]->m_sAppr2 = 0;
            SendEventToNearClient_TypeA(sTargetH, DEF_OWNERTYPE_NPC,
                                        MSGID_EVENT_MOTION,
                                        DEF_OBJECTNULLACTION, 0, 0, 0);
            switch (m_pNpcList[sTargetH]->m_sType) {
            case 36:
              iConstructionPoint = 700;
              iWarContribution = 700;
              break;
            case 37:
              iConstructionPoint = 700;
              iWarContribution = 700;
              break;
            case 38:
              iConstructionPoint = 500;
              iWarContribution = 500;
              break;
            case 39:
              iConstructionPoint = 500;
              iWarContribution = 500;
              break;
            }

            m_pClientList[sAttackerH]->m_iWarContribution += iWarContribution;
            if (m_pClientList[sAttackerH]->m_iWarContribution >
                DEF_MAXWARCONTRIBUTION)
              m_pClientList[sAttackerH]->m_iWarContribution =
                  DEF_MAXWARCONTRIBUTION;
            wsprintf(G_cTxt, "Construction Complete! WarContribution: +%d",
                     iWarContribution);
            PutLogList(G_cTxt);
            SendNotifyMsg(0, sAttackerH, DEF_NOTIFY_CONSTRUCTIONPOINT,
                          m_pClientList[sAttackerH]->m_iConstructionPoint,
                          m_pClientList[sAttackerH]->m_iWarContribution, 0, 0);
            break;
          case 5:
            m_pNpcList[sTargetH]->m_sAppr2 = 1;
            SendEventToNearClient_TypeA(sTargetH, DEF_OWNERTYPE_NPC,
                                        MSGID_EVENT_MOTION,
                                        DEF_OBJECTNULLACTION, 0, 0, 0);
            break;
          case 10:
            m_pNpcList[sTargetH]->m_sAppr2 = 2;
            SendEventToNearClient_TypeA(sTargetH, DEF_OWNERTYPE_NPC,
                                        MSGID_EVENT_MOTION,
                                        DEF_OBJECTNULLACTION, 0, 0, 0);
            break;
          }
          break;
        }

        m_pNpcList[sTargetH]->m_iBuildCount--;
        if (m_pNpcList[sTargetH]->m_iBuildCount <= 0) {
          m_pNpcList[sTargetH]->m_iBuildCount = 0;
        }
        return 0;
      }
      if ((wWeaponType == 27) && (m_pNpcList[sTargetH]->m_cCropType != 0) &&
          (m_pNpcList[sTargetH]->m_cActionLimit == 5) &&
          (m_pNpcList[sTargetH]->m_iBuildCount > 0)) {
        cFarmingSkill = m_pClientList[sAttackerH]->m_cSkillMastery[2];
        cCropSkill = m_pNpcList[sTargetH]->m_cCropSkill;
        if (cFarmingSkill < 20)
          return 0;
        if (m_pClientList[sAttackerH]->m_iLevel < 20)
          return 0;
        switch (m_pNpcList[sTargetH]->m_sType) {
        case 64:
          switch (m_pNpcList[sTargetH]->m_iBuildCount) {
          case 1:
            m_pNpcList[sTargetH]->m_sAppr2 = 3;
            SendEventToNearClient_TypeA(sTargetH, DEF_OWNERTYPE_NPC,
                                        MSGID_EVENT_MOTION,
                                        DEF_OBJECTNULLACTION, 0, 0, 0);
            // sub_4B67E0
            CalculateSSN_SkillIndex(sAttackerH, 2,
                                    cFarmingSkill <= cCropSkill + 10);
            _CheckFarmingAction(sAttackerH, sTargetH, 1);
            DeleteNpc(sTargetH);
            return 0;
          case 8:
            m_pNpcList[sTargetH]->m_sAppr2 = 3;
            SendEventToNearClient_TypeA(sTargetH, DEF_OWNERTYPE_NPC,
                                        MSGID_EVENT_MOTION,
                                        DEF_OBJECTNULLACTION, 0, 0, 0);
            CalculateSSN_SkillIndex(sAttackerH, 2,
                                    cFarmingSkill <= cCropSkill + 10);
            _CheckFarmingAction(sAttackerH, sTargetH, 0);
            break;
          case 18:
            m_pNpcList[sTargetH]->m_sAppr2 = 2;
            SendEventToNearClient_TypeA(sTargetH, DEF_OWNERTYPE_NPC,
                                        MSGID_EVENT_MOTION,
                                        DEF_OBJECTNULLACTION, 0, 0, 0);
            CalculateSSN_SkillIndex(sAttackerH, 2,
                                    cFarmingSkill <= cCropSkill + 10);
            _CheckFarmingAction(sAttackerH, sTargetH, 0);
            break;
          }
          break;
        }
        m_pNpcList[sTargetH]->m_iBuildCount--;
        if (m_pNpcList[sTargetH]->m_iBuildCount <= 0) {
          m_pNpcList[sTargetH]->m_iBuildCount = 0;
        }
        return 0;
      }
    }

    sTgtX = m_pNpcList[sTargetH]->m_sX;
    sTgtY = m_pNpcList[sTargetH]->m_sY;
    break;
  }

  if ((cAttackerType == DEF_OWNERTYPE_PLAYER) &&
      (cTargetType == DEF_OWNERTYPE_PLAYER)) {

    sX = m_pClientList[sAttackerH]->m_sX;
    sY = m_pClientList[sAttackerH]->m_sY;

    dX = m_pClientList[sTargetH]->m_sX;
    dY = m_pClientList[sTargetH]->m_sY;

    if (m_pMapList[m_pClientList[sTargetH]->m_cMapIndex]->iGetAttribute(
            sX, sY, 0x00000006) != 0)
      return 0;
    if (m_pMapList[m_pClientList[sTargetH]->m_cMapIndex]->iGetAttribute(
            dX, dY, 0x00000006) != 0)
      return 0;
  }

  if (cAttackerType == DEF_OWNERTYPE_PLAYER) {
    if ((m_pClientList[sAttackerH]->m_iDex +
         m_pClientList[sAttackerH]->m_iAngelicDex) > 50) {
      iAttackerHitRatio += ((m_pClientList[sAttackerH]->m_iDex +
                             m_pClientList[sAttackerH]->m_iAngelicDex) -
                            50);
    }
  }

  if (wWeaponType >= 40) {
    switch (
        m_pMapList[m_pClientList[sAttackerH]->m_cMapIndex]->m_cWhetherStatus) {
    case 0:
      break;
    case 1:
      iAttackerHitRatio -= (iAttackerHitRatio / 20);
      break;
    case 2:
      iAttackerHitRatio -= (iAttackerHitRatio / 10);
      break;
    case 3:
      iAttackerHitRatio -= (iAttackerHitRatio / 4);
      break;
    }
  }

  if (iAttackerHitRatio < 0)
    iAttackerHitRatio = 0;
  switch (cTargetType) {
  case DEF_OWNERTYPE_PLAYER:
    cProtect =
        m_pClientList[sTargetH]->m_cMagicEffectStatus[DEF_MAGICTYPE_PROTECT];
    break;

  case DEF_OWNERTYPE_NPC:
    cProtect =
        m_pNpcList[sTargetH]->m_cMagicEffectStatus[DEF_MAGICTYPE_PROTECT];
    break;
  }

  if (cAttackerType == DEF_OWNERTYPE_PLAYER) {
    if (m_pClientList[sAttackerH]
            ->m_sItemEquipmentStatus[DEF_EQUIPPOS_TWOHAND] != -1) {
      if (m_pClientList[sAttackerH]
              ->m_pItemList[m_pClientList[sAttackerH]->m_sItemEquipmentStatus
                                [DEF_EQUIPPOS_TWOHAND]] == 0) {
        m_pClientList[sAttackerH]->m_bIsItemEquipped
            [m_pClientList[sAttackerH]
                 ->m_sItemEquipmentStatus[DEF_EQUIPPOS_TWOHAND]] = false;
        DeleteClient(sAttackerH, true, true);
        return 0;
      }

      if (m_pClientList[sAttackerH]
              ->m_pItemList[m_pClientList[sAttackerH]
                                ->m_sItemEquipmentStatus[DEF_EQUIPPOS_TWOHAND]]
              ->m_sItemEffectType == DEF_ITEMEFFECTTYPE_ATTACK_ARROW) {
        if (m_pClientList[sAttackerH]->m_cArrowIndex == -1) {
          return 0;
        } else {
          if (m_pClientList[sAttackerH]
                  ->m_pItemList[m_pClientList[sAttackerH]->m_cArrowIndex] == 0)
            return 0;

          if (bArrowUse != true)
            m_pClientList[sAttackerH]
                ->m_pItemList[m_pClientList[sAttackerH]->m_cArrowIndex]
                ->m_dwCount--;
          if (m_pClientList[sAttackerH]
                  ->m_pItemList[m_pClientList[sAttackerH]->m_cArrowIndex]
                  ->m_dwCount <= 0) {

            ItemDepleteHandler(sAttackerH,
                               m_pClientList[sAttackerH]->m_cArrowIndex, false);
            m_pClientList[sAttackerH]->m_cArrowIndex =
                _iGetArrowItemIndex(sAttackerH);
          } else {
            SendNotifyMsg(
                0, sAttackerH, DEF_NOTIFY_SETITEMCOUNT,
                m_pClientList[sAttackerH]->m_cArrowIndex,
                m_pClientList[sAttackerH]
                    ->m_pItemList[m_pClientList[sAttackerH]->m_cArrowIndex]
                    ->m_dwCount,
                false, 0);
            iCalcTotalWeight(sAttackerH);
          }
        }
        if (cProtect == 1)
          return 0;
      } else {
        switch (cProtect) {
        case 3:
          iTargetDefenseRatio += 40;
          break;
        case 4:
          iTargetDefenseRatio += 100;
          break;
        }
        if (iTargetDefenseRatio < 0)
          iTargetDefenseRatio = 1;
      }
    }
  } else {
    switch (cProtect) {
    case 1:
      switch (m_pNpcList[sAttackerH]->m_sType) {
      case 54:
        if ((abs(sTgtX - m_pNpcList[sAttackerH]->m_sX) >= 1) ||
            (abs(sTgtY - m_pNpcList[sAttackerH]->m_sY) >= 1))
          return 0;
      }
      break;
    case 3:
      iTargetDefenseRatio += 40;
      break;
    case 4:
      iTargetDefenseRatio += 100;
      break;
    }
    if (iTargetDefenseRatio < 0)
      iTargetDefenseRatio = 1;
  }

  if (cAttackerDir == cTargetDir)
    iTargetDefenseRatio = iTargetDefenseRatio / 2;
  if (iTargetDefenseRatio < 1)
    iTargetDefenseRatio = 1;

  dTmp1 = (double)(iAttackerHitRatio);
  dTmp2 = (double)(iTargetDefenseRatio);
  dTmp3 = (dTmp1 / dTmp2) * 50.0f;
  iDestHitRatio = (int)(dTmp3);

  if (iDestHitRatio < DEF_MINIMUMHITRATIO)
    iDestHitRatio = DEF_MINIMUMHITRATIO;
  if (iDestHitRatio > DEF_MAXIMUMHITRATIO)
    iDestHitRatio = DEF_MAXIMUMHITRATIO;

  if ((bIsAttackerBerserk) && (iAttackMode < 20)) {
    iAP_SM = iAP_SM * 2;
    iAP_L = iAP_L * 2;
  }

  if (cAttackerType == DEF_OWNERTYPE_PLAYER) {
    iAP_SM += m_pClientList[sAttackerH]->m_iAddPhysicalDamage;
    iAP_L += m_pClientList[sAttackerH]->m_iAddPhysicalDamage;
  }

  if (bNearAttack) {
    iAP_SM = iAP_SM / 2;
    iAP_L = iAP_L / 2;
  }

  if (cTargetType == DEF_OWNERTYPE_PLAYER) {
    iAP_SM -= (iDice(1, m_pClientList[sTargetH]->m_iVit / 10) - 1);
    iAP_L -= (iDice(1, m_pClientList[sTargetH]->m_iVit / 10) - 1);
  }

  if (cAttackerType == DEF_OWNERTYPE_PLAYER) {
    if (iAP_SM <= 1)
      iAP_SM = 1;
    if (iAP_L <= 1)
      iAP_L = 1;
  } else {
    if (iAP_SM <= 0)
      iAP_SM = 0;
    if (iAP_L <= 0)
      iAP_L = 0;
  }

  iResult = iDice(1, 100);

  if (iResult <= iDestHitRatio) {
    if (cAttackerType == DEF_OWNERTYPE_PLAYER) {

      if (((m_pClientList[sAttackerH]->m_iHungerStatus <= 10) ||
           (m_pClientList[sAttackerH]->m_iSP <= 0)) &&
          (iDice(1, 10) == 5))
        return false;
      m_pClientList[sAttackerH]->m_iComboAttackCount++;
      if (m_pClientList[sAttackerH]->m_iComboAttackCount < 0)
        m_pClientList[sAttackerH]->m_iComboAttackCount = 0;
      if (m_pClientList[sAttackerH]->m_iComboAttackCount > 4)
        m_pClientList[sAttackerH]->m_iComboAttackCount = 1;
      iWeaponSkill = _iGetWeaponSkillType(sAttackerH);
      iComboBonus = iGetComboAttackBonus(
          iWeaponSkill, m_pClientList[sAttackerH]->m_iComboAttackCount);

      if ((m_pClientList[sAttackerH]->m_iComboAttackCount > 1) &&
          (m_pClientList[sAttackerH]->m_iAddCD != 0))
        iComboBonus += m_pClientList[sAttackerH]->m_iAddCD;

      iAP_SM += iComboBonus;
      iAP_L += iComboBonus;

      switch (m_pClientList[sAttackerH]->m_iSpecialWeaponEffectType) {
      case 0:
        break;
      case 1:
        if ((m_pClientList[sAttackerH]->m_iSuperAttackLeft > 0) &&
            (iAttackMode >= 20)) {
          iAP_SM += m_pClientList[sAttackerH]->m_iSpecialWeaponEffectValue;
          iAP_L += m_pClientList[sAttackerH]->m_iSpecialWeaponEffectValue;
        }
        break;

      case 2:
        cAttackerSA = 61;
        iAttackerSAvalue =
            m_pClientList[sAttackerH]->m_iSpecialWeaponEffectValue * 5;
        break;

      case 3:
        cAttackerSA = 62;
        break;
      }

      if (m_pMapList[m_pClientList[sAttackerH]->m_cMapIndex]->m_bIsFightZone) {
        iAP_SM += iAP_SM / 3;
        iAP_L += iAP_L / 3;
      }

      if (bCheckHeldenianMap(sAttackerH, m_iBTFieldMapIndex,
                             DEF_OWNERTYPE_PLAYER) == 1) {
        iAP_SM += iAP_SM / 3;
        iAP_L += iAP_L / 3;
      }

      if ((cTargetType == DEF_OWNERTYPE_PLAYER) && (m_bIsCrusadeMode) &&
          (m_pClientList[sAttackerH]->m_iCrusadeDuty == 1)) {
        if (m_pClientList[sAttackerH]->m_iLevel <= 80) {
          iAP_SM += iAP_SM;
          iAP_L += iAP_L;
        } else if (m_pClientList[sAttackerH]->m_iLevel <= 100) {
          iAP_SM += (iAP_SM * 7) / 10;
          iAP_L += (iAP_L * 7) / 10;
        } else {
          iAP_SM += iAP_SM / 3;
          iAP_L += iAP_L / 3;
        }
      }
    }

    switch (cTargetType) {
    case DEF_OWNERTYPE_PLAYER:
      ClearSkillUsingStatus(sTargetH);
      if ((dwTime - m_pClientList[sTargetH]->m_dwTime) >
          DEF_RAGPROTECTIONTIME) {
        return 0;
      } else {
        switch (cAttackerSA) {
        case 62:
          if (m_pClientList[sTargetH]->m_iRating < 0) {
            iTemp = abs(m_pClientList[sTargetH]->m_iRating) / 10;
            if (iTemp > 10)
              iTemp = 10;
            iAP_SM += iTemp;
          }
          break;
        }

        iAP_Abs_Armor = 0;
        iAP_Abs_Shield = 0;
        iTemp = iDice(1, 10000);
        if ((iTemp >= 1) && (iTemp < 5000))
          iHitPoint = 1;
        else if ((iTemp >= 5000) && (iTemp < 7500))
          iHitPoint = 2;
        else if ((iTemp >= 7500) && (iTemp < 9000))
          iHitPoint = 3;
        else if ((iTemp >= 9000) && (iTemp <= 10000))
          iHitPoint = 4;

        switch (iHitPoint) {
        case 1:
          if (m_pClientList[sTargetH]
                  ->m_iDamageAbsorption_Armor[DEF_EQUIPPOS_BODY] > 0) {
            if (m_pClientList[sTargetH]
                    ->m_iDamageAbsorption_Armor[DEF_EQUIPPOS_BODY] >= 80)
              dTmp1 = 80.0f;
            else
              dTmp1 = (double)m_pClientList[sTargetH]
                          ->m_iDamageAbsorption_Armor[DEF_EQUIPPOS_BODY];
            dTmp2 = (double)iAP_SM;
            dTmp3 = (dTmp1 / 100.0f) * dTmp2;
            iAP_Abs_Armor = (int)dTmp3;
          }
          break;
        case 2:
          if ((m_pClientList[sTargetH]
                   ->m_iDamageAbsorption_Armor[DEF_EQUIPPOS_PANTS] +
               m_pClientList[sTargetH]
                   ->m_iDamageAbsorption_Armor[DEF_EQUIPPOS_LEGGINGS]) > 0) {
            if ((m_pClientList[sTargetH]
                     ->m_iDamageAbsorption_Armor[DEF_EQUIPPOS_PANTS] +
                 m_pClientList[sTargetH]
                     ->m_iDamageAbsorption_Armor[DEF_EQUIPPOS_LEGGINGS]) >= 80)
              dTmp1 = 80.0f;
            else
              dTmp1 =
                  (double)(m_pClientList[sTargetH]
                               ->m_iDamageAbsorption_Armor[DEF_EQUIPPOS_PANTS] +
                           m_pClientList[sTargetH]->m_iDamageAbsorption_Armor
                               [DEF_EQUIPPOS_LEGGINGS]);
            dTmp2 = (double)iAP_SM;
            dTmp3 = (dTmp1 / 100.0f) * dTmp2;

            iAP_Abs_Armor = (int)dTmp3;
          }
          break;

        case 3:
          if (m_pClientList[sTargetH]
                  ->m_iDamageAbsorption_Armor[DEF_EQUIPPOS_ARMS] > 0) {
            if (m_pClientList[sTargetH]
                    ->m_iDamageAbsorption_Armor[DEF_EQUIPPOS_ARMS] >= 80)
              dTmp1 = 80.0f;
            else
              dTmp1 = (double)m_pClientList[sTargetH]
                          ->m_iDamageAbsorption_Armor[DEF_EQUIPPOS_ARMS];
            dTmp2 = (double)iAP_SM;
            dTmp3 = (dTmp1 / 100.0f) * dTmp2;

            iAP_Abs_Armor = (int)dTmp3;
          }
          break;

        case 4:
          if (m_pClientList[sTargetH]
                  ->m_iDamageAbsorption_Armor[DEF_EQUIPPOS_HEAD] > 0) {
            if (m_pClientList[sTargetH]
                    ->m_iDamageAbsorption_Armor[DEF_EQUIPPOS_HEAD] >= 80)
              dTmp1 = 80.0f;
            else
              dTmp1 = (double)m_pClientList[sTargetH]
                          ->m_iDamageAbsorption_Armor[DEF_EQUIPPOS_HEAD];
            dTmp2 = (double)iAP_SM;
            dTmp3 = (dTmp1 / 100.0f) * dTmp2;

            iAP_Abs_Armor = (int)dTmp3;
          }
          break;
        }

        if (m_pClientList[sTargetH]->m_iDamageAbsorption_Shield > 0) {
          if (iDice(1, 100) <= (m_pClientList[sTargetH]->m_cSkillMastery[11])) {
            CalculateSSN_SkillIndex(sTargetH, 11, 1);
            if (m_pClientList[sTargetH]->m_iDamageAbsorption_Shield >= 80)
              dTmp1 = 80.0f;
            else
              dTmp1 =
                  (double)m_pClientList[sTargetH]->m_iDamageAbsorption_Shield;
            dTmp2 = (double)iAP_SM;
            dTmp3 = (dTmp1 / 100.0f) * dTmp2;

            iAP_Abs_Shield = (int)dTmp3;

            iTemp = m_pClientList[sTargetH]
                        ->m_sItemEquipmentStatus[DEF_EQUIPPOS_LHAND];
            if ((iTemp != -1) &&
                (m_pClientList[sTargetH]->m_pItemList[iTemp] != 0)) {
              if ((m_pClientList[sTargetH]->m_cSide != 0) &&
                  (m_pClientList[sTargetH]->m_pItemList[iTemp]->m_wCurLifeSpan >
                   0)) {
                m_pClientList[sTargetH]->m_pItemList[iTemp]->m_wCurLifeSpan--;
                SendNotifyMsg(
                    0, sTargetH, DEF_NOTIFY_CURLIFESPAN, iTemp,
                    m_pClientList[sTargetH]->m_pItemList[iTemp]->m_wCurLifeSpan,
                    0, 0);
              }
              if (m_pClientList[sTargetH]->m_pItemList[iTemp]->m_wCurLifeSpan ==
                  0) {
                SendNotifyMsg(
                    0, sTargetH, DEF_NOTIFY_ITEMLIFESPANEND,
                    m_pClientList[sTargetH]->m_pItemList[iTemp]->m_cEquipPos,
                    iTemp, 0, 0);
                ReleaseItemHandler(sTargetH, iTemp, true);
              }
            }
          }
        }

        iAP_SM = iAP_SM - (iAP_Abs_Armor + iAP_Abs_Shield);
        if (iAP_SM <= 0)
          iAP_SM = 1;

        if ((cAttackerType == DEF_OWNERTYPE_PLAYER) &&
            (m_pClientList[sAttackerH] != 0) &&
            (m_pClientList[sAttackerH]->m_bIsSpecialAbilityEnabled)) {
          switch (m_pClientList[sAttackerH]->m_iSpecialAbilityType) {
          case 0:
            break;
          case 1:
            iTemp = (m_pClientList[sTargetH]->m_iHP / 2);
            if (iTemp > iAP_SM)
              iAP_SM = iTemp;
            if (iAP_SM <= 0)
              iAP_SM = 1;
            break;
          case 2:
            if (m_pClientList[sTargetH]
                    ->m_cMagicEffectStatus[DEF_MAGICTYPE_ICE] == 0) {
              m_pClientList[sTargetH]->m_cMagicEffectStatus[DEF_MAGICTYPE_ICE] =
                  1;
              SetIceFlag(sTargetH, DEF_OWNERTYPE_PLAYER, true);
              bRegisterDelayEvent(DEF_DELAYEVENTTYPE_MAGICRELEASE,
                                  DEF_MAGICTYPE_ICE, dwTime + 30000, sTargetH,
                                  DEF_OWNERTYPE_PLAYER, 0, 0, 0, 1, 0, 0);
              SendNotifyMsg(0, sTargetH, DEF_NOTIFY_MAGICEFFECTON,
                            DEF_MAGICTYPE_ICE, 1, 0, 0);
            }
            break;
          case 3:
            if (m_pClientList[sTargetH]
                    ->m_cMagicEffectStatus[DEF_MAGICTYPE_HOLDOBJECT] == 0) {
              m_pClientList[sTargetH]
                  ->m_cMagicEffectStatus[DEF_MAGICTYPE_HOLDOBJECT] = 2;
              bRegisterDelayEvent(DEF_DELAYEVENTTYPE_MAGICRELEASE,
                                  DEF_MAGICTYPE_HOLDOBJECT, dwTime + 10000,
                                  sTargetH, DEF_OWNERTYPE_PLAYER, 0, 0, 0, 10,
                                  0, 0);
              SendNotifyMsg(0, sTargetH, DEF_NOTIFY_MAGICEFFECTON,
                            DEF_MAGICTYPE_HOLDOBJECT, 10, 0, 0);
            }
            break;
          case 4:
            iAP_SM = (m_pClientList[sTargetH]->m_iHP);
            break;
          case 5:
            m_pClientList[sAttackerH]->m_iHP += iAP_SM;
            if (iGetMaxHP(sAttackerH) < m_pClientList[sAttackerH]->m_iHP)
              m_pClientList[sAttackerH]->m_iHP = iGetMaxHP(sAttackerH);
            SendNotifyMsg(0, sAttackerH, DEF_NOTIFY_HP, 0, 0, 0, 0);
            break;
          }
        }

        if ((cAttackerType == DEF_OWNERTYPE_PLAYER) &&
            (m_pClientList[sAttackerH] != 0) &&
            (m_pClientList[sTargetH]->m_bIsSpecialAbilityEnabled)) {
          switch (m_pClientList[sTargetH]->m_iSpecialAbilityType) {
          case 50:
            if (m_pClientList[sAttackerH]
                    ->m_sItemEquipmentStatus[DEF_EQUIPPOS_TWOHAND] != -1)
              sWeaponIndex = m_pClientList[sAttackerH]
                                 ->m_sItemEquipmentStatus[DEF_EQUIPPOS_TWOHAND];
            else
              sWeaponIndex = m_pClientList[sAttackerH]
                                 ->m_sItemEquipmentStatus[DEF_EQUIPPOS_RHAND];
            if (sWeaponIndex != -1)
              m_pClientList[sAttackerH]
                  ->m_pItemList[sWeaponIndex]
                  ->m_wCurLifeSpan = 0;
            break;
          case 51:
            if (iHitPoint == m_pClientList[sTargetH]->m_iSpecialAbilityEquipPos)
              iAP_SM = 0;
            break;
          case 52:
            iAP_SM = 0;
            break;
          }
        }

        if ((m_pClientList[sTargetH]->m_bIsLuckyEffect) &&
            (iDice(1, 10) == 5) && (m_pClientList[sTargetH]->m_iHP <= iAP_SM)) {
          iAP_SM = m_pClientList[sTargetH]->m_iHP - 1;
        }

        switch (iHitPoint) {
        case 1:
          iTemp = m_pClientList[sTargetH]
                      ->m_sItemEquipmentStatus[DEF_EQUIPPOS_BODY];
          if ((iTemp != -1) &&
              (m_pClientList[sTargetH]->m_pItemList[iTemp] != 0)) {
            bCalculateEnduranceDecrement(sTargetH, sAttackerH, cTargetType,
                                         iTemp);
          }
          break;

        case 2:
          iTemp = m_pClientList[sTargetH]
                      ->m_sItemEquipmentStatus[DEF_EQUIPPOS_PANTS];
          if ((iTemp != -1) &&
              (m_pClientList[sTargetH]->m_pItemList[iTemp] != 0)) {
            bCalculateEnduranceDecrement(sTargetH, sAttackerH, cTargetType,
                                         iTemp);
          } else {
            iTemp = m_pClientList[sTargetH]
                        ->m_sItemEquipmentStatus[DEF_EQUIPPOS_LEGGINGS];
            if ((iTemp != -1) &&
                (m_pClientList[sTargetH]->m_pItemList[iTemp] != 0)) {
              bCalculateEnduranceDecrement(sTargetH, sAttackerH, cTargetType,
                                           iTemp);
            }
          }
          break;

        case 3:
          iTemp = m_pClientList[sTargetH]
                      ->m_sItemEquipmentStatus[DEF_EQUIPPOS_ARMS];
          if ((iTemp != -1) &&
              (m_pClientList[sTargetH]->m_pItemList[iTemp] != 0)) {
            bCalculateEnduranceDecrement(sTargetH, sAttackerH, cTargetType,
                                         iTemp);
          }
          break;

        case 4:
          iTemp = m_pClientList[sTargetH]
                      ->m_sItemEquipmentStatus[DEF_EQUIPPOS_HEAD];
          if ((iTemp != -1) &&
              (m_pClientList[sTargetH]->m_pItemList[iTemp] != 0)) {
            bCalculateEnduranceDecrement(sTargetH, sAttackerH, cTargetType,
                                         iTemp);
          }
          break;
        }

        if ((cAttackerSA == 2) &&
            (m_pClientList[sTargetH]
                 ->m_cMagicEffectStatus[DEF_MAGICTYPE_PROTECT] != 0)) {
          SendNotifyMsg(0, sTargetH, DEF_NOTIFY_MAGICEFFECTOFF,
                        DEF_MAGICTYPE_PROTECT,
                        m_pClientList[sTargetH]
                            ->m_cMagicEffectStatus[DEF_MAGICTYPE_PROTECT],
                        0, 0);
          switch (m_pClientList[sTargetH]
                      ->m_cMagicEffectStatus[DEF_MAGICTYPE_PROTECT]) {
          case 1:
            SetProtectionFromArrowFlag(sTargetH, DEF_OWNERTYPE_PLAYER, false);
            break;
          case 2:
          case 5:
            SetMagicProtectionFlag(sTargetH, DEF_OWNERTYPE_PLAYER, false);
            break;
          case 3:
          case 4:
            SetDefenseShieldFlag(sTargetH, DEF_OWNERTYPE_PLAYER, false);
            break;
          }
          m_pClientList[sTargetH]->m_cMagicEffectStatus[DEF_MAGICTYPE_PROTECT] =
              0;
          bRemoveFromDelayEventList(sTargetH, DEF_OWNERTYPE_PLAYER,
                                    DEF_MAGICTYPE_PROTECT);
        }

        if ((m_pClientList[sTargetH]->m_bIsPoisoned == false) &&
            ((cAttackerSA == 5) || (cAttackerSA == 6) || (cAttackerSA == 61))) {
          if (bCheckResistingPoisonSuccess(sTargetH, DEF_OWNERTYPE_PLAYER) ==
              false) {
            m_pClientList[sTargetH]->m_bIsPoisoned = true;
            if (cAttackerSA == 5)
              m_pClientList[sTargetH]->m_iPoisonLevel = 15;
            else if (cAttackerSA == 6)
              m_pClientList[sTargetH]->m_iPoisonLevel = 40;
            else if (cAttackerSA == 61)
              m_pClientList[sTargetH]->m_iPoisonLevel = iAttackerSAvalue;

            m_pClientList[sTargetH]->m_dwPoisonTime = dwTime;
            SendNotifyMsg(0, sTargetH, DEF_NOTIFY_MAGICEFFECTON,
                          DEF_MAGICTYPE_POISON,
                          m_pClientList[sTargetH]->m_iPoisonLevel, 0, 0);
            SetPoisonFlag(sTargetH, DEF_OWNERTYPE_PLAYER, true);
          }
        }

        m_pClientList[sTargetH]->m_iHP -= iAP_SM;
        if (m_pClientList[sTargetH]->m_iHP <= 0) {
          if (cAttackerType == DEF_OWNERTYPE_PLAYER)
            bAnalyzeCriminalAction(sAttackerH, m_pClientList[sTargetH]->m_sX,
                                   m_pClientList[sTargetH]->m_sY);
          ClientKilledHandler(sTargetH, sAttackerH, cAttackerType, iAP_SM);
          bKilled = true;
          iKilledDice = m_pClientList[sTargetH]->m_iLevel;
        } else {
          if (iAP_SM > 0) {
            if (m_pClientList[sTargetH]->m_iAddTransMana > 0) {
              dTmp1 = (double)m_pClientList[sTargetH]->m_iAddTransMana;
              dTmp2 = (double)iAP_SM;
              dTmp3 = (dTmp1 / 100.0f) * dTmp2;
              iTemp = iGetMaxMP(sTargetH);
              m_pClientList[sTargetH]->m_iMP += (int)dTmp3;
              if (m_pClientList[sTargetH]->m_iMP > iTemp)
                m_pClientList[sTargetH]->m_iMP = iTemp;
            }
            if (m_pClientList[sTargetH]->m_iAddChargeCritical > 0) {
              if (iDice(1, 100) <=
                  (m_pClientList[sTargetH]->m_iAddChargeCritical)) {
                iMaxSuperAttack = (m_pClientList[sTargetH]->m_iLevel / 10);
                if (m_pClientList[sTargetH]->m_iSuperAttackLeft <
                    iMaxSuperAttack)
                  m_pClientList[sTargetH]->m_iSuperAttackLeft++;
                SendNotifyMsg(0, sTargetH, DEF_NOTIFY_SUPERATTACKLEFT, 0, 0, 0,
                              0);
              }
            }

            SendNotifyMsg(0, sTargetH, DEF_NOTIFY_HP, 0, 0, 0, 0);

            if (cAttackerType == DEF_OWNERTYPE_PLAYER)
              sAttackerWeapon =
                  ((m_pClientList[sAttackerH]->m_sAppr2 & 0x0FF0) >> 4);
            else
              sAttackerWeapon = 1;

            if ((cAttackerType == DEF_OWNERTYPE_PLAYER) &&
                (m_pMapList[m_pClientList[sAttackerH]->m_cMapIndex]
                     ->m_bIsFightZone))
              iMoveDamage = 60;
            else
              iMoveDamage = 40;

            if (iAP_SM >= iMoveDamage) {
              if (sTgtX == sAtkX) {
                if (sTgtY == sAtkY)
                  goto CAE_SKIPDAMAGEMOVE;
                else if (sTgtY > sAtkY)
                  cDamageMoveDir = 5;
                else if (sTgtY < sAtkY)
                  cDamageMoveDir = 1;
              } else if (sTgtX > sAtkX) {
                if (sTgtY == sAtkY)
                  cDamageMoveDir = 3;
                else if (sTgtY > sAtkY)
                  cDamageMoveDir = 4;
                else if (sTgtY < sAtkY)
                  cDamageMoveDir = 2;
              } else if (sTgtX < sAtkX) {
                if (sTgtY == sAtkY)
                  cDamageMoveDir = 7;
                else if (sTgtY > sAtkY)
                  cDamageMoveDir = 6;
                else if (sTgtY < sAtkY)
                  cDamageMoveDir = 8;
              }
              m_pClientList[sTargetH]->m_iLastDamage = iAP_SM;

              SendNotifyMsg(0, sTargetH, DEF_NOTIFY_DAMAGEMOVE, cDamageMoveDir,
                            iAP_SM, sAttackerWeapon, 0);
            } else {
            CAE_SKIPDAMAGEMOVE:
              int iProb;
              if (cAttackerType == DEF_OWNERTYPE_PLAYER) {
                switch (m_pClientList[sAttackerH]->m_sUsingWeaponSkill) {
                case 6:
                  iProb = 3500;
                  break;
                case 8:
                  iProb = 1000;
                  break;
                case 9:
                  iProb = 2900;
                  break;
                case 10:
                  iProb = 2500;
                  break;
                case 14:
                  iProb = 2000;
                  break;
                case 21:
                  iProb = 2000;
                  break;
                default:
                  iProb = 1;
                  break;
                }
              } else
                iProb = 1;

              if (iDice(1, 10000) >= iProb)
                SendEventToNearClient_TypeA(
                    sTargetH, DEF_OWNERTYPE_PLAYER, MSGID_EVENT_MOTION,
                    DEF_OBJECTDAMAGE, iAP_SM, sAttackerWeapon, 0);
            }

            if (m_pClientList[sTargetH]
                    ->m_cMagicEffectStatus[DEF_MAGICTYPE_HOLDOBJECT] == 1) {
              SendNotifyMsg(
                  0, sTargetH, DEF_NOTIFY_MAGICEFFECTOFF,
                  DEF_MAGICTYPE_HOLDOBJECT,
                  m_pClientList[sTargetH]
                      ->m_cMagicEffectStatus[DEF_MAGICTYPE_HOLDOBJECT],
                  0, 0);
              m_pClientList[sTargetH]
                  ->m_cMagicEffectStatus[DEF_MAGICTYPE_HOLDOBJECT] = 0;
              bRemoveFromDelayEventList(sTargetH, DEF_OWNERTYPE_PLAYER,
                                        DEF_MAGICTYPE_HOLDOBJECT);
            }

            m_pClientList[sTargetH]->m_iSuperAttackCount++;
            if (m_pClientList[sTargetH]->m_iSuperAttackCount > 14) {
              m_pClientList[sTargetH]->m_iSuperAttackCount = 0;
              iMaxSuperAttack = (m_pClientList[sTargetH]->m_iLevel / 10);
              if (m_pClientList[sTargetH]->m_iSuperAttackLeft < iMaxSuperAttack)
                m_pClientList[sTargetH]->m_iSuperAttackLeft++;
              SendNotifyMsg(0, sTargetH, DEF_NOTIFY_SUPERATTACKLEFT, 0, 0, 0,
                            0);
            }
          }
        }
      }
      break;

    case DEF_OWNERTYPE_NPC:
      if (m_pNpcList[sTargetH]->m_cBehavior == DEF_BEHAVIOR_DEAD)
        return 0;
      if (m_pNpcList[sTargetH]->m_bIsKilled)
        return 0;
      if (m_bIsCrusadeMode) {
        if (cAttackerSide == m_pNpcList[sTargetH]->m_cSide) {
          switch (m_pNpcList[sTargetH]->m_sType) {
          case 40:
          case 41:
          case 43:
          case 44:
          case 45:
          case 46:
          case 47:
          case 51:
            return 0;

          default:
            break;
          }
        } else {
          switch (m_pNpcList[sTargetH]->m_sType) {
          case 41:
            if (cAttackerSide != 0) {
              m_pNpcList[sTargetH]->m_iV1 += iAP_L;
              if (m_pNpcList[sTargetH]->m_iV1 > 500) {
                m_pNpcList[sTargetH]->m_iV1 = 0;
                m_pNpcList[sTargetH]->m_iManaStock--;
                if (m_pNpcList[sTargetH]->m_iManaStock <= 0)
                  m_pNpcList[sTargetH]->m_iManaStock = 0;
                wsprintf(G_cTxt, "ManaStock down: %d",
                         m_pNpcList[sTargetH]->m_iManaStock);
                PutLogList(G_cTxt);
              }
            }
            break;
          }
        }
      }
      switch (m_pNpcList[sTargetH]->m_cActionLimit) {
      case 1:
      case 2:
        return 0;
      }

      if (m_pNpcList[sTargetH]->m_cSize == 0)
        iDamage = iAP_SM;
      else
        iDamage = iAP_L;

      if (m_pNpcList[sTargetH]->m_iAbsDamage < 0) {
        dTmp1 = (double)iDamage;
        dTmp2 = (double)(abs(m_pNpcList[sTargetH]->m_iAbsDamage)) / 100.0f;
        dTmp3 = dTmp1 * dTmp2;
        dTmp2 = dTmp1 - dTmp3;
        iDamage = (int)dTmp2;
        if (iDamage < 0)
          iDamage = 1;
        else if ((m_pNpcList[sTargetH]->m_sType == 31) &&
                 (cAttackerType == 1) && (m_pClientList[sAttackerH] != 0) &&
                 (m_pClientList[sAttackerH]->m_iSpecialAbilityType == 7))
          iDamage += iDice(3, 2);
      }

      if ((cAttackerSA == 2) &&
          (m_pNpcList[sTargetH]->m_cMagicEffectStatus[DEF_MAGICTYPE_PROTECT] !=
           0)) {
        switch (
            m_pNpcList[sTargetH]->m_cMagicEffectStatus[DEF_MAGICTYPE_PROTECT]) {
        case 1:
          SetProtectionFromArrowFlag(sTargetH, DEF_OWNERTYPE_NPC, false);
          break;
        case 2:
        case 5:
          SetMagicProtectionFlag(sTargetH, DEF_OWNERTYPE_NPC, false);
          break;
        case 3:
        case 4:
          SetDefenseShieldFlag(sTargetH, DEF_OWNERTYPE_NPC, false);
          break;
        }
        m_pNpcList[sTargetH]->m_cMagicEffectStatus[DEF_MAGICTYPE_PROTECT] = 0;
        bRemoveFromDelayEventList(sTargetH, DEF_OWNERTYPE_NPC,
                                  DEF_MAGICTYPE_PROTECT);
      }

      switch (m_pNpcList[sTargetH]->m_cActionLimit) {
      case 0:
      case 3:
      case 5:
        m_pNpcList[sTargetH]->m_iHP -= iDamage;
        break;
      }

      if (m_pNpcList[sTargetH]->m_iHP <= 0) {
        NpcKilledHandler(sAttackerH, cAttackerType, sTargetH, iDamage);
        bKilled = true;
        iKilledDice = m_pNpcList[sTargetH]->m_iHitDice;
      } else {
        if ((m_pNpcList[sTargetH]->m_sType != 21) &&
            (m_pNpcList[sTargetH]->m_sType != 55) &&
            (m_pNpcList[sTargetH]->m_sType != 56) &&
            (m_pNpcList[sTargetH]->m_cSide == cAttackerSide))
          goto CAE_SKIPCOUNTERATTACK;

        if (m_pNpcList[sTargetH]->m_cActionLimit != 0)
          goto CAE_SKIPCOUNTERATTACK;
        if (m_pNpcList[sTargetH]->m_bIsPermAttackMode)
          goto CAE_SKIPCOUNTERATTACK;
        if ((m_pNpcList[sTargetH]->m_bIsSummoned) &&
            (m_pNpcList[sTargetH]->m_iSummonControlMode == 1))
          goto CAE_SKIPCOUNTERATTACK;
        if (m_pNpcList[sTargetH]->m_sType == 51)
          goto CAE_SKIPCOUNTERATTACK;

        if (iDice(1, 3) == 2) {
          if (m_pNpcList[sTargetH]->m_cBehavior == DEF_BEHAVIOR_ATTACK) {
            tX = tY = 0;
            switch (m_pNpcList[sTargetH]->m_cTargetType) {
            case DEF_OWNERTYPE_PLAYER:
              if (m_pClientList[m_pNpcList[sTargetH]->m_iTargetIndex] != 0) {
                tX = m_pClientList[m_pNpcList[sTargetH]->m_iTargetIndex]->m_sX;
                tY = m_pClientList[m_pNpcList[sTargetH]->m_iTargetIndex]->m_sY;
              }
              break;

            case DEF_OWNERTYPE_NPC:
              if (m_pNpcList[m_pNpcList[sTargetH]->m_iTargetIndex] != 0) {
                tX = m_pNpcList[m_pNpcList[sTargetH]->m_iTargetIndex]->m_sX;
                tY = m_pNpcList[m_pNpcList[sTargetH]->m_iTargetIndex]->m_sY;
              }
              break;
            }

            iDst1 = (m_pNpcList[sTargetH]->m_sX - tX) *
                        (m_pNpcList[sTargetH]->m_sX - tX) +
                    (m_pNpcList[sTargetH]->m_sY - tY) *
                        (m_pNpcList[sTargetH]->m_sY - tY);

            tX = tY = 0;
            switch (cAttackerType) {
            case DEF_OWNERTYPE_PLAYER:
              if (m_pClientList[sAttackerH] != 0) {
                tX = m_pClientList[sAttackerH]->m_sX;
                tY = m_pClientList[sAttackerH]->m_sY;
              }
              break;

            case DEF_OWNERTYPE_NPC:
              if (m_pNpcList[sAttackerH] != 0) {
                tX = m_pNpcList[sAttackerH]->m_sX;
                tY = m_pNpcList[sAttackerH]->m_sY;
              }
              break;
            }

            iDst2 = (m_pNpcList[sTargetH]->m_sX - tX) *
                        (m_pNpcList[sTargetH]->m_sX - tX) +
                    (m_pNpcList[sTargetH]->m_sY - tY) *
                        (m_pNpcList[sTargetH]->m_sY - tY);

            if (iDst2 <= iDst1) {
              m_pNpcList[sTargetH]->m_cBehavior = DEF_BEHAVIOR_ATTACK;
              m_pNpcList[sTargetH]->m_sBehaviorTurnCount = 0;
              m_pNpcList[sTargetH]->m_iTargetIndex = sAttackerH;
              m_pNpcList[sTargetH]->m_cTargetType = cAttackerType;
            }
          } else {
            m_pNpcList[sTargetH]->m_cBehavior = DEF_BEHAVIOR_ATTACK;
            m_pNpcList[sTargetH]->m_sBehaviorTurnCount = 0;
            m_pNpcList[sTargetH]->m_iTargetIndex = sAttackerH;
            m_pNpcList[sTargetH]->m_cTargetType = cAttackerType;
          }
        }

      CAE_SKIPCOUNTERATTACK:

        if ((iDice(1, 3) == 2) && (m_pNpcList[sTargetH]->m_cActionLimit == 0))
          m_pNpcList[sTargetH]->m_dwTime = dwTime;

        if (cAttackerType == DEF_OWNERTYPE_PLAYER)
          sAttackerWeapon =
              ((m_pClientList[sAttackerH]->m_sAppr2 & 0x0FF0) >> 4);
        else
          sAttackerWeapon = 1;

        if ((wWeaponType < 40) && (m_pNpcList[sTargetH]->m_cActionLimit == 4)) {
          if (sTgtX == sAtkX) {
            if (sTgtY == sAtkY)
              goto CAE_SKIPDAMAGEMOVE2;
            else if (sTgtY > sAtkY)
              cDamageMoveDir = 5;
            else if (sTgtY < sAtkY)
              cDamageMoveDir = 1;
          } else if (sTgtX > sAtkX) {
            if (sTgtY == sAtkY)
              cDamageMoveDir = 3;
            else if (sTgtY > sAtkY)
              cDamageMoveDir = 4;
            else if (sTgtY < sAtkY)
              cDamageMoveDir = 2;
          } else if (sTgtX < sAtkX) {
            if (sTgtY == sAtkY)
              cDamageMoveDir = 7;
            else if (sTgtY > sAtkY)
              cDamageMoveDir = 6;
            else if (sTgtY < sAtkY)
              cDamageMoveDir = 8;
          }

          dX = m_pNpcList[sTargetH]->m_sX + _tmp_cTmpDirX[cDamageMoveDir];
          dY = m_pNpcList[sTargetH]->m_sY + _tmp_cTmpDirY[cDamageMoveDir];

          if (m_pMapList[m_pNpcList[sTargetH]->m_cMapIndex]->bGetMoveable(
                  dX, dY, 0) == false) {
            cDamageMoveDir = iDice(1, 8);
            dX = m_pNpcList[sTargetH]->m_sX + _tmp_cTmpDirX[cDamageMoveDir];
            dY = m_pNpcList[sTargetH]->m_sY + _tmp_cTmpDirY[cDamageMoveDir];

            if (m_pMapList[m_pNpcList[sTargetH]->m_cMapIndex]->bGetMoveable(
                    dX, dY, 0) == false)
              goto CAE_SKIPDAMAGEMOVE2;
          }

          m_pMapList[m_pNpcList[sTargetH]->m_cMapIndex]->ClearOwner(
              5, sTargetH, DEF_OWNERTYPE_NPC, m_pNpcList[sTargetH]->m_sX,
              m_pNpcList[sTargetH]->m_sY);
          m_pMapList[m_pNpcList[sTargetH]->m_cMapIndex]->SetOwner(
              sTargetH, DEF_OWNERTYPE_NPC, dX, dY);
          m_pNpcList[sTargetH]->m_sX = dX;
          m_pNpcList[sTargetH]->m_sY = dY;
          m_pNpcList[sTargetH]->m_cDir = cDamageMoveDir;

          SendEventToNearClient_TypeA(sTargetH, DEF_OWNERTYPE_NPC,
                                      MSGID_EVENT_MOTION, DEF_OBJECTMOVE, 0, 0,
                                      0);

          dX = m_pNpcList[sTargetH]->m_sX + _tmp_cTmpDirX[cDamageMoveDir];
          dY = m_pNpcList[sTargetH]->m_sY + _tmp_cTmpDirY[cDamageMoveDir];

          if (m_pMapList[m_pNpcList[sTargetH]->m_cMapIndex]->bGetMoveable(
                  dX, dY, 0) == false) {
            cDamageMoveDir = iDice(1, 8);
            dX = m_pNpcList[sTargetH]->m_sX + _tmp_cTmpDirX[cDamageMoveDir];
            dY = m_pNpcList[sTargetH]->m_sY + _tmp_cTmpDirY[cDamageMoveDir];
            if (m_pMapList[m_pNpcList[sTargetH]->m_cMapIndex]->bGetMoveable(
                    dX, dY, 0) == false)
              goto CAE_SKIPDAMAGEMOVE2;
          }

          m_pMapList[m_pNpcList[sTargetH]->m_cMapIndex]->ClearOwner(
              5, sTargetH, DEF_OWNERTYPE_NPC, m_pNpcList[sTargetH]->m_sX,
              m_pNpcList[sTargetH]->m_sY);
          m_pMapList[m_pNpcList[sTargetH]->m_cMapIndex]->SetOwner(
              sTargetH, DEF_OWNERTYPE_NPC, dX, dY);
          m_pNpcList[sTargetH]->m_sX = dX;
          m_pNpcList[sTargetH]->m_sY = dY;
          m_pNpcList[sTargetH]->m_cDir = cDamageMoveDir;

          SendEventToNearClient_TypeA(sTargetH, DEF_OWNERTYPE_NPC,
                                      MSGID_EVENT_MOTION, DEF_OBJECTMOVE, 0, 0,
                                      0);

          if (bCheckEnergySphereDestination(sTargetH, sAttackerH,
                                            cAttackerType)) {
            if (cAttackerType == DEF_OWNERTYPE_PLAYER) {
              iExp = (m_pNpcList[sTargetH]->m_iExp / 3);
              if (m_pNpcList[sTargetH]->m_iNoDieRemainExp > 0)
                iExp += m_pNpcList[sTargetH]->m_iNoDieRemainExp;

              if (m_pClientList[sAttackerH]->m_iAddExp != 0) {
                dTmp1 = (double)m_pClientList[sAttackerH]->m_iAddExp;
                dTmp2 = (double)iExp;
                dTmp3 = (dTmp1 / 100.0f) * dTmp2;
                iExp += (int)dTmp3;
              }

              if ((m_bIsCrusadeMode) && (iExp > 10))
                iExp = 10;

              GetExp(sAttackerH, iExp);

              DeleteNpc(sTargetH);
              return false;
            }
          }

        CAE_SKIPDAMAGEMOVE2:;
        } else {
          SendEventToNearClient_TypeA(sTargetH, DEF_OWNERTYPE_NPC,
                                      MSGID_EVENT_MOTION, DEF_OBJECTDAMAGE,
                                      iDamage, sAttackerWeapon, 0);
        }

        if (m_pNpcList[sTargetH]
                ->m_cMagicEffectStatus[DEF_MAGICTYPE_HOLDOBJECT] == 1) {
          m_pNpcList[sTargetH]->m_cMagicEffectStatus[DEF_MAGICTYPE_HOLDOBJECT] =
              0;
          bRemoveFromDelayEventList(sTargetH, DEF_OWNERTYPE_NPC,
                                    DEF_MAGICTYPE_HOLDOBJECT);
        } else if (m_pNpcList[sTargetH]
                       ->m_cMagicEffectStatus[DEF_MAGICTYPE_HOLDOBJECT] == 2) {
          if ((m_pNpcList[sTargetH]->m_iHitDice > 50) && (iDice(1, 10) == 5)) {
            m_pNpcList[sTargetH]
                ->m_cMagicEffectStatus[DEF_MAGICTYPE_HOLDOBJECT] = 0;
            bRemoveFromDelayEventList(sTargetH, DEF_OWNERTYPE_NPC,
                                      DEF_MAGICTYPE_HOLDOBJECT);
          }
        }

        if ((m_pNpcList[sTargetH]->m_iNoDieRemainExp > 0) &&
            (m_pNpcList[sTargetH]->m_bIsSummoned != true) &&
            (cAttackerType == DEF_OWNERTYPE_PLAYER) &&
            (m_pClientList[sAttackerH] != 0)) {
          if (m_pNpcList[sTargetH]->m_iNoDieRemainExp > iDamage) {
            iExp = iDamage;
            m_pNpcList[sTargetH]->m_iNoDieRemainExp -= iDamage;
          } else {
            iExp = m_pNpcList[sTargetH]->m_iNoDieRemainExp;
            m_pNpcList[sTargetH]->m_iNoDieRemainExp = 0;
          }

          if (m_pClientList[sAttackerH]->m_iAddExp != 0) {
            dTmp1 = (double)m_pClientList[sAttackerH]->m_iAddExp;
            dTmp2 = (double)iExp;
            dTmp3 = (dTmp1 / 100.0f) * dTmp2;
            iExp += (int)dTmp3;
          }

          if (m_bIsCrusadeMode)
            iExp = iExp / 3;

          if (m_pClientList[sAttackerH]->m_iLevel > 100) {
            switch (m_pNpcList[sTargetH]->m_sType) {
            case 55:
            case 56:
              iExp = 0;
              break;
            default:
              break;
            }
          }
        }
      }
      break;
    }

    if (cAttackerType == DEF_OWNERTYPE_PLAYER) {
      if (m_pClientList[sAttackerH]
              ->m_sItemEquipmentStatus[DEF_EQUIPPOS_TWOHAND] != -1)
        sWeaponIndex = m_pClientList[sAttackerH]
                           ->m_sItemEquipmentStatus[DEF_EQUIPPOS_TWOHAND];
      else
        sWeaponIndex = m_pClientList[sAttackerH]
                           ->m_sItemEquipmentStatus[DEF_EQUIPPOS_RHAND];

      if ((sWeaponIndex != -1) && (bArrowUse != true)) {
        if ((m_pClientList[sAttackerH]->m_pItemList[sWeaponIndex] != 0) &&
            (m_pClientList[sAttackerH]->m_pItemList[sWeaponIndex]->m_sIDnum !=
             231)) {
          if (bKilled == false)
            CalculateSSN_ItemIndex(sAttackerH, sWeaponIndex, 1);
          else {
            if (m_pClientList[sAttackerH]->m_iHP <= 3)
              CalculateSSN_ItemIndex(sAttackerH, sWeaponIndex,
                                     iDice(1, iKilledDice) * 2);
            else
              CalculateSSN_ItemIndex(sAttackerH, sWeaponIndex,
                                     iDice(1, iKilledDice));
          }
        }

        if ((m_pClientList[sAttackerH]->m_pItemList[sWeaponIndex] != 0) &&
            (m_pClientList[sAttackerH]
                 ->m_pItemList[sWeaponIndex]
                 ->m_wMaxLifeSpan != 0)) {
          iWepLifeOff = 1;
          if ((wWeaponType >= 1) && (wWeaponType < 40)) {
            switch (m_pMapList[m_pClientList[sAttackerH]->m_cMapIndex]
                        ->m_cWhetherStatus) {
            case 0:
              break;
            case 1:
              if (iDice(1, 3) == 1)
                iWepLifeOff++;
              break;
            case 2:
              if (iDice(1, 2) == 1)
                iWepLifeOff += iDice(1, 2);
              break;
            case 3:
              if (iDice(1, 2) == 1)
                iWepLifeOff += iDice(1, 3);
              break;
            }
          }

          if (m_pClientList[sAttackerH]->m_cSide != 0) {
            if (m_pClientList[sAttackerH]
                    ->m_pItemList[sWeaponIndex]
                    ->m_wCurLifeSpan < iWepLifeOff)
              m_pClientList[sAttackerH]
                  ->m_pItemList[sWeaponIndex]
                  ->m_wCurLifeSpan = 0;
            else
              m_pClientList[sAttackerH]
                  ->m_pItemList[sWeaponIndex]
                  ->m_wCurLifeSpan -= iWepLifeOff;

            SendNotifyMsg(0, sAttackerH, DEF_NOTIFY_CURLIFESPAN, sWeaponIndex,
                          m_pClientList[sAttackerH]
                              ->m_pItemList[sWeaponIndex]
                              ->m_wCurLifeSpan,
                          0, 0);
          }

          if (m_pClientList[sAttackerH]
                  ->m_pItemList[sWeaponIndex]
                  ->m_wCurLifeSpan == 0) {
            SendNotifyMsg(0, sAttackerH, DEF_NOTIFY_ITEMLIFESPANEND,
                          m_pClientList[sAttackerH]
                              ->m_pItemList[sWeaponIndex]
                              ->m_cEquipPos,
                          sWeaponIndex, 0, 0);
            ReleaseItemHandler(sAttackerH, sWeaponIndex, true);
          }
        }
      } else {
        if (wWeaponType == 0) {
          CalculateSSN_SkillIndex(sAttackerH, 5, 1);
        }
      }
    }
  } else {
    if (cAttackerType == DEF_OWNERTYPE_PLAYER) {
      m_pClientList[sAttackerH]->m_iComboAttackCount = 0;
    }
  }

  return iExp;
}

