// October 19, 2004 - 3.51 translated
bool CGame::_bNpcBehavior_ManaCollector(int iNpcH) {
  int dX, dY, iMaxMP, iTotal;
  short sOwnerH;
  char cOwnerType;
  double dV1, dV2, dV3;
  bool bRet;

  if (m_pNpcList[iNpcH] == 0)
    return false;
  if (m_pNpcList[iNpcH]->m_sAppr2 != 0)
    return false;

  bRet = false;
  for (dX = m_pNpcList[iNpcH]->m_sX - 5; dX <= m_pNpcList[iNpcH]->m_sX + 5;
       dX++)
    for (dY = m_pNpcList[iNpcH]->m_sY - 5; dY <= m_pNpcList[iNpcH]->m_sY + 5;
         dY++) {
      m_pMapList[m_pNpcList[iNpcH]->m_cMapIndex]->GetOwner(&sOwnerH,
                                                           &cOwnerType, dX, dY);
      if (sOwnerH != 0) {
        switch (cOwnerType) {
        case DEF_OWNERTYPE_PLAYER:
          if (m_pNpcList[iNpcH]->m_cSide == m_pClientList[sOwnerH]->m_cSide) {
            iMaxMP = iGetMaxMP(sOwnerH);
            if (m_pClientList[sOwnerH]->m_iMP < iMaxMP) {
              iTotal = iDice(1, (m_pClientList[sOwnerH]->m_iMag +
                                 m_pClientList[sOwnerH]->m_iAngelicMag));
              if (m_pClientList[sOwnerH]->m_iAddMP != 0) {
                dV2 = (double)iTotal;
                dV3 = (double)m_pClientList[sOwnerH]->m_iAddMP;
                dV1 = (dV3 / 100.0f) * dV2;
                iTotal += (int)dV1;
              }

              m_pClientList[sOwnerH]->m_iMP += iTotal;

              if (m_pClientList[sOwnerH]->m_iMP > iMaxMP)
                m_pClientList[sOwnerH]->m_iMP = iMaxMP;

              SendNotifyMsg(0, sOwnerH, DEF_NOTIFY_MP, 0, 0, 0, 0);
            }
          }
          break;

        case DEF_OWNERTYPE_NPC:
          if ((m_pNpcList[sOwnerH]->m_sType == 42) &&
              (m_pNpcList[sOwnerH]->m_iV1 > 0)) {
            if (m_pNpcList[sOwnerH]->m_iV1 >= 3) {
              m_iCollectedMana[m_pNpcList[iNpcH]->m_cSide] += 3;
              m_pNpcList[sOwnerH]->m_iV1 -= 3;
              bRet = true;
            } else {
              m_iCollectedMana[m_pNpcList[iNpcH]->m_cSide] +=
                  m_pNpcList[sOwnerH]->m_iV1;
              m_pNpcList[sOwnerH]->m_iV1 = 0;
              bRet = true;
            }
          }
          break;
        }
      }
    }
  return bRet;
}

// October 19, 2004 - 3.51 translated
void CGame::MeteorStrikeMsgHandler(char cAttackerSide) {
  int i;
  DWORD dwTime = timeGetTime();

  switch (cAttackerSide) {
  case 1:
    if (m_iElvineMapIndex != -1) {
      for (i = 1; i < DEF_MAXCLIENTS; i++)
        if ((m_pClientList[i] != 0) && (m_pClientList[i]->m_bIsInitComplete)) {
          if (strcmp(m_pMapList[m_pClientList[i]->m_cMapIndex]->m_cLocationName,
                     "elvine") == 0) {
            SendNotifyMsg(0, i, DEF_NOTIFY_METEORSTRIKECOMING, 1, 0, 0, 0);
          } else {
            SendNotifyMsg(0, i, DEF_NOTIFY_METEORSTRIKECOMING, 2, 0, 0, 0);
          }
        }
      bRegisterDelayEvent(DEF_DELAYEVENTTYPE_METEORSTRIKE, 0, dwTime + 5000, 0,
                          0, m_iElvineMapIndex, 0, 0, 0, 0, 0);
    } else {
      for (i = 1; i < DEF_MAXCLIENTS; i++)
        if (m_pClientList[i] != 0) {
          SendNotifyMsg(0, i, DEF_NOTIFY_METEORSTRIKECOMING, 2, 0, 0, 0);
        }
    }
    break;

  case 2:
    if (m_iAresdenMapIndex != -1) {
      for (i = 1; i < DEF_MAXCLIENTS; i++)
        if ((m_pClientList[i] != 0) && (m_pClientList[i]->m_bIsInitComplete)) {
          if (strcmp(m_pMapList[m_pClientList[i]->m_cMapIndex]->m_cLocationName,
                     "aresden") == 0) {
            SendNotifyMsg(0, i, DEF_NOTIFY_METEORSTRIKECOMING, 3, 0, 0, 0);
          } else {
            SendNotifyMsg(0, i, DEF_NOTIFY_METEORSTRIKECOMING, 4, 0, 0, 0);
          }
        }
      bRegisterDelayEvent(DEF_DELAYEVENTTYPE_METEORSTRIKE, 0, dwTime + 1000 * 5,
                          0, 0, m_iAresdenMapIndex, 0, 0, 0, 0, 0);
    } else {
      for (i = 1; i < DEF_MAXCLIENTS; i++)
        if (m_pClientList[i] != 0) {
          SendNotifyMsg(0, i, DEF_NOTIFY_METEORSTRIKECOMING, 4, 0, 0, 0);
        }
    }
    break;
  }
}

// October 19, 2004 - 3.51 translated
void CGame::_NpcBehavior_GrandMagicGenerator(int iNpcH) {
  switch (m_pNpcList[iNpcH]->m_cSide) {
  case 1:
    if (m_iAresdenMana > DEF_GMGMANACONSUMEUNIT) {
      m_iAresdenMana = 0;
      m_pNpcList[iNpcH]->m_iManaStock++;
      if (m_pNpcList[iNpcH]->m_iManaStock > m_pNpcList[iNpcH]->m_iMaxMana) {
        _GrandMagicLaunchMsgSend(1, 1);
        MeteorStrikeMsgHandler(1);
        m_pNpcList[iNpcH]->m_iManaStock = 0;
        m_iAresdenMana = 0;
      }
      wsprintf(G_cTxt, "(!) Aresden GMG %d/%d", m_pNpcList[iNpcH]->m_iManaStock,
               m_pNpcList[iNpcH]->m_iMaxMana);
      PutLogList(G_cTxt);
    }
    break;

  case 2:
    if (m_iElvineMana > DEF_GMGMANACONSUMEUNIT) {
      m_iElvineMana = 0;
      m_pNpcList[iNpcH]->m_iManaStock++;
      if (m_pNpcList[iNpcH]->m_iManaStock > m_pNpcList[iNpcH]->m_iMaxMana) {
        _GrandMagicLaunchMsgSend(1, 2);
        MeteorStrikeMsgHandler(2);
        m_pNpcList[iNpcH]->m_iManaStock = 0;
        m_iElvineMana = 0;
      }
      wsprintf(G_cTxt, "(!) Elvine GMG %d/%d", m_pNpcList[iNpcH]->m_iManaStock,
               m_pNpcList[iNpcH]->m_iMaxMana);
      PutLogList(G_cTxt);
    }
    break;
  }
}

// October 19, 2004 - 3.51 translated
bool CGame::_bNpcBehavior_Detector(int iNpcH) {
  int dX, dY;
  short sOwnerH;
  char cOwnerType, cSide;
  bool bFlag = false;

  if (m_pNpcList[iNpcH] == 0)
    return false;
  if (m_pNpcList[iNpcH]->m_sAppr2 != 0)
    return false;

  for (dX = m_pNpcList[iNpcH]->m_sX - 10; dX <= m_pNpcList[iNpcH]->m_sX + 10;
       dX++)
    for (dY = m_pNpcList[iNpcH]->m_sY - 10; dY <= m_pNpcList[iNpcH]->m_sY + 10;
         dY++) {
      m_pMapList[m_pNpcList[iNpcH]->m_cMapIndex]->GetOwner(&sOwnerH,
                                                           &cOwnerType, dX, dY);

      cSide = 0;
      if (sOwnerH != 0) {
        switch (cOwnerType) {
        case DEF_OWNERTYPE_PLAYER:
          cSide = m_pClientList[sOwnerH]->m_cSide;
          break;

        case DEF_OWNERTYPE_NPC:
          cSide = m_pNpcList[sOwnerH]->m_cSide;
          break;
        }
      }

      if ((cSide != 0) && (cSide != m_pNpcList[iNpcH]->m_cSide)) {
        switch (cOwnerType) {
        case DEF_OWNERTYPE_PLAYER:
          if (m_pClientList[sOwnerH]
                  ->m_cMagicEffectStatus[DEF_MAGICTYPE_INVISIBILITY] != 0) {
            m_pClientList[sOwnerH]
                ->m_cMagicEffectStatus[DEF_MAGICTYPE_INVISIBILITY] = 0;
            SetInvisibilityFlag(sOwnerH, cOwnerType, false);
          }
          break;

        case DEF_OWNERTYPE_NPC:
          if (m_pNpcList[sOwnerH]
                  ->m_cMagicEffectStatus[DEF_MAGICTYPE_INVISIBILITY] != 0) {
            m_pNpcList[sOwnerH]
                ->m_cMagicEffectStatus[DEF_MAGICTYPE_INVISIBILITY] = 0;
            SetInvisibilityFlag(sOwnerH, cOwnerType, false);
          }
          break;
        }

        bFlag = true;
      }
    }

  return bFlag;
}

// October 19,2004 - 3.51 translated
void CGame::NpcBehavior_Dead(int iNpcH) {
  DWORD dwTime;

  if (m_pNpcList[iNpcH] == 0)
    return;

  dwTime = timeGetTime();
  m_pNpcList[iNpcH]->m_sBehaviorTurnCount++;
  if (m_pNpcList[iNpcH]->m_sBehaviorTurnCount > 5) {
    m_pNpcList[iNpcH]->m_sBehaviorTurnCount = 0;
  }

  if ((dwTime - m_pNpcList[iNpcH]->m_dwDeadTime) >
      m_pNpcList[iNpcH]->m_dwRegenTime)
    DeleteNpc(iNpcH);
}

