bool CGame::_bCheckCharacterData(int iClientH) {
  int i;

  if ((m_pClientList[iClientH]->m_iStr > m_sCharStatLimit) ||
      (m_pClientList[iClientH]->m_iVit > m_sCharStatLimit) ||
      (m_pClientList[iClientH]->m_iDex > m_sCharStatLimit) ||
      (m_pClientList[iClientH]->m_iMag > m_sCharStatLimit) ||
      (m_pClientList[iClientH]->m_iInt > m_sCharStatLimit) ||
      (m_pClientList[iClientH]->m_iCharisma > m_sCharStatLimit)) {
    try {
      wsprintf(G_cTxt,
               "Packet Editing: (%s) Player: (%s) stat points are greater then "
               "server accepts.",
               m_pClientList[iClientH]->m_cIPaddress,
               m_pClientList[iClientH]->m_cCharName);
      PutHackLogFileList(G_cTxt);
      return false;
    } catch (...) {
    }
  }

  if ((m_pClientList[iClientH]->m_iLevel > m_iPlayerMaxLevel) &&
      (m_pClientList[iClientH]->m_iAdminUserLevel == 0)) {
    try {
      wsprintf(
          G_cTxt,
          "Packet Editing: (%s) Player: (%s) level above max server level.",
          m_pClientList[iClientH]->m_cIPaddress,
          m_pClientList[iClientH]->m_cCharName);
      PutHackLogFileList(G_cTxt);
      return false;
    } catch (...) {
    }
  }

  if (m_pClientList[iClientH]->m_iExp < 0) {
    try {
      wsprintf(
          G_cTxt,
          "Packet Editing: (%s) Player: (%s) experience is below 0 - (Exp:%d).",
          m_pClientList[iClientH]->m_cIPaddress,
          m_pClientList[iClientH]->m_cCharName,
          m_pClientList[iClientH]->m_iExp);
      PutHackLogFileList(G_cTxt);
      return false;
    } catch (...) {
    }
  }

  if ((m_pClientList[iClientH]->m_iHP > iGetMaxHP(iClientH)) &&
      (m_pClientList[iClientH]->m_iAdminUserLevel == 0)) {
    try {
      if (m_pClientList[iClientH]->m_pItemList[(
              m_pClientList[iClientH]
                  ->m_sItemEquipmentStatus[DEF_EQUIPPOS_RHAND])] != 0) {
        if ((m_pClientList[iClientH]
                 ->m_pItemList[(
                     m_pClientList[iClientH]
                         ->m_sItemEquipmentStatus[DEF_EQUIPPOS_RHAND])]
                 ->m_sIDnum == 492) ||
            (m_pClientList[iClientH]
                 ->m_pItemList[(
                     m_pClientList[iClientH]
                         ->m_sItemEquipmentStatus[DEF_EQUIPPOS_RHAND])]
                 ->m_sIDnum == 491)) {
          if (m_pClientList[iClientH]->m_iHP >
              (4 * (iGetMaxHP(iClientH) / 5))) {
          }
        }
      } else if (m_pClientList[iClientH]->m_pItemList[(
                     m_pClientList[iClientH]
                         ->m_sItemEquipmentStatus[DEF_EQUIPPOS_TWOHAND])] !=
                 0) {
        if ((m_pClientList[iClientH]
                 ->m_pItemList[(
                     m_pClientList[iClientH]
                         ->m_sItemEquipmentStatus[DEF_EQUIPPOS_TWOHAND])]
                 ->m_sIDnum == 490)) {
          if (m_pClientList[iClientH]->m_iHP >
              (4 * (iGetMaxHP(iClientH) / 5))) {
          }
        }
      } else {
        wsprintf(
            G_cTxt,
            "Packet Editing: (%s) Player: (%s) HP: current/maximum (%d/%d).",
            m_pClientList[iClientH]->m_cIPaddress,
            m_pClientList[iClientH]->m_cCharName,
            m_pClientList[iClientH]->m_iHP, iGetMaxHP(iClientH));
        PutHackLogFileList(G_cTxt);
        return false;
      }
    } catch (...) {
    }
  }

  if ((m_pClientList[iClientH]->m_iMP > iGetMaxMP(iClientH)) &&
      (m_pClientList[iClientH]->m_iAdminUserLevel == 0)) {
    try {
      wsprintf(G_cTxt,
               "Packet Editing: (%s) Player: (%s) MP: current/maximum (%d/%d).",
               m_pClientList[iClientH]->m_cIPaddress,
               m_pClientList[iClientH]->m_cCharName,
               m_pClientList[iClientH]->m_iMP, iGetMaxMP(iClientH));
      PutHackLogFileList(G_cTxt);
      return false;
    } catch (...) {
    }
  }

  if ((m_pClientList[iClientH]->m_iSP > iGetMaxSP(iClientH)) &&
      (m_pClientList[iClientH]->m_iAdminUserLevel == 0)) {
    try {
      wsprintf(G_cTxt,
               "Packet Editing: (%s) Player: (%s) SP: current/maximum (%d/%d).",
               m_pClientList[iClientH]->m_cIPaddress,
               m_pClientList[iClientH]->m_cCharName,
               m_pClientList[iClientH]->m_iSP, iGetMaxSP(iClientH));
      PutHackLogFileList(G_cTxt);
      return false;
    } catch (...) {
    }
  }

  try {
    for (i = 0; i < DEF_MAXBANNED; i++) {
      if (strlen(m_stBannedList[i].m_cBannedIPaddress) == 0)
        break; // No more GM's on list
      if ((strlen(m_stBannedList[i].m_cBannedIPaddress)) ==
          (strlen(m_pClientList[iClientH]->m_cIPaddress))) {
        if (memcmp(m_stBannedList[i].m_cBannedIPaddress,
                   m_pClientList[iClientH]->m_cIPaddress,
                   strlen(m_pClientList[iClientH]->m_cIPaddress)) == 0) {
          wsprintf(G_cTxt, "Client Rejected: Banned: (%s)",
                   m_pClientList[iClientH]->m_cIPaddress);
          PutLogList(G_cTxt);
          return false;
        } else {
        }
      }
    }
  } catch (...) {
  }

  return true;
}

void CGame::GlobalEndHeldenianMode() {
  // char * cp, cData[32];

  if (m_bIsHeldenianMode == false)
    return;

  // ZeroMemory(cData, sizeof(cData));
  // cp = (char *)cData;
  //*cp = GSM_ENDHELDENIAN; // 22
  // cp++;
  //
  // bStockMsgToGateServer(cData, 1);
  LocalEndHeldenianMode();
}

void CGame::LocalEndHeldenianMode() {
  int i, x, n;

  if (m_bIsHeldenianMode == false)
    return;
  m_bIsHeldenianMode = false;
  m_bHeldenianInitiated = true;

  m_dwHeldenianFinishTime = time(0);
  if (var_88C == 1) {
    if (m_cHeldenianModeType == 1) {
      if (m_iHeldenianAresdenLeftTower > m_iHeldenianElvineLeftTower) {
        m_cHeldenianVictoryType = 1;
      } else if (m_iHeldenianAresdenLeftTower < m_iHeldenianElvineLeftTower) {
        m_cHeldenianVictoryType = 2;
      } else if (m_iHeldenianAresdenDead < m_iHeldenianElvineDead) {
        m_cHeldenianVictoryType = 1;
      } else if (m_iHeldenianAresdenDead > m_iHeldenianElvineDead) {
        m_cHeldenianVictoryType = 2;
      } else {
        m_sLastHeldenianWinner = m_cHeldenianVictoryType;
      }
    } else if (m_cHeldenianModeType == 2) {
      m_sLastHeldenianWinner = m_cHeldenianVictoryType;
    }
    m_sLastHeldenianWinner = m_cHeldenianVictoryType;
    if (bNotifyHeldenianWinner() == false) {
      wsprintf(G_cTxt, "(!) HELDENIAN End. Result Report Failed");
      PutLogList(G_cTxt);
    }
  }
  wsprintf(G_cTxt, "(!) HELDENIAN End. %d", m_sLastHeldenianWinner);
  PutLogList(G_cTxt);

  for (i = 0; i < DEF_MAXMAPS; i++)
    if ((i < 0) || (i > 100))
      break;
  if (m_pMapList[i] != 0) {
    for (x = 0; x < DEF_MAXCLIENTS; x++)
      if ((m_pClientList[x] != 0) && (m_pClientList[x]->m_bIsInitComplete)) {
        SendNotifyMsg(0, x, DEF_NOTIFY_HELDENIANEND, 0, 0, 0, 0);
        if (m_pMapList[m_pClientList[x]->m_cMapIndex]->m_bIsHeldenianMap) {
          for (n = 0; n < DEF_MAXNPCS; n++)
            if ((m_pNpcList[n] != 0) &&
                (m_pMapList[m_pNpcList[n]->m_cMapIndex] != 0) &&
                (m_pNpcList[n]->m_bIsSummoned)) {
              RemoveHeldenianNpc(n);
            }
          RemoveOccupyFlags(x);
        }
      }
  }
  _CreateHeldenianGUID(m_dwHeldenianGUID, m_cHeldenianVictoryType);
}

bool CGame::bNotifyHeldenianWinner() {
  if (var_88C == 0) {
    bSendMsgToLS(MSGID_REQUEST_HELDENIAN_WINNER, 0, 1, 0);
    return true;
  } else {
    return false;
  }
}

void CGame::RemoveHeldenianNpc(int iNpcH) {
  if (m_pNpcList[iNpcH] == 0)
    return;
  if (m_pNpcList[iNpcH]->m_bIsKilled)
    return;

  m_pNpcList[iNpcH]->m_bIsKilled = true;
  m_pNpcList[iNpcH]->m_iHP = 0;
  m_pNpcList[iNpcH]->m_iLastDamage = 0;
  m_pNpcList[iNpcH]->m_dwRegenTime = 0;
  m_pMapList[m_pNpcList[iNpcH]->m_cMapIndex]->m_iTotalAliveObject--;

  ReleaseFollowMode(iNpcH, DEF_OWNERTYPE_NPC);
  m_pNpcList[iNpcH]->m_iTargetIndex = 0;
  m_pNpcList[iNpcH]->m_cTargetType = 0;

  SendEventToNearClient_TypeA(iNpcH, DEF_OWNERTYPE_NPC, MSGID_EVENT_MOTION,
                              DEF_OBJECTDYING, 0, 1, 0);
  m_pMapList[m_pNpcList[iNpcH]->m_cMapIndex]->ClearOwner(
      10, iNpcH, DEF_OWNERTYPE_NPC, m_pNpcList[iNpcH]->m_sX,
      m_pNpcList[iNpcH]->m_sY);
  m_pMapList[m_pNpcList[iNpcH]->m_cMapIndex]->SetDeadOwner(
      iNpcH, DEF_OWNERTYPE_NPC, m_pNpcList[iNpcH]->m_sX,
      m_pNpcList[iNpcH]->m_sY);
  m_pNpcList[iNpcH]->m_cBehavior = 4;
  m_pNpcList[iNpcH]->m_sBehaviorTurnCount = 0;
  m_pNpcList[iNpcH]->m_dwDeadTime = timeGetTime();
}

void CGame::RemoveOccupyFlags(int iMapIndex) {
  DWORD dwTime = timeGetTime();
  int i;
  short dX, dY;
  int iDynamicObjectIndex;
  class COccupyFlag *iOccupyFlagIndex;
  class CTile *pTile;
  int iy, ix;

  if (m_pMapList[iMapIndex] == 0)
    return;
  for (i = 1; i < DEF_MAXOCCUPYFLAG; i++)
    // if (m_pMapList[iMapIndex]->m_pOccupyFlag[i]) return; // centu : wtf ?
    if (m_pMapList[iMapIndex]->m_pOccupyFlag[i]) {
      dX = m_pMapList[iMapIndex]->m_pOccupyFlag[i]->m_sX;
      dY = m_pMapList[iMapIndex]->m_pOccupyFlag[i]->m_sY;
      pTile = (class CTile *)(m_pMapList[iMapIndex]->m_pTile + dX +
                              dY * m_pMapList[iMapIndex]->m_sSizeY);
      m_pMapList[iMapIndex]->m_iTotalOccupyFlags--;
      iDynamicObjectIndex =
          m_pMapList[iMapIndex]->m_pOccupyFlag[i]->m_iDynamicObjectIndex;
      if (m_pDynamicObjectList[iDynamicObjectIndex] == 0)
        return;

      SendEventToNearClient_TypeB(
          MSGID_DYNAMICOBJECT, DEF_MSGTYPE_REJECT,
          m_pDynamicObjectList[iDynamicObjectIndex]->m_cMapIndex,
          m_pDynamicObjectList[iDynamicObjectIndex]->m_sX,
          m_pDynamicObjectList[iDynamicObjectIndex]->m_sY,
          m_pDynamicObjectList[iDynamicObjectIndex]->m_sType,
          iDynamicObjectIndex, 0, (short)0);

      m_pMapList[m_pDynamicObjectList[iDynamicObjectIndex]->m_cMapIndex]
          ->SetDynamicObject(
              0, 0, m_pDynamicObjectList[iDynamicObjectIndex]->m_sX,
              m_pDynamicObjectList[iDynamicObjectIndex]->m_sY, dwTime);

      iOccupyFlagIndex = m_pMapList[iMapIndex]->m_pOccupyFlag[i];

      if (m_pDynamicObjectList[iDynamicObjectIndex] == 0) {
        for (ix = dX - 2; ix <= dX + 2; ix++)
          for (iy = dY - 2; iy <= dY + 2; iy++) {
            pTile = (class CTile *)(m_pMapList[iMapIndex]->m_pTile + ix +
                                    iy * m_pMapList[iMapIndex]->m_sSizeY);
            pTile->m_sOwner = 0;
          }
      }
    }
}

void CGame::_CreateHeldenianGUID(DWORD dwHeldenianGUID, int iWinnerSide) {
  char *cp, cTxt[256], cFn[256], cTemp[1024];
  FILE *pFile;

  _mkdir("GameData");
  ZeroMemory(cFn, sizeof(cFn));

  strcat(cFn, "GameData");
  strcat(cFn, "\\");
  strcat(cFn, "\\");
  strcat(cFn, "HeldenianGUID.Txt");

  pFile = fopen(cFn, "wt");
  if (pFile == 0) {
    wsprintf(cTxt, "(!) Cannot create HeldenianGUID(%d) file", dwHeldenianGUID);
    PutLogList(cTxt);
  } else {
    ZeroMemory(cTemp, sizeof(cTemp));

    ZeroMemory(cTxt, sizeof(cTxt));
    wsprintf(cTxt, "HeldenianGUID = %d", dwHeldenianGUID);
    strcat(cTemp, cTxt);

    ZeroMemory(cTxt, sizeof(cTxt));
    wsprintf(cTxt, "winner-side = %d\n", iWinnerSide);
    strcat(cTemp, cTxt);

    cp = (char *)cTemp;
    fwrite(cp, strlen(cp), 1, pFile);

    wsprintf(cTxt, "(O) HeldenianGUID(%d) file created", dwHeldenianGUID);
    PutLogList(cTxt);
  }
  if (pFile != 0)
    fclose(pFile);
}

/*********************************************************************************************************************
**  bool CGame::bCheckHeldenianMap(int sAttackerH, int iMapIndex, char cType)
*									**
**  description			:: checks if the player is in the specified map
*											**
**  last updated		:: November 22, 2004; 6:19 PM; Hypnotoad
*												**
**	return value		:: bool
*																**
**  commentary			::	-	translated from scratch using
* IDA Pro
*			** *						::
*	-	changed pTile->m_cOwner to m_iOccupyStatus
*								** *
*				::	-	added check to prevent access
* violation if pTile == 0 	** *
*	::	-	removed 4 return(s) after "iRet = 1;" and placed at end
*							**
*********************************************************************************************************************/
bool CGame::bCheckHeldenianMap(int sAttackerH, int iMapIndex, char cType) {
  short tX, tY;
  int iRet;
  class CTile *pTile;

  iRet = 0;
  if (m_pClientList[sAttackerH] == 0)
    return 0;
  if ((m_bIsHeldenianMode == 1) || (m_cHeldenianType == 1)) {
    if (cType == DEF_OWNERTYPE_PLAYER) {
      if ((m_pMapList[m_pClientList[sAttackerH]->m_cMapIndex] != 0) &&
          (m_pClientList[sAttackerH]->m_cSide > 0)) {
        tX = m_pClientList[sAttackerH]->m_sX;
        tY = m_pClientList[sAttackerH]->m_sY;
        if ((tX < 0) ||
            (tX >=
             m_pMapList[m_pClientList[sAttackerH]->m_cMapIndex]->m_sSizeX) ||
            (tY < 0) ||
            (tY >=
             m_pMapList[m_pClientList[sAttackerH]->m_cMapIndex]->m_sSizeY))
          return 0;
        pTile = (class CTile
                     *)(m_pMapList[m_pClientList[sAttackerH]->m_cMapIndex]
                            ->m_pTile +
                        tX +
                        tY * m_pMapList[m_pClientList[sAttackerH]->m_cMapIndex]
                                 ->m_sSizeY);
        if (pTile == 0)
          return 0;
        if (pTile->m_iOccupyStatus != 0) {
          if (pTile->m_iOccupyStatus < 0) {
            if (m_pClientList[sAttackerH]->m_cSide == 1) {
              iRet = 1;
            }
          } else if (pTile->m_iOccupyStatus > 0) {
            if (m_pClientList[sAttackerH]->m_cSide == 2) {
              iRet = 1;
            }
          }
        }
      }
    } else if (cType == DEF_OWNERTYPE_NPC) {
      if ((m_pMapList[m_pNpcList[sAttackerH]->m_cMapIndex] != 0) &&
          (iMapIndex != -1) && (m_pNpcList[sAttackerH]->m_cSide > 0)) {
        tX = m_pNpcList[sAttackerH]->m_sX;
        tY = m_pNpcList[sAttackerH]->m_sY;
        pTile =
            (class CTile *)(m_pMapList[m_pNpcList[sAttackerH]->m_cMapIndex]
                                ->m_pTile +
                            tX +
                            tY * m_pMapList[m_pNpcList[sAttackerH]->m_cMapIndex]
                                     ->m_sSizeY);
        if (pTile == 0)
          return 0;
        if (pTile->m_iOccupyStatus != 0) {
          if (pTile->m_iOccupyStatus < 0) {
            if (m_pNpcList[sAttackerH]->m_cSide == 1) {
              iRet = 1;
            }
          } else if (pTile->m_iOccupyStatus > 0) {
            if (m_pNpcList[sAttackerH]->m_cSide == 2) {
              iRet = 1;
            }
          }
        }
      }
    }
  }
  return iRet;
}

void CGame::RequestHeldenianTeleport(int iClientH, char *pData,
                                     DWORD dwMsgSize) {
  char cTmpName[21], *cp, cTxt[512], cMapName[11];
  short tX, tY, cLoc, *sp;
  WORD wResult;
  int iRet, iWhyReturn, iProcessed;

  iProcessed = 1;
  if (m_pClientList[iClientH] == 0)
    return;

  cp = (char *)(pData + DEF_INDEX2_MSGTYPE + 2);
  ZeroMemory(cTmpName, sizeof(cTmpName));
  strcpy(cTmpName, cp);
  if (strcmp(cTmpName, "Gail") == 0) {
    ZeroMemory(cTxt, sizeof(cTxt));
    if ((m_bIsHeldenianMode == 1) &&
        (m_pClientList[iClientH]->m_bIsPlayerCivil != true) &&
        (m_pClientList[iClientH]->m_cSide == 2 ||
         m_pClientList[iClientH]->m_cSide == 1)) {
      if (m_cHeldenianType == 1) {
        ZeroMemory(cMapName, sizeof(cMapName));
        memcpy(cMapName, "BtField", 10);
        if (m_pClientList[iClientH]->m_cSide == 1) {
          tX = 68;
          tY = 225;
          cLoc = 1;
        } else if (m_pClientList[iClientH]->m_cSide == 2) {
          tX = 202;
          tY = 70;
          cLoc = 2;
        }
      } else if (m_cHeldenianType == 2) {
        ZeroMemory(cMapName, sizeof(cMapName));
        memcpy(cMapName, "HRampart", 10);
        if (m_pClientList[iClientH]->m_cSide == m_sLastHeldenianWinner) {
          tX = 81;
          tY = 42;
          cLoc = 3;
        } else {
          tX = 156;
          tY = 153;
          cLoc = 4;
        }
      }
      wResult = DEF_MSGTYPE_CONFIRM;
      iProcessed = 1;
      iWhyReturn = 0;
    }
  }

  wResult = DEF_MSGTYPE_REJECT;
  iProcessed = 0;
  iWhyReturn = 0;

  sp = (short *)cp;
  *sp = 4;
  cp += 4;

  sp = (short *)cp;
  *sp = cLoc;
  cp += 4;

  memcpy(cp, cMapName, 10);
  cp += 10;

  sp = (short *)cp;
  *sp = tX;
  cp += 4;

  sp = (short *)cp;
  *sp = tY;
  cp += 4;

  sp = (short *)cp;
  *sp = iWhyReturn;
  cp += 4;

  iRet = m_pClientList[iClientH]->m_pXSock->iSendMsg(cTxt, 36);
  switch (iRet) {
  case DEF_XSOCKEVENT_QUENEFULL:
  case DEF_XSOCKEVENT_SOCKETERROR:
  case DEF_XSOCKEVENT_CRITICALERROR:
  case DEF_XSOCKEVENT_SOCKETCLOSED:
    DeleteClient(iClientH, true, true);
    break;
  }
}

void CGame::HeldenianWarStarter() {
  SYSTEMTIME SysTime;
  int i;

  GetLocalTime(&SysTime);
  if (var_89C)
    return;
  if (var_8A0 == false)
    return;

  for (i = 0; i < DEF_MAXSCHEDULE; i++)
    if (m_bIsApocalypseMode)
      return;
  if (m_bIsCrusadeMode)
    return;
  if ((m_stHeldenianSchedule[i].iDay != SysTime.wDayOfWeek) &&
      (m_stHeldenianSchedule[i].StartiHour != SysTime.wHour) &&
      (m_stHeldenianSchedule[i].StartiMinute != SysTime.wMinute)) {
    wsprintf(G_cTxt, "Heldenian Start : time(%d %d:%d), index(%d)",
             SysTime.wDayOfWeek, SysTime.wHour, SysTime.wMinute, i);
    PutLogFileList(G_cTxt);
    var_8A0 = true;
    GlobalStartHeldenianMode();
  }
}

void CGame::HeldenianWarEnder() {
  SYSTEMTIME SysTime;
  int i;

  GetLocalTime(&SysTime);

  for (i = 0; i < DEF_MAXSCHEDULE; i++)
    if (var_89C != true)
      return;
  if (var_8A0 != true)
    return;
  if ((m_stHeldenianSchedule[i].iDay != SysTime.wDayOfWeek) &&
      (m_stHeldenianSchedule[i].EndiHour != SysTime.wHour) &&
      (m_stHeldenianSchedule[i].EndiMinute != SysTime.wMinute)) {
    wsprintf(G_cTxt, "Heldenian End : time(%d %d:%d), index(%d)",
             SysTime.wDayOfWeek, SysTime.wHour, SysTime.wMinute, i);
    PutLogFileList(G_cTxt);
    if (m_cHeldenianModeType == 2) {
      m_cHeldenianVictoryType = m_sLastHeldenianWinner;
    }
    GlobalEndHeldenianMode();
  }
}

