void CGame::AutomatedHeldenianTimer() {
  DWORD dwTime;
  int x, i;

  dwTime = time(0);
  if ((dwTime == m_dwHeldenianStartTime - 300) &&
      (m_bHeldenianInitiated != true) && (m_bIsHeldenianMode != true)) {
    wsprintf(G_cTxt, "Heldenian Fight Start");
    PutLogFileList(G_cTxt);
    m_bIsHeldenianMode = false;
    for (x = 0; x < DEF_MAXMAPS; x++) {
      if (m_pMapList[x] == 0)
        return;
      if (m_pMapList[x]->m_bIsHeldenianMap)
        return;
      for (i = 0; i < DEF_MAXCLIENTS; i++) {
        if (m_pClientList[i] == 0)
          return;
        if (m_pClientList[i]->m_bIsInitComplete != true)
          return;
        if (m_pClientList[i]->m_cMapIndex == x) {
          SendNotifyMsg(0, i, DEF_NOTIFY_HELDENIANSTART, 0, 0, 0, 0);
        }
      }
    }
  }
  if ((dwTime > (180 - var_A38)) && (m_bHeldenianInitiated) &&
      (m_bIsHeldenianMode)) {
    wsprintf(G_cTxt, "Heldenian Fight End");
    PutLogFileList(G_cTxt);
    m_bHeldenianInitiated = false;
    for (x = 0; x < DEF_MAXMAPS; x++) {
      if (m_pMapList[x] == 0)
        return;
      if (m_pMapList[x]->m_bIsHeldenianMap)
        return;
      for (i = 0; i < DEF_MAXCLIENTS; i++) {
        if (m_pClientList[i] == 0)
          return;
        if (m_pClientList[i]->m_bIsInitComplete != true)
          return;
        if (m_pClientList[i]->m_cMapIndex == x) {
          SendNotifyMsg(0, i, DEF_NOTIFY_0BE8, 0, 0, 0, 0);
          RequestTeleportHandler(i, "1   ", 0, -1, -1);
        }
      }
    }
  }
}

void CGame::AdminOrder_GetFightzoneTicket(int iClientH) {
  int iReserveTime, iFightzoneTN, iFightzoneN;
  char cTemp[21];
  SYSTEMTIME SysTime;

  if (m_pClientList[iClientH] == 0)
    return;
  if (memcmp(m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->m_cName,
             "fightzone", 9) == 0) {

    iReserveTime = m_pClientList[iClientH]->m_iReserveTime;
    GetLocalTime(&SysTime);
    m_pClientList[iClientH]->m_iReserveTime =
        SysTime.wMonth * 10000 + SysTime.wDay * 100 + (SysTime.wHour + 3);

    ZeroMemory(cTemp, sizeof(cTemp));
    strcpy(cTemp,
           (m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->m_cName + 9));
    iFightzoneN = m_pClientList[iClientH]->m_iFightzoneNumber;
    iFightzoneTN = m_pClientList[iClientH]->m_iFightZoneTicketNumber;
    m_pClientList[iClientH]->m_iFightZoneTicketNumber = 10;
    m_pClientList[iClientH]->m_iFightzoneNumber = atoi(cTemp);

    GetFightzoneTicketHandler(iClientH);
    GetFightzoneTicketHandler(iClientH);
    GetFightzoneTicketHandler(iClientH);

    m_pClientList[iClientH]->m_iFightzoneNumber = iFightzoneN;
    m_pClientList[iClientH]->m_iFightZoneTicketNumber = iFightzoneTN;
    m_pClientList[iClientH]->m_iReserveTime = iReserveTime;
  } else {
    iReserveTime = m_pClientList[iClientH]->m_iReserveTime;
    GetLocalTime(&SysTime);
    m_pClientList[iClientH]->m_iReserveTime =
        SysTime.wMonth * 10000 + SysTime.wDay * 100 + (SysTime.wHour + 2);

    ZeroMemory(cTemp, sizeof(cTemp));
    strcpy(cTemp,
           (m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->m_cName + 9));
    iFightzoneN = m_pClientList[iClientH]->m_iFightzoneNumber;
    iFightzoneTN = m_pClientList[iClientH]->m_iFightZoneTicketNumber;
    m_pClientList[iClientH]->m_iFightZoneTicketNumber = 10;
    m_pClientList[iClientH]->m_iFightzoneNumber = 1;

    GetFightzoneTicketHandler(iClientH);
    GetFightzoneTicketHandler(iClientH);
    GetFightzoneTicketHandler(iClientH);

    m_pClientList[iClientH]->m_iFightzoneNumber = iFightzoneN;
    m_pClientList[iClientH]->m_iFightZoneTicketNumber = iFightzoneTN;
    m_pClientList[iClientH]->m_iReserveTime = iReserveTime;
  }
}

void CGame::SetHeldenianMode() {
  SYSTEMTIME SysTime;

  GetLocalTime(&SysTime);
  m_dwHeldenianStartHour = SysTime.wHour;
  m_dwHeldenianStartMinute = SysTime.wMinute;

  if (m_cHeldenianModeType != 2) {
    m_cHeldenianVictoryType = m_sLastHeldenianWinner;
  }
}

void CGame::CheckCrusadeResultCalculation(int iClientH) {
  if (m_pClientList[iClientH] == 0)
    return;
  if (m_pClientList[iClientH]->m_cVar == 1)
    return;

  if ((m_bIsCrusadeMode == false) &&
      (m_pClientList[iClientH]->m_dwCrusadeGUID != 0)) {
    if (m_pClientList[iClientH]->m_iWarContribution > DEF_MAXWARCONTRIBUTION)
      m_pClientList[iClientH]->m_iWarContribution = DEF_MAXWARCONTRIBUTION;
    if (m_pClientList[iClientH]->m_dwCrusadeGUID == m_dwCrusadeGUID) {
      if (m_iCrusadeWinnerSide == 0) {
        m_pClientList[iClientH]->m_iExpStock +=
            (m_pClientList[iClientH]->m_iWarContribution / 6);
        SendNotifyMsg(0, iClientH, DEF_NOTIFY_CRUSADE, (DWORD)m_bIsCrusadeMode,
                      0, m_pClientList[iClientH]->m_iWarContribution, 0);
        _bCrusadeLog(DEF_CRUSADELOG_GETEXP, iClientH,
                     (m_pClientList[iClientH]->m_iWarContribution / 6), 0);
      } else {
        if (m_iCrusadeWinnerSide == m_pClientList[iClientH]->m_cSide) {
          if (m_pClientList[iClientH]->m_iLevel <= 80) {
            m_pClientList[iClientH]->m_iWarContribution +=
                m_pClientList[iClientH]->m_iLevel * 100;
          } else if (m_pClientList[iClientH]->m_iLevel <= 100) {
            m_pClientList[iClientH]->m_iWarContribution +=
                m_pClientList[iClientH]->m_iLevel * 40;
          } else
            m_pClientList[iClientH]->m_iWarContribution +=
                m_pClientList[iClientH]->m_iLevel;
          m_pClientList[iClientH]->m_iExpStock +=
              m_pClientList[iClientH]->m_iWarContribution;
          SendNotifyMsg(0, iClientH, DEF_NOTIFY_CRUSADE,
                        (DWORD)m_bIsCrusadeMode, 0,
                        m_pClientList[iClientH]->m_iWarContribution, 0);
          _bCrusadeLog(DEF_CRUSADELOG_GETEXP, iClientH,
                       m_pClientList[iClientH]->m_iWarContribution, 0);
        } else if (m_iCrusadeWinnerSide != m_pClientList[iClientH]->m_cSide) {
          if (m_pClientList[iClientH]->m_iLevel <= 80) {
            m_pClientList[iClientH]->m_iWarContribution +=
                m_pClientList[iClientH]->m_iLevel * 100;
          } else if (m_pClientList[iClientH]->m_iLevel <= 100) {
            m_pClientList[iClientH]->m_iWarContribution +=
                m_pClientList[iClientH]->m_iLevel * 40;
          } else
            m_pClientList[iClientH]->m_iWarContribution +=
                m_pClientList[iClientH]->m_iLevel;
          m_pClientList[iClientH]->m_iExpStock +=
              m_pClientList[iClientH]->m_iWarContribution / 10;
          SendNotifyMsg(0, iClientH, DEF_NOTIFY_CRUSADE,
                        (DWORD)m_bIsCrusadeMode, 0,
                        -1 * m_pClientList[iClientH]->m_iWarContribution, 0);
          _bCrusadeLog(DEF_CRUSADELOG_GETEXP, iClientH,
                       (m_pClientList[iClientH]->m_iWarContribution / 10), 0);
        }
      }
    } else {
      SendNotifyMsg(0, iClientH, DEF_NOTIFY_CRUSADE, (DWORD)m_bIsCrusadeMode, 0,
                    0, 0, -1);
    }
    m_pClientList[iClientH]->m_iCrusadeDuty = 0;
    m_pClientList[iClientH]->m_iWarContribution = 0;
    m_pClientList[iClientH]->m_dwCrusadeGUID = 0;
    m_pClientList[iClientH]->m_dwSpeedHackCheckTime = timeGetTime();
    m_pClientList[iClientH]->m_iSpeedHackCheckExp =
        m_pClientList[iClientH]->m_iExp;
  }
}

void CGame::CheckHeldenianResultCalculation(int iClientH) {
  double dV1, dV2, dV3;

  if (m_pClientList[iClientH] == 0)
    return;
  if (m_pClientList[iClientH]->m_cVar != 2)
    return;
  if ((m_cHeldenianType == 0) ||
      (m_pClientList[iClientH]->m_dwHeldenianGUID == 0))
    return;
  if (m_pClientList[iClientH]->m_dwHeldenianGUID == m_dwHeldenianGUID) {
    if (m_pClientList[iClientH]->m_cSide == m_sLastHeldenianWinner) {
      if (m_pClientList[iClientH]->m_iLevel <= 80) {
        m_pClientList[iClientH]->m_iWarContribution +=
            (m_pClientList[iClientH]->m_iLevel) * 200;
      } else if (m_pClientList[iClientH]->m_iLevel > 80 &&
                 m_pClientList[iClientH]->m_iLevel <= 100) {
        m_pClientList[iClientH]->m_iWarContribution +=
            (m_pClientList[iClientH]->m_iLevel) * 100;
      } else if (m_pClientList[iClientH]->m_iLevel > 100) {
        m_pClientList[iClientH]->m_iWarContribution +=
            (m_pClientList[iClientH]->m_iLevel) * 30;
      }
      dV2 = (double)m_pClientList[iClientH]->m_iExp;
      dV3 = (double)m_pClientList[iClientH]->m_iWarContribution * 1.2f;
      dV1 = dV2 + dV3;
      GetExp(iClientH, (DWORD)dV1);
    } else {
      GetExp(iClientH, (m_pClientList[iClientH]->m_iWarContribution / 5));
    }
    m_pClientList[iClientH]->m_iWarContribution = 0;
    m_pClientList[iClientH]->m_dwHeldenianGUID = 0;
    m_pClientList[iClientH]->m_dwSpeedHackCheckTime = timeGetTime();
    m_pClientList[iClientH]->m_iSpeedHackCheckExp =
        m_pClientList[iClientH]->m_iExp;
  }
}

void CGame::NotifyStartHeldenianMode() {
  int i, x;

  if (m_bIsHeldenianMode)
    return;
  if (m_bHeldenianInitiated)
    return;
  if (var_88C != true) {
    PutLogList("Heldenian Fight Start");
    m_bHeldenianInitiated = false;
    for (i = 0; i < DEF_MAXMAPS; i++) {
      if (m_pMapList[i] == 0)
        return;
      if (m_pMapList[i]->m_bIsHeldenianMap != true)
        return;
      for (x = 0; x < DEF_MAXCLIENTS; x++) {
        if (m_pClientList[x] == 0)
          return;
        if (m_pClientList[x]->m_bIsInitComplete != true)
          return;
        if (m_pClientList[x]->m_cMapIndex == i) {
          SendNotifyMsg(0, x, DEF_NOTIFY_HELDENIANSTART, 0, 0, 0, 0);
        }
      }
    }
  }
}

bool CGame::UpdateHeldenianStatus() {
  int i;
  bool bFlag;
  int iShortCutIndex, iClientH;

  if (m_bIsHeldenianMode != true)
    return false;
  for (i = 0; i < DEF_MAXMAPS; i++)
    if (m_pMapList[i] != 0) {
      if (m_pMapList[i]->m_bIsHeldenianMap) {
        bFlag = true;
        iShortCutIndex = 0;
      }
      if (bFlag) {
        iClientH = m_iClientShortCut[iShortCutIndex];
        iShortCutIndex++;
        if (iClientH == 0) {
          bFlag = 0;
        } else {
          if ((m_pClientList[iClientH] != 0) &&
              (m_pClientList[iClientH]->m_bIsInitComplete) &&
              (strcmp(m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->m_cName,
                      "BtField") == 0)) {
            SendNotifyMsg(0, iClientH, DEF_NOTIFY_HELDENIANCOUNT,
                          m_iHeldenianAresdenLeftTower,
                          m_iHeldenianElvineLeftTower, m_iHeldenianAresdenDead,
                          0, m_iHeldenianElvineDead, 0);
          }
        }
      }
    }
  return true;
}

void CGame::AddGizon(int iClientH) {
  m_pClientList[iClientH]->m_iGizonItemUpgradeLeft++;
  SendNotifyMsg(0, iClientH, DEF_NOTIFY_GIZONITEMUPGRADELEFT,
                m_pClientList[iClientH]->m_iGizonItemUpgradeLeft, 0, 0, 0);

  m_pClientList[iClientH]->m_iNextLevelExp =
      m_iLevelExpTable[m_iPlayerMaxLevel + 1];
  m_pClientList[iClientH]->m_iExp = m_iLevelExpTable[m_iPlayerMaxLevel];
}

void CGame::ForceRecallProcess() {
  int i;
  int iMapSide = 0;

  DWORD *dwp, dwTime;

  dwTime = timeGetTime();

  for (i = 1; i < DEF_MAXCLIENTS; i++) {
    if (m_pClientList[i] != 0) {
      if (m_pClientList[i]->m_bIsInitComplete) {
        // force recall in enemy buidlings at crusade
        iMapSide = iGetMapLocationSide(
            m_pMapList[m_pClientList[i]->m_cMapIndex]->m_cName);
        if ((memcmp(m_pClientList[i]->m_cLocation, "are", 3) == 0) &&
            (iMapSide == 2) && (m_pClientList[i]->m_iAdminUserLevel == 0) &&
            (m_bIsCrusadeMode)) {
          RequestTeleportHandler(i, "2   ", "aresden", -1, -1);
        }
        if ((memcmp(m_pClientList[i]->m_cLocation, "elv", 3) == 0) &&
            (iMapSide == 1) && (m_pClientList[i]->m_iAdminUserLevel == 0) &&
            (m_bIsCrusadeMode)) {
          RequestTeleportHandler(i, "2   ", "elvine", -1, -1);
        }

        // remove mim in building
        if ((memcmp(m_pMapList[m_pClientList[i]->m_cMapIndex]->m_cName, "wrhus",
                    5) == 0) ||
            (strcmp(m_pMapList[m_pClientList[i]->m_cMapIndex]->m_cName,
                    "gshop_1") == 0) ||
            (strcmp(m_pMapList[m_pClientList[i]->m_cMapIndex]->m_cName,
                    "bsmith_1") == 0) ||
            (strcmp(m_pMapList[m_pClientList[i]->m_cMapIndex]->m_cName,
                    "cath_1") == 0) ||
            (strcmp(m_pMapList[m_pClientList[i]->m_cMapIndex]->m_cName,
                    "CmdHall_1") == 0) ||
            (strcmp(m_pMapList[m_pClientList[i]->m_cMapIndex]->m_cName,
                    "cityhall_1") == 0) ||
            (strcmp(m_pMapList[m_pClientList[i]->m_cMapIndex]->m_cName,
                    "gshop_2") == 0) ||
            (strcmp(m_pMapList[m_pClientList[i]->m_cMapIndex]->m_cName,
                    "bsmith_2") == 0) ||
            (strcmp(m_pMapList[m_pClientList[i]->m_cMapIndex]->m_cName,
                    "cath_2") == 0) ||
            (strcmp(m_pMapList[m_pClientList[i]->m_cMapIndex]->m_cName,
                    "CmdHall_2") == 0) ||
            (strcmp(m_pMapList[m_pClientList[i]->m_cMapIndex]->m_cName,
                    "cityhall_2") == 0) ||
            (memcmp(m_pMapList[m_pClientList[i]->m_cMapIndex]->m_cName,
                    "wzdtwr", 6) == 0) ||
            (memcmp(m_pMapList[m_pClientList[i]->m_cMapIndex]->m_cName,
                    "gldhall", 7) == 0)) {
          // SetIllusionFlag(i, DEF_OWNERTYPE_PLAYER, false);
          if (m_pClientList[i]->m_iStatus & 0x00200000) {
            SetIllusionMovementFlag(i, DEF_OWNERTYPE_PLAYER, false);
            bRemoveFromDelayEventList(i, DEF_OWNERTYPE_PLAYER,
                                      DEF_MAGICTYPE_CONFUSE);
            bRegisterDelayEvent(DEF_DELAYEVENTTYPE_MAGICRELEASE,
                                DEF_MAGICTYPE_CONFUSE, dwTime + 2, i,
                                DEF_OWNERTYPE_PLAYER, 0, 0, 0, 4, 0, 0);
          }
        }
      }
      // check gizon errors
      if (m_pClientList[i]->m_iLevel < 180) {
        if (m_pClientList[i]->m_iGizonItemUpgradeLeft > 0) {
          m_pClientList[i]->m_iGizonItemUpgradeLeft = 0;
        }
      }
    }
  }
}

// in stat change, check skillpoints
void CGame::SkillCheck(int sTargetH) {
  // magic
  while ((m_pClientList[sTargetH]->m_iMag * 2) <
         m_pClientList[sTargetH]->m_cSkillMastery[4]) {
    m_pClientList[sTargetH]->m_cSkillMastery[4]--;
  }
  // hand attack
  while ((m_pClientList[sTargetH]->m_iStr * 2) <
         m_pClientList[sTargetH]->m_cSkillMastery[5]) {
    m_pClientList[sTargetH]->m_cSkillMastery[5]--;
  }
  // hammer
  while ((m_pClientList[sTargetH]->m_iDex * 2) <
         m_pClientList[sTargetH]->m_cSkillMastery[14]) {
    m_pClientList[sTargetH]->m_cSkillMastery[14]--;
  }
  // shield
  while ((m_pClientList[sTargetH]->m_iDex * 2) <
         m_pClientList[sTargetH]->m_cSkillMastery[11]) {
    m_pClientList[sTargetH]->m_cSkillMastery[11]--;
  }
  // axe
  while ((m_pClientList[sTargetH]->m_iDex * 2) <
         m_pClientList[sTargetH]->m_cSkillMastery[10]) {
    m_pClientList[sTargetH]->m_cSkillMastery[10]--;
  }
  // fencing
  while ((m_pClientList[sTargetH]->m_iDex * 2) <
         m_pClientList[sTargetH]->m_cSkillMastery[9]) {
    m_pClientList[sTargetH]->m_cSkillMastery[9]--;
  }
  // LS
  while ((m_pClientList[sTargetH]->m_iDex * 2) <
         m_pClientList[sTargetH]->m_cSkillMastery[8]) {
    m_pClientList[sTargetH]->m_cSkillMastery[8]--;
  }
  // SS
  while ((m_pClientList[sTargetH]->m_iDex * 2) <
         m_pClientList[sTargetH]->m_cSkillMastery[7]) {
    m_pClientList[sTargetH]->m_cSkillMastery[7]--;
  }
  // archery
  while ((m_pClientList[sTargetH]->m_iDex * 2) <
         m_pClientList[sTargetH]->m_cSkillMastery[6]) {
    m_pClientList[sTargetH]->m_cSkillMastery[6]--;
  }
  // staff
  while ((m_pClientList[sTargetH]->m_iMag * 2) <
         m_pClientList[sTargetH]->m_cSkillMastery[21]) {
    m_pClientList[sTargetH]->m_cSkillMastery[21]--;
  }
  // alc
  while ((m_pClientList[sTargetH]->m_iInt * 2) <
         m_pClientList[sTargetH]->m_cSkillMastery[12]) {
    m_pClientList[sTargetH]->m_cSkillMastery[12]--;
  }
  // manu
  while ((m_pClientList[sTargetH]->m_iStr * 2) <
         m_pClientList[sTargetH]->m_cSkillMastery[13]) {
    m_pClientList[sTargetH]->m_cSkillMastery[13]--;
  }
  // pr
  while ((m_pClientList[sTargetH]->m_iVit * 2) <
         m_pClientList[sTargetH]->m_cSkillMastery[23]) {
    m_pClientList[sTargetH]->m_cSkillMastery[23]--;
  }
  // pc
  while ((m_pClientList[sTargetH]->m_iInt * 2) <
         m_pClientList[sTargetH]->m_cSkillMastery[19]) {
    m_pClientList[sTargetH]->m_cSkillMastery[19]--;
  }
  // farming
  while ((m_pClientList[sTargetH]->m_iInt * 2) <
         m_pClientList[sTargetH]->m_cSkillMastery[2]) {
    m_pClientList[sTargetH]->m_cSkillMastery[2]--;
  }
  // fishing
  while ((m_pClientList[sTargetH]->m_iDex * 2) <
         m_pClientList[sTargetH]->m_cSkillMastery[1]) {
    m_pClientList[sTargetH]->m_cSkillMastery[1]--;
  }
  // mining
  while ((m_pClientList[sTargetH]->m_iStr * 2) <
         m_pClientList[sTargetH]->m_cSkillMastery[0]) {
    m_pClientList[sTargetH]->m_cSkillMastery[0]--;
  }
}

bool CGame::IsEnemyZone(int i) {
  if (memcmp(m_pClientList[i]->m_cLocation, "elv", 3) == 0) {
    if ((strcmp(m_pMapList[m_pClientList[i]->m_cMapIndex]->m_cLocationName,
                "aresden") == 0) ||
        (strcmp(m_pMapList[m_pClientList[i]->m_cMapIndex]->m_cLocationName,
                "aresdend1") == 0) ||
        (strcmp(m_pMapList[m_pClientList[i]->m_cMapIndex]->m_cLocationName,
                "areuni") == 0) ||
        (strcmp(m_pMapList[m_pClientList[i]->m_cMapIndex]->m_cLocationName,
                "huntzone2") == 0) ||
        (strcmp(m_pMapList[m_pClientList[i]->m_cMapIndex]->m_cLocationName,
                "huntzone4") == 0)) {
      return true;
    }
  } else if (memcmp(m_pClientList[i]->m_cLocation, "are", 3) == 0) {
    if ((strcmp(m_pMapList[m_pClientList[i]->m_cMapIndex]->m_cLocationName,
                "elvine") == 0) ||
        (strcmp(m_pMapList[m_pClientList[i]->m_cMapIndex]->m_cLocationName,
                "elvined1") == 0) ||
        (strcmp(m_pMapList[m_pClientList[i]->m_cMapIndex]->m_cLocationName,
                "elvuni") == 0) ||
        (strcmp(m_pMapList[m_pClientList[i]->m_cMapIndex]->m_cLocationName,
                "huntzone1") == 0) ||
        (strcmp(m_pMapList[m_pClientList[i]->m_cMapIndex]->m_cLocationName,
                "huntzone3") == 0)) {
      return true;
    }
  }
  return false;
}

void CGame::LoteryHandler(int iClientH) {
  class CItem *pItem;
  int iItemID;
  if (m_pClientList[iClientH] == 0)
    return;
  switch (iDice(1, 22)) {
  case 1:
    iItemID = 656;
    break; // XelimaStone
  case 2:
    iItemID = 657;
    break; // MerienStone
  case 3:
    iItemID = 650;
    break; // ZemstoneOfSacrifice
  case 4:
    iItemID = 652;
    break; // RedBall
  case 5:
    iItemID = 654;
    break; // BlueBall
  case 6:
    iItemID = 881;
    break; // ArmorDye(Indigo)
  case 7:
    iItemID = 882;
    break; // ArmorDye(CrimsonRed)
  case 8:
    iItemID = 883;
    break; // ArmorDye(Gold)
  case 9:
    iItemID = 884;
    break; // ArmorDye(Aqua)
  case 10:
    iItemID = 885;
    break; // ArmorDye(Pink)
  case 11:
    iItemID = 886;
    break; // ArmorDye(Violet)
  case 12:
    iItemID = 887;
    break; // ArmorDye(Blue)
  case 13:
    iItemID = 888;
    break; // ArmorDye(Khaki)
  case 14:
    iItemID = 889;
    break; // ArmorDye(Yellow)
  case 15:
    iItemID = 890;
    break; // ArmorDye(Red)
  case 16:
    iItemID = 971;
    break; // ArmorDye(Green)
  case 17:
    iItemID = 972;
    break; // ArmorDye(Black)
  case 18:
    iItemID = 973;
    break; // ArmorDye(Knight)
  case 19:
    iItemID = 970;
    break; // CritCandy
  case 20:
    iItemID = 651;
    break; // GreenBall
  case 21:
    iItemID = 653;
    break; // YellowBall
  case 22:
    iItemID = 655;
    break; // PearlBall
  }

  // chance
  if (iDice(1, 120) <= 3)
    iItemID = 650; // ZemstoneOfSacrifice
  // chance

  pItem = new class CItem;
  if (_bInitItemAttr(pItem, iItemID) == false) {
    delete pItem;
  } else {
    m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->bSetItem(
        m_pClientList[iClientH]->m_sX, m_pClientList[iClientH]->m_sY, pItem);
    SendEventToNearClient_TypeB(MSGID_EVENT_COMMON, DEF_COMMONTYPE_ITEMDROP,
                                m_pClientList[iClientH]->m_cMapIndex,
                                m_pClientList[iClientH]->m_sX,
                                m_pClientList[iClientH]->m_sY, pItem->m_sIDnum,
                                0, pItem->m_cItemColor, pItem->m_dwAttribute);
  }
}

