/*********************************************************************************************************************
**  bool CGame::SetAngelFlag(short sOwnerH, char cOwnerType, int iStatus, iTemp)
*		Snoopy			**
** description	  :: Sets the staus to send or not Angels to every client
*						**
*********************************************************************************************************************/
void CGame::SetAngelFlag(short sOwnerH, char cOwnerType, int iStatus,
                         int iTemp) {
  if (cOwnerType != DEF_OWNERTYPE_PLAYER)
    return;
  if (m_pClientList[sOwnerH] == 0)
    return;
  switch (iStatus) {
  case 1: // STR Angel
    m_pClientList[sOwnerH]->m_iStatus =
        m_pClientList[sOwnerH]->m_iStatus | 0x00001000;
    break;
  case 2: // DEX Angel
    m_pClientList[sOwnerH]->m_iStatus =
        m_pClientList[sOwnerH]->m_iStatus | 0x00002000;
    break;
  case 3: // INT Angel
    m_pClientList[sOwnerH]->m_iStatus =
        m_pClientList[sOwnerH]->m_iStatus | 0x00004000;
    break;
  case 4: // MAG Angel
    m_pClientList[sOwnerH]->m_iStatus =
        m_pClientList[sOwnerH]->m_iStatus | 0x00008000;
    break;
  default:
  case 0: // Remove all Angels
    m_pClientList[sOwnerH]->m_iStatus =
        m_pClientList[sOwnerH]->m_iStatus & 0xFFFF00FF;
    break;
  }
  if (iTemp > 4) {
    int iAngelicStars = (iTemp / 3) * (iTemp / 5);
    m_pClientList[sOwnerH]->m_iStatus =
        m_pClientList[sOwnerH]->m_iStatus | (iAngelicStars << 8);
  }
  SendEventToNearClient_TypeA(sOwnerH, DEF_OWNERTYPE_PLAYER, MSGID_EVENT_MOTION,
                              DEF_OBJECTNULLACTION, 0, 0, 0);
}

/*********************************************************************************************************************
**  bool CGame::GetAngelHandler(int iClientH, char * pData, DWORD dwMsgSize)
*									**
** description	  :: Reversed and coded by Snoopy
*													**
*********************************************************************************************************************/
void CGame::GetAngelHandler(int iClientH, char *pData, DWORD dwMsgSize) {
  char *cp, cData[256], cTmpName[21];
  int iAngel;
  class CItem *pItem;
  int iRet, iEraseReq;
  char cItemName[21];
  short *sp;
  WORD *wp;
  int *ip;
  DWORD *dwp;
  if (m_pClientList[iClientH] == 0)
    return;
  if (m_pClientList[iClientH]->m_bIsInitComplete == false)
    return;
  if (_iGetItemSpaceLeft(iClientH) == 0) {
    SendItemNotifyMsg(iClientH, DEF_NOTIFY_CANNOTCARRYMOREITEM, 0, 0);
    return;
  }
  cp = (char *)(pData + DEF_INDEX2_MSGTYPE + 2);
  ZeroMemory(cTmpName, sizeof(cTmpName));
  strcpy(cTmpName, cp);
  cp += 20;
  ip = (int *)cp;
  iAngel = (int)*ip; // 0x00 l a i
  cp += 2;
  wsprintf(G_cTxt, "PC(%s) obtained an Angel (%d).   %s(%d %d)",
           m_pClientList[iClientH]->m_cCharName, iAngel,
           m_pClientList[iClientH]->m_cMapName, m_pClientList[iClientH]->m_sX,
           m_pClientList[iClientH]->m_sY);
  PutLogList(G_cTxt);
  switch (iAngel) {
  case 1: // STR
    // iItemNbe = 1108;
    wsprintf(cItemName, "AngelicPandent(STR)");
    break;
  case 2: // DEX
    // iItemNbe = 1109;
    wsprintf(cItemName, "AngelicPandent(DEX)");
    break;
  case 3: // INT
    // iItemNbe = 1110;
    wsprintf(cItemName, "AngelicPandent(INT)");
    break;
  case 4: // MAG
    // iItemNbe = 1111;
    wsprintf(cItemName, "AngelicPandent(MAG)");
    break;
  default:
    PutLogList("Gail asked to create a wrong item!");
    break;
  }
  // Them create the summonScroll
  pItem = 0;
  pItem = new class CItem;
  if (pItem == 0)
    return;
  if ((_bInitItemAttr(pItem, cItemName))) {
    pItem->m_sTouchEffectType = DEF_ITET_UNIQUE_OWNER;
    pItem->m_sTouchEffectValue1 = m_pClientList[iClientH]->m_sCharIDnum1;
    pItem->m_sTouchEffectValue2 = m_pClientList[iClientH]->m_sCharIDnum2;
    pItem->m_sTouchEffectValue3 = m_pClientList[iClientH]->m_sCharIDnum3;
    if (_bAddClientItemList(iClientH, pItem, &iEraseReq)) {
      ZeroMemory(cData, sizeof(cData));
      dwp = (DWORD *)(cData + DEF_INDEX4_MSGID);
      *dwp = MSGID_NOTIFY;
      wp = (WORD *)(cData + DEF_INDEX2_MSGTYPE);
      *wp = DEF_NOTIFY_ITEMOBTAINED;
      cp = (char *)(cData + DEF_INDEX2_MSGTYPE + 2);
      *cp = 1;
      cp++;
      memcpy(cp, pItem->m_cName, 20);
      cp += 20;
      dwp = (DWORD *)cp;
      *dwp = pItem->m_dwCount;
      cp += 4;
      *cp = pItem->m_cItemType;
      cp++;
      *cp = pItem->m_cEquipPos;
      cp++;
      *cp = (char)0;
      cp++;
      sp = (short *)cp;
      *sp = pItem->m_sLevelLimit;
      cp += 2;
      *cp = pItem->m_cGenderLimit;
      cp++;
      wp = (WORD *)cp;
      *wp = pItem->m_wCurLifeSpan;
      cp += 2;
      wp = (WORD *)cp;
      *wp = pItem->m_wWeight;
      cp += 2;
      sp = (short *)cp;
      *sp = pItem->m_sSprite;
      cp += 2;
      sp = (short *)cp;
      *sp = pItem->m_sSpriteFrame;
      cp += 2;
      *cp = pItem->m_cItemColor;
      cp++;
      *cp = (char)pItem->m_sItemSpecEffectValue2; // v1.41
      cp++;
      dwp = (DWORD *)cp;
      *dwp = pItem->m_dwAttribute;
      cp += 4;
      if (iEraseReq == 1)
        delete pItem;
      iRet = m_pClientList[iClientH]->m_pXSock->iSendMsg(cData, 53);
      switch (iRet) {
      case DEF_XSOCKEVENT_QUENEFULL:
      case DEF_XSOCKEVENT_SOCKETERROR:
      case DEF_XSOCKEVENT_CRITICALERROR:
      case DEF_XSOCKEVENT_SOCKETCLOSED:
        DeleteClient(iClientH, true, true);
        break;
      }
    } else {
      m_pMapList[m_pClientList[iClientH]->m_cMapIndex]->bSetItem(
          m_pClientList[iClientH]->m_sX, m_pClientList[iClientH]->m_sY, pItem);
      SendEventToNearClient_TypeB(
          MSGID_EVENT_COMMON, DEF_COMMONTYPE_ITEMDROP,
          m_pClientList[iClientH]->m_cMapIndex, m_pClientList[iClientH]->m_sX,
          m_pClientList[iClientH]->m_sY, pItem->m_sIDnum, 0,
          pItem->m_cItemColor, pItem->m_dwAttribute); // v1.4
      dwp = (DWORD *)(cData + DEF_INDEX4_MSGID);
      *dwp = MSGID_NOTIFY;
      wp = (WORD *)(cData + DEF_INDEX2_MSGTYPE);
      *wp = DEF_NOTIFY_CANNOTCARRYMOREITEM;
      iRet = m_pClientList[iClientH]->m_pXSock->iSendMsg(cData, 6);
      switch (iRet) {
      case DEF_XSOCKEVENT_QUENEFULL:
      case DEF_XSOCKEVENT_SOCKETERROR:
      case DEF_XSOCKEVENT_CRITICALERROR:
      case DEF_XSOCKEVENT_SOCKETCLOSED:
        DeleteClient(iClientH, true, true);
        break;
      }
    }
  } else {
    delete pItem;
    pItem = 0;
  }
}

void CGame::RequestEnchantUpgradeHandler(int client, DWORD type, DWORD lvl,
                                         int iType) {
  auto &player = m_pClientList[client];
  if (player == 0 || type == 0)
    return;

  if (lvl < 2 || lvl >= 17)
    return; // nivel mayor a 1 y menor a 17

  int req = GetRequiredLevelForUpgrade(lvl);

  switch (iType) {
    // Upgrade one
  case UPGRADEONE_SHARD:
    // descuenta los shards necesarios
    if (player->m_pShards[type][lvl] != 0 &&
        player->m_pShards[type][lvl]->iCount >= req) {
      player->m_pShards[type][lvl]->iCount -= req;
      SendNotifyMsg(0, client, msg_shard, type, lvl + 1,
                    player->m_pShards[type][lvl]->iCount,
                    player->m_pShards[type][lvl]->cName, 0, 0, 0, 0, 0, 0,
                    player->m_pShards[type][lvl]->cDesc);

      // agrego uno al nivel siguiente
      if (player->m_pShards[type][lvl + 1] == 0) {
        player->m_pShards[type][lvl + 1] = new class CEnchanting;

        strcpy(player->m_pShards[type][lvl + 1]->cName, GetShardName(type));
        strcpy(player->m_pShards[type][lvl + 1]->cDesc, GetShardDesc(type));
        player->m_pShards[type][lvl + 1]->dwType = type;
        player->m_pShards[type][lvl + 1]->dwValue = lvl + 2;
      }

      player->m_pShards[type][lvl + 1]->iCount++;

      SendNotifyMsg(0, client, msg_shard, type, lvl + 2,
                    player->m_pShards[type][lvl + 1]->iCount,
                    player->m_pShards[type][lvl + 1]->cName, 0, 0, 0, 0, 0, 0,
                    player->m_pShards[type][lvl + 1]->cDesc);
    }
    break;
  case UPGRADEONE_FRAGMENT:
    // descuenta los fragments necesarios
    if (player->m_pFragments[type][lvl] != 0 &&
        player->m_pFragments[type][lvl]->iCount >= req) {
      player->m_pFragments[type][lvl]->iCount -= req;
      SendNotifyMsg(0, client, msg_fragment, type, lvl + 1,
                    player->m_pFragments[type][lvl]->iCount,
                    player->m_pFragments[type][lvl]->cName, 0, 0, 0, 0, 0, 0,
                    player->m_pFragments[type][lvl]->cDesc);

      // agrego uno al nivel siguiente
      if (player->m_pFragments[type][lvl + 1] == 0) {
        player->m_pFragments[type][lvl + 1] = new class CEnchanting;

        strcpy(player->m_pFragments[type][lvl + 1]->cName,
               GetFragmentName(type));
        strcpy(player->m_pFragments[type][lvl + 1]->cDesc,
               GetFragmentDesc(type));
        player->m_pFragments[type][lvl + 1]->dwType = type;
        player->m_pFragments[type][lvl + 1]->dwValue = lvl + 2;
      }

      player->m_pFragments[type][lvl + 1]->iCount++;

      SendNotifyMsg(0, client, msg_fragment, type, lvl + 2,
                    player->m_pFragments[type][lvl + 1]->iCount,
                    player->m_pFragments[type][lvl + 1]->cName, 0, 0, 0, 0, 0,
                    0, player->m_pFragments[type][lvl + 1]->cDesc);
    }
    break;

    // Upgrade all
  case UPGRADEALL_SHARD:
    // descuenta los shards necesarios
    if (player->m_pShards[type][lvl] != 0) {
      while (player->m_pShards[type][lvl]->iCount >= req) {
        player->m_pShards[type][lvl]->iCount -= req;
        SendNotifyMsg(0, client, msg_shard, type, lvl + 1,
                      player->m_pShards[type][lvl]->iCount,
                      player->m_pShards[type][lvl]->cName, 0, 0, 0, 0, 0, 0,
                      player->m_pShards[type][lvl]->cDesc);

        // agrego uno al nivel siguiente
        if (player->m_pShards[type][lvl + 1] == 0) {
          player->m_pShards[type][lvl + 1] = new class CEnchanting;

          strcpy(player->m_pShards[type][lvl + 1]->cName, GetShardName(type));
          strcpy(player->m_pShards[type][lvl + 1]->cDesc, GetShardDesc(type));
          player->m_pShards[type][lvl + 1]->dwType = type;
          player->m_pShards[type][lvl + 1]->dwValue = lvl + 2;
        }

        player->m_pShards[type][lvl + 1]->iCount++;

        SendNotifyMsg(0, client, msg_shard, type, lvl + 2,
                      player->m_pShards[type][lvl + 1]->iCount,
                      player->m_pShards[type][lvl + 1]->cName, 0, 0, 0, 0, 0, 0,
                      player->m_pShards[type][lvl + 1]->cDesc);
      }
    }
    break;
  case UPGRADEALL_FRAGMENT:
    // descuenta los fragments necesarios
    if (player->m_pFragments[type][lvl] != 0) {
      while (player->m_pFragments[type][lvl]->iCount >= req) {
        player->m_pFragments[type][lvl]->iCount -= req;
        SendNotifyMsg(0, client, msg_fragment, type, lvl + 1,
                      player->m_pFragments[type][lvl]->iCount,
                      player->m_pFragments[type][lvl]->cName, 0, 0, 0, 0, 0, 0,
                      player->m_pFragments[type][lvl]->cDesc);

        // agrego uno al nivel siguiente
        if (player->m_pFragments[type][lvl + 1] == 0) {
          player->m_pFragments[type][lvl + 1] = new class CEnchanting;

          strcpy(player->m_pFragments[type][lvl + 1]->cName,
                 GetFragmentName(type));
          strcpy(player->m_pFragments[type][lvl + 1]->cDesc,
                 GetFragmentDesc(type));
          player->m_pFragments[type][lvl + 1]->dwType = type;
          player->m_pFragments[type][lvl + 1]->dwValue = lvl + 2;
        }

        player->m_pFragments[type][lvl + 1]->iCount++;

        SendNotifyMsg(0, client, msg_fragment, type, lvl + 2,
                      player->m_pFragments[type][lvl + 1]->iCount,
                      player->m_pFragments[type][lvl + 1]->cName, 0, 0, 0, 0, 0,
                      0, player->m_pFragments[type][lvl + 1]->cDesc);
      }
    }
    break;
  }
}
int CGame::GetRequiredLevelForUpgrade(DWORD value) {
  if (value >= 1 && value <= 5) {
    return 4;
  } else if (value > 5 && value <= 10) {
    return 3;
  }

  return 2;
}
void CGame::RequestItemEnchantHandler(int iClientH, int sDestItemID,
                                      int iType) {
  auto player = m_pClientList[iClientH];

  if (sDestItemID < 0 || sDestItemID > DEF_MAXITEMS)
    return;
  if (player == 0 || player->m_pItemList[sDestItemID] == 0)
    return;

  auto &dst_attr = player->m_pItemList[sDestItemID]->m_dwAttribute;

  auto dst_dwType1 = (dst_attr & 0x00F00000) >> 20;
  auto dst_dwValue1 = (dst_attr & 0x000F0000) >> 16;
  auto dst_dwType2 = (dst_attr & 0x0000F000) >> 12;
  auto dst_dwValue2 = (dst_attr & 0x00000F00) >> 8;

  for (int i = 0; i < 13; i++) {
    for (int x = 0; x < 17; x++) {
      if (iType == 0) {
        if (player->m_pShards[i][x] == 0 ||
            player->m_pShards[i][x]->iCount == 0)
          continue;
        if (dst_dwType1 == 0 || dst_dwType1 != player->m_pShards[i][x]->dwType)
          continue; // no es del mismo tipo
        if (dst_dwValue1 != player->m_pShards[i][x]->dwValue)
          continue; // no es del mismo level

        auto dst_value = dst_dwValue1 + 1;

        dst_attr = 0;
        dst_dwType1 = dst_dwType1 << 20;
        dst_dwValue1 = dst_value << 16;
        dst_attr = dst_attr | dst_dwType1 | dst_dwValue1;

        if (dst_dwType2 != 0) // mantengo los mismos stats
        {
          dst_dwType2 = dst_dwType2 << 12;
          dst_dwValue2 = dst_dwValue2 << 8;
          dst_attr = dst_attr | dst_dwType2 | dst_dwValue2;
        }

        player->m_pShards[i][x]->iCount--;
        SendNotifyMsg(0, iClientH, msg_shard, player->m_pShards[i][x]->dwType,
                      player->m_pShards[i][x]->dwValue,
                      player->m_pShards[i][x]->iCount,
                      player->m_pShards[i][x]->cName, 0, 0, 0, 0, 0, 0,
                      player->m_pShards[i][x]->cDesc);
      } else {
        if (player->m_pFragments[i][x] == 0 ||
            player->m_pFragments[i][x]->iCount == 0)
          continue;
        if (dst_dwType2 == 0 ||
            dst_dwType2 != player->m_pFragments[i][x]->dwType)
          continue; // no es del mismo tipo
        if (dst_dwValue2 != player->m_pFragments[i][x]->dwValue)
          continue; // no es del mismo level

        auto dst_value = dst_dwValue2 + 1;

        dst_attr = 0;
        dst_dwType1 = dst_dwType1 << 20;
        dst_dwValue1 = dst_dwValue1 << 16;
        dst_dwType2 = dst_dwType2 << 12;
        dst_dwValue2 = dst_value << 8;
        dst_attr = dst_attr | dst_dwType1 | dst_dwValue1;
        dst_attr = dst_attr | dst_dwType2 | dst_dwValue2;

        player->m_pFragments[i][x]->iCount--;
        SendNotifyMsg(0, iClientH, msg_fragment,
                      player->m_pFragments[i][x]->dwType,
                      player->m_pFragments[i][x]->dwValue,
                      player->m_pFragments[i][x]->iCount,
                      player->m_pFragments[i][x]->cName, 0, 0, 0, 0, 0, 0,
                      player->m_pFragments[i][x]->cDesc);
      }

      CalculateSSN_SkillIndex(iClientH, 20, 1);
      goto BREAK_LOOP;
    }
  }
  return;
BREAK_LOOP:
  SendNotifyMsg(0, iClientH, DEF_NOTIFY_ITEMATTRIBUTECHANGE, sDestItemID,
                player->m_pItemList[sDestItemID]->m_dwAttribute, 0, 0);
}

void CGame::RequestItemDisenchantHandler(int iClientH, int iItemIndex) {
  auto player = m_pClientList[iClientH];

  if (player == 0)
    return;
  if ((iItemIndex < 0) || (iItemIndex >= DEF_MAXITEMS))
    return;
  if (player->m_pItemList[iItemIndex] == 0)
    return;

  if ((player->m_pItemList[iItemIndex]->m_sTouchEffectValue1 ==
       player->m_sCharIDnum1) &&
      (player->m_pItemList[iItemIndex]->m_sTouchEffectValue2 ==
       player->m_sCharIDnum2) &&
      (player->m_pItemList[iItemIndex]->m_sTouchEffectValue3 ==
       player->m_sCharIDnum3)) {
    return; // si es un item unico no se puede
  }

  auto attr = player->m_pItemList[iItemIndex]->m_dwAttribute;
  auto dwType1 = (attr & 0x00F00000) >> 20;
  auto dwValue1 = (attr & 0x000F0000) >> 16;
  auto dwType2 = (attr & 0x0000F000) >> 12;
  auto dwValue2 = (attr & 0x00000F00) >> 8;

  if (dwType1 != 0) {
    DWORD type = dwType1;
    DWORD value = dwValue1 - 1;
    if (player->m_pShards[type][value] == 0) {
      player->m_pShards[type][value] = new class CEnchanting;

      strcpy(player->m_pShards[type][value]->cName, GetShardName(dwType1));
      strcpy(player->m_pShards[type][value]->cDesc, GetShardDesc(dwType1));
      player->m_pShards[type][value]->dwType = dwType1;
      player->m_pShards[type][value]->dwValue = dwValue1;
    }

    player->m_pShards[type][value]->iCount++;

    SendNotifyMsg(0, iClientH, msg_shard, dwType1, dwValue1,
                  player->m_pShards[type][value]->iCount,
                  player->m_pShards[type][value]->cName, 0, 0, 0, 0, 0, 0,
                  player->m_pShards[type][value]->cDesc);
  }

  if (dwType2 != 0) {
    DWORD type = dwType2;
    DWORD value = dwValue2 - 1;
    if (player->m_pFragments[type][value] == 0) {
      player->m_pFragments[type][value] = new class CEnchanting;

      strcpy(player->m_pFragments[type][value]->cName,
             GetFragmentName(dwType2));
      strcpy(player->m_pFragments[type][value]->cDesc,
             GetFragmentDesc(dwType2));
      player->m_pFragments[type][value]->dwType = dwType2;
      player->m_pFragments[type][value]->dwValue = dwValue2;
    }

    player->m_pFragments[type][value]->iCount++;

    SendNotifyMsg(0, iClientH, msg_fragment, dwType2, dwValue2,
                  player->m_pFragments[type][value]->iCount,
                  player->m_pFragments[type][value]->cName, 0, 0, 0, 0, 0, 0,
                  player->m_pFragments[type][value]->cDesc);
  }

  ItemDepleteHandler(iClientH, iItemIndex, true); // destruye el item
}

